-- 2026-10-19 전문가 검토 반영 (단원 69, 활동 34)
update public.lessons set content=$j${"quiz": [{"q": "我是学生。(wǒ shì xuésheng)의 뜻은 무엇일까요?", "answer": 1, "choices": ["나는 선생님이에요.", "나는 학생이에요.", "너는 학생이니?", "나는 한국 사람이에요."], "explain": "我는 '나', 是는 '~이다', 学生은 '학생'이에요."}, {"q": "친구의 이름을 물어볼 때 하는 말은?", "answer": 2, "choices": ["你好！", "再见！", "你叫什么名字？", "我是韩国人。"], "explain": "什么는 '무엇', 名字는 '이름'이라서 '이름이 뭐야?'라는 뜻이에요."}, {"q": "문장 끝에 붙이면 묻는 말이 되는 글자는?", "answer": 0, "choices": ["吗 (ma)", "是 (shì)", "我 (wǒ)", "叫 (jiào)"], "explain": "你是中国人吗？처럼 문장 끝에 吗를 붙이면 '~이니?' 하고 묻는 말이 돼요."}, {"q": "'나는 중국 사람이 아니에요.'를 중국어로 바르게 쓴 것은?", "answer": 3, "choices": ["我是中国人。", "你是中国人吗？", "我叫中国人。", "我不是中国人。"], "explain": "'아니다'는 是 앞에 不를 붙인 不是(bú shì)로 말해요."}, {"q": "처음 만난 친구에게 '만나서 반가워.'라고 할 때 알맞은 말은?", "answer": 0, "choices": ["认识你很高兴。", "再见！", "老师好！", "我是学生。"], "explain": "认识你很高兴(rènshi nǐ hěn gāoxìng)은 '너를 알게 되어 기뻐', 곧 '만나서 반가워'라는 뜻이에요."}], "intro": "중국에서 온 새 친구를 만났어요! 반갑게 인사하고 내 이름을 말해 주고 싶다면 어떻게 할까요? 오늘은 중국어로 나를 소개하는 방법을 처음부터 배워요.", "summary": ["你好(nǐ hǎo)는 '안녕', 再见(zàijiàn)은 '잘 가'예요.", "我是 ~ (wǒ shì)는 '나는 ~이에요', 我叫 ~ (wǒ jiào)는 '내 이름은 ~이에요'예요.", "문장 끝에 吗(ma)를 붙이면 묻는 말, 是 앞에 不를 붙이면 '~이 아니에요'가 돼요."], "keywords": [{"word": "병음", "meaning": "중국어 소리를 알파벳으로 적은 것 (예: nǐ hǎo)"}, {"word": "성조", "meaning": "소리의 높낮이. 1성(ā)·2성(á)·3성(ǎ)·4성(à) 네 가지가 있어요"}, {"word": "我是 (wǒ shì)", "meaning": "나는 ~이에요"}, {"word": "我叫 (wǒ jiào)", "meaning": "내 이름은 ~이에요"}, {"word": "吗 (ma)", "meaning": "문장 끝에 붙여 묻는 말을 만드는 글자"}], "sections": [{"paras": ["중국어로 '안녕'은 你好(nǐ hǎo, 니하오)예요. 你(nǐ)는 '너', 好(hǎo)는 '좋다'라는 뜻이에요.", "알파벳 위의 작은 표시는 성조예요. 성조는 소리의 높낮이인데, 높낮이가 달라지면 뜻도 달라져요. ā는 높고 평평하게, á는 쭉 올리고, ǎ는 내렸다가 올리고, à는 뚝 떨어뜨려 읽어요.", "헤어질 때는 再见(zàijiàn, 짜이지엔)이라고 말해요. 선생님께는 老师好(lǎoshī hǎo, 라오스 하오)라고 인사해요."], "figure": "두 아이가 교실 앞에서 웃으며 손을 흔들어 인사하는 모습", "example": "你好！(nǐ hǎo, 니하오) → 안녕! / 再见！(zàijiàn, 짜이지엔) → 잘 가!", "heading": "인사는 你好(nǐ hǎo)로 시작해요"}, {"paras": ["我(wǒ, 워)는 '나', 是(shì, 스)는 '~이다'라는 뜻이에요. 我是 뒤에 나를 나타내는 말을 붙이면 '나는 ~이에요'가 돼요.", "我是学生(wǒ shì xuésheng, 워 스 쉐셩)은 '나는 학생이에요', 我是韩国人(wǒ shì Hánguórén, 워 스 한궈런)은 '나는 한국 사람이에요'예요. 중국어는 우리말과 달리 '나는 - 이다 - 학생' 순서로 말해요."], "figure": "'나 - 이다 - 학생' 순서로 놓인 낱말 카드 세 장 그림", "example": "我 + 是 + 学生 → 我是学生。(나는 학생이에요.)", "heading": "我是(wǒ shì)로 '나는 ~이에요'를 말해요"}, {"paras": ["이름을 말할 때는 我叫(wǒ jiào, 워 지아오) 뒤에 이름을 붙여요. 叫는 '(이름을) 부르다'라는 뜻이에요.", "이름을 물을 때는 你叫什么名字？(nǐ jiào shénme míngzi, 니 지아오 선머 밍쯔)라고 해요. 什么(shénme)는 '무엇', 名字(míngzi)는 '이름'이에요.", "我是敏浩(wǒ shì Mǐnhào, 워 스 민하오)처럼 我是 뒤에 이름을 붙여도 '나는 민호야'라는 뜻이 돼요."], "figure": "이름표를 가슴에 단 아이가 친구에게 자기 이름을 말하는 모습", "example": "A: 你叫什么名字？(이름이 뭐야?)  B: 我叫敏浩。(wǒ jiào Mǐnhào, 워 지아오 민하오 → 나는 민호라고 해.)", "heading": "이름은 我叫(wǒ jiào)로 말해요"}, {"paras": ["문장 끝에 吗(ma, 마)를 붙이면 묻는 말이 돼요. 你是中国人吗？(nǐ shì Zhōngguórén ma, 니 스 중궈런 마)는 '너는 중국 사람이니?'예요.", "'아니에요'라고 할 때는 是 앞에 不를 붙여 不是(bú shì, 부 스)라고 해요. 不는 원래 bù(뿌)인데, 是처럼 뚝 떨어지는 소리(4성) 앞에서는 bú(부)로 올려 읽어요.", "처음 만난 친구에게는 认识你很高兴(rènshi nǐ hěn gāoxìng, 런스 니 헌 까오싱), '만나서 반가워'라고 말해 보세요."], "figure": "한국 국기와 중국 국기를 각각 든 두 아이가 마주 보고 이야기하는 모습", "example": "A: 你是中国人吗？ B: 我不是中国人，我是韩国人。(나는 중국 사람이 아니야. 한국 사람이야.)", "heading": "吗(ma)로 묻고, 不是(bú shì)로 아니라고 해요"}], "parent_tip": "중국어는 같은 소리라도 성조(높낮이)가 다르면 뜻이 달라지므로, 병음 위 표시를 보며 손으로 높낮이를 그려 가며 읽게 하면 좋습니다. 你好처럼 3성이 두 번 이어지면 실제로는 앞 글자를 2성처럼 올려 'ní hǎo'로 읽는데, 표기는 nǐ hǎo 그대로 둡니다. 저녁 식사 때 '你叫什么名字？'라고 물어 아이가 '我叫○○。'로 대답하는 놀이를 해 보세요.", "expressions": [{"en": "你好！", "ko": "안녕! / 안녕하세요!", "note": "nǐ hǎo (니하오)"}, {"en": "我是学生。", "ko": "나는 학생이에요.", "note": "wǒ shì xuésheng (워 스 쉐셩)"}, {"en": "我是韩国人。", "ko": "나는 한국 사람이에요.", "note": "wǒ shì Hánguórén (워 스 한궈런)"}, {"en": "我叫敏浩。", "ko": "내 이름은 민호예요.", "note": "wǒ jiào Mǐnhào (워 지아오 민하오)"}, {"en": "你叫什么名字？", "ko": "이름이 뭐예요?", "note": "nǐ jiào shénme míngzi (니 지아오 선머 밍쯔)"}, {"en": "你是中国人吗？", "ko": "너는 중국 사람이니?", "note": "nǐ shì Zhōngguórén ma (니 스 중궈런 마)"}, {"en": "我不是中国人。", "ko": "나는 중국 사람이 아니에요.", "note": "wǒ bú shì Zhōngguórén (워 부 스 중궈런)"}, {"en": "认识你很高兴。", "ko": "만나서 반가워요.", "note": "rènshi nǐ hěn gāoxìng (런스 니 헌 까오싱)"}, {"en": "老师好！", "ko": "선생님, 안녕하세요!", "note": "lǎoshī hǎo (라오스 하오)"}, {"en": "再见！", "ko": "잘 가! / 안녕히 계세요!", "note": "zàijiàn (짜이지엔)"}]}$j$::jsonb where slug='c5-01';
update public.lessons set content=$j${"quiz": [{"q": "七(qī)은 숫자 몇일까요?", "answer": 2, "choices": ["1", "4", "7", "9"], "explain": "七(qī, 치)은 7이에요."}, {"q": "你几岁？(nǐ jǐ suì)의 뜻은?", "answer": 0, "choices": ["너 몇 살이야?", "이름이 뭐야?", "너는 학생이니?", "몇 시야?"], "explain": "几는 '몇', 岁는 '살'이라서 '몇 살이야?'예요."}, {"q": "'나는 열한 살이에요.'를 바르게 쓴 것은?", "answer": 2, "choices": ["我是十一。", "我一十岁。", "我十一岁。", "我岁十一。"], "explain": "나이는 我 + 숫자 + 岁 순서로 말하고, 11은 十一예요."}, {"q": "'두 살'을 중국어로 바르게 말한 것은?", "answer": 3, "choices": ["二岁", "十二岁", "二十岁", "两岁"], "explain": "두 살은 两岁(liǎng suì)라고 해요."}, {"q": "我十二岁，你呢？에서 你呢？의 뜻은?", "answer": 1, "choices": ["너도?", "너는?", "몇 살?", "안녕?"], "explain": "你呢？(nǐ ne)는 '너는?' 하고 되묻는 말이에요."}], "intro": "새 친구와 친해지면 '너 몇 살이야?' 하고 궁금해지지요. 오늘은 중국어 숫자를 익히고, 나이를 묻고 대답하는 말을 배워요.", "summary": ["숫자 1~10: 一 二 三 四 五 六 七 八 九 十, 11은 十一, 20은 二十예요.", "你几岁？(nǐ jǐ suì)로 묻고, 我 + 숫자 + 岁로 대답해요. 두 살은 两岁예요.", "你呢？는 '너는?', 也는 '~도'라는 뜻이에요."], "keywords": [{"word": "几 (jǐ)", "meaning": "몇"}, {"word": "岁 (suì)", "meaning": "살(나이를 세는 말)"}, {"word": "两 (liǎng)", "meaning": "둘. 두 살, 두 개처럼 셀 때 쓰는 '2'"}, {"word": "也 (yě)", "meaning": "~도"}, {"word": "呢 (ne)", "meaning": "'~는?' 하고 되물을 때 붙이는 글자"}], "sections": [{"paras": ["중국어 숫자는 한자로 써요. 一(yī, 이) 1, 二(èr, 얼) 2, 三(sān, 싼) 3, 四(sì, 쓰) 4, 五(wǔ, 우) 5예요.", "六(liù, 리우) 6, 七(qī, 치) 7, 八(bā, 바) 8, 九(jiǔ, 지우) 9, 十(shí, 스) 10이에요. 손가락을 하나씩 접으며 소리 내어 세어 보세요."], "figure": "아이 두 손의 손가락을 하나씩 펴며 수를 세는 모습", "example": "一 yī, 二 èr, 三 sān, 四 sì, 五 wǔ, 六 liù, 七 qī, 八 bā, 九 jiǔ, 十 shí", "heading": "1부터 10까지 세어 봐요"}, {"paras": ["11은 '열 + 하나'라서 十一(shíyī, 스이), 12는 十二(shí'èr, 스얼)이에요. 우리말 '십일, 십이'와 만드는 방법이 똑같아요.", "20은 '둘 + 열'이라서 二十(èrshí, 얼스), 25는 二十五(èrshíwǔ, 얼스우)예요. 이렇게 하면 99 九十九(jiǔshíjiǔ)까지 모두 말할 수 있어요."], "figure": "숫자 블록을 이어 붙여 큰 수를 만드는 장난감 블록 사진", "example": "十一 = 11 / 十二 = 12 / 二十 = 20 / 二十五 = 25 / 九十九 = 99", "heading": "11부터 99까지는 블록처럼 붙여요"}, {"paras": ["几(jǐ, 지)는 '몇', 岁(suì, 쑤이)는 '살'이에요. 그래서 你几岁？(nǐ jǐ suì, 니 지 쑤이)는 '너 몇 살이야?'예요.", "대답은 我 + 숫자 + 岁로 해요. 我十二岁(wǒ shí'èr suì, 워 스얼 쑤이)는 '나는 열두 살이야'예요. 우리말의 '~이에요'에 해당하는 是는 넣지 않아요.", "조심! 두 살은 二岁가 아니라 两岁(liǎng suì, 량 쑤이)라고 해요. 하지만 열두 살은 그대로 十二岁예요."], "figure": "생일 케이크 위에 꽂힌 초를 아이가 세어 보는 모습", "example": "A: 你几岁？(너 몇 살이야?)  B: 我十二岁。(나는 열두 살이야.)", "heading": "你几岁？(nǐ jǐ suì) — 몇 살이야?"}, {"paras": ["几岁는 주로 어린아이에게 나이를 물을 때 써요. 비슷한 또래 친구에게는 你多大？(nǐ duō dà, 니 둬 다)라고도 물어요.", "대답한 뒤 상대에게 되물을 때는 你呢？(nǐ ne, 니 너), '너는?'이라고 해요. 나이가 같다면 我也十二岁(wǒ yě shí'èr suì, 워 예 스얼 쑤이), '나도 열두 살이야'라고 해요. 也(yě)는 '~도'예요.", "가족 나이도 말할 수 있어요. 我弟弟八岁(wǒ dìdi bā suì)는 '내 남동생은 여덟 살이에요'예요."], "figure": "같은 반 친구 두 명이 서로 손가락으로 나이를 보여 주며 웃는 모습", "example": "A: 我十二岁，你呢？  B: 我也十二岁。", "heading": "你多大？와 你呢？도 알아 두어요"}], "parent_tip": "중국어 나이 말하기에는 '是'가 들어가지 않는다는 점(我十二岁)과, 2살은 二岁가 아닌 两岁라는 점을 아이가 자주 헷갈립니다. 계단을 오르거나 물건을 셀 때 중국어 숫자로 함께 세어 보시고, 가족 한 사람씩 가리키며 '他几岁？'라고 물어 '○岁'로 답하는 놀이를 해 보세요.", "expressions": [{"en": "你几岁？", "ko": "너 몇 살이야?", "note": "nǐ jǐ suì (니 지 쑤이)"}, {"en": "我十二岁。", "ko": "나는 열두 살이에요.", "note": "wǒ shí'èr suì (워 스얼 쑤이)"}, {"en": "我十一岁。", "ko": "나는 열한 살이에요.", "note": "wǒ shíyī suì (워 스이 쑤이)"}, {"en": "你多大？", "ko": "너 몇 살이야? (또래에게)", "note": "nǐ duō dà (니 둬 다)"}, {"en": "你呢？", "ko": "너는?", "note": "nǐ ne (니 너)"}, {"en": "我也十二岁。", "ko": "나도 열두 살이에요.", "note": "wǒ yě shí'èr suì (워 예 스얼 쑤이)"}, {"en": "我弟弟八岁。", "ko": "내 남동생은 여덟 살이에요.", "note": "wǒ dìdi bā suì (워 디디 바 쑤이)"}, {"en": "我妹妹两岁。", "ko": "내 여동생은 두 살이에요.", "note": "wǒ mèimei liǎng suì (워 메이메이 량 쑤이)"}, {"en": "十", "ko": "10, 열", "note": "shí (스)"}, {"en": "二十", "ko": "20, 스물", "note": "èrshí (얼스)"}]}$j$::jsonb where slug='c5-02';
update public.lessons set content=$j${"quiz": [{"q": "现在几点？(xiànzài jǐ diǎn)의 뜻은?", "answer": 1, "choices": ["오늘은 며칠이에요?", "지금 몇 시예요?", "몇 살이에요?", "무슨 요일이에요?"], "explain": "现在는 '지금', 几点은 '몇 시'예요."}, {"q": "'2시'를 중국어로 바르게 말한 것은?", "answer": 2, "choices": ["二点", "十二点", "两点", "二分"], "explain": "2시는 两点(liǎng diǎn)이라고 해요. 十二点은 12시예요."}, {"q": "六点半은 몇 시일까요?", "answer": 0, "choices": ["6시 30분", "6시 5분", "5시 30분", "6시 반 전"], "explain": "六点은 6시, 半은 30분(반)이라서 6시 30분이에요."}, {"q": "'나는 7시에 일어나요.'를 바른 순서로 쓴 것은?", "answer": 3, "choices": ["我起床七点。", "七点起床我。", "起床我七点。", "我七点起床。"], "explain": "중국어는 나 → 시간 → 하는 일 순서로 말해요."}, {"q": "晚上(wǎnshang)의 뜻은?", "answer": 2, "choices": ["아침", "오후", "저녁, 밤", "지금"], "explain": "早上은 아침, 下午는 오후, 晚上은 저녁이나 밤이에요."}], "intro": "학교 가는 시간, 학원 가는 시간, 잠자는 시간… 하루는 시간으로 가득해요. 오늘은 중국어로 '지금 몇 시야?'라고 묻고, 내 하루를 시간으로 소개해 봐요.", "summary": ["'시'는 숫자 + 点, '분'은 숫자 + 分, '반'은 半이에요. 2시는 两点!", "现在几点？로 묻고, 现在 + 시간으로 대답해요.", "중국어는 '나 → 시간 → 하는 일' 순서로 말해요. 我七点起床。"], "keywords": [{"word": "点 (diǎn)", "meaning": "시(시각)"}, {"word": "分 (fēn)", "meaning": "분"}, {"word": "半 (bàn)", "meaning": "반(30분)"}, {"word": "现在 (xiànzài)", "meaning": "지금"}, {"word": "两点 (liǎng diǎn)", "meaning": "2시 (二点이라고 하지 않아요)"}], "sections": [{"paras": ["시계의 '시'는 点(diǎn, 디엔)이에요. 숫자 뒤에 点을 붙이면 돼요. 三点(sān diǎn, 싼 디엔)은 3시, 十二点(shí'èr diǎn)은 12시예요.", "조심! 2시는 二点이 아니라 两点(liǎng diǎn, 량 디엔)이라고 해요. 나이에서 두 살을 两岁라고 한 것과 같아요."], "figure": "벽에 걸린 둥근 아날로그 시계와 그 앞에 서 있는 아이", "example": "一点 1시 / 两点 2시 / 三点 3시 / 十点 10시 / 十二点 12시", "heading": "'몇 시'는 숫자 + 点(diǎn)이에요"}, {"paras": ["'분'은 숫자 뒤에 分(fēn, 펀)을 붙여요. 八点十分(bā diǎn shí fēn, 바 디엔 스 펀)은 8시 10분, 七点二十分(qī diǎn èrshí fēn)은 7시 20분이에요.", "'30분'은 우리말처럼 '반'이라고 할 수 있어요. 半(bàn, 빤)을 点 뒤에 붙여 三点半(sān diǎn bàn, 싼 디엔 빤)이라고 하면 3시 반이에요."], "figure": "8시 10분과 3시 30분을 가리키는 시계 두 개를 나란히 놓은 그림", "example": "八点十分 = 8시 10분 / 三点半 = 3시 반(3시 30분)", "heading": "'몇 분'은 分(fēn), '반'은 半(bàn)"}, {"paras": ["现在(xiànzài, 시엔짜이)는 '지금', 几(jǐ)는 '몇'이에요. 그래서 现在几点？(xiànzài jǐ diǎn, 시엔짜이 지 디엔)은 '지금 몇 시예요?'예요.", "대답은 现在 + 시간으로 해요. 现在三点。(지금 3시예요.) 现在九点半。(지금 9시 반이에요.)", "아침·오후·저녁을 함께 말하면 더 정확해요. 早上(zǎoshang, 짜오샹) 아침, 下午(xiàwǔ, 시아우) 오후, 晚上(wǎnshang, 완샹) 저녁·밤이에요. 이 말은 시간 앞에 붙여요."], "figure": "손목시계를 들여다보는 아이의 손목 사진", "example": "A: 现在几点？  B: 现在下午四点。(지금 오후 4시야.)", "heading": "现在几点？— 지금 몇 시예요?"}, {"paras": ["중국어는 '언제'를 하는 일 앞에 말해요. 我七点起床。(wǒ qī diǎn qǐchuáng, 워 치 디엔 치촹)은 '나는 7시에 일어나요.'예요. 起床은 '일어나다'예요.", "我八点去学校。(wǒ bā diǎn qù xuéxiào)는 '나는 8시에 학교에 가요.', 我晚上十点睡觉。(wǒ wǎnshang shí diǎn shuìjiào)는 '나는 밤 10시에 자요.'예요.", "순서를 기억해요. 我(나) → 시간 → 하는 일! 우리말 '나는 7시에 일어나요'와 순서가 비슷해서 쉬워요."], "figure": "아침 햇살이 드는 방에서 알람시계 옆 침대에서 일어나는 아이", "example": "我 + 七点 + 起床 → 我七点起床。(나는 7시에 일어나요.)", "heading": "시간은 '무엇을 하다' 앞에 와요"}], "parent_tip": "아이들이 2시를 二点으로 말하는 실수를 자주 합니다(정답: 两点). 또 '我起床七点'처럼 시간을 동사 뒤에 두기 쉬우니 '시간은 하는 일 앞'이라고 짚어 주세요. 집 시계를 가리키며 '现在几点？'라고 하루에 한두 번 물어보면 숫자와 시간 표현을 함께 복습할 수 있습니다.", "expressions": [{"en": "现在几点？", "ko": "지금 몇 시예요?", "note": "xiànzài jǐ diǎn (시엔짜이 지 디엔)"}, {"en": "现在三点。", "ko": "지금 3시예요.", "note": "xiànzài sān diǎn (시엔짜이 싼 디엔)"}, {"en": "两点", "ko": "2시", "note": "liǎng diǎn (량 디엔)"}, {"en": "三点半", "ko": "3시 반", "note": "sān diǎn bàn (싼 디엔 빤)"}, {"en": "八点十分", "ko": "8시 10분", "note": "bā diǎn shí fēn (바 디엔 스 펀)"}, {"en": "我七点起床。", "ko": "나는 7시에 일어나요.", "note": "wǒ qī diǎn qǐchuáng (워 치 디엔 치촹)"}, {"en": "我八点去学校。", "ko": "나는 8시에 학교에 가요.", "note": "wǒ bā diǎn qù xuéxiào (워 바 디엔 취 쉐시아오)"}, {"en": "我晚上十点睡觉。", "ko": "나는 밤 10시에 자요.", "note": "wǒ wǎnshang shí diǎn shuìjiào (워 완샹 스 디엔 수이지아오)"}, {"en": "早上", "ko": "아침", "note": "zǎoshang (짜오샹)"}, {"en": "下午", "ko": "오후", "note": "xiàwǔ (시아우)"}]}$j$::jsonb where slug='c5-04';
update public.lessons set content=$j${"quiz": [{"q": "洗手间在哪儿？의 뜻은?", "answer": 0, "choices": ["화장실은 어디에 있어요?", "학교는 어디에 있어요?", "화장실은 저기에 있어요.", "화장실에 가요."], "explain": "洗手间은 '화장실', 在哪儿은 '어디에 있어요?'예요."}, {"q": "'저기'를 뜻하는 말은?", "answer": 2, "choices": ["哪儿 (nǎr)", "这儿 (zhèr)", "那儿 (nàr)", "旁边 (pángbiān)"], "explain": "那儿(nàr, 4성)이 '저기'예요. 哪儿(nǎr, 3성)은 '어디'예요."}, {"q": "超市在学校旁边。의 뜻은?", "answer": 3, "choices": ["마트는 학교 앞에 있어요.", "학교는 마트 옆에 있어요.", "마트는 학교 뒤에 있어요.", "마트는 학교 옆에 있어요."], "explain": "A + 在 + B + 旁边은 'A는 B 옆에 있어요'예요."}, {"q": "'우리 집은 서울에 있어요.'를 바르게 쓴 것은?", "answer": 0, "choices": ["我家在首尔。", "首尔在我家。", "我家首尔在。", "我在家首尔。"], "explain": "있는 것(我家) + 在 + 장소(首尔) 순서예요."}, {"q": "医院(yīyuàn)은 어떤 곳일까요?", "answer": 1, "choices": ["도서관", "병원", "마트", "학교"], "explain": "医院(이위엔)은 '병원'이에요."}], "intro": "낯선 곳에서 화장실이나 도서관을 찾고 싶을 때가 있지요. 그럴 때 '어디예요?'라고 물을 수 있으면 아주 든든해요. 오늘은 중국어로 장소를 묻고 위치를 말하는 법을 배워요.", "summary": ["장소 + 在哪儿？: '~은 어디에 있어요?' (哪儿 nǎr = 어디)", "这儿(zhèr) 여기, 那儿(nàr) 저기. 哪儿(3성)과 那儿(4성)은 성조로 구별해요.", "A + 在 + B + 前边/后边/旁边: 'A는 B의 앞/뒤/옆에 있어요.'"], "keywords": [{"word": "在 (zài)", "meaning": "~에 있다"}, {"word": "哪儿 (nǎr)", "meaning": "어디 (3성)"}, {"word": "这儿 / 那儿 (zhèr / nàr)", "meaning": "여기 / 저기"}, {"word": "旁边 (pángbiān)", "meaning": "옆"}, {"word": "洗手间 (xǐshǒujiān)", "meaning": "화장실"}], "sections": [{"paras": ["在(zài, 짜이)는 '~에 있다', 哪儿(nǎr, 날)은 '어디'예요. 찾는 장소 뒤에 在哪儿？을 붙이면 '~은 어디에 있어요?'가 돼요.", "洗手间在哪儿？(xǐshǒujiān zài nǎr, 시서우지엔 짜이 날)은 '화장실은 어디에 있어요?'예요. 洗手间은 '화장실'이에요.", "哪儿의 儿(r)은 혀끝을 살짝 말아 올려 'ㄹ' 받침처럼 소리 내요."], "figure": "건물 복도에서 두리번거리며 길을 찾는 아이", "example": "洗手间在哪儿？(화장실은 어디예요?) / 学校在哪儿？(학교는 어디예요?)", "heading": "___在哪儿？— ~은 어디에 있어요?"}, {"paras": ["这儿(zhèr, 절)은 '여기', 那儿(nàr, 날)은 '저기'예요. 대답은 在 + 장소로 해요. 在那儿。(zài nàr)은 '저기에 있어요.'예요.", "哪儿(nǎr, 어디)과 那儿(nàr, 저기)은 소리가 비슷해요! 哪儿은 내렸다 올리는 3성, 那儿은 뚝 떨어지는 4성이에요. 성조를 잘 들어 보세요."], "figure": "한 아이가 손가락으로 멀리 있는 문을 가리키는 모습", "example": "A: 洗手间在哪儿？  B: 在那儿。(저기 있어요.)", "heading": "这儿(여기)·那儿(저기)으로 대답해요"}, {"paras": ["前边(qiánbian, 치엔비엔)은 '앞', 后边(hòubian, 허우비엔)은 '뒤', 旁边(pángbiān, 팡비엔)은 '옆'이에요.", "'A는 B의 옆에 있어요'는 A + 在 + B + 旁边이라고 해요. 超市在学校旁边。(chāoshì zài xuéxiào pángbiān)은 '마트는 학교 옆에 있어요.'예요.", "우리말 '학교 옆'과 순서가 같아서 쉬워요. 기준이 되는 장소 뒤에 위치 말을 붙이면 돼요."], "figure": "학교 건물 옆에 작은 가게가 있는 동네 거리 모형", "example": "图书馆在医院后边。(túshūguǎn zài yīyuàn hòubian) → 도서관은 병원 뒤에 있어요.", "heading": "앞·뒤·옆으로 자세히 말해요"}, {"paras": ["学校(xuéxiào, 쉐시아오) 학교, 图书馆(túshūguǎn, 투수관) 도서관, 医院(yīyuàn, 이위엔) 병원, 超市(chāoshì, 차오스) 마트예요.", "家(jiā, 지아)는 '집'이에요. 你家在哪儿？(nǐ jiā zài nǎr)은 '너희 집은 어디야?'예요. 我家在首尔。(wǒ jiā zài Shǒu'ěr, 워 지아 짜이 서우얼)는 '우리 집은 서울에 있어.'예요."], "figure": "언덕 위에서 내려다본 아파트와 학교가 있는 동네 풍경", "example": "A: 你家在哪儿？  B: 我家在首尔。", "heading": "장소 낱말과 우리 집"}], "parent_tip": "哪儿(nǎr, 어디)과 那儿(nàr, 저기)은 성조만 다르기 때문에 아이가 자주 헷갈립니다. 손으로 3성(✓ 모양)과 4성(↘)을 그리며 구별해 보세요. 집 안 물건을 숨겨 두고 '书在哪儿？(책은 어디에 있어?)'—'在桌子旁边(책상 옆에)' 같은 보물찾기 놀이를 하면 위치 말을 재미있게 익힐 수 있습니다.", "expressions": [{"en": "洗手间在哪儿？", "ko": "화장실은 어디에 있어요?", "note": "xǐshǒujiān zài nǎr (시서우지엔 짜이 날)"}, {"en": "在那儿。", "ko": "저기에 있어요.", "note": "zài nàr (짜이 날)"}, {"en": "学校在这儿。", "ko": "학교는 여기에 있어요.", "note": "xuéxiào zài zhèr (쉐시아오 짜이 절)"}, {"en": "你家在哪儿？", "ko": "너희 집은 어디야?", "note": "nǐ jiā zài nǎr (니 지아 짜이 날)"}, {"en": "我家在首尔。", "ko": "우리 집은 서울에 있어요.", "note": "wǒ jiā zài Shǒu'ěr (워 지아 짜이 서우얼)"}, {"en": "超市在学校旁边。", "ko": "마트는 학교 옆에 있어요.", "note": "chāoshì zài xuéxiào pángbiān (차오스 짜이 쉐시아오 팡비엔)"}, {"en": "图书馆在医院后边。", "ko": "도서관은 병원 뒤에 있어요.", "note": "túshūguǎn zài yīyuàn hòubian (투수관 짜이 이위엔 허우비엔)"}, {"en": "前边", "ko": "앞", "note": "qiánbian (치엔비엔)"}, {"en": "后边", "ko": "뒤", "note": "hòubian (허우비엔)"}, {"en": "旁边", "ko": "옆", "note": "pángbiān (팡비엔)"}]}$j$::jsonb where slug='c5-08';
update public.lessons set content=$j${"quiz": [{"q": "今天天气怎么样？의 뜻은?", "answer": 0, "choices": ["오늘 날씨 어때요?", "오늘은 무슨 요일이에요?", "오늘은 몇 월 며칠이에요?", "지금 몇 시예요?"], "explain": "天气는 '날씨', 怎么样은 '어때요?'예요."}, {"q": "'오늘은 추워요.'를 바르게 쓴 것은?", "answer": 2, "choices": ["今天是冷。", "今天很热。", "今天很冷。", "今天冷很。"], "explain": "춥다는 冷이고, 是 대신 很을 앞에 붙여요."}, {"q": "下雪了。의 뜻은?", "answer": 3, "choices": ["비가 와요.", "바람이 불어요.", "맑아요.", "눈이 와요."], "explain": "雪(xuě)는 '눈'이라서 下雪了는 '눈이 와요'예요."}, {"q": "夏天(xiàtiān)은 어느 계절일까요?", "answer": 1, "choices": ["봄", "여름", "가을", "겨울"], "explain": "春天 봄, 夏天 여름, 秋天 가을, 冬天 겨울이에요."}, {"q": "가을 날씨를 알맞게 말한 것은?", "answer": 0, "choices": ["秋天很凉快。", "秋天下雪了。", "秋天是热。", "秋天很冷很热。"], "explain": "秋天很凉快。는 '가을은 시원해요.'예요."}], "intro": "아침에 창밖을 보면 '오늘은 덥나? 비가 오나?' 궁금하지요. 날씨는 누구와도 나눌 수 있는 좋은 이야깃거리예요. 오늘은 중국어로 날씨를 묻고 말해 봐요.", "summary": ["今天天气怎么样？로 날씨를 물어요.", "덥다·춥다는 很 + 热/冷: 今天很热。(是는 쓰지 않아요!)", "下雨了(비), 下雪了(눈), 刮风了(바람), 晴天(맑은 날) / 계절: 春天·夏天·秋天·冬天"], "keywords": [{"word": "天气 (tiānqì)", "meaning": "날씨"}, {"word": "怎么样 (zěnmeyàng)", "meaning": "어때요?"}, {"word": "热 / 冷 (rè / lěng)", "meaning": "덥다 / 춥다"}, {"word": "下雨 / 下雪 (xià yǔ / xià xuě)", "meaning": "비가 오다 / 눈이 오다"}, {"word": "很 (hěn)", "meaning": "아주, 매우. 날씨·느낌 말 앞에 붙여 써요(이때는 是를 쓰지 않아요)."}], "sections": [{"paras": ["天气(tiānqì, 티엔치)는 '날씨', 怎么样(zěnmeyàng, 쩐머양)은 '어때요?'예요.", "그래서 今天天气怎么样？(jīntiān tiānqì zěnmeyàng, 진티엔 티엔치 쩐머양)은 '오늘 날씨 어때요?'예요. 明天(내일)을 넣으면 내일 날씨도 물을 수 있어요."], "figure": "창문 밖 하늘을 바라보는 아이의 뒷모습", "example": "今天天气怎么样？(오늘 날씨 어때?) / 明天天气怎么样？(내일 날씨 어때?)", "heading": "今天天气怎么样？— 오늘 날씨 어때요?"}, {"paras": ["热(rè, 러)는 '덥다', 冷(lěng, 렁)은 '춥다'예요. 날씨를 말할 때는 앞에 很(hěn)을 붙여 今天很热。(오늘은 더워요.), 今天很冷。(오늘은 추워요.)이라고 해요.", "조심! '덥다, 춥다' 같은 말 앞에는 是를 쓰지 않아요. 今天是热。가 아니라 今天很热。예요. 이때 很은 '아주'라는 뜻이 약해서 그냥 '더워요'로 생각하면 돼요.", "凉快(liángkuai, 량콰이)는 '시원하다', 暖和(nuǎnhuo, 놘훠)는 '따뜻하다'예요."], "figure": "한쪽은 반팔에 부채, 다른 쪽은 목도리와 장갑을 낀 아이 그림", "example": "今天很热。(오늘은 더워요.) / 今天很冷。(오늘은 추워요.) / 今天很凉快。(오늘은 시원해요.)", "heading": "덥다·춥다는 很(hěn) + 날씨 말"}, {"paras": ["下雨了(xià yǔ le, 시아 위 러)는 '비가 와요', 下雪了(xià xuě le, 시아 쉐 러)는 '눈이 와요', 刮风了(guā fēng le, 꽈 펑 러)는 '바람이 불어요'예요.", "끝의 了(le)는 '이제 막 그렇게 됐다'는 느낌을 더해요. 창밖을 보다가 '어, 비 온다!' 할 때 딱 맞는 말이에요.", "맑은 날은 晴天(qíngtiān, 칭티엔), 흐린 날은 阴天(yīntiān, 인티엔)이에요. 이건 '날'이라는 이름이라 今天是晴天。(오늘은 맑은 날이에요.)처럼 是를 써요."], "figure": "창문 유리에 빗방울이 맺히고 우산이 옆에 세워진 모습", "example": "A: 今天天气怎么样？  B: 下雨了。(비가 와.)", "heading": "비·눈·바람 — 下雨了, 下雪了, 刮风了"}, {"paras": ["春天(chūntiān, 춘티엔) 봄, 夏天(xiàtiān, 시아티엔) 여름, 秋天(qiūtiān, 치우티엔) 가을, 冬天(dōngtiān, 똥티엔) 겨울이에요.", "夏天很热，冬天很冷。은 '여름은 덥고, 겨울은 추워요.'예요. 春天很暖和。(봄은 따뜻해요.) 秋天很凉快。(가을은 시원해요.)도 말해 보세요."], "figure": "벚꽃, 수박, 단풍잎, 눈사람이 네 칸에 나뉘어 놓인 계절 그림", "example": "春天很暖和。/ 夏天很热。/ 秋天很凉快。/ 冬天很冷。", "heading": "계절 날씨도 말해요"}], "parent_tip": "'今天是热'처럼 형용사 앞에 是를 넣는 것이 가장 흔한 실수입니다. 날씨·기분을 나타내는 말 앞에는 是 대신 很을 쓴다고 짚어 주세요. 매일 아침 창밖을 보며 '今天天气怎么样？'라고 묻고 아이가 '今天很冷。/ 下雨了。'로 답하게 하면 자연스럽게 입에 붙습니다.", "expressions": [{"en": "今天天气怎么样？", "ko": "오늘 날씨 어때요?", "note": "jīntiān tiānqì zěnmeyàng (진티엔 티엔치 쩐머양)"}, {"en": "今天很热。", "ko": "오늘은 더워요.", "note": "jīntiān hěn rè (진티엔 헌 러)"}, {"en": "今天很冷。", "ko": "오늘은 추워요.", "note": "jīntiān hěn lěng (진티엔 헌 렁)"}, {"en": "下雨了。", "ko": "비가 와요.", "note": "xià yǔ le (시아 위 러)"}, {"en": "下雪了。", "ko": "눈이 와요.", "note": "xià xuě le (시아 쉐 러)"}, {"en": "刮风了。", "ko": "바람이 불어요.", "note": "guā fēng le (꽈 펑 러)"}, {"en": "今天是晴天。", "ko": "오늘은 맑은 날이에요.", "note": "jīntiān shì qíngtiān (진티엔 스 칭티엔)"}, {"en": "春天很暖和。", "ko": "봄은 따뜻해요.", "note": "chūntiān hěn nuǎnhuo (춘티엔 헌 놘훠)"}, {"en": "秋天很凉快。", "ko": "가을은 시원해요.", "note": "qiūtiān hěn liángkuai (치우티엔 헌 량콰이)"}, {"en": "明天下雨吗？", "ko": "내일 비가 와요?", "note": "míngtiān xià yǔ ma (밍티엔 시아 위 마)"}]}$j$::jsonb where slug='c5-10';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-01_kw.mp3", "q0": "assets/audio/n/e1-01_q0.mp3", "q1": "assets/audio/n/e1-01_q1.mp3", "q2": "assets/audio/n/e1-01_q2.mp3", "q3": "assets/audio/n/e1-01_q3.mp3", "q4": "assets/audio/n/e1-01_q4.mp3", "s0": "assets/audio/n/e1-01_s0.mp3", "s1": "assets/audio/n/e1-01_s1.mp3", "s2": "assets/audio/n/e1-01_s2.mp3", "s3": "assets/audio/n/e1-01_s3.mp3", "sum": "assets/audio/n/e1-01_sum.mp3", "cover": "assets/audio/n/e1-01_cover.mp3"}, "quiz": [{"q": "🍎 apple은 어떤 글자로 시작할까요?", "answer": 1, "choices": ["B", "A", "C", "D"], "explain": "apple은 A(에이)로 시작해요."}, {"q": "A 다음에 오는 글자는?", "answer": 2, "choices": ["C", "D", "B", "M"], "explain": "A, B, C 차례예요. A 다음은 B예요."}, {"q": "'엠'이라고 부르는 글자는?", "answer": 0, "choices": ["M", "N", "H", "K"], "explain": "M의 이름은 '엠'이에요. 🌙 moon의 첫 글자예요."}, {"q": "알파벳은 모두 몇 개일까요?", "answer": 3, "choices": ["13개", "20개", "10개", "26개"], "explain": "알파벳은 A부터 Z까지 26개예요. 오늘은 그중 13개를 배웠어요."}, {"q": "K 바로 앞 글자는?", "answer": 1, "choices": ["L", "J", "I", "M"], "explain": "I, J, K, L 차례예요. K 바로 앞은 J예요."}], "intro": "영어에는 글자가 26개 있어요. 🔤 오늘은 앞의 13개를 만나요.", "summary": ["알파벳은 영어 글자이고 26개예요.", "A부터 M까지 13개 글자의 이름을 배웠어요.", "노래로 부르면 차례를 쉽게 외워요."], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자. 모두 26개예요."}, {"word": "글자 이름", "meaning": "글자를 부르는 말. A는 '에이'예요."}, {"word": "차례", "meaning": "A, B, C처럼 글자가 놓이는 순서"}], "sections": [{"paras": ["알파벳은 영어 글자예요.", "모두 26개가 있어요.", "오늘은 A부터 M까지 배워요."], "figure": "책상 위에 A부터 M까지 차례로 놓인 나무 알파벳 블록", "example": "A B C D E F G H I J K L M", "heading": "알파벳은 영어 글자예요"}, {"paras": ["글자마다 이름이 있어요.", "A는 '에이'라고 불러요.", "🍎 apple은 A로 시작해요."], "figure": "사과, 곰 인형, 고양이 인형이 나란히 놓인 책상", "example": "A 에이 · B 비 · C 씨 · D 디 · E 이 · F 에프 · G 지", "heading": "A부터 G까지 이름을 불러요"}, {"paras": ["H는 '에이치'예요.", "🦁 lion은 L로 시작해요.", "🌙 moon은 M으로 시작해요."], "figure": "아이 손이 알파벳 카드를 한 장씩 집는 모습", "example": "H 에이치 · I 아이 · J 제이 · K 케이 · L 엘 · M 엠", "heading": "H부터 M까지 이름을 불러요"}, {"paras": ["알파벳 노래를 불러요. 🎵", "손가락으로 짚으며 불러요.", "차례를 쉽게 외울 수 있어요."], "figure": "아이가 손가락으로 알파벳 카드 줄을 짚으며 노래하는 모습", "example": "A B C D E F G, H I J K L M", "heading": "노래로 외워요"}], "parent_tip": "이 단계에서는 글자 '이름'만 익히고, 글자 '소리'(파닉스)는 다음 단원에서 다룹니다. 알파벳 카드를 섞어 놓고 '에이 찾아볼까?'처럼 놀이로 한 글자씩 찾게 하시면 좋습니다. G(지)와 J(제이), I(아이)와 E(이)를 아이들이 자주 헷갈립니다.", "expressions": [{"en": "A", "ko": "에이", "note": "🍎 apple의 첫 글자"}, {"en": "B", "ko": "비", "note": "🐻 bear의 첫 글자"}, {"en": "C", "ko": "씨", "note": "🐱 cat의 첫 글자"}, {"en": "D", "ko": "디", "note": "🐶 dog의 첫 글자"}, {"en": "E", "ko": "이", "note": "🥚 egg의 첫 글자"}, {"en": "F", "ko": "에프", "note": "🐟 fish의 첫 글자"}, {"en": "G", "ko": "지", "note": "🍇 grapes의 첫 글자"}, {"en": "H", "ko": "에이치", "note": "🎩 hat의 첫 글자"}, {"en": "I", "ko": "아이", "note": "🍦 ice cream의 첫 글자"}, {"en": "J", "ko": "제이", "note": "🧃 juice의 첫 글자"}, {"en": "K", "ko": "케이", "note": "🪁 kite의 첫 글자"}, {"en": "L, M", "ko": "엘, 엠", "note": "🦁 lion, 🌙 moon의 첫 글자"}]}$j$::jsonb where slug='e1-01';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-02_kw.mp3", "q0": "assets/audio/n/e1-02_q0.mp3", "q1": "assets/audio/n/e1-02_q1.mp3", "q2": "assets/audio/n/e1-02_q2.mp3", "q3": "assets/audio/n/e1-02_q3.mp3", "q4": "assets/audio/n/e1-02_q4.mp3", "s0": "assets/audio/n/e1-02_s0.mp3", "s1": "assets/audio/n/e1-02_s1.mp3", "s2": "assets/audio/n/e1-02_s2.mp3", "s3": "assets/audio/n/e1-02_s3.mp3", "sum": "assets/audio/n/e1-02_sum.mp3", "cover": "assets/audio/n/e1-02_cover.mp3"}, "quiz": [{"q": "🐷 pig는 어떤 글자로 시작할까요?", "answer": 2, "choices": ["B", "D", "P", "Q"], "explain": "pig는 P(피)로 시작해요."}, {"q": "Z 바로 앞 글자는?", "answer": 0, "choices": ["Y", "X", "W", "V"], "explain": "X, Y, Z 차례예요. Z 바로 앞은 Y예요."}, {"q": "'더블유'라고 부르는 글자는?", "answer": 3, "choices": ["V", "M", "N", "W"], "explain": "W의 이름은 '더블유'예요."}, {"q": "N 다음에 오는 글자는?", "answer": 1, "choices": ["M", "O", "P", "Q"], "explain": "M, N, O 차례예요. N 다음은 O예요."}, {"q": "알파벳 맨 마지막 글자는?", "answer": 2, "choices": ["A", "X", "Z", "Y"], "explain": "알파벳은 A로 시작해서 Z로 끝나요."}], "intro": "지난번에 A부터 M까지 배웠어요. 🔤 오늘은 나머지 13개를 만나요.", "summary": ["N부터 Z까지 13개 글자를 배웠어요.", "R은 '알', W는 '더블유'라고 불러요.", "Z가 알파벳 맨 마지막 글자예요."], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자 26개"}, {"word": "마지막 글자", "meaning": "알파벳 맨 끝 글자 Z"}, {"word": "알파벳 노래", "meaning": "26개 글자를 차례대로 부르는 노래"}], "sections": [{"paras": ["M 다음은 N이에요.", "N부터 Z까지 13개예요.", "Z가 맨 마지막 글자예요."], "figure": "책상 위에 N부터 Z까지 차례로 놓인 나무 알파벳 블록", "example": "N O P Q R S T U V W X Y Z", "heading": "알파벳 뒷부분이에요"}, {"paras": ["R은 '알'이라고 불러요.", "🐷 pig는 P로 시작해요.", "☀️ sun은 S로 시작해요."], "figure": "돼지 인형과 호랑이 인형이 놓인 아이 책상", "example": "N 엔 · O 오 · P 피 · Q 큐 · R 알 · S 에스 · T 티", "heading": "N부터 T까지 이름을 불러요"}, {"paras": ["W는 '더블유'예요. 이름이 길어요.", "🦓 zebra는 Z로 시작해요.", "X는 🦊 fox 끝에 있어요."], "figure": "우산, 요요, 얼룩말 인형이 나란히 놓인 모습", "example": "U 유 · V 브이 · W 더블유 · X 엑스 · Y 와이 · Z 지", "heading": "U부터 Z까지 이름을 불러요"}, {"paras": ["알파벳 노래를 끝까지 불러요. 🎵", "LMNOP는 빨리 지나가요.", "천천히 한 글자씩 짚어요."], "figure": "아이가 바닥에 26개 알파벳 카드를 한 줄로 늘어놓은 모습", "example": "Q R S, T U V, W X, Y and Z", "heading": "A부터 Z까지 이어 불러요"}], "parent_tip": "알파벳 노래에서 L-M-N-O-P를 한 덩어리 'elemeno'처럼 부르는 아이가 많으니 천천히 짚으며 불러 주세요. Z는 미국식 '지', 영국식 '제드'로 부르며 둘 다 맞습니다. A~M 카드와 합쳐 26장을 차례대로 늘어놓는 놀이를 해 보세요.", "expressions": [{"en": "N", "ko": "엔", "note": "👃 nose의 첫 글자"}, {"en": "O", "ko": "오", "note": "🐙 octopus의 첫 글자"}, {"en": "P", "ko": "피", "note": "🐷 pig의 첫 글자"}, {"en": "Q", "ko": "큐", "note": "👸 queen의 첫 글자"}, {"en": "R", "ko": "알", "note": "🐰 rabbit의 첫 글자"}, {"en": "S", "ko": "에스", "note": "☀️ sun의 첫 글자"}, {"en": "T", "ko": "티", "note": "🐯 tiger의 첫 글자"}, {"en": "U", "ko": "유", "note": "☂️ umbrella의 첫 글자"}, {"en": "V", "ko": "브이", "note": "🎻 violin의 첫 글자"}, {"en": "W", "ko": "더블유", "note": "⌚ watch의 첫 글자"}, {"en": "X", "ko": "엑스", "note": "🦊 fox의 끝 글자"}, {"en": "Y, Z", "ko": "와이, 지", "note": "🪀 yo-yo, 🦓 zebra의 첫 글자. Z '지'는 G '지'와 달리 벌 소리 '즈'처럼 시작해요"}]}$j$::jsonb where slug='e1-02';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-05_kw.mp3", "q0": "assets/audio/n/e1-05_q0.mp3", "q1": "assets/audio/n/e1-05_q1.mp3", "q2": "assets/audio/n/e1-05_q2.mp3", "q3": "assets/audio/n/e1-05_q3.mp3", "q4": "assets/audio/n/e1-05_q4.mp3", "s0": "assets/audio/n/e1-05_s0.mp3", "s1": "assets/audio/n/e1-05_s1.mp3", "s2": "assets/audio/n/e1-05_s2.mp3", "s3": "assets/audio/n/e1-05_s3.mp3", "sum": "assets/audio/n/e1-05_sum.mp3", "cover": "assets/audio/n/e1-05_cover.mp3"}, "quiz": [{"q": "🐷 pig의 첫소리 글자는?", "answer": 1, "choices": ["b", "p", "q", "d"], "explain": "pig는 입술을 터뜨리는 '프' 소리, p로 시작해요."}, {"q": "☀️ sun과 첫소리가 같은 낱말은?", "answer": 0, "choices": ["🐍 snake", "🦓 zebra", "🐯 tiger", "🐙 octopus"], "explain": "sun과 snake는 둘 다 s '스' 소리로 시작해요."}, {"q": "🦊 fox에서 x 소리는 어디에 있을까요?", "answer": 2, "choices": ["맨 앞", "가운데", "맨 끝", "없어요"], "explain": "fox는 f-o-x예요. x는 맨 끝에서 '크스' 소리가 나요."}, {"q": "윗니로 아랫입술을 살짝 물고 내는 소리는?", "answer": 3, "choices": ["🐷 pig의 p", "🐰 rabbit의 r", "🐯 tiger의 t", "🎻 violin의 v"], "explain": "v는 윗니가 아랫입술에 닿아요."}, {"q": "☂️ umbrella의 첫 글자는?", "answer": 2, "choices": ["a", "o", "u", "e"], "explain": "umbrella는 짧은 '어' 소리, u로 시작해요."}], "intro": "지난번에 a부터 m까지 소리를 배웠어요. 👂 오늘은 n부터 z까지 소리를 들어 봐요.", "summary": ["n부터 z까지 낱말 첫소리를 들어 봤어요.", "x는 fox처럼 낱말 끝에서 자주 소리 나요.", "v와 b, s와 z는 입 모양으로 구별해요."], "keywords": [{"word": "첫소리", "meaning": "낱말을 말할 때 맨 처음 나는 소리"}, {"word": "끝소리", "meaning": "낱말 맨 끝에서 나는 소리 (fox의 x)"}, {"word": "입 모양", "meaning": "소리를 낼 때 입술·이·혀의 모양"}], "sections": [{"paras": ["👃 nose는 콧소리 '은'으로 시작해요.", "🐷 pig는 입술을 붙였다 '프' 터뜨려요.", "q 뒤에는 거의 늘 u가 와요. 👸 queen!"], "figure": "돼지 인형과 토끼 인형이 나란히 앉은 책상", "example": "n - nose · o - octopus · p - pig · q - queen · r - rabbit", "heading": "n부터 r까지 소리"}, {"paras": ["☀️ sun은 뱀 소리 '스'로 시작해요. 🐍", "☂️ umbrella는 짧게 '어' 해요.", "🎻 violin은 윗니로 아랫입술을 물어요."], "figure": "노란 우산과 장난감 바이올린이 놓인 아이 방", "example": "s - sun · t - tiger · u - umbrella · v - violin", "heading": "s부터 v까지 소리"}, {"paras": ["⌚ watch는 입술을 동그랗게 '우' 해요.", "x는 🦊 fox처럼 끝에서 '크스' 소리가 나요.", "🦓 zebra는 벌 소리 '즈'로 시작해요. 🐝"], "figure": "요요와 얼룩말 인형, 여우 인형이 놓인 책상", "example": "w - watch · x - fox · y - yo-yo · z - zebra", "heading": "w부터 z까지 소리"}, {"paras": ["v와 b는 달라요.", "v는 윗니가 입술에 닿고, b는 두 입술이 붙어요.", "s는 바람 소리, z는 벌 소리예요."], "figure": "아이가 거울 앞에서 입 모양을 보는 모습", "example": "v - violin · b - bear · s - sun · z - zebra", "heading": "헷갈리는 소리 짝"}], "parent_tip": "r과 l, v와 b, f와 p는 우리말에 없는 구별이라 아이들이 어려워합니다. 거울 앞에서 입 모양(윗니가 입술에 닿는지)을 함께 보며 연습하면 좋습니다. 한글로 적은 소리는 참고용이니 듣기 버튼으로 실제 소리를 꼭 들려주세요.", "expressions": [{"en": "n - nose", "ko": "👃 코", "note": "콧소리 '은'"}, {"en": "o - octopus", "ko": "🐙 문어", "note": "입을 크게 벌려 '아'"}, {"en": "p - pig", "ko": "🐷 돼지", "note": "입술을 붙였다 '프' 터뜨려요"}, {"en": "q - queen", "ko": "👸 여왕", "note": "qu는 '크우' 소리"}, {"en": "r - rabbit", "ko": "🐰 토끼", "note": "입술을 동그랗게 '루'"}, {"en": "s - sun", "ko": "☀️ 해", "note": "뱀 소리 '스'"}, {"en": "t - tiger", "ko": "🐯 호랑이", "note": "'트' 소리"}, {"en": "u - umbrella", "ko": "☂️ 우산", "note": "짧게 '어'"}, {"en": "v - violin", "ko": "🎻 바이올린", "note": "윗니로 아랫입술을 물고 '브'"}, {"en": "w - watch", "ko": "⌚ 손목시계", "note": "입술을 동그랗게 '우'"}, {"en": "x - fox", "ko": "🦊 여우", "note": "x는 끝에서 '크스'"}, {"en": "y - yo-yo, z - zebra", "ko": "🪀 요요, 🦓 얼룩말", "note": "y는 '이' 하고 짧게 미끄러지듯(yo-yo의 '요'), z는 벌 소리 '즈'"}]}$j$::jsonb where slug='e1-05';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-06_kw.mp3", "q0": "assets/audio/n/e1-06_q0.mp3", "q1": "assets/audio/n/e1-06_q1.mp3", "q2": "assets/audio/n/e1-06_q2.mp3", "q3": "assets/audio/n/e1-06_q3.mp3", "q4": "assets/audio/n/e1-06_q4.mp3", "s0": "assets/audio/n/e1-06_s0.mp3", "s1": "assets/audio/n/e1-06_s1.mp3", "s2": "assets/audio/n/e1-06_s2.mp3", "s3": "assets/audio/n/e1-06_s3.mp3", "sum": "assets/audio/n/e1-06_sum.mp3", "cover": "assets/audio/n/e1-06_cover.mp3"}, "quiz": [{"q": "🐶 그림에 맞는 낱말은?", "answer": 1, "choices": ["dig", "dog", "bag", "pig"], "explain": "d-o-g, '드-아-그'를 이으면 dog이에요."}, {"q": "c-a-t를 이어 읽으면?", "answer": 2, "choices": ["cut", "cot", "cat", "kit"], "explain": "'크-애-트'를 이으면 cat이에요. 🐱"}, {"q": "cat에서 c를 h로 바꾸면?", "answer": 3, "choices": ["hot", "hut", "hit", "hat"], "explain": "h-a-t, hat이 돼요. 🎩"}, {"q": "☀️ sun의 가운데 모음은?", "answer": 0, "choices": ["u", "a", "o", "i"], "explain": "s-u-n, 가운데는 짧은 '어' 소리 u예요."}, {"q": "pen의 가운데를 a로 바꾸면 어떤 그림일까요?", "answer": 0, "choices": ["🍳 pan", "🐷 pig", "🛏️ bed", "🖊️ pen"], "explain": "p-a-n, pan은 프라이팬이에요."}], "intro": "글자 소리를 알면 낱말을 읽을 수 있어요. 🐱 소리를 이어서 cat을 읽어 봐요.", "summary": ["글자 소리를 하나씩 낸 뒤 이으면 낱말이 돼요.", "가운데 모음 a e i o u는 짧게 소리 내요.", "한 글자만 바꿔도 새 낱말이 돼요."], "keywords": [{"word": "모음", "meaning": "a, e, i, o, u 다섯 글자"}, {"word": "이어 읽기", "meaning": "글자 소리를 하나씩 낸 뒤 이어서 낱말로 읽기"}, {"word": "낱말 가족", "meaning": "끝소리가 같은 낱말들 (cat, hat, bat)"}], "sections": [{"paras": ["글자 소리를 하나씩 내요.", "c, a, t → '크, 애, 트'.", "빨리 이으면 cat! 🐱"], "figure": "아이 손가락이 나무 글자 블록 세 개를 차례로 짚는 모습", "example": "c + a + t = cat · d + o + g = dog", "heading": "소리를 이어 읽어요"}, {"paras": ["a e i o u는 모음이에요.", "세 글자 낱말 가운데에 자주 와요.", "짧게 소리 내요."], "figure": "고양이 인형, 펜, 돼지 인형, 상자, 장난감 버스가 한 줄로 놓인 책상", "example": "a: cat 🐱 hat 🎩 · e: bed 🛏️ pen 🖊️ · i: pig 🐷 six · o: dog 🐶 box 📦 · u: sun ☀️ bus 🚌", "heading": "가운데 모음이 중요해요"}, {"paras": ["cat의 c를 h로 바꾸면?", "hat이 돼요! 🎩", "끝소리가 같은 낱말 가족이에요."], "figure": "고양이 인형 옆에 작은 모자와 매트가 놓인 모습", "example": "cat · hat · bat · mat", "heading": "첫 글자만 바꿔 봐요"}, {"paras": ["가운데 모음을 바꾸면 뜻이 바뀌어요.", "pen의 e를 a로 바꾸면 pan이에요. 🖊️→🍳"], "figure": "책상 위의 펜과 장난감 프라이팬", "example": "pen → pan · pin → pen", "heading": "가운데만 바꿔 봐요"}], "parent_tip": "처음에는 '크-애-트'처럼 천천히 끊어 읽다가 점점 빠르게 이어 붙이도록 도와주세요. 이때 '크'를 길게 '크으'로 늘이면 이어 읽기가 어려워지니 짧게 끊어 주시면 좋습니다. 글자 카드 한 장만 바꿔 cat→hat→bat처럼 새 낱말을 만드는 놀이가 효과적입니다.", "expressions": [{"en": "c, a, t - cat", "ko": "🐱 고양이", "note": "소리를 하나씩 내고 이어 읽어요"}, {"en": "cat", "ko": "🐱 고양이", "note": "가운데 a '애'"}, {"en": "hat", "ko": "🎩 모자", "note": "가운데 a '애'"}, {"en": "bed", "ko": "🛏️ 침대", "note": "가운데 e '에'"}, {"en": "pen", "ko": "🖊️ 펜", "note": "가운데 e '에'"}, {"en": "pig", "ko": "🐷 돼지", "note": "가운데 i '이'"}, {"en": "six", "ko": "6 여섯", "note": "가운데 i '이'"}, {"en": "dog", "ko": "🐶 개", "note": "가운데 o '아'"}, {"en": "box", "ko": "📦 상자", "note": "가운데 o '아'"}, {"en": "sun", "ko": "☀️ 해", "note": "가운데 u '어'"}, {"en": "bus", "ko": "🚌 버스", "note": "가운데 u '어'"}, {"en": "pan", "ko": "🍳 프라이팬", "note": "pen과 가운데만 달라요"}]}$j$::jsonb where slug='e1-06';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-07_kw.mp3", "q0": "assets/audio/n/e1-07_q0.mp3", "q1": "assets/audio/n/e1-07_q1.mp3", "q2": "assets/audio/n/e1-07_q2.mp3", "q3": "assets/audio/n/e1-07_q3.mp3", "q4": "assets/audio/n/e1-07_q4.mp3", "s0": "assets/audio/n/e1-07_s0.mp3", "s1": "assets/audio/n/e1-07_s1.mp3", "s2": "assets/audio/n/e1-07_s2.mp3", "s3": "assets/audio/n/e1-07_s3.mp3", "sum": "assets/audio/n/e1-07_sum.mp3", "cover": "assets/audio/n/e1-07_cover.mp3"}, "quiz": [{"q": "🙋 '나'를 뜻하는 낱말은?", "answer": 1, "choices": ["you", "I", "a", "the"], "explain": "I는 '나'예요. 언제나 대문자로 써요."}, {"q": "👉 '너'를 뜻하는 낱말은?", "answer": 2, "choices": ["I", "the", "you", "a"], "explain": "you는 '너'예요."}, {"q": "🐱 '고양이 한 마리'는?", "answer": 0, "choices": ["a cat", "I cat", "you cat", "cat a"], "explain": "'하나'라는 뜻의 a를 cat 앞에 써요."}, {"q": "바르게 쓴 문장은?", "answer": 3, "choices": ["i see a dog.", "i See a dog.", "see I a dog.", "I see a dog."], "explain": "I는 언제나 대문자로 써요. 문장의 첫 글자도 대문자로 써요. 그래서 'I see a dog.'가 맞아요."}, {"q": "'I see the sun.'의 뜻은?", "answer": 2, "choices": ["너는 해를 봐요.", "나는 달을 봐요.", "나는 해를 봐요.", "나는 해가 좋아요."], "explain": "I 나는, see 봐요, the sun 해."}], "intro": "영어 책을 펴면 자꾸 보이는 낱말이 있어요. 📖 눈으로 보자마자 읽어 봐요.", "summary": ["I는 '나', you는 '너'예요.", "a는 '하나의', the는 '그'예요.", "I는 언제나 대문자로 써요."], "keywords": [{"word": "I", "meaning": "나. 언제나 대문자로 써요."}, {"word": "you", "meaning": "너"}, {"word": "a", "meaning": "하나의 (a cat 고양이 한 마리)"}, {"word": "the", "meaning": "그 (다 아는 것 앞에 써요)"}], "sections": [{"paras": ["책에 같은 낱말이 자꾸 나와요.", "I, you, the, a예요.", "보자마자 바로 읽어요. 👀"], "figure": "펼쳐진 그림책 위에 아이 손가락이 놓인 모습", "example": "I · you · the · a", "heading": "자주 보는 낱말이 있어요"}, {"paras": ["I는 '나'예요. 🙋", "I는 언제나 대문자로 써요.", "you는 '너'예요. 👉"], "figure": "두 아이가 마주 보고 웃는 모습", "example": "I like you. 나는 너를 좋아해.", "heading": "I는 나, you는 너"}, {"paras": ["a는 '하나'라는 뜻이에요.", "a cat은 고양이 한 마리예요. 🐱", "the는 '그'예요. 다 아는 것에 써요."], "figure": "강아지 인형 한 개가 창가 햇빛 아래 놓인 모습", "example": "a dog 🐶 개 한 마리 · the sun ☀️ 해", "heading": "a는 하나, the는 그"}, {"paras": ["I see는 '나는 ~을 봐요'예요.", "뒤의 낱말만 바꿔 읽어요."], "figure": "아이가 쌍안경으로 창밖을 보는 모습", "example": "I see a cat. · I see the sun. · I see you.", "heading": "문장으로 읽어요"}], "parent_tip": "I, you, the, a 같은 낱말은 소리로 풀어 읽기보다 통째로 눈에 익히는 '사이트 워드'입니다. 그림책을 함께 읽으며 이 낱말이 나올 때마다 손가락으로 짚게 해 보세요. a와 the의 차이는 이 단계에서 깊게 설명하지 않고 '하나', '그' 정도로만 알려 주셔도 충분합니다.", "expressions": [{"en": "I", "ko": "나 🙋", "note": "아이. 언제나 대문자"}, {"en": "you", "ko": "너 👉", "note": "유"}, {"en": "the", "ko": "그", "note": "더"}, {"en": "a", "ko": "하나의", "note": "어. 낱말 앞에서 짧게"}, {"en": "a cat", "ko": "🐱 고양이 한 마리"}, {"en": "the sun", "ko": "☀️ 해"}, {"en": "I see a dog.", "ko": "나는 개 한 마리를 봐요. 🐶"}, {"en": "I see the sun.", "ko": "나는 해를 봐요. ☀️"}, {"en": "I see you.", "ko": "나는 너를 봐요. 👀"}, {"en": "I like you.", "ko": "나는 너를 좋아해요. 💛"}, {"en": "you and I", "ko": "너와 나"}]}$j$::jsonb where slug='e1-07';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-08_kw.mp3", "q0": "assets/audio/n/e1-08_q0.mp3", "q1": "assets/audio/n/e1-08_q1.mp3", "q2": "assets/audio/n/e1-08_q2.mp3", "q3": "assets/audio/n/e1-08_q3.mp3", "q4": "assets/audio/n/e1-08_q4.mp3", "s0": "assets/audio/n/e1-08_s0.mp3", "s1": "assets/audio/n/e1-08_s1.mp3", "s2": "assets/audio/n/e1-08_s2.mp3", "s3": "assets/audio/n/e1-08_s3.mp3", "sum": "assets/audio/n/e1-08_sum.mp3", "cover": "assets/audio/n/e1-08_cover.mp3"}, "quiz": [{"q": "🍎🍎🍎 사과는 몇 개? 영어로 고르세요.", "answer": 1, "choices": ["two", "three", "four", "five"], "explain": "사과가 3개예요. 3은 three예요."}, {"q": "ten은 몇일까요?", "answer": 3, "choices": ["1", "6", "8", "10"], "explain": "ten은 10이에요."}, {"q": "5를 영어로 하면?", "answer": 2, "choices": ["four", "nine", "five", "six"], "explain": "5는 five예요."}, {"q": "\"몇 개예요?\"를 영어로 하면?", "answer": 0, "choices": ["How many?", "Hello!", "Thank you.", "Goodbye."], "explain": "개수를 물을 때 How many?라고 해요."}, {"q": "seven 다음 숫자는?", "answer": 3, "choices": ["six", "nine", "ten", "eight"], "explain": "7 다음은 8, eight이에요."}], "intro": "🍎 사과가 몇 개 있을까요? 오늘은 영어로 1부터 10까지 세어 봐요.", "summary": ["1~5는 one, two, three, four, five예요.", "6~10은 six, seven, eight, nine, ten이에요.", "How many?는 \"몇 개예요?\"라는 뜻이에요."], "keywords": [{"word": "one ~ ten", "meaning": "영어로 1부터 10까지의 숫자"}, {"word": "How many?", "meaning": "몇 개예요? 하고 묻는 말"}, {"word": "세기", "meaning": "하나씩 짚으며 몇 개인지 알아보는 것"}], "sections": [{"paras": ["1은 one, 2는 two예요.", "3은 three, 4는 four, 5는 five예요.", "손가락을 하나씩 펴며 말해 봐요. ✋"], "figure": "아이 손가락 다섯 개를 하나씩 펴는 모습", "example": "🍎 one, 🍎🍎 two, 🍎🍎🍎 three, 🍎🍎🍎🍎 four, 🍎🍎🍎🍎🍎 five", "heading": "1부터 5까지 세어요"}, {"paras": ["6은 six, 7은 seven이에요.", "8은 eight, 9는 nine이에요.", "10은 ten이에요. 손가락이 모두 펴졌어요! 🙌"], "figure": "두 손을 활짝 편 아이의 손", "example": "⭐ six, seven, eight, nine, ten!", "heading": "6부터 10까지 세어요"}, {"paras": ["two는 w 소리가 안 나요. [투]라고 읽어요.", "eight도 gh 소리가 안 나요. [에잇]이라고 읽어요."], "figure": "책상 위에 놓인 숫자 블록 장난감", "example": "two [투], eight [에잇]", "heading": "숫자 글자를 살펴봐요"}, {"paras": ["How many?는 \"몇 개예요?\"라는 뜻이에요.", "세어 보고 숫자로 대답해요."], "figure": "강아지 인형 세 개를 손가락으로 세는 아이", "example": "How many? 🐶🐶🐶 → Three!", "heading": "How many? 몇 개예요?"}], "parent_tip": "two와 eight처럼 글자와 소리가 다른 숫자를 아이가 가장 많이 헷갈립니다. 계단을 오르거나 간식을 나눌 때 영어로 함께 세어 보세요. \"How many cookies?\"라고 묻고 숫자로 대답하게 하면 자연스럽게 익힙니다.", "expressions": [{"en": "one", "ko": "1, 하나", "note": "[원]"}, {"en": "two", "ko": "2, 둘", "note": "[투] w는 소리가 안 나요"}, {"en": "three", "ko": "3, 셋", "note": "[쓰리] 혀를 이 사이에 살짝"}, {"en": "four", "ko": "4, 넷", "note": "[포]"}, {"en": "five", "ko": "5, 다섯", "note": "[파이브]"}, {"en": "six", "ko": "6, 여섯", "note": "[식스]"}, {"en": "seven", "ko": "7, 일곱", "note": "[세븐]"}, {"en": "eight", "ko": "8, 여덟", "note": "[에잇] gh는 소리가 안 나요"}, {"en": "nine", "ko": "9, 아홉", "note": "[나인]"}, {"en": "ten", "ko": "10, 열", "note": "[텐]"}, {"en": "How many?", "ko": "몇 개예요?", "note": "개수를 물을 때"}]}$j$::jsonb where slug='e1-08';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-10_kw.mp3", "q0": "assets/audio/n/e1-10_q0.mp3", "q1": "assets/audio/n/e1-10_q1.mp3", "q2": "assets/audio/n/e1-10_q2.mp3", "q3": "assets/audio/n/e1-10_q3.mp3", "q4": "assets/audio/n/e1-10_q4.mp3", "s0": "assets/audio/n/e1-10_s0.mp3", "s1": "assets/audio/n/e1-10_s1.mp3", "s2": "assets/audio/n/e1-10_s2.mp3", "s3": "assets/audio/n/e1-10_s3.mp3", "sum": "assets/audio/n/e1-10_sum.mp3", "cover": "assets/audio/n/e1-10_cover.mp3"}, "quiz": [{"q": "🌅 아침에 선생님을 만났어요. 뭐라고 할까요?", "answer": 1, "choices": ["Good evening!", "Good morning!", "Goodbye!", "See you!"], "explain": "아침 인사는 Good morning!이에요."}, {"q": "친구가 How are you?라고 물었어요. 알맞은 대답은?", "answer": 0, "choices": ["I'm fine, thank you.", "Goodbye!", "Good morning!", "Hello!"], "explain": "안부를 물으면 I'm fine, thank you.라고 대답해요."}, {"q": "👋 집에 갈 때 친구에게 하는 말은?", "answer": 3, "choices": ["Hi!", "Good morning!", "How are you?", "Bye!"], "explain": "헤어질 때는 Bye!라고 해요."}, {"q": "See you!의 뜻은?", "answer": 2, "choices": ["잘 지내?", "고마워.", "또 만나!", "좋은 아침!"], "explain": "See you!는 또 만나자는 인사예요."}, {"q": "🌙 저녁에 만난 이웃에게 하는 인사는?", "answer": 3, "choices": ["Good afternoon!", "Good morning!", "Bye!", "Good evening!"], "explain": "저녁에 만나면 Good evening!이라고 해요."}], "intro": "👋 친구를 만나면 \"안녕!\" 하고 인사하지요? 영어로도 반갑게 인사해 봐요.", "summary": ["만나면 Hello! / Hi!라고 해요.", "How are you?에는 I'm fine, thank you.로 대답해요.", "헤어질 때는 Goodbye! / Bye! / See you!라고 해요."], "keywords": [{"word": "Hello / Hi", "meaning": "만났을 때 하는 인사"}, {"word": "How are you?", "meaning": "잘 지내? 하고 안부를 묻는 말"}, {"word": "Goodbye / Bye", "meaning": "헤어질 때 하는 인사"}], "sections": [{"paras": ["만나면 Hello! 또는 Hi!라고 해요.", "Hi는 친구끼리 쓰는 짧은 인사예요."], "figure": "손을 흔들며 인사하는 두 아이", "example": "👧 Hello! 👦 Hi!", "heading": "만났을 때 인사해요"}, {"paras": ["🌅 아침에는 Good morning!", "☀️ 낮에는 Good afternoon!", "🌙 저녁에는 Good evening!"], "figure": "아침 햇살이 비치는 창가의 식탁", "example": "아침에 선생님께: Good morning!", "heading": "아침, 낮, 저녁 인사"}, {"paras": ["How are you?는 \"잘 지내?\"라는 뜻이에요.", "I'm fine, thank you.로 대답해요.", "기분이 좋으면 I'm good!이라고 해도 돼요."], "figure": "웃으며 이야기하는 엄마와 아이", "example": "👩 How are you? 👦 I'm fine, thank you.", "heading": "안부를 물어요"}, {"paras": ["헤어질 때는 Goodbye! 또는 Bye!라고 해요.", "See you!는 \"또 만나!\"라는 뜻이에요."], "figure": "학교 앞에서 손을 흔들며 헤어지는 아이들", "example": "👋 Bye! See you!", "heading": "헤어질 때 인사해요"}], "parent_tip": "Good night!은 만날 때가 아니라 잠자리에 들거나 밤에 헤어질 때 쓰는 말이라 Good evening!과 헷갈리기 쉽습니다. 아침에 일어나면 \"Good morning!\", 등교할 때 \"Bye! See you!\"처럼 하루 생활 속에서 짧게 주고받아 보세요.", "expressions": [{"en": "Hello!", "ko": "안녕하세요! / 안녕!", "note": "만났을 때"}, {"en": "Hi!", "ko": "안녕!", "note": "친구끼리 짧게"}, {"en": "Good morning!", "ko": "좋은 아침이에요!", "note": "아침 인사"}, {"en": "Good afternoon!", "ko": "안녕하세요! (낮 인사)", "note": "점심 지나서"}, {"en": "Good evening!", "ko": "안녕하세요! (저녁 인사)", "note": "저녁에 만났을 때"}, {"en": "How are you?", "ko": "잘 지내? / 어떻게 지내?", "note": "안부를 물을 때"}, {"en": "I'm fine, thank you.", "ko": "잘 지내, 고마워.", "note": "How are you?에 대답"}, {"en": "I'm good!", "ko": "좋아!", "note": "기분이 좋을 때"}, {"en": "Goodbye!", "ko": "잘 가! / 안녕히 가세요!", "note": "헤어질 때"}, {"en": "Bye!", "ko": "안녕! (헤어질 때)", "note": "짧게"}, {"en": "See you!", "ko": "또 만나!", "note": "헤어질 때"}]}$j$::jsonb where slug='e1-10';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-11_kw.mp3", "q0": "assets/audio/n/e1-11_q0.mp3", "q1": "assets/audio/n/e1-11_q1.mp3", "q2": "assets/audio/n/e1-11_q2.mp3", "q3": "assets/audio/n/e1-11_q3.mp3", "q4": "assets/audio/n/e1-11_q4.mp3", "s0": "assets/audio/n/e1-11_s0.mp3", "s1": "assets/audio/n/e1-11_s1.mp3", "s2": "assets/audio/n/e1-11_s2.mp3", "s3": "assets/audio/n/e1-11_s3.mp3", "sum": "assets/audio/n/e1-11_sum.mp3", "cover": "assets/audio/n/e1-11_cover.mp3"}, "quiz": [{"q": "👨 아빠를 소개할 때 알맞은 말은?", "answer": 1, "choices": ["This is my mom.", "This is my dad.", "This is my friend.", "Nice to meet you."], "explain": "아빠는 dad예요. This is my dad.라고 해요."}, {"q": "my의 뜻은?", "answer": 0, "choices": ["나의", "너의", "이것", "친구"], "explain": "my는 \"나의\"라는 뜻이에요."}, {"q": "처음 만난 친구에게 하는 말은?", "answer": 3, "choices": ["Goodbye!", "This is my dad.", "How many?", "Nice to meet you."], "explain": "처음 만나면 Nice to meet you.라고 해요."}, {"q": "Nice to meet you.에 알맞은 대답은?", "answer": 2, "choices": ["I'm fine.", "Bye!", "Nice to meet you, too.", "This is my mom."], "explain": "\"나도 반가워\"는 Nice to meet you, too.예요."}, {"q": "👦 남자 형제를 소개해요. This is my ____.", "answer": 2, "choices": ["sister", "mom", "brother", "friend"], "explain": "남자 형제는 brother예요."}], "intro": "👩 친구에게 우리 엄마를 소개하고 싶어요. 영어로는 어떻게 말할까요?", "summary": ["This is ~로 사람을 소개해요.", "my는 \"나의\": my mom, my dad, my friend.", "소개받으면 Nice to meet you.라고 해요."], "keywords": [{"word": "This is ~", "meaning": "이 사람은(이것은) ~야, 하고 소개하는 말"}, {"word": "my", "meaning": "나의"}, {"word": "Nice to meet you.", "meaning": "만나서 반가워."}], "sections": [{"paras": ["가까이 있는 사람을 소개할 때 This is ~라고 해요.", "This is 다음에 소개할 사람을 말해요."], "figure": "아이가 엄마 옆에 서서 친구에게 손으로 가리키는 모습", "example": "This is my mom. (이분은 우리 엄마야.)", "heading": "This is ~는 \"이 사람은 ~야\""}, {"paras": ["my는 \"나의\"라는 뜻이에요.", "👨 my dad, 👩 my mom이에요.", "👧 my sister, 👦 my brother도 있어요."], "figure": "가족사진 액자가 놓인 책상", "example": "This is my dad. This is my sister.", "heading": "가족을 소개해요"}, {"paras": ["친구는 friend예요.", "이름을 넣어서 소개할 수도 있어요."], "figure": "나란히 서서 웃는 두 친구", "example": "This is my friend, Mina. (얘는 내 친구 미나야.)", "heading": "친구를 소개해요"}, {"paras": ["Nice to meet you.는 \"만나서 반가워.\"예요.", "상대도 Nice to meet you, too.라고 대답해요."], "figure": "악수하는 두 아이의 손", "example": "👧 Nice to meet you. 👦 Nice to meet you, too.", "heading": "소개받으면 이렇게 말해요"}], "parent_tip": "영어는 형·오빠·남동생을 모두 brother, 언니·누나·여동생을 모두 sister라고 해서 아이가 신기해합니다. 인형이나 가족사진을 가리키며 \"This is my ~.\"로 소개 놀이를 해 보세요. 소개를 받으면 \"Nice to meet you.\"라고 답하도록 역할을 바꿔 주면 좋습니다.", "expressions": [{"en": "This is my mom.", "ko": "이분은 우리 엄마야.", "note": "가족 소개"}, {"en": "This is my dad.", "ko": "이분은 우리 아빠야."}, {"en": "This is my sister.", "ko": "이 사람은 우리 언니(누나, 여동생)야.", "note": "sister는 여자 형제"}, {"en": "This is my brother.", "ko": "이 사람은 우리 오빠(형, 남동생)야.", "note": "brother는 남자 형제"}, {"en": "This is my friend.", "ko": "얘는 내 친구야."}, {"en": "This is my friend, Mina.", "ko": "얘는 내 친구 미나야.", "note": "이름을 넣어 소개"}, {"en": "Nice to meet you.", "ko": "만나서 반가워.", "note": "처음 만났을 때"}, {"en": "Nice to meet you, too.", "ko": "나도 만나서 반가워.", "note": "대답할 때"}, {"en": "mom", "ko": "엄마", "note": "[맘]"}, {"en": "dad", "ko": "아빠", "note": "[대드]"}]}$j$::jsonb where slug='e1-11';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/e1-13_kw.mp3", "q0": "assets/audio/n/e1-13_q0.mp3", "q1": "assets/audio/n/e1-13_q1.mp3", "q2": "assets/audio/n/e1-13_q2.mp3", "q3": "assets/audio/n/e1-13_q3.mp3", "q4": "assets/audio/n/e1-13_q4.mp3", "s0": "assets/audio/n/e1-13_s0.mp3", "s1": "assets/audio/n/e1-13_s1.mp3", "s2": "assets/audio/n/e1-13_s2.mp3", "s3": "assets/audio/n/e1-13_s3.mp3", "sum": "assets/audio/n/e1-13_sum.mp3", "cover": "assets/audio/n/e1-13_cover.mp3"}, "quiz": [{"q": "🚻 화장실에 가고 싶어요. 선생님께 뭐라고 할까요?", "answer": 1, "choices": ["Can I sit here?", "Can I go to the bathroom?", "I like the bathroom.", "Goodbye!"], "explain": "화장실은 bathroom이에요. Can I go to the bathroom?이라고 물어요."}, {"q": "Can I sit here?의 뜻은?", "answer": 0, "choices": ["여기 앉아도 돼요?", "나가도 돼요?", "물 마셔도 돼요?", "여기 있어요."], "explain": "sit은 앉다, here는 여기예요."}, {"q": "허락할 때 하는 대답은?", "answer": 3, "choices": ["Sorry, you can't.", "No, I don't.", "Bye!", "Sure!"], "explain": "Sure!는 \"그럼, 물론이지!\"라는 허락의 말이에요."}, {"q": "더 공손하게 부탁할 때 붙이는 말은?", "answer": 0, "choices": ["please", "sorry", "hello", "bye"], "explain": "please를 붙이면 공손한 부탁이 돼요."}, {"q": "🍪 엄마가 쿠키를 먹어도 된다고 했어요. 내가 할 말은?", "answer": 2, "choices": ["Sorry.", "Can I?", "Thank you!", "Hello!"], "explain": "부탁을 들어주면 Thank you!라고 해요."}], "intro": "💧 목이 말라요. 물을 마셔도 되는지 영어로 물어볼까요?", "summary": ["Can I ~?는 \"~해도 돼요?\"예요.", "허락은 Sure! / Yes, you can., 거절은 Sorry, you can't.", "please를 붙이고, 들어주면 Thank you!"], "keywords": [{"word": "Can I ~?", "meaning": "~해도 돼요? 하고 허락을 구하는 말"}, {"word": "Sure!", "meaning": "그럼! 물론이지!"}, {"word": "please", "meaning": "부탁할 때 붙이는 공손한 말"}], "sections": [{"paras": ["무엇을 해도 되는지 물을 때 Can I ~?라고 해요.", "Can I 다음에 하고 싶은 일을 말해요."], "figure": "문 앞에서 엄마를 바라보는 아이", "example": "Can I go out? (나가도 돼요?)", "heading": "Can I ~?는 \"~해도 돼요?\""}, {"paras": ["🚻 Can I go to the bathroom? 화장실 가도 돼요?", "🪑 Can I sit here? 여기 앉아도 돼요?", "🍪 Can I have a cookie? 쿠키 먹어도 돼요?"], "figure": "책상 위의 물컵과 쿠키 한 개", "example": "Can I have some water? (물 좀 마셔도 돼요?)", "heading": "이럴 때 써요"}, {"paras": ["괜찮으면 Sure! 또는 Yes, you can.이라고 해요.", "안 되면 Sorry, you can't.라고 해요."], "figure": "고개를 끄덕이며 웃는 선생님", "example": "Can I sit here? → Sure! 😊", "heading": "대답하는 방법"}, {"paras": ["끝에 please를 붙이면 더 공손해요.", "들어주면 Thank you!라고 말해요."], "figure": "물컵을 건네받는 아이 손", "example": "Can I have some water, please? → Sure! → Thank you!", "heading": "예쁘게 부탁해요"}], "parent_tip": "Can I ~?는 3학년부터 배우는 학교 영어와 실제 생활에서 가장 많이 쓰는 표현 중 하나입니다. 간식이나 TV 시간처럼 아이가 무언가를 원할 때 \"Can I ~, please?\"로 부탁하게 하고 Sure! / Sorry, you can't.로 답해 주세요. 허락을 받으면 Thank you!까지 말하도록 이끌어 주시면 좋습니다.", "expressions": [{"en": "Can I go out?", "ko": "나가도 돼요?"}, {"en": "Can I go to the bathroom?", "ko": "화장실에 가도 돼요?"}, {"en": "Can I sit here?", "ko": "여기 앉아도 돼요?"}, {"en": "Can I have a cookie?", "ko": "쿠키 하나 먹어도 돼요?"}, {"en": "Can I have some water, please?", "ko": "물 좀 마셔도 될까요?", "note": "please로 공손하게"}, {"en": "Sure!", "ko": "그럼! / 물론이지!", "note": "허락할 때"}, {"en": "Yes, you can.", "ko": "응, 해도 돼.", "note": "허락할 때"}, {"en": "Sorry, you can't.", "ko": "미안, 안 돼.", "note": "안 될 때"}, {"en": "please", "ko": "부탁해요(공손하게)", "note": "[플리즈]"}, {"en": "Thank you!", "ko": "고맙습니다!", "note": "들어주었을 때"}]}$j$::jsonb where slug='e1-13';
update public.lessons set content=$j${"quiz": [{"q": "물건값을 물어볼 때 쓰는 말은?", "answer": 1, "choices": ["How are you?", "How much is it?", "What's this?", "Can I help you?"], "explain": "How much is it?은 '얼마예요?'라는 뜻이에요."}, {"q": "\"Can I help you?\"에 알맞은 대답은?", "answer": 0, "choices": ["I want an eraser.", "It's sunny.", "I'm ten years old.", "Goodbye."], "explain": "도와 드릴까 묻는 말에는 사고 싶은 물건을 I want ~.로 말해요."}, {"q": "물건을 건네주면서 하는 말은?", "answer": 1, "choices": ["You're welcome.", "Here you are.", "How much?", "Nice to meet you."], "explain": "Here you are.는 '여기 있어요'라는 뜻으로 물건을 건넬 때 써요."}, {"q": "\"It's 1,000 won.\"의 뜻은?", "answer": 2, "choices": ["100원이에요.", "10원이에요.", "1,000원이에요.", "10,000원이에요."], "explain": "one thousand(1,000)이니까 1,000원이에요."}, {"q": "\"Thank you.\"에 대한 대답으로 알맞은 것은?", "answer": 3, "choices": ["Here you are.", "I want a ball.", "How much is it?", "You're welcome."], "explain": "고맙다는 말에는 You're welcome.(천만에요.)로 대답해요."}], "intro": "문구점에서 연필을 사고 싶을 때, 영어로는 어떻게 말할까요? 가게 놀이를 하듯 같이 배워 봐요.", "summary": ["점원은 Can I help you?로 묻고, 손님은 I want ~.로 사고 싶은 것을 말해요.", "값은 How much is it?으로 묻고 It's ~ won.으로 대답해요.", "물건을 건넬 때는 Here you are., 고마울 땐 Thank you.라고 해요."], "keywords": [{"word": "want", "meaning": "원하다, 갖고 싶다"}, {"word": "How much", "meaning": "얼마"}, {"word": "won", "meaning": "우리나라 돈 단위 '원'"}, {"word": "Here you are.", "meaning": "물건을 건넬 때 하는 말 '여기 있어요'"}], "sections": [{"paras": ["가게에 들어가면 점원이 \"Can I help you?(도와 드릴까요?)\"라고 물어요.", "사고 싶은 물건이 있으면 \"I want a pencil.(연필을 사고 싶어요.)\"처럼 I want 뒤에 물건 이름을 붙여요."], "figure": "문구점 계산대 앞에서 아이가 연필을 가리키고 점원이 웃는 그림", "example": "Can I help you? - I want a pencil.", "heading": "갖고 싶은 물건 말하기"}, {"paras": ["물건값이 궁금하면 \"How much is it?(그것은 얼마예요?)\"라고 물어요.", "점원은 \"It's 500 won.(500원이에요.)\"처럼 It's 뒤에 값을 말해 줘요. 100은 one hundred, 500은 five hundred, 1,000은 one thousand라고 읽어요."], "figure": "가격표에 1,000 won이라고 적힌 공책 그림", "example": "How much is it? - It's 1,000 won.", "heading": "값 물어보기"}, {"paras": ["물건을 건넬 때는 \"Here you are.(여기 있어요.)\"라고 말해요.", "받은 사람은 \"Thank you.(고마워요.)\"라고 하고, 상대는 \"You're welcome.(천만에요.)\"라고 대답해요."], "figure": "점원이 공책을 건네고 아이가 돈을 내는 모습", "example": "Here you are. - Thank you. - You're welcome.", "heading": "물건 주고받으며 인사하기"}], "parent_tip": "부모님께: 집에 있는 물건에 가격표를 붙여 가게 놀이를 해 보시면 표현이 금방 익숙해집니다. 아이들은 100(one hundred)과 1,000(one thousand)을 헷갈리기 쉬우니 숫자를 바꿔 가며 물어봐 주세요. 아이가 점원 역할도 해 보게 하면 묻는 말과 대답을 모두 연습할 수 있습니다.", "expressions": [{"en": "Can I help you?", "ko": "도와 드릴까요?", "note": "점원이 손님에게"}, {"en": "I want a pencil.", "ko": "연필을 사고 싶어요.", "note": "갖고 싶은 물건 말하기"}, {"en": "How much is it?", "ko": "그것은 얼마예요?", "note": "값을 물을 때"}, {"en": "It's 500 won.", "ko": "500원이에요.", "note": "값을 알려 줄 때"}, {"en": "Here you are.", "ko": "여기 있어요.", "note": "물건이나 돈을 건넬 때"}, {"en": "Thank you.", "ko": "고마워요."}, {"en": "You're welcome.", "ko": "천만에요.", "note": "고맙다는 말에 대답할 때"}]}$j$::jsonb where slug='e3-02';
update public.lessons set content=$j${"quiz": [{"q": "날씨를 물을 때 쓰는 말은?", "answer": 1, "choices": ["How old are you?", "How's the weather?", "How much is it?", "What's this?"], "explain": "weather는 날씨예요. How's the weather?로 날씨를 물어요."}, {"q": "비가 내리는 그림에 알맞은 말은?", "answer": 2, "choices": ["It's sunny.", "It's snowy.", "It's rainy.", "It's hot."], "explain": "비가 오는 날씨는 rainy예요."}, {"q": "\"It's windy.\"의 뜻은?", "answer": 0, "choices": ["바람이 불어.", "눈이 와.", "더워.", "맑아."], "explain": "windy는 바람이 부는 날씨예요."}, {"q": "눈사람을 만드는 날의 날씨로 알맞은 것은?", "answer": 3, "choices": ["It's hot.", "It's sunny and hot.", "It's rainy.", "It's snowy and cold."], "explain": "눈사람은 눈이 오고 추운 날 만들어요. snowy and cold가 알맞아요."}, {"q": "\"It's rainy.\"라고 들었을 때 이어서 할 말로 알맞은 것은?", "answer": 0, "choices": ["Take your umbrella.", "Wear your sunglasses.", "Let's make a snowman.", "Nice to meet you."], "explain": "비가 오니 우산(umbrella)을 챙기라고 말해요."}], "intro": "아침에 창밖을 보며 \"오늘은 비가 오네!\" 하고 말하죠? 영어로도 날씨를 묻고 답할 수 있어요.", "summary": ["날씨는 How's the weather?로 물어요.", "대답은 It's 뒤에 sunny, rainy, cloudy, snowy, windy를 붙여요.", "더우면 It's hot., 추우면 It's cold.라고 해요."], "keywords": [{"word": "weather", "meaning": "날씨"}, {"word": "sunny", "meaning": "해가 쨍쨍한, 맑은"}, {"word": "rainy", "meaning": "비가 오는"}, {"word": "cloudy", "meaning": "구름이 낀, 흐린"}, {"word": "snowy", "meaning": "눈이 오는"}, {"word": "windy", "meaning": "바람이 부는"}], "sections": [{"paras": ["날씨가 궁금할 때는 \"How's the weather?(날씨가 어때?)\"라고 물어요.", "How's는 How is를 줄인 말이고, weather는 '날씨'라는 뜻이에요."], "figure": "창문 밖을 바라보며 날씨를 궁금해하는 아이 그림", "example": "How's the weather today? (오늘 날씨 어때?)", "heading": "날씨를 묻는 말"}, {"paras": ["대답할 때는 It's 뒤에 날씨를 나타내는 말을 붙여요. 이때 It은 '그것'이라는 뜻이 아니라 날씨를 말할 때 쓰는 말이에요.", "맑으면 sunny, 비가 오면 rainy, 흐리면 cloudy, 눈이 오면 snowy, 바람이 불면 windy예요."], "figure": "해, 비구름, 회색 구름, 눈송이, 바람 그림 아래 sunny, rainy, cloudy, snowy, windy 낱말 카드", "example": "It's sunny. / It's rainy. / It's snowy.", "heading": "It's + 날씨로 대답해요"}, {"paras": ["기온을 말할 때도 It's를 써요. 더우면 hot, 추우면 cold, 따뜻하면 warm이에요.", "날씨에 맞게 \"Take your umbrella.(우산 가져가.)\"처럼 챙길 물건을 말해 줄 수도 있어요."], "figure": "추운 날 외투와 목도리를 한 아이와 더운 날 반팔 입은 아이를 나란히 그린 그림", "example": "It's cold. Wear your coat. (추워. 외투 입어.)", "heading": "덥고 추운 것도 말해요"}], "parent_tip": "부모님께: 아이들은 rain(비)과 rainy(비가 오는)처럼 -y가 붙는 차이를 자주 헷갈립니다. \"비·눈·해·구름·바람(rain, snow, sun, cloud, wind)으로 날씨를 말할 땐 It's 다음에 y가 붙은 말(rainy, snowy...)을 써요. 단, sun은 n을 하나 더 붙여 sunny라고 써요. hot, cold, warm은 그대로 써요.\"라고 짚어 주세요. 매일 아침 창밖을 보며 \"How's the weather?\"라고 묻는 습관을 들이면 가장 자연스럽게 익힐 수 있습니다.", "expressions": [{"en": "How's the weather?", "ko": "날씨가 어때?", "note": "날씨를 물을 때"}, {"en": "It's sunny.", "ko": "날씨가 맑아."}, {"en": "It's rainy.", "ko": "비가 와."}, {"en": "It's cloudy.", "ko": "흐려."}, {"en": "It's snowy.", "ko": "눈이 와."}, {"en": "It's hot.", "ko": "더워."}, {"en": "It's cold.", "ko": "추워."}, {"en": "Take your umbrella.", "ko": "우산 가져가.", "note": "비 오는 날 챙겨 줄 때"}]}$j$::jsonb where slug='e3-04';
update public.lessons set content=$j${"quiz": [{"q": "바나나는 무슨 색일까요?", "answer": 1, "choices": ["It's purple.", "It's yellow.", "It's black.", "It's blue."], "explain": "바나나는 노란색, yellow예요."}, {"q": "숫자 12를 영어로 하면?", "answer": 0, "choices": ["twelve", "twenty", "two", "eleven"], "explain": "12는 twelve예요. twenty는 20, eleven은 11이에요."}, {"q": "개수를 물을 때 쓰는 말은?", "answer": 2, "choices": ["What color is it?", "How are you?", "How many pencils?", "Who is she?"], "explain": "How many ~?는 '몇 개야?'라는 뜻이에요."}, {"q": "사과가 네 개 있어요. 알맞은 말은?", "answer": 3, "choices": ["Four apple.", "Five apples.", "Fourteen apples.", "Four apples."], "explain": "4는 four이고, 둘 이상이니 apples로 써요."}, {"q": "\"It's green.\"에 어울리는 것은?", "answer": 0, "choices": ["나뭇잎", "눈", "까마귀", "딸기"], "explain": "green은 초록색이에요. 나뭇잎이 초록색이에요."}], "intro": "크레파스 상자에는 여러 가지 색이 있고, 사탕 봉지에는 사탕이 여러 개 있죠? 색깔과 수를 영어로 말해 봐요.", "summary": ["색깔은 What color is it?으로 묻고 It's ~.로 대답해요.", "13부터 19까지는 숫자 뒤에 -teen이 붙어요.", "개수는 How many ~?로 묻고, 둘 이상이면 낱말 끝에 s를 붙여요."], "keywords": [{"word": "color", "meaning": "색깔"}, {"word": "red / blue / yellow", "meaning": "빨강 / 파랑 / 노랑"}, {"word": "How many", "meaning": "몇 개"}, {"word": "-teen", "meaning": "13~19를 나타내는 숫자 뒤에 붙는 말"}, {"word": "-s", "meaning": "둘 이상일 때 낱말 끝에 붙는 말"}], "sections": [{"paras": ["빨강은 red, 노랑은 yellow, 파랑은 blue, 초록은 green이에요.", "주황은 orange, 보라는 purple, 분홍은 pink, 검정은 black, 하양은 white예요."], "figure": "크레파스 상자 속 색마다 영어 이름이 적힌 그림", "example": "The apple is red. (사과는 빨간색이야.)", "heading": "여러 가지 색깔"}, {"paras": ["색깔을 물을 때는 \"What color is it?(그것은 무슨 색이야?)\"라고 해요.", "대답은 \"It's blue.(파란색이야.)\"처럼 It's 뒤에 색깔을 붙여요."], "figure": "노란 바나나를 들고 색을 묻는 두 친구", "example": "What color is it? - It's yellow.", "heading": "색깔을 묻고 답하기"}, {"paras": ["one(1), two(2), three(3), four(4), five(5), six(6), seven(7), eight(8), nine(9), ten(10)이에요.", "11은 eleven, 12는 twelve, 13부터 19까지는 thirteen, fourteen처럼 뒤에 -teen이 붙어요. 13은 thirteen, 15는 fifteen, 18은 eighteen으로 철자가 조금 달라지니 조심해요. 20은 twenty예요."], "figure": "1부터 20까지 숫자 카드가 줄지어 있는 그림", "example": "eleven(11), twelve(12), thirteen(13) … nineteen(19), twenty(20)", "heading": "1부터 20까지 세기"}, {"paras": ["개수를 물을 때는 \"How many apples?(사과가 몇 개야?)\"라고 해요. 둘 이상일 때는 apples처럼 낱말 끝에 s를 붙여요.", "대답은 \"Three apples.(사과 세 개.)\"처럼 숫자를 먼저 말해요."], "figure": "바구니 속 사과 세 개를 손가락으로 세는 아이", "example": "How many balls? - Five balls.", "heading": "몇 개인지 묻고 답하기"}], "parent_tip": "부모님께: thirteen(13)과 thirty(30), fourteen(14)과 forty(40)는 소리가 비슷해 헷갈리기 쉽습니다. 간식을 줄 때 \"How many?\"라고 묻고 아이가 영어로 세게 해 보세요. 색깔은 옷을 고를 때 \"What color is it?\"으로 매일 연습할 수 있습니다.", "expressions": [{"en": "What color is it?", "ko": "그것은 무슨 색이야?", "note": "색깔을 물을 때"}, {"en": "It's red.", "ko": "빨간색이야."}, {"en": "How many apples?", "ko": "사과가 몇 개야?", "note": "개수를 물을 때"}, {"en": "Three apples.", "ko": "사과 세 개."}, {"en": "I like blue.", "ko": "나는 파란색이 좋아."}, {"en": "Let's count!", "ko": "같이 세어 보자!"}]}$j$::jsonb where slug='e3-05';
update public.lessons set content=$j${"quiz": [{"q": "'나는 슬퍼.'를 영어로 하면?", "answer": 1, "choices": ["I'm happy.", "I'm sad.", "I'm hungry.", "I'm angry."], "explain": "sad는 '슬픈'이에요."}, {"q": "점심 먹기 전 배가 꼬르륵거릴 때 알맞은 말은?", "answer": 2, "choices": ["I'm sleepy.", "I'm angry.", "I'm hungry.", "I'm happy."], "explain": "배가 고플 때는 hungry를 써요."}, {"q": "\"Are you tired?\"에 '아니'라고 대답할 때 알맞은 말은?", "answer": 0, "choices": ["No, I'm not.", "Yes, I am.", "No, you are.", "I'm tired."], "explain": "아니라고 할 때는 No, I'm not.이라고 해요."}, {"q": "\"I'm very happy.\"의 뜻은?", "answer": 3, "choices": ["나는 조금 슬퍼.", "나는 배고파.", "너는 기뻐.", "나는 정말 기뻐."], "explain": "very는 '정말, 매우'라는 뜻이에요."}, {"q": "친구가 울고 있을 때 건넬 말로 알맞은 것은?", "answer": 1, "choices": ["Nice to meet you.", "What's wrong?", "How much is it?", "It's sunny."], "explain": "What's wrong?은 '무슨 일 있어?'라는 뜻이에요."}], "intro": "시험을 잘 봐서 기쁠 때도, 친구와 다퉈서 속상할 때도 있죠? 내 기분을 영어로 말해 봐요.", "summary": ["기분이나 몸 상태를 나타내는 말에는 happy, sad, angry, tired, hungry 등이 있어요.", "내 기분은 I'm + 기분으로 말해요.", "친구에게는 Are you ~?로 묻고 Yes, I am. / No, I'm not.으로 대답해요."], "keywords": [{"word": "happy", "meaning": "기쁜, 행복한"}, {"word": "sad", "meaning": "슬픈"}, {"word": "angry", "meaning": "화난"}, {"word": "tired", "meaning": "피곤한"}, {"word": "hungry", "meaning": "배고픈"}], "sections": [{"paras": ["기쁘면 happy, 슬프면 sad, 화가 나면 angry, 피곤하면 tired예요.", "배가 고프면 hungry, 졸리면 sleepy라고 해요. 기분이나 몸 상태를 나타내는 말이에요."], "figure": "웃는 얼굴, 우는 얼굴, 화난 얼굴, 하품하는 얼굴 그림 아래 영어 낱말", "example": "happy(기쁜), sad(슬픈), angry(화난), tired(피곤한)", "heading": "기분을 나타내는 말"}, {"paras": ["내 기분을 말할 때는 \"I'm happy.(나는 기뻐.)\"처럼 I'm 뒤에 기분을 나타내는 말을 붙여요. I'm은 I am을 줄인 말이에요.", "기분을 더 크게 말하고 싶으면 very를 넣어요. \"I'm very happy.(나는 정말 기뻐.)\""], "figure": "아이가 'I'm happy!'라고 말풍선을 띄우는 그림", "example": "I'm sad. / I'm very hungry.", "heading": "I'm + 기분 으로 말해요"}, {"paras": ["친구의 기분이 궁금하면 \"Are you happy?(너 기분 좋아?)\"라고 물을 수 있어요.", "맞으면 \"Yes, I am.\", 아니면 \"No, I'm not.\"이라고 대답해요. 슬퍼 보이는 친구에게는 \"What's wrong?(무슨 일 있어?)\"이라고 물어봐 줘요."], "figure": "축 처진 친구에게 다가가 말을 거는 아이", "example": "Are you tired? - Yes, I am. / No, I'm not.", "heading": "친구의 기분 묻기"}], "parent_tip": "부모님께: 아이들은 \"I happy.\"처럼 am을 빼먹는 실수를 자주 합니다. \"I'm은 꼭 붙어 다녀요\"라고 짚어 주세요. 하루를 마무리할 때 \"How do you feel today?\"라고 묻고 아이가 영어로 기분을 말하게 하면 감정 표현 연습에도 좋습니다.", "expressions": [{"en": "I'm happy.", "ko": "나는 기뻐."}, {"en": "I'm sad.", "ko": "나는 슬퍼."}, {"en": "I'm hungry.", "ko": "나는 배고파."}, {"en": "Are you tired?", "ko": "너 피곤하니?", "note": "친구의 기분이나 상태를 물을 때"}, {"en": "Yes, I am.", "ko": "응, 그래."}, {"en": "No, I'm not.", "ko": "아니, 그렇지 않아."}, {"en": "What's wrong?", "ko": "무슨 일 있어?", "note": "속상해 보이는 친구에게"}]}$j$::jsonb where slug='e3-07';
update public.lessons set content=$j${"quiz": [{"q": "'나는 고양이를 좋아해.'를 영어로 하면?", "answer": 0, "choices": ["I like cats.", "I don't like cats.", "Do you like cats?", "I'm a cat."], "explain": "좋아할 때는 I like ~.로 말해요."}, {"q": "\"Do you like soccer?\"에 '응'이라고 대답할 때는?", "answer": 2, "choices": ["No, I don't.", "Yes, I am.", "Yes, I do.", "I like."], "explain": "Do you ~?로 물으면 Yes, I do.로 대답해요."}, {"q": "\"I don't like milk.\"의 뜻은?", "answer": 3, "choices": ["나는 우유를 좋아해.", "너는 우유를 좋아하니?", "우유가 몇 개야?", "나는 우유를 좋아하지 않아."], "explain": "don't like는 '좋아하지 않다'예요."}, {"q": "친구가 무엇을 좋아하는지 물을 때 알맞은 말은?", "answer": 1, "choices": ["What's your name?", "What do you like?", "How are you?", "What color is it?"], "explain": "What do you like?는 '너는 무엇을 좋아해?'라는 뜻이에요."}, {"q": "\"My favorite fruit is grapes.\"에서 favorite의 뜻은?", "answer": 0, "choices": ["가장 좋아하는", "싫어하는", "맛있는", "작은"], "explain": "favorite은 '가장 좋아하는'이라는 뜻이에요."}], "intro": "좋아하는 과일, 좋아하는 운동, 좋아하는 동물이 있나요? 영어로 좋아하는 것을 말하고 친구에게도 물어봐요.", "summary": ["좋아하는 것은 I like ~., 싫어하는 것은 I don't like ~.로 말해요.", "친구에게는 Do you like ~?로 물어요.", "대답은 Yes, I do. 또는 No, I don't.로 해요."], "keywords": [{"word": "like", "meaning": "좋아하다"}, {"word": "don't", "meaning": "~하지 않다(do not의 줄임말)"}, {"word": "Do you ~?", "meaning": "너는 ~하니? 하고 묻는 말"}, {"word": "favorite", "meaning": "가장 좋아하는"}], "sections": [{"paras": ["좋아하는 것을 말할 때는 \"I like apples.(나는 사과를 좋아해.)\"처럼 I like 뒤에 좋아하는 것을 붙여요.", "과일이나 동물처럼 셀 수 있는 것은 보통 apples, dogs처럼 s를 붙여서 말해요."], "figure": "아이가 사과와 축구공을 안고 웃는 그림", "example": "I like bananas. / I like soccer.", "heading": "I like ~ 로 좋아하는 것 말하기"}, {"paras": ["좋아하지 않을 때는 \"I don't like carrots.(나는 당근을 좋아하지 않아.)\"라고 해요.", "don't는 do not을 줄인 말로 '~하지 않다'라는 뜻이에요."], "figure": "당근 앞에서 고개를 젓는 아이", "example": "I don't like snakes. (나는 뱀을 좋아하지 않아.)", "heading": "싫어하는 것 말하기"}, {"paras": ["\"Do you like pizza?(너 피자 좋아해?)\"처럼 Do you like로 물어요.", "좋아하면 \"Yes, I do.\", 좋아하지 않으면 \"No, I don't.\"라고 대답해요. 무엇을 좋아하는지 물을 때는 \"What do you like?\"라고 해요."], "figure": "두 친구가 피자를 사이에 두고 이야기하는 장면", "example": "Do you like cats? - Yes, I do. / No, I don't.", "heading": "친구에게 묻고 답하기"}], "parent_tip": "부모님께: \"Do you like ~?\"에 \"Yes, I am.\"이라고 잘못 대답하는 경우가 많습니다. Are you로 물으면 am, Do you로 물으면 do로 대답한다고 묶어서 알려 주세요. 식사 시간에 반찬을 가리키며 \"Do you like it?\"이라고 물어보면 자연스럽게 연습할 수 있습니다.", "expressions": [{"en": "I like apples.", "ko": "나는 사과를 좋아해."}, {"en": "I don't like carrots.", "ko": "나는 당근을 좋아하지 않아."}, {"en": "Do you like pizza?", "ko": "너 피자 좋아해?", "note": "친구에게 물을 때"}, {"en": "Yes, I do.", "ko": "응, 좋아해."}, {"en": "No, I don't.", "ko": "아니, 좋아하지 않아."}, {"en": "What do you like?", "ko": "너는 무엇을 좋아해?"}, {"en": "My favorite color is blue.", "ko": "내가 가장 좋아하는 색은 파란색이야."}]}$j$::jsonb where slug='e3-08';
update public.lessons set content=$j${"quiz": [{"q": "play의 과거형은?", "answer": 1, "choices": ["playing", "played", "plays", "plaied"], "explain": "play 뒤에 -ed를 붙여 played가 돼요."}, {"q": "go의 과거형은?", "answer": 2, "choices": ["goed", "gone", "went", "going"], "explain": "go는 모양이 완전히 바뀌어 went가 돼요."}, {"q": "\"What did you do yesterday?\"에 알맞은 대답은?", "answer": 0, "choices": ["I went to the zoo.", "I go to the zoo.", "I'm going to the zoo.", "It's sunny."], "explain": "어제 한 일을 물었으니 과거형 went를 써서 대답해요."}, {"q": "\"I ate ice cream.\"의 뜻은?", "answer": 3, "choices": ["나는 아이스크림을 먹을 거야.", "나는 아이스크림을 좋아해.", "나는 아이스크림을 먹고 있어.", "나는 아이스크림을 먹었어."], "explain": "ate는 eat(먹다)의 과거형이에요."}, {"q": "빈칸에 알맞은 말은? I ___ a movie last weekend.", "answer": 1, "choices": ["watch", "watched", "watches", "watching"], "explain": "last weekend(지난 주말)는 지난 일이니 과거형 watched를 써요."}], "intro": "주말에 무엇을 했는지 친구에게 이야기하고 싶을 때가 있죠? 이미 지나간 일은 영어로 조금 다르게 말해요.", "summary": ["지나간 일은 동사의 과거형으로 말해요. 대부분 -ed를 붙여요.", "go-went, eat-ate, see-saw처럼 모양이 바뀌는 동사도 있어요.", "지난 일은 What did you do ~?로 묻고 과거형으로 대답해요."], "keywords": [{"word": "과거형", "meaning": "이미 지나간 일을 나타내는 동사 모양"}, {"word": "-ed", "meaning": "과거형을 만들 때 동사 뒤에 붙이는 말"}, {"word": "yesterday", "meaning": "어제"}, {"word": "last weekend", "meaning": "지난 주말"}, {"word": "did", "meaning": "지난 일을 물을 때 쓰는 말"}], "sections": [{"paras": ["어제나 지난주처럼 이미 지나간 일을 말할 때는 동사의 모양을 바꿔요. 이것을 과거형이라고 해요.", "대부분은 동사 뒤에 -ed를 붙여요. play → played, watch → watched, visit → visited처럼요."], "figure": "달력에서 어제 날짜에 축구공 스티커가 붙어 있는 그림", "example": "I played soccer yesterday. (나는 어제 축구를 했어.)", "heading": "지난 일은 동사 모양이 바뀌어요"}, {"paras": ["어떤 동사는 -ed를 붙이지 않고 모양이 완전히 바뀌어요. go → went, eat → ate, see → saw, have → had, make → made예요.", "이런 동사는 자주 쓰니까 짝을 지어 외워 두면 좋아요."], "figure": "go-went, eat-ate, see-saw 짝꿍 카드 그림", "example": "I went to the beach. I ate ice cream.", "heading": "모양이 특별하게 바뀌는 동사"}, {"paras": ["\"What did you do yesterday?(너는 어제 무엇을 했니?)\"라고 물어요. did는 지난 일을 물을 때 쓰는 말이에요.", "대답은 과거형을 써서 \"I visited my grandma.(나는 할머니를 찾아뵈었어.)\"처럼 해요. 때를 나타내는 말 yesterday(어제), last weekend(지난 주말)를 함께 쓰면 좋아요."], "figure": "텐트 앞에서 캠핑하는 가족 그림", "example": "What did you do last weekend? - I went camping.", "heading": "지난 일 묻고 답하기"}], "parent_tip": "부모님께: 아이들은 \"goed\", \"eated\"처럼 모든 동사에 -ed를 붙이는 실수를 자주 합니다. 이는 규칙을 잘 이해했다는 신호이기도 하니 칭찬해 주시고, 특별한 동사만 따로 짝지어 알려 주세요. 저녁 식사 때 \"What did you do today?\"라고 물어 하루를 영어 한두 문장으로 말해 보게 하면 좋습니다.", "expressions": [{"en": "What did you do yesterday?", "ko": "너는 어제 무엇을 했니?", "note": "지난 일을 물을 때"}, {"en": "I played soccer.", "ko": "나는 축구를 했어."}, {"en": "I watched a movie.", "ko": "나는 영화를 봤어."}, {"en": "I went to the beach.", "ko": "나는 바닷가에 갔어."}, {"en": "I visited my grandma.", "ko": "나는 할머니를 찾아뵈었어."}, {"en": "I ate pizza.", "ko": "나는 피자를 먹었어."}, {"en": "It was fun!", "ko": "재미있었어!", "note": "지난 일에 대한 느낌을 말할 때"}]}$j$::jsonb where slug='e5-05';
update public.lessons set content=$j${"quiz": [{"q": "あ행 글자의 순서로 알맞은 것은 무엇일까요?", "answer": 0, "choices": ["あ い う え お", "あ う い お え", "あ い え う お", "お え う い あ"], "explain": "あ행은 あ(아), い(이), う(우), え(에), お(오) 순서예요."}, {"q": "'코' 소리를 나타내는 히라가나는 무엇일까요?", "answer": 2, "choices": ["い", "く", "こ", "け"], "explain": "こ는 가로 두 줄로 쓰는 글자로 '코'라고 읽어요. 세로 두 줄인 い는 '이'예요."}, {"q": "😊 '얼굴'을 뜻하는 낱말은 무엇일까요?", "answer": 3, "choices": ["いえ", "あか", "えき", "かお"], "explain": "かお(kao, 카오)는 얼굴이에요. いえ는 집, あか는 빨강, えき는 역이에요."}, {"q": "あ와 お를 구별하는 방법으로 알맞은 것은 무엇일까요?", "answer": 0, "choices": ["お는 오른쪽 위에 작은 점이 있어요.", "あ가 お보다 획이 더 많아요.", "お는 세로 두 줄로 써요.", "둘은 소리가 같아요."], "explain": "お는 오른쪽 위에 작은 점이 있고 '오'라고 읽어요."}, {"q": "いか는 어떻게 읽을까요?", "answer": 0, "choices": ["이카", "이코", "아카", "코카"], "explain": "い(이) + か(카) = いか(이카), 뜻은 오징어 🦑 예요."}], "intro": "한글을 배울 때 '가나다라'부터 배웠지요? 일본어 히라가나는 'あいうえお(아이우에오)'부터 시작해요. 오늘은 첫 두 줄인 あ행과 か행 열 글자를 익혀 봐요.", "summary": ["あ행은 あ(아) い(이) う(우) え(에) お(오), 일본어의 기본 소리예요.", "か행은 k 소리를 붙인 か(카) き(키) く(쿠) け(케) こ(코)예요.", "あ와 お, い와 こ처럼 닮은 글자는 다른 부분을 찾아 구별해요."], "keywords": [{"word": "あ행", "meaning": "あ, い, う, え, お 다섯 글자. 일본어의 기본 소리(모음)예요."}, {"word": "か행", "meaning": "か, き, く, け, こ 다섯 글자. あ행 소리에 k(ㅋ) 소리를 붙였어요."}, {"word": "모음", "meaning": "아, 이, 우, 에, 오처럼 목에서 막힘 없이 나오는 소리."}, {"word": "오십음도", "meaning": "히라가나를 あ행, か행… 순서대로 표처럼 늘어놓은 것."}], "sections": [{"paras": ["あ행은 あ(a, 아), い(i, 이), う(u, 우), え(e, 에), お(o, 오) 다섯 글자예요. 일본어 글자 소리는 거의 모두 이 다섯 소리(모음)로 끝나요.", "우리말 ㅏ, ㅣ, ㅜ, ㅔ, ㅗ와 거의 같아요. 다만 う는 입술을 앞으로 쭉 내밀지 않고 편하게 '우' 하고 소리 내요.", "순서는 꼭 あ, い, う, え, お예요. '아이우에오' 하고 노래처럼 외워 두면 다음 줄도 쉽게 익힐 수 있어요."], "figure": "히라가나 あ, い, う, え, お 카드 다섯 장이 한 줄로 놓여 있고, 아이 손가락이 차례로 짚는 모습", "example": "あ(아) い(이) う(우) え(에) お(오)", "heading": "일본어의 기본 소리 다섯 개, あ행"}, {"paras": ["か행은 あ행 소리 앞에 k(ㅋ) 소리를 붙인 줄이에요. か(ka, 카), き(ki, 키), く(ku, 쿠), け(ke, 케), こ(ko, 코)예요.", "낱말 첫머리에서는 '카'에 가깝게, 낱말 가운데에서는 '까'처럼 살짝 세게 들리기도 해요. 둘 다 같은 か 소리예요.", "한글에서 ㅋ과 ㅏ를 합치면 '카'가 되는 것과 비슷해요. 다만 히라가나는 글자 하나가 통째로 '카' 소리를 나타내요."], "figure": "あいうえお 줄 아래에 かきくけこ 줄이 표처럼 나란히 적힌 공책 한 쪽", "example": "k + a → か(카) / k + i → き(키) / k + u → く(쿠) / k + e → け(케) / k + o → こ(코)", "heading": "k 소리를 붙이면 か행"}, {"paras": ["あ와 お는 아주 비슷해요. お는 오른쪽 위에 작은 점이 찍혀 있어요. 이 점이 있으면 '오'예요.", "い와 こ도 헷갈려요. い는 세로로 두 줄, こ는 가로로 두 줄이에요. '이'는 서 있고, '코'는 누워 있다고 기억해요.", "く는 한 획으로 꺾어 쓰는 글자로, '<' 모양처럼 생겼어요. 입을 벌린 새 부리를 떠올려 보세요."], "figure": "あ와 お, い와 こ 카드를 두 장씩 나란히 놓고 다른 부분에 빨간 동그라미를 친 모습", "example": "あ(아) ↔ お(오): 오른쪽 위 점 확인! / い(이) 세로 두 줄 ↔ こ(코) 가로 두 줄", "heading": "헷갈리는 글자 구별하기"}, {"paras": ["あ행과 か행만 알아도 읽을 수 있는 낱말이 많아요. 글자를 하나씩 읽고 이어서 말해 보세요.", "いえ는 い(이)와 え(에)를 이어서 '이에', 뜻은 '집'이에요. かお는 '카오', 뜻은 '얼굴'이에요."], "figure": "집, 얼굴, 빨간 사과, 오징어, 단풍잎 그림 카드 아래에 히라가나 낱말이 적힌 모습", "example": "🏠 いえ(ie, 이에) 집 / 😊 かお(kao, 카오) 얼굴 / 🔴 あか(aka, 아카) 빨강 / 🦑 いか(ika, 이카) 오징어 / 🍁 あき(aki, 아키) 가을", "heading": "열 글자로 낱말을 읽어요"}], "parent_tip": "부모님께: 아이들은 あ/お, い/こ를 자주 헷갈립니다. 글자 카드를 만들어 부모님이 소리를 말하면 아이가 카드를 고르는 놀이를 해 보세요. 'いえ(집)', 'かお(얼굴)'처럼 아는 물건을 가리키며 일본어로 말해 보면 오래 기억합니다.", "expressions": [{"en": "あいうえお", "ko": "あ행 다섯 글자", "note": "a i u e o (아 이 우 에 오)"}, {"en": "かきくけこ", "ko": "か행 다섯 글자", "note": "ka ki ku ke ko (카 키 쿠 케 코)"}, {"en": "いえ", "ko": "집 🏠", "note": "ie (이에)"}, {"en": "かお", "ko": "얼굴 😊", "note": "kao (카오)"}, {"en": "あか", "ko": "빨강 🔴", "note": "aka (아카)"}, {"en": "あお", "ko": "파랑 🔵", "note": "ao (아오)"}, {"en": "いか", "ko": "오징어 🦑", "note": "ika (이카)"}, {"en": "かき", "ko": "감 🟠", "note": "kaki (카키)"}, {"en": "あき", "ko": "가을 🍁", "note": "aki (아키)"}, {"en": "えき", "ko": "역(기차역) 🚉", "note": "eki (에키)"}, {"en": "こえ", "ko": "목소리 🗣️", "note": "koe (코에)"}]}$j$::jsonb where slug='j3-02';
update public.lessons set content=$j${"quiz": [{"q": "ふ를 로마자로 바르게 쓴 것은 무엇일까요?", "answer": 2, "choices": ["hu", "pu", "fu", "bu"], "explain": "ふ는 fu라고 쓰고, 입술을 살짝 오므려 '후'라고 읽어요."}, {"q": "ほ와 は를 구별하는 방법으로 알맞은 것은 무엇일까요?", "answer": 0, "choices": ["ほ는 오른쪽 위에 가로줄이 하나 더 있어요.", "は가 ほ보다 획이 더 많아요.", "ほ는 끝에 고리가 없어요.", "둘은 소리가 같아요."], "explain": "ほ(호)는 오른쪽 위에 가로줄이 하나 더 있어 위가 막혀 있어요."}, {"q": "👂 '귀'를 뜻하는 낱말은 무엇일까요?", "answer": 3, "choices": ["もも", "むし", "はな", "みみ"], "explain": "みみ(mimi, 미미)는 귀예요. もも는 복숭아, むし는 벌레, はな는 꽃이에요."}, {"q": "끝에 작은 고리가 __없는__ 글자는 무엇일까요?", "answer": 1, "choices": ["ぬ", "め", "ね", "ま"], "explain": "め(메)는 고리 없이 끝나요. ぬ, ね, ま는 끝에 고리가 있어요."}, {"q": "こんにちは의 끝 글자 は는 어떻게 읽을까요?", "answer": 2, "choices": ["하", "호", "와", "바"], "explain": "'~은/는'에서 온 は라서 '와(wa)'로 읽어 '콘니치와'가 돼요."}], "intro": "봄에 피는 꽃을 일본어로 はな(하나), 밤하늘의 별을 ほし(호시)라고 해요. 오늘은 は행과 ま행 열 글자를 배워서 꽃, 별, 귀 같은 낱말을 읽어 봐요.", "summary": ["は행은 は ひ ふ へ ほ(하 히 후 헤 호), ふ는 fu예요.", "ま행은 ま み む め も(마 미 무 메 모)예요.", "は/ほ, ぬ/め는 닮은 글자라서 다른 부분을 찾아 구별해요."], "keywords": [{"word": "は행", "meaning": "は, ひ, ふ, へ, ほ. h 소리 줄인데 ふ만 fu(후)예요."}, {"word": "ま행", "meaning": "ま, み, む, め, も. 우리말 '마미무메모'와 소리가 비슷해요."}, {"word": "'~은/는'의 は", "meaning": "'~은/는'이라는 뜻으로 쓰는 は. 이때는 '와(wa)'로 읽어요."}], "sections": [{"paras": ["は행은 は(ha, 하), ひ(hi, 히), ふ(fu, 후), へ(he, 헤), ほ(ho, 호)예요.", "ふ는 로마자로 fu라고 써요. 윗니로 아랫입술을 무는 영어 f가 아니라, 입술을 살짝 오므리고 바람을 내보내며 '후' 하고 소리 내요.", "へ는 산 모양 '^'처럼 생긴 쉬운 글자예요. 가타카나 ヘ도 거의 똑같이 생겼어요."], "figure": "꽃 한 송이, 작은 장난감 배, 별 모양 스티커가 책상 위에 놓인 모습", "example": "🌸 はな(hana, 하나) 꽃 / 🧍 ひと(hito, 히토) 사람 / 🚢 ふね(fune, 후네) 배 / ⭐ ほし(hoshi, 호시) 별", "heading": "h 소리 줄, は행 — ふ를 조심해요"}, {"paras": ["は와 ほ는 아주 닮았어요. ほ는 오른쪽 위에 가로줄이 하나 더 있어서 위쪽이 막혀 있어요.", "위가 열려 있으면 は(하), 위가 막혀 있으면 ほ(호)예요. 손가락으로 오른쪽 윗부분을 짚어 보며 확인해요."], "figure": "は 카드와 ほ 카드를 나란히 놓고 ほ의 맨 위 가로줄에 빨간 동그라미를 친 모습", "example": "は(하) — 오른쪽 위가 열려 있어요 / ほ(호) — 오른쪽 위에 가로줄이 하나 더 있어요", "heading": "は와 ほ를 구별해요"}, {"paras": ["ま행은 ま(ma, 마), み(mi, 미), む(mu, 무), め(me, 메), も(mo, 모)예요. 우리말 '마미무메모'와 소리가 거의 같아요.", "め와 지난 시간에 배운 ぬ는 쌍둥이처럼 닮았어요. ぬ는 끝에 작은 고리가 있고, め는 고리 없이 끝나요.", "め는 혼자서 '눈 👁️'이라는 뜻의 낱말도 돼요. 글자 하나짜리 낱말이에요."], "figure": "복숭아 두 개와 돋보기로 작은 벌레 장난감을 보는 아이 손", "example": "👂 みみ(mimi, 미미) 귀 / 🍑 もも(momo, 모모) 복숭아 / 🐛 むし(mushi, 무시) 벌레 / 👁️ め(me, 메) 눈", "heading": "m 소리 줄, ま행"}, {"paras": ["は는 보통 '하'로 읽지만, 문장에서 '~은/는'이라는 뜻으로 쓰일 때는 '와(wa)'로 읽어요.", "그래서 인사말 こんにちは도 끝의 は를 '와'로 읽어 '콘니치와'가 돼요. 지금은 '이럴 때도 있구나' 하고 알아 두기만 하면 돼요."], "figure": "공책에 はな와 こんにちは를 쓰고 は 글자 아래에 각각 '하', '와'라고 작게 적은 모습", "example": "はな(하나) 꽃 → は를 '하'로 읽어요 / こんにちは(콘니치와) → 끝의 は를 '와'로 읽어요", "heading": "알아 두면 좋은 것: は를 '와'로 읽을 때"}], "parent_tip": "부모님께: 아이들은 は/ほ, ぬ/め를 자주 헷갈립니다. 두 글자를 크게 써서 '다른 곳 찾기' 놀이를 해 보세요. 또 は를 '와'로 읽는 경우는 지금 깊이 설명하지 않아도 됩니다. 'みみ(귀)', 'め(눈)', 'あたま(머리)'처럼 몸을 가리키며 말해 보는 놀이도 좋습니다.", "expressions": [{"en": "はひふへほ", "ko": "は행 다섯 글자", "note": "ha hi fu he ho (하 히 후 헤 호)"}, {"en": "まみむめも", "ko": "ま행 다섯 글자", "note": "ma mi mu me mo (마 미 무 메 모)"}, {"en": "はな", "ko": "꽃 🌸 (코라는 뜻도 있어요)", "note": "hana (하나)"}, {"en": "ほし", "ko": "별 ⭐", "note": "hoshi (호시)"}, {"en": "ふね", "ko": "배 🚢", "note": "fune (후네)"}, {"en": "ひと", "ko": "사람 🧍", "note": "hito (히토)"}, {"en": "みみ", "ko": "귀 👂", "note": "mimi (미미)"}, {"en": "もも", "ko": "복숭아 🍑", "note": "momo (모모)"}, {"en": "むし", "ko": "벌레 🐛", "note": "mushi (무시)"}, {"en": "め", "ko": "눈 👁️", "note": "me (메)"}, {"en": "あたま", "ko": "머리", "note": "atama (아타마)"}]}$j$::jsonb where slug='j3-04';
update public.lessons set content=$j${"quiz": [{"q": "や행에 들어 있는 글자가 __아닌__ 것은 무엇일까요?", "answer": 3, "choices": ["や", "ゆ", "よ", "わ"], "explain": "や행은 や, ゆ, よ 세 글자예요. わ는 わ행 글자예요."}, {"q": "아래에 작은 고리가 있는 글자는 무엇일까요?", "answer": 1, "choices": ["ろ", "る", "ら", "り"], "explain": "る(루)는 아래에 고리가 있고, ろ(로)는 고리 없이 끝나요."}, {"q": "を에 대한 설명으로 알맞은 것은 무엇일까요?", "answer": 2, "choices": ["'워'라고 읽어요.", "낱말 맨 앞에 자주 와요.", "'오'라고 읽고 '~을/를'이라는 뜻으로 써요.", "'응'이라고 읽어요."], "explain": "を는 お와 같이 '오'로 읽고, '~을/를'이라는 뜻으로만 써요."}, {"q": "🍊 みかん은 어떻게 읽을까요?", "answer": 0, "choices": ["미캉", "미카", "무캉", "미칸나"], "explain": "み(미) + か(카) + ん(받침) = 미캉, 뜻은 귤이에요."}, {"q": "ん에 대한 설명으로 알맞은 것은 무엇일까요?", "answer": 1, "choices": ["낱말 맨 앞에 와요.", "받침처럼 앞 글자에 붙어 소리 나요.", "'와'라고 읽어요.", "ら행 글자예요."], "explain": "ん은 받침처럼 앞 글자에 붙어 소리 나고, 낱말 맨 앞에는 오지 않아요."}], "intro": "드디어 히라가나 46글자의 마지막 부분이에요! や행, ら행, わ행과 특별한 글자 ん을 배우면 기본 히라가나를 모두 읽을 수 있어요.", "summary": ["や행은 や ゆ よ 세 글자, ら행은 ら り る れ ろ(라 리 루 레 로)예요.", "わ행의 を는 '오'로 읽고 '~을/를'이라는 뜻으로만 써요.", "ん은 받침처럼 소리 나는 글자이고, 이제 기본 히라가나 46글자를 모두 배웠어요."], "keywords": [{"word": "や행", "meaning": "や, ゆ, よ 세 글자뿐인 줄."}, {"word": "ら행", "meaning": "ら, り, る, れ, ろ. 우리말 'ㄹ' 소리와 비슷해요."}, {"word": "を", "meaning": "'오'로 읽고, 문장에서 '~을/를'이라는 뜻으로만 쓰는 글자."}, {"word": "ん", "meaning": "받침처럼 앞 글자에 붙어 소리 나는 글자. 낱말 맨 앞에는 오지 않아요."}, {"word": "오십음도", "meaning": "히라가나를 줄과 칸에 맞춰 늘어놓은 표."}], "sections": [{"paras": ["や행은 や(ya, 야), ゆ(yu, 유), よ(yo, 요) 세 글자예요. 다른 줄과 달리 다섯 글자가 아니라 세 글자뿐이에요.", "오십음도 표에서 や행의 い 자리와 え 자리는 비어 있어요. 오늘날 일본어에는 그 자리에 들어갈 소리(yi, ye)가 따로 없기 때문이에요."], "figure": "창밖으로 눈 덮인 산과 밤하늘의 달이 보이는 창가 책상 풍경", "example": "⛰️ やま(yama, 야마) 산 / ❄️ ゆき(yuki, 유키) 눈 / 🌙 よる(yoru, 요루) 밤", "heading": "세 글자뿐인 や행"}, {"paras": ["ら행은 ら(ra, 라), り(ri, 리), る(ru, 루), れ(re, 레), ろ(ro, 로)예요. 로마자는 r이지만 소리는 우리말 'ㄹ'과 거의 같아요.", "る와 ろ는 닮았어요. る는 아래에 작은 고리가 있고, ろ는 고리 없이 끝나요.", "れ, わ, ね는 왼쪽에 세로 막대가 있는 삼총사예요. 끝을 보고 구별해요. れ는 끝이 바깥으로 툭 튀어나가고, わ는 둥글게 감싸고, ね는 작은 고리로 끝나요."], "figure": "れ, わ, ね 카드 세 장을 나란히 놓고 끝부분에 서로 다른 색 동그라미를 친 모습", "example": "🐿️ りす(risu, 리스) 다람쥐 / 🐒 さる(saru, 사루) 원숭이 / 🚗 くるま(kuruma, 쿠루마) 자동차 / ☁️ そら(sora, 소라) 하늘", "heading": "r 소리 줄, ら행"}, {"paras": ["わ행에는 わ(wa, 와)와 を(o, 오) 두 글자가 있어요. を는 お와 똑같이 '오'라고 읽지만, 문장에서 '~을/를'이라는 뜻으로만 써요.", "ん(n, 응)은 혼자서 한 박자를 차지하는 특별한 글자예요. 우리말 받침처럼 앞 글자에 붙어서 소리 나고, 낱말 맨 앞에는 절대 오지 않아요.", "ん은 뒤에 오는 소리에 따라 'ㄴ', 'ㅁ', 'ㅇ' 받침처럼 들려요. 낱말 끝에 오면 콧소리 'ㅇ'에 가깝게 들려요."], "figure": "펼친 그림책 옆에 귤 두 개가 놓인 책상", "example": "📖 ほん(hon, 홍) 책 / 🍊 みかん(mikan, 미캉) 귤 / 📖 ほんを よみます(hon o yomimasu, 홍오 요미마스) 책을 읽어요", "heading": "わ, を 그리고 특별한 글자 ん"}, {"paras": ["あ행부터 ん까지 기본 히라가나 46글자를 모두 배웠어요. 이제 어떤 히라가나 낱말이든 한 글자씩 읽어 낼 수 있어요.", "헷갈리는 글자가 있으면 오십음도 표를 보며 다시 확인해요. 매일 다섯 글자씩 소리 내어 읽으면 금방 익숙해져요."], "figure": "벽에 붙은 히라가나 오십음도 표 앞에서 아이가 손가락으로 글자를 짚는 모습(글자는 흐리게)", "example": "🐊 わに(wani, 와니) 악어 / 🙋 わたし(watashi, 와타시) 나 / 💭 ゆめ(yume, 유메) 꿈", "heading": "히라가나 46글자를 다 배웠어요"}], "parent_tip": "부모님께: れ/わ/ね, る/ろ는 히라가나에서 가장 많이 헷갈리는 글자입니다. 또 ん을 '응'으로 한 글자처럼 따로 읽어 '호응'이라고 하는 실수가 많으니, 앞 글자에 붙여 '홍'처럼 읽도록 도와주세요. 오늘로 기본 히라가나를 다 배웠으니 오십음도 표를 함께 소리 내어 읽어 보며 축하해 주세요.", "expressions": [{"en": "やゆよ", "ko": "や행 세 글자", "note": "ya yu yo (야 유 요)"}, {"en": "らりるれろ", "ko": "ら행 다섯 글자", "note": "ra ri ru re ro (라 리 루 레 로)"}, {"en": "わをん", "ko": "わ, を, ん", "note": "wa o n (와 오 응)"}, {"en": "ゆき", "ko": "눈(하늘에서 내리는 눈) ❄️", "note": "yuki (유키)"}, {"en": "よる", "ko": "밤 🌙", "note": "yoru (요루)"}, {"en": "そら", "ko": "하늘 ☁️", "note": "sora (소라)"}, {"en": "さる", "ko": "원숭이 🐒", "note": "saru (사루)"}, {"en": "くるま", "ko": "자동차 🚗", "note": "kuruma (쿠루마)"}, {"en": "わに", "ko": "악어 🐊", "note": "wani (와니)"}, {"en": "ほん", "ko": "책 📖", "note": "hon (홍)"}, {"en": "みかん", "ko": "귤 🍊", "note": "mikan (미캉)"}, {"en": "ほんを よみます", "ko": "책을 읽어요", "note": "hon o yomimasu (홍오 요미마스)"}]}$j$::jsonb where slug='j3-05';
update public.lessons set content=$j${"quiz": [{"q": "🌙 저녁에 만난 사람에게 하는 인사는 무엇일까요?", "answer": 2, "choices": ["おはようございます", "こんにちは", "こんばんは", "おやすみなさい"], "explain": "저녁 인사는 こんばんは(콤방와)예요. おやすみなさい는 잘 때 하는 인사예요."}, {"q": "こんにちは는 어떻게 읽을까요?", "answer": 1, "choices": ["콘니치하", "콘니치와", "곤니치히", "콘니치호"], "explain": "끝의 は는 '와'로 읽어서 '콘니치와'예요."}, {"q": "친구가 선물을 줬을 때 할 말은 무엇일까요?", "answer": 0, "choices": ["ありがとう", "すみません", "さようなら", "いただきます"], "explain": "고마울 때는 ありがとう(아리가토-)라고 해요."}, {"q": "🍚 밥을 다 먹은 뒤에 하는 인사는 무엇일까요?", "answer": 3, "choices": ["いただきます", "はじめまして", "またね", "ごちそうさまでした"], "explain": "다 먹은 뒤에는 ごちそうさまでした(고치소-사마데시타), 먹기 전에는 いただきます라고 해요."}, {"q": "처음 만난 친구에게 하는 인사는 무엇일까요?", "answer": 1, "choices": ["おやすみなさい", "はじめまして", "どういたしまして", "ごちそうさまでした"], "explain": "처음 만났을 때는 はじめまして(하지메마시테)라고 해요."}], "intro": "우리말에 '안녕하세요', '고마워요', '잘 자'가 있듯이 일본어에도 때에 맞는 인사말이 있어요. 히라가나로 인사말을 읽고, 소리 내어 따라 해 봐요.", "summary": ["아침 おはようございます, 낮 こんにちは, 저녁 こんばんは로 때에 맞게 인사해요.", "こんにちは, こんばんは의 끝 は는 '와'로 읽고, おはよう의 よう는 '요-'로 길게 읽어요.", "ありがとう(고마워), すみません(미안해요), いただきます(잘 먹겠습니다)도 함께 익혀요."], "keywords": [{"word": "인사말", "meaning": "만나고 헤어질 때, 고마울 때 주고받는 말."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. おはよう의 よう는 '요-'로 길게 읽어요."}, {"word": "오지기", "meaning": "일본에서 인사할 때 고개와 허리를 숙이는 몸짓."}], "sections": [{"paras": ["일본어는 시간에 따라 인사말이 달라요. 아침에는 おはようございます(오하요- 고자이마스), 낮에는 こんにちは(콘니치와), 저녁에는 こんばんは(콤방와)라고 해요.", "친구나 가족에게 아침 인사를 할 때는 짧게 おはよう(오하요-)라고만 해도 돼요.", "こんにちは와 こんばんは의 끝 글자 は는 '하'가 아니라 '와'로 읽어요. 꼭 기억해 두세요!"], "figure": "아침 해, 한낮의 해, 저녁 달이 그려진 세 장의 그림 카드가 나란히 놓인 모습", "example": "🌅 아침: おはようございます(ohayou gozaimasu, 오하요- 고자이마스) / ☀️ 낮: こんにちは(konnichiwa, 콘니치와) / 🌙 저녁: こんばんは(konbanwa, 콤방와)", "heading": "아침, 낮, 저녁 인사가 달라요"}, {"paras": ["おはよう는 '오하요우'라고 또박또박 읽지 않고 '오하요-' 하고 よ를 길게 늘여 읽어요. 이렇게 う가 앞 소리를 길게 만드는 경우가 많아요.", "ありがとう(아리가토-), さようなら(사요-나라)도 마찬가지예요. 이 책에서는 길게 읽는 곳을 '-'로 표시했어요."], "figure": "고무줄을 길게 늘이는 아이 손 그림 옆에 '요-' 소리를 길게 늘이는 모습을 표현한 그림", "example": "おはよう → 오하요- / ありがとう → 아리가토- / さようなら → 사요-나라", "heading": "う는 앞 소리를 길게 늘여요"}, {"paras": ["헤어질 때는 さようなら(사요-나라)라고 해요. 친구끼리는 またね(마타네, 또 만나)를 더 자주 써요.", "밤에 잠자리에 들 때는 おやすみなさい(오야스미나사이, 안녕히 주무세요)라고 해요."], "figure": "학교 앞에서 손을 흔들며 헤어지는 두 아이의 뒷모습", "example": "👋 またね(matane, 마타네) 또 봐 / 😴 おやすみなさい(oyasuminasai, 오야스미나사이) 잘 자요", "heading": "헤어질 때, 잘 때"}, {"paras": ["고마울 때는 ありがとう(아리가토-), 더 공손하게는 ありがとうございます(아리가토- 고자이마스)라고 해요. 가볍게 どうも(도-모)라고도 하는데, 짧고 가벼운 말이라 웃어른께는 ありがとうございます가 더 좋아요. 대답으로는 どういたしまして(도-이타시마시테, 천만에요)라고 해요.", "미안할 때나 '저기요' 하고 부를 때는 すみません(스미마셍)이라고 해요.", "처음 만난 사람에게는 はじめまして(하지메마시테, 처음 뵙겠습니다)라고 해요. 밥 먹기 전에는 いただきます(이타다키마스), 다 먹은 뒤에는 ごちそうさまでした(고치소-사마데시타)라고 해요. 일본 사람들은 인사할 때 고개를 숙이는 '오지기'를 함께 해요."], "figure": "식탁 앞에서 두 손을 모으고 고개를 살짝 숙이는 아이", "example": "🙏 ありがとう(arigatou, 아리가토-) 고마워 / 🍚 いただきます(itadakimasu, 이타다키마스) 잘 먹겠습니다", "heading": "고마워요, 미안해요, 잘 먹겠습니다"}], "parent_tip": "부모님께: 인사말은 외우기보다 생활에서 써 보는 것이 가장 좋습니다. 오늘 하루는 아침에 'おはよう', 식사 때 'いただきます', 잘 때 'おやすみなさい'를 가족이 함께 일본어로 말해 보세요. 아이가 こんにちは를 '콘니치하'로 읽으면 끝의 は는 '와'로 읽는다는 점을 다시 짚어 주세요.", "expressions": [{"en": "おはようございます", "ko": "안녕하세요 (아침 인사)", "note": "ohayou gozaimasu (오하요- 고자이마스)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (콘니치와) — 끝의 は는 '와'"}, {"en": "こんばんは", "ko": "안녕하세요 (저녁 인사)", "note": "konbanwa (콤방와) — 끝의 は는 '와'"}, {"en": "さようなら", "ko": "안녕히 가세요", "note": "sayounara (사요-나라)"}, {"en": "またね", "ko": "또 봐 (친구끼리)", "note": "matane (마타네)"}, {"en": "おやすみなさい", "ko": "안녕히 주무세요, 잘 자요", "note": "oyasuminasai (오야스미나사이)"}, {"en": "ありがとう", "ko": "고마워", "note": "arigatou (아리가토-)"}, {"en": "どういたしまして", "ko": "천만에요", "note": "douitashimashite (도-이타시마시테)"}, {"en": "すみません", "ko": "미안해요 / 저기요", "note": "sumimasen (스미마셍)"}, {"en": "はじめまして", "ko": "처음 뵙겠습니다", "note": "hajimemashite (하지메마시테)"}, {"en": "いただきます", "ko": "잘 먹겠습니다", "note": "itadakimasu (이타다키마스)"}, {"en": "ごちそうさまでした", "ko": "잘 먹었습니다", "note": "gochisousama deshita (고치소-사마데시타)"}]}$j$::jsonb where slug='j3-07';
update public.lessons set content=$j${"quiz": [{"q": "일본어로 3은 무엇일까요?", "answer": 1, "choices": ["いち", "さん", "ご", "に"], "explain": "3은 さん(상)이에요. いち는 1, ご는 5, に는 2예요."}, {"q": "はち는 숫자 몇일까요?", "answer": 2, "choices": ["6", "7", "8", "9"], "explain": "はち(하치)는 8이에요."}, {"q": "きゅう는 어떻게 읽을까요?", "answer": 1, "choices": ["키우", "큐-", "기유", "쿠"], "explain": "き와 작은 ゅ가 합쳐져 '큐', 끝의 う로 길게 늘여 '큐-'라고 읽어요."}, {"q": "🍎🍎 + 🍎🍎🍎 = ? 일본어로 알맞은 것은 무엇일까요?", "answer": 3, "choices": ["よん", "ろく", "なな", "ご"], "explain": "2 + 3 = 5이고, 5는 ご(고)예요."}, {"q": "다음 중 7을 읽는 법으로 알맞은 것은 무엇일까요?", "answer": 0, "choices": ["なな", "はち", "よん", "じゅう"], "explain": "7은 なな(나나)예요. しち(시치)라고도 읽어요."}], "intro": "숨바꼭질할 때 '하나, 둘, 셋' 하고 세지요? 일본 아이들은 'いち, に, さん(이치, 니, 상)' 하고 세어요. 오늘은 일본어로 1부터 10까지 세는 법을 배워요.", "summary": ["1~5는 いち, に, さん, よん, ご(이치, 니, 상, 용, 고)예요.", "6~10은 ろく, なな, はち, きゅう, じゅう(로쿠, 나나, 하치, 큐-, 주-)예요.", "작은 ゅ는 앞 글자와 합쳐 한 소리가 되고, 4·7·9는 읽는 법이 두 가지예요."], "keywords": [{"word": "작은 ゅ", "meaning": "앞 글자와 합쳐져 한 소리가 되는 작은 글자. きゅ(큐), じゅ(주)."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. きゅう는 '큐-'로 읽어요."}, {"word": "たす", "meaning": "'더하기'라는 뜻의 말. 타스라고 읽어요."}], "sections": [{"paras": ["1은 いち(ichi, 이치), 2는 に(ni, 니), 3은 さん(san, 상), 4는 よん(yon, 용), 5는 ご(go, 고)예요.", "に는 한 글자, ご도 한 글자라서 짧아요. 짧은 숫자일수록 또렷하게 말해요.", "さん의 ん은 받침처럼 앞 글자에 붙어서 한 번에 '상' 하고 소리 내요."], "figure": "아이 손가락 다섯 개를 하나씩 펴며 수를 세는 모습", "example": "1️⃣ いち(이치) 2️⃣ に(니) 3️⃣ さん(상) 4️⃣ よん(용) 5️⃣ ご(고)", "heading": "1부터 5까지"}, {"paras": ["6은 ろく(roku, 로쿠), 7은 なな(nana, 나나), 8은 はち(hachi, 하치), 9는 きゅう(kyuu, 큐-), 10은 じゅう(juu, 주-)예요.", "きゅう와 じゅう에는 작은 ゅ가 들어 있어요. 작은 ゅ는 앞 글자와 합쳐서 한 소리가 돼요. き(키)+ゅ(유)는 '키유'가 아니라 '큐', じ(지)+ゅ(유)는 '주'예요.", "끝의 う는 앞 소리를 길게 늘여요. 그래서 '큐-', '주-' 하고 길게 읽어요."], "figure": "큰 글자 き 옆에 작은 글자 ゅ 카드를 붙여 놓은 모습", "example": "6️⃣ ろく(로쿠) 7️⃣ なな(나나) 8️⃣ はち(하치) 9️⃣ きゅう(큐-) 🔟 じゅう(주-)", "heading": "6부터 10까지와 작은 ゅ"}, {"paras": ["4, 7, 9는 읽는 법이 두 가지예요. 4는 よん 또는 し(시), 7은 なな 또는 しち(시치), 9는 きゅう 또는 く(쿠)예요.", "보통 수를 셀 때는 よん, なな, きゅう를 더 많이 써요. 이 단원에서도 이 세 가지로 익혀요."], "figure": "숫자 카드 4, 7, 9 아래에 읽는 법 카드가 두 장씩 놓여 있는 모습", "example": "4 = よん(용) / し(시) · 7 = なな(나나) / しち(시치) · 9 = きゅう(큐-) / く(쿠)", "heading": "읽는 법이 두 가지인 숫자"}, {"paras": ["일본어 숫자를 알면 간단한 계산도 일본어로 말할 수 있어요. さん たす よん は なな(상 타스 용 와 나나)는 '3 더하기 4는 7'이라는 뜻이에요.", "10보다 큰 수는 じゅう 뒤에 숫자를 붙여요. 11은 じゅういち(주-이치), 12는 じゅうに(주-니)예요."], "figure": "사과 세 개와 사과 네 개를 모아 일곱 개를 만드는 아이 손", "example": "🍎🍎🍎 + 🍎🍎🍎🍎 → さん たす よん は なな (3 + 4 = 7) / じゅう + いち → じゅういち(11)", "heading": "숫자로 놀아 봐요"}], "parent_tip": "부모님께: 계단을 오르거나 줄넘기를 할 때 일본어로 수를 세어 보세요. 몸을 움직이며 세면 빨리 외웁니다. きゅう를 '키유-'처럼 두 소리로 나누어 읽는 실수가 많으니, 작은 ゅ는 앞 글자와 한 소리로 합쳐진다는 점을 짚어 주세요. 4·7·9의 다른 읽기(し, しち, く)는 들어 본 정도로 충분합니다.", "expressions": [{"en": "いち", "ko": "1, 하나", "note": "ichi (이치)"}, {"en": "に", "ko": "2, 둘", "note": "ni (니)"}, {"en": "さん", "ko": "3, 셋", "note": "san (상)"}, {"en": "よん", "ko": "4, 넷 (し라고도 읽어요)", "note": "yon (용)"}, {"en": "ご", "ko": "5, 다섯", "note": "go (고)"}, {"en": "ろく", "ko": "6, 여섯", "note": "roku (로쿠)"}, {"en": "なな", "ko": "7, 일곱 (しち라고도 읽어요)", "note": "nana (나나)"}, {"en": "はち", "ko": "8, 여덟", "note": "hachi (하치)"}, {"en": "きゅう", "ko": "9, 아홉 (く라고도 읽어요)", "note": "kyuu (큐-)"}, {"en": "じゅう", "ko": "10, 열", "note": "juu (주-)"}, {"en": "じゅういち", "ko": "11, 열하나", "note": "juuichi (주-이치)"}]}$j$::jsonb where slug='j3-08';
update public.lessons set content=$j${"quiz": [{"q": "👩 '엄마'를 뜻하는 낱말은 무엇일까요?", "answer": 1, "choices": ["おとうさん", "おかあさん", "おねえさん", "おばさん"], "explain": "엄마는 おかあさん(오카-상)이에요. おとうさん은 아빠예요."}, {"q": "👴 '할아버지'를 뜻하는 낱말은 무엇일까요?", "answer": 2, "choices": ["おじさん", "おにいさん", "おじいさん", "おとうと"], "explain": "할아버지는 じ를 길게 읽는 おじいさん(오지-상)이에요. おじさん(오지상)은 아저씨예요."}, {"q": "✏️ えんぴつ는 무슨 뜻일까요?", "answer": 0, "choices": ["연필", "가방", "책", "시계"], "explain": "えんぴつ(엠피츠)는 연필이에요."}, {"q": "'이것은 책이에요.'를 일본어로 바르게 쓴 것은 무엇일까요?", "answer": 3, "choices": ["これは かばんです。", "これは とけいです。", "わたしは ほんです。", "これは ほんです。"], "explain": "'이것은 ~예요'는 これは ~です, 책은 ほん이라서 これは ほんです예요."}, {"q": "わたしの かばん은 무슨 뜻일까요?", "answer": 1, "choices": ["엄마의 가방", "내 가방", "새 가방", "가방 속 책"], "explain": "わたし는 '나', の는 '~의'라서 '나의 가방(내 가방)'이에요."}], "intro": "일본 만화에서 'おかあさん(오카-상)!' 하고 엄마를 부르는 소리를 들어 본 적 있나요? 오늘은 가족을 부르는 말과 책상 위 물건 이름을 배우고, '이것은 ~예요'라고 말해 봐요.", "summary": ["엄마 おかあさん, 아빠 おとうさん, 형·오빠 おにいさん, 누나·언니 おねえさん이에요.", "おばあさん(할머니)과 おばさん(아주머니)처럼 길게 읽느냐에 따라 뜻이 달라져요.", "これは ~です(코레와 ~데스)로 '이것은 ~예요'라고 말할 수 있어요."], "keywords": [{"word": "かぞく", "meaning": "가족. 카조쿠라고 읽어요."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. おばあさん의 ばあ는 '바-'로 길게 읽어요."}, {"word": "これは ~です", "meaning": "'이것은 ~예요'라는 문장. は는 '와'로 읽어요."}, {"word": "の", "meaning": "'~의'라는 뜻. わたしの는 '나의'예요."}], "sections": [{"paras": ["엄마는 おかあさん(okaasan, 오카-상), 아빠는 おとうさん(otousan, 오토-상)이에요. 가족은 かぞく(kazoku, 카조쿠)라고 해요.", "형이나 오빠는 おにいさん(oniisan, 오니-상), 누나나 언니는 おねえさん(oneesan, 오네-상)이에요. 남동생은 おとうと(otouto, 오토-토), 여동생은 いもうと(imouto, 이모-토)예요.", "나 자신은 わたし(watashi, 와타시)라고 해요. 남자아이든 여자아이든 쓸 수 있어요."], "figure": "식탁에 둘러앉은 가족 다섯 명의 뒷모습과 손이 보이는 따뜻한 저녁 장면", "example": "👩 おかあさん(오카-상) 엄마 / 👨 おとうさん(오토-상) 아빠 / 👦 おにいさん(오니-상) 형·오빠 / 👧 おねえさん(오네-상) 누나·언니", "heading": "우리 가족을 불러요"}, {"paras": ["할머니는 おばあさん(obaasan, 오바-상), 할아버지는 おじいさん(ojiisan, 오지-상)이에요. ば와 じ를 길게 늘여 읽어요.", "그런데 길게 읽지 않으면 뜻이 바뀌어요! おばさん(오바상)은 '아주머니·이모·고모', おじさん(오지상)은 '아저씨·삼촌'이에요.", "그래서 긴소리를 만드는 あ, い 같은 글자를 빠뜨리지 않고 쓰고, 길게 소리 내는 것이 중요해요."], "figure": "할머니와 아주머니, 할아버지와 아저씨가 짝지어 서 있는 모습을 그린 그림 카드 네 장", "example": "👵 おばあさん(오바-상) 할머니 ↔ おばさん(오바상) 아주머니 / 👴 おじいさん(오지-상) 할아버지 ↔ おじさん(오지상) 아저씨", "heading": "길게 읽느냐에 따라 뜻이 달라져요"}, {"paras": ["책은 ほん(hon, 홍), 연필은 えんぴつ(enpitsu, 엠피츠), 가방은 かばん(kaban, 카방)이에요.", "책상은 つくえ(tsukue, 츠쿠에), 의자는 いす(isu, 이스), 우산은 かさ(kasa, 카사), 시계는 とけい(tokei, 토케-)예요.", "とけい의 けい는 '케이'보다 '케-'처럼 길게 들려요."], "figure": "책상 위에 책, 연필, 가방, 탁상시계가 가지런히 놓여 있는 모습", "example": "📖 ほん(홍) 책 / ✏️ えんぴつ(엠피츠) 연필 / 🎒 かばん(카방) 가방 / ⏰ とけい(토케-) 시계", "heading": "책상 위 물건 이름"}, {"paras": ["물건을 가리키며 'これは ~です(코레와 ~데스)'라고 하면 '이것은 ~예요'라는 뜻이 돼요. 여기서도 は는 '와'로 읽어요. ん 뒤에 で가 오면 ん이 'ㄴ'처럼 들려서 ほんです는 '혼데스', かばんです는 '카반데스'로 읽어요.", "'나의 ~'라고 할 때는 の(노)를 써요. わたしの かばん(와타시노 카방)은 '나의 가방', 곧 '내 가방'이에요."], "figure": "아이가 손가락으로 책을 가리키고 있는 모습", "example": "これは ほんです。(코레와 혼데스) 이것은 책이에요. / これは わたしの かばんです。(코레와 와타시노 카반데스) 이것은 내 가방이에요.", "heading": "'이것은 ~예요' 말하기"}], "parent_tip": "부모님께: 일본어에서는 남의 가족을 부를 때와 내 가족을 남에게 말할 때 쓰는 말이 다르지만(예: はは, ちち), 이 단계에서는 집에서 부르는 말(おかあさん 등)만 익혀도 충분합니다. 집 안 물건을 가리키며 'これは なんですか?(이건 뭐예요?)'라고 묻고 아이가 'これは ~です'로 답하는 놀이를 해 보세요.", "expressions": [{"en": "かぞく", "ko": "가족 👨‍👩‍👧‍👦", "note": "kazoku (카조쿠)"}, {"en": "おかあさん", "ko": "엄마, 어머니 👩", "note": "okaasan (오카-상)"}, {"en": "おとうさん", "ko": "아빠, 아버지 👨", "note": "otousan (오토-상)"}, {"en": "おにいさん", "ko": "형, 오빠 👦", "note": "oniisan (오니-상)"}, {"en": "おねえさん", "ko": "누나, 언니 👧", "note": "oneesan (오네-상)"}, {"en": "おばあさん", "ko": "할머니 👵", "note": "obaasan (오바-상)"}, {"en": "おじいさん", "ko": "할아버지 👴", "note": "ojiisan (오지-상)"}, {"en": "わたし", "ko": "나, 저", "note": "watashi (와타시)"}, {"en": "えんぴつ", "ko": "연필 ✏️", "note": "enpitsu (엠피츠)"}, {"en": "かばん", "ko": "가방 🎒", "note": "kaban (카방)"}, {"en": "とけい", "ko": "시계 ⏰", "note": "tokei (토케-)"}, {"en": "これは ほんです", "ko": "이것은 책이에요.", "note": "kore wa hon desu (코레와 혼데스)"}]}$j$::jsonb where slug='j3-09';
update public.lessons set content=$j${"quiz": [{"q": "처음 만난 사람에게 하는 인사는 무엇일까요?", "answer": 0, "choices": ["はじめまして", "おやすみ", "ありがとう", "さようなら"], "explain": "はじめまして(하지메마시테)는 '처음 뵙겠습니다'라는 뜻이에요."}, {"q": "わたしは ジュンです。 에서 は는 어떻게 읽을까요?", "answer": 1, "choices": ["하(ha)", "와(wa)", "아(a)", "바(ba)"], "explain": "'~은/는'이라는 뜻으로 쓰인 は는 '와(wa)'로 읽어요."}, {"q": "'한국 사람이에요.'를 일본어로 바르게 말한 것은?", "answer": 2, "choices": ["にほんじんです。", "しょうがくせいです。", "かんこくじんです。", "よろしくおねがいします。"], "explain": "かんこく(한국) + じん(사람) + です = かんこくじんです예요."}, {"q": "자기소개를 마치며 '잘 부탁합니다'라고 할 때 쓰는 말은?", "answer": 3, "choices": ["こんにちは", "はじめまして", "わたしは", "よろしくおねがいします"], "explain": "よろしくおねがいします(요로시쿠 오네가이시마스)는 '잘 부탁합니다'예요."}, {"q": "さん을 붙이면 __어색한__ 것은 무엇일까요?", "answer": 2, "choices": ["친구 이름 ミナ", "반 친구 이름 ハルト", "내 이름", "새로 만난 사람 이름"], "explain": "さん은 다른 사람을 높여 부르는 말이라 내 이름에는 붙이지 않아요."}], "intro": "일본 친구를 처음 만났어요. 웃으면서 \"안녕, 나는 ○○야!\"라고 일본어로 말할 수 있다면 정말 멋지겠죠? 오늘은 일본어를 하나도 몰라도 바로 쓸 수 있는 자기소개를 배워요.", "summary": ["처음 만나면 はじめまして(하지메마시테)라고 인사해요.", "わたしは ○○です(와타시와 ○○데스)로 이름을 말해요. 이때 は는 '와'로 읽어요.", "마지막에는 よろしくおねがいします(요로시쿠 오네가이시마스)로 마무리해요."], "keywords": [{"word": "히라가나", "meaning": "일본어의 기본 글자. あ, い, う 같은 글자"}, {"word": "가타카나", "meaning": "외국에서 온 말이나 외국 사람 이름을 쓰는 글자. ア, イ, ウ 같은 글자"}, {"word": "わたし", "meaning": "나, 저 (watashi, 와타시)"}, {"word": "です", "meaning": "~예요, ~이에요 (desu, 데스)"}, {"word": "は(와)", "meaning": "'~은/는'이라는 뜻일 때는 '와(wa)'로 읽어요"}], "sections": [{"paras": ["일본어에는 히라가나, 가타카나, 한자 세 가지 글자가 있어요. 히라가나는 일본어의 기본 글자이고, 가타카나는 외국에서 온 말이나 외국 사람 이름을 쓸 때 주로 써요.", "처음에는 글자를 다 외우지 않아도 괜찮아요. 이 단원에서는 일본어 옆에 로마자와 한글 소리를 함께 적어 두었으니, 소리를 듣고 따라 말해 보세요."], "figure": "히라가나 あいうえお 와 가타카나 アイウエオ 를 나란히 적은 글자 카드", "example": "히라가나: あ(a, 아) い(i, 이) う(u, 우) え(e, 에) お(o, 오) / 가타카나: ア イ ウ エ オ (소리는 똑같아요)", "heading": "일본어 글자는 세 가지예요"}, {"paras": ["처음 만난 사람에게는 はじめまして(hajimemashite, 하지메마시테)라고 인사해요. '처음 뵙겠습니다'라는 뜻이에요.", "낮에 만나면 こんにちは(konnichiwa, 콘니치와)도 함께 쓸 수 있어요. こんにちは의 마지막 글자 は는 이 인사말에서 '와'로 읽어요."], "figure": "두 아이가 손을 흔들며 처음 인사하는 모습", "example": "はじめまして。(hajimemashite, 하지메마시테) → 처음 뵙겠습니다.", "heading": "처음 만나면 はじめまして"}, {"paras": ["'저는 ○○예요'는 わたしは ○○です(watashi wa ○○ desu, 와타시와 ○○데스)라고 해요. わたし는 '나, 저', です는 '~예요/이에요'라는 뜻이에요.", "여기서 は는 글자 이름은 '하'지만, '~은/는'이라는 뜻으로 쓸 때는 '와(wa)'라고 읽어요. 아주 중요한 규칙이에요!", "です의 す는 아주 약하게 소리 내서, '데스'보다 '데ㅅ'에 가깝게 들려요. 한국 이름은 보통 가타카나로 써요. 예를 들어 '미나'는 ミナ(mina, 미나)예요."], "figure": "가슴에 손을 얹고 자기 이름을 말하는 아이", "example": "わたしは ミナです。(watashi wa mina desu, 와타시와 미나데스) → 저는 미나예요.", "heading": "わたしは ~です 로 이름을 말해요"}, {"paras": ["나라 이름 뒤에 じん(jin, 징)을 붙이면 '○○ 사람'이 돼요. 한국 사람은 かんこくじん(kankokujin, 캉코쿠징), 일본 사람은 にほんじん(nihonjin, 니혼징)이에요.", "초등학생은 しょうがくせい(shougakusei, 쇼-가쿠세-)라고 해요. 앞에서 배운 です를 붙이면 바로 문장이 돼요."], "figure": "한국과 일본 국기를 든 두 아이", "example": "かんこくじんです。(kankokujin desu, 캉코쿠진데스) → 한국 사람이에요.", "heading": "어느 나라 사람인지, 몇 학년인지도 말해요"}, {"paras": ["자기소개가 끝나면 よろしくおねがいします(yoroshiku onegaishimasu, 요로시쿠 오네가이시마스)라고 말하고 고개를 살짝 숙여요. '잘 부탁합니다'라는 뜻이에요.", "친구 이름을 부를 때는 이름 뒤에 さん(san, 상)을 붙여요. 'ミナさん'처럼요. 하지만 내 이름에는 さん을 붙이지 않아요."], "figure": "고개를 살짝 숙여 인사하는 아이", "example": "はじめまして。わたしは ミナです。かんこくじんです。よろしくおねがいします。", "heading": "마지막은 よろしくおねがいします"}], "parent_tip": "부모님께: 아이들이 가장 많이 헷갈리는 것은 '~은/는'으로 쓰인 は를 '와'로 읽는 규칙입니다. 듣기 버튼으로 소리를 먼저 들려준 뒤, 부모님이 일본 친구 역할을 맡아 \"おなまえは？\"라고 묻고 아이가 세 문장으로 자기소개를 하게 해 보세요. 글자를 외우는 것보다 소리 내어 말해 보는 경험이 먼저입니다.", "expressions": [{"en": "はじめまして", "ko": "처음 뵙겠습니다", "note": "hajimemashite (하지메마시테)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (콘니치와)"}, {"en": "わたし", "ko": "나, 저", "note": "watashi (와타시)"}, {"en": "わたしは ミナです。", "ko": "저는 미나예요.", "note": "watashi wa mina desu (와타시와 미나데스)"}, {"en": "おなまえは？", "ko": "이름이 뭐예요?", "note": "onamae wa? (오나마에와?)"}, {"en": "かんこくじんです。", "ko": "한국 사람이에요.", "note": "kankokujin desu (캉코쿠진데스)"}, {"en": "にほんじん", "ko": "일본 사람", "note": "nihonjin (니혼징)"}, {"en": "しょうがくせいです。", "ko": "초등학생이에요.", "note": "shougakusei desu (쇼-가쿠세-데스)"}, {"en": "よろしくおねがいします。", "ko": "잘 부탁합니다.", "note": "yoroshiku onegaishimasu (요로시쿠 오네가이시마스)"}, {"en": "ミナさん", "ko": "미나 씨 (다른 사람 이름 뒤에 붙여요)", "note": "mina san (미나상)"}]}$j$::jsonb where slug='j5-01';
update public.lessons set content=$j${"quiz": [{"q": "내 손에 들고 있는 물건을 가리킬 때 쓰는 말은?", "answer": 0, "choices": ["これ", "それ", "あれ", "どれ"], "explain": "말하는 사람 가까이에 있는 물건은 これ(이것)예요."}, {"q": "これは なんですか。 의 뜻은?", "answer": 1, "choices": ["이것은 연필이에요.", "이것은 무엇이에요?", "저것은 어느 것이에요?", "그것은 책이에요?"], "explain": "なん은 '무엇', か는 질문이에요. '이것은 무엇이에요?'라는 뜻이에요."}, {"q": "멀리 하늘을 나는 새를 가리키며 '저것'이라고 할 때 쓰는 말은?", "answer": 2, "choices": ["これ", "それ", "あれ", "この"], "explain": "나와 친구 모두에게서 멀리 있으면 あれ(저것)예요."}, {"q": "A: これは ペンですか。 B: (펜이 아니라 연필이에요.) 알맞은 대답은?", "answer": 3, "choices": ["はい、そうです。", "これは ペンです。", "はい、ペンです。", "いいえ、ちがいます。"], "explain": "펜이 아니니까 いいえ、ちがいます(아니요, 달라요)라고 해요."}, {"q": "'이 책'을 일본어로 바르게 쓴 것은?", "answer": 1, "choices": ["これほん", "このほん", "それほん", "あのほん"], "explain": "물건 이름 앞에는 この를 붙여요. このほん은 '이 책', あのほん은 '저 책'이에요."}], "intro": "일본 문구점에서 귀여운 물건을 발견했어요. 손으로 가리키며 \"이건 뭐예요?\"라고 묻고 싶다면 어떻게 말할까요? 오늘은 물건을 가리키는 말 これ・それ・あれ를 배워요.", "summary": ["これ(이것)・それ(그것)・あれ(저것)・どれ(어느 것)는 거리에 따라 골라 써요.", "これは なんですか(코레와 난데스카)로 묻고, ~は ~です로 대답해요.", "맞으면 はい、そうです, 아니면 いいえ、ちがいます라고 해요."], "keywords": [{"word": "これ", "meaning": "이것 — 말하는 사람 가까이 (kore, 코레)"}, {"word": "それ", "meaning": "그것 — 듣는 사람 가까이 (sore, 소레)"}, {"word": "あれ", "meaning": "저것 — 둘 다에게서 멀리 (are, 아레)"}, {"word": "どれ", "meaning": "어느 것 (dore, 도레)"}, {"word": "なん", "meaning": "무엇 (nan, 낭)"}, {"word": "か", "meaning": "문장 끝에 붙여 질문을 만드는 말 (ka, 카)"}], "sections": [{"paras": ["내 가까이에 있는 물건은 これ(kore, 코레) '이것', 듣는 사람 가까이에 있는 물건은 それ(sore, 소레) '그것'이에요.", "둘 다에게서 멀리 있는 물건은 あれ(are, 아레) '저것'이고, '어느 것'을 물을 때는 どれ(dore, 도레)를 써요.", "앞 글자만 보면 こ(이)・そ(그)・あ(저)・ど(어느)예요. 한국어 '이・그・저・어느'와 똑같이 짝지어 외우면 쉬워요."], "figure": "책상 위 물건, 친구 손의 물건, 멀리 창밖 물건을 가리키는 세 장면", "example": "これ(코레) 이것 / それ(소레) 그것 / あれ(아레) 저것 / どれ(도레) 어느 것", "heading": "これ・それ・あれ・どれ"}, {"paras": ["'이것은 무엇이에요?'는 これは なんですか(kore wa nan desu ka, 코레와 난데스카)예요. なん은 '무엇', か는 문장 끝에 붙어서 질문을 만들어요.", "일본어는 질문 끝에도 보통 물음표 대신 마침표(。)를 찍어요. 말할 때는 끝을 살짝 올려요.", "여기서도 は는 '와'로 읽는다는 것, 잊지 않았죠?"], "figure": "아이가 신기한 물건을 들고 고개를 갸웃하는 모습", "example": "これは なんですか。(kore wa nan desu ka, 코레와 난데스카) → 이것은 무엇이에요?", "heading": "これは なんですか? 로 물어요"}, {"paras": ["친구가 내 손의 물건을 가리키며 それ(그것)라고 물으면, 그 물건은 내 가까이에 있으니 나는 これは ~です로 대답해요. 반대로 친구가 자기 손의 물건을 これ라고 물으면, 나는 それは ~です라고 해요.", "물건 이름은 ほん(hon, 홍) 책, かばん(kaban, 카방) 가방, えんぴつ(enpitsu, 엠피츠) 연필, ペン(pen, 펭) 펜 등이 있어요. ペン처럼 외국에서 온 말은 가타카나로 써요. ほんです처럼 ん 뒤에 で가 오면 ん이 'ㄴ'처럼 들려서 '혼데스'라고 읽어요."], "figure": "연필, 책, 가방, 펜이 놓인 책상", "example": "A: それは なんですか。 B: これは えんぴつです。 (그건 뭐예요? / 이건 연필이에요.)", "heading": "それは ~です 로 대답해요"}, {"paras": ["'이것은 펜이에요?'처럼 '예/아니요'로 답하는 질문도 있어요. 맞으면 はい、そうです(hai, sou desu, 하이 소-데스) '네, 그래요.'라고 해요.", "틀리면 いいえ、ちがいます(iie, chigaimasu, 이-에 치가이마스) '아니요, 달라요.'라고 해요."], "figure": "고개를 끄덕이는 아이와 고개를 젓는 아이", "example": "A: これは ペンですか。 B: いいえ、ちがいます。えんぴつです。", "heading": "はい・いいえ 로 대답해요"}, {"paras": ["물건 이름 앞에 붙여서 '이 ○○, 그 ○○, 저 ○○'라고 할 때는 この(kono, 코노)・その(sono, 소노)・あの(ano, 아노)를 써요.", "このほん은 '이 책', あのいぬ는 '저 개'예요. これ・それ・あれ는 혼자 쓰고, この・その・あの는 꼭 뒤에 물건 이름이 와요."], "figure": "", "example": "このかばんは わたしの かばんです。 (이 가방은 내 가방이에요.)", "heading": "この・その・あの + 물건"}], "parent_tip": "부모님께: 한국어의 '이・그・저・어느'와 일본어의 こ・そ・あ・ど가 거의 그대로 대응해서 한국 아이들이 쉽게 익히는 부분입니다. 다만 상대가 これ로 물으면 나는 それ로 답하는 '시점 바꾸기'를 헷갈려합니다. 집 안 물건을 아이 손, 부모님 손, 멀리 놓고 \"これは なんですか。\" 놀이를 해 보세요.", "expressions": [{"en": "これ", "ko": "이것", "note": "kore (코레)"}, {"en": "それ", "ko": "그것", "note": "sore (소레)"}, {"en": "あれ", "ko": "저것", "note": "are (아레)"}, {"en": "どれ", "ko": "어느 것", "note": "dore (도레)"}, {"en": "これは なんですか。", "ko": "이것은 무엇이에요?", "note": "kore wa nan desu ka (코레와 난데스카)"}, {"en": "それは ほんです。", "ko": "그것은 책이에요.", "note": "sore wa hon desu (소레와 혼데스)"}, {"en": "あれは ねこです。", "ko": "저것은 고양이예요.", "note": "are wa neko desu (아레와 네코데스)"}, {"en": "はい、そうです。", "ko": "네, 그래요.", "note": "hai, sou desu (하이, 소-데스)"}, {"en": "いいえ、ちがいます。", "ko": "아니요, 달라요.", "note": "iie, chigaimasu (이-에, 치가이마스)"}, {"en": "えんぴつ", "ko": "연필", "note": "enpitsu (엠피츠)"}, {"en": "かばん", "ko": "가방", "note": "kaban (카방)"}, {"en": "このほん", "ko": "이 책", "note": "kono hon (코노 홍)"}]}$j$::jsonb where slug='j5-02';
update public.lessons set content=$j${"quiz": [{"q": "일본어 숫자 ご(go, 고)는 얼마일까요?", "answer": 0, "choices": ["5", "2", "9", "7"], "explain": "いち・に・さん・よん・ご, 다섯 번째인 ご가 5예요."}, {"q": "なんさいですか。는 무엇을 묻는 말일까요?", "answer": 1, "choices": ["이름", "나이", "학년", "사는 곳"], "explain": "さい는 '~살'이에요. なんさい는 '몇 살'이에요."}, {"q": "'11살이에요.'를 일본어로 바르게 말한 것은?", "answer": 2, "choices": ["じゅういちさいです。", "いちじゅうさいです。", "じゅういっさいです。", "じゅうさいです。"], "explain": "11살은 소리가 바뀌어 じゅういっさい(주-잇사이)예요."}, {"q": "'6학년이에요.'를 일본어로 바르게 말한 것은?", "answer": 3, "choices": ["ろくさいです。", "ごねんせいです。", "なんねんせいですか。", "ろくねんせいです。"], "explain": "학년은 숫자 + ねんせい예요. 6은 ろく니까 ろくねんせいです예요."}, {"q": "8살은 일본어로 어떻게 말할까요?", "answer": 2, "choices": ["はちじ", "はちねんせい", "はっさい", "はっぴゃく"], "explain": "8살은 작은 っ가 들어가 はっさい(핫사이)예요. はちじ는 8시, はちねんせい는 8학년이에요."}], "intro": "새로 사귄 일본 친구가 나와 동갑인지 궁금해요. \"몇 살이야?\"라고 일본어로 물어볼 수 있다면 금방 더 친해질 수 있겠죠? 오늘은 숫자와 함께 나이를 묻고 답하는 법을 배워요.", "summary": ["일본어 숫자: いち・に・さん・よん・ご・ろく・なな・はち・きゅう・じゅう", "나이는 숫자 + さい, 묻는 말은 なんさいですか(난사이데스카)예요.", "1살 いっさい, 8살 はっさい, 10살 じゅっさい, 11살 じゅういっさい처럼 작은 っ가 들어가는 나이를 조심해요."], "keywords": [{"word": "さい", "meaning": "나이를 셀 때 숫자 뒤에 붙이는 말 (sai, 사이) — '~살'"}, {"word": "なんさい", "meaning": "몇 살 (nansai, 난사이)"}, {"word": "작은 っ", "meaning": "잠깐 멈추는 소리. いっさい(잇사이)처럼 읽어요"}, {"word": "ねんせい", "meaning": "~학년 (nensei, 넨세-)"}], "sections": [{"paras": ["일본어 숫자는 いち(ichi, 이치) 1, に(ni, 니) 2, さん(san, 상) 3, よん(yon, 용) 4, ご(go, 고) 5예요.", "이어서 ろく(roku, 로쿠) 6, なな(nana, 나나) 7, はち(hachi, 하치) 8, きゅう(kyuu, 큐-) 9, じゅう(juu, 주-) 10이에요. 4는 し, 7은 しち라고도 하지만 오늘은 よん과 なな를 써요.", "11은 じゅういち(10+1), 12는 じゅうに(10+2)처럼 10 뒤에 숫자를 붙이면 돼요."], "figure": "손가락으로 1부터 10까지 세는 두 손", "example": "1 いち · 2 に · 3 さん · 4 よん · 5 ご · 6 ろく · 7 なな · 8 はち · 9 きゅう · 10 じゅう", "heading": "1부터 10까지 세어 봐요"}, {"paras": ["나이를 셀 때는 숫자 뒤에 さい(sai, 사이)를 붙여요. '몇 살'은 なんさい(nansai, 난사이)예요.", "'몇 살이에요?'는 なんさいですか(nansai desu ka, 난사이데스카)라고 물어요. 친구 이름을 넣어 ユナさんは なんさいですか。라고 물을 수도 있어요."], "figure": "생일 케이크 앞에서 촛불을 세는 아이", "example": "なんさいですか。(nansai desu ka, 난사이데스카) → 몇 살이에요?", "heading": "なんさいですか? 몇 살이에요?"}, {"paras": ["몇몇 나이는 소리가 조금 바뀌어요. 1살은 いっさい(issai, 잇사이), 8살은 はっさい(hassai, 핫사이), 10살은 じゅっさい(jussai, 줏사이)예요.", "작게 쓴 っ는 '잠깐 멈추는 소리'예요. 한국어 받침 'ㅅ'처럼 짧게 끊었다가 다음 글자를 읽어요.", "그래서 11살은 じゅういっさい(juuissai, 주-잇사이), 12살은 じゅうにさい(juunisai, 주-니사이)예요."], "figure": "", "example": "11さい じゅういっさい(주-잇사이) / 12さい じゅうにさい(주-니사이)", "heading": "작은 っ 가 들어가는 나이"}, {"paras": ["대답은 나이 뒤에 です를 붙이면 돼요. 11살이면 じゅういっさいです(주-잇사이데스), 12살이면 じゅうにさいです(주-니사이데스)예요.", "학년을 말하고 싶으면 숫자 뒤에 ねんせい(nensei, 넨세-)를 붙여요. 5학년은 ごねんせい(gonensei, 고넨세-), 6학년은 ろくねんせい(rokunensei, 로쿠넨세-)예요."], "figure": "가방을 멘 초등학생 두 명이 이야기하는 모습", "example": "A: なんさいですか。 B: じゅうにさいです。ろくねんせいです。 (12살이에요. 6학년이에요.)", "heading": "じゅういっさいです 로 대답해요"}], "parent_tip": "부모님께: 숫자 자체보다 1・8・10살처럼 작은 っ(촉음)가 생기는 소리 변화를 아이가 어려워합니다. 가족의 나이를 하나씩 일본어로 말해 보는 놀이가 좋습니다. 다만 어른 나이(예: 40살 よんじゅっさい)는 숫자가 길어지니, 아이 또래 나이와 학년 중심으로 연습해 주세요.", "expressions": [{"en": "なんさいですか。", "ko": "몇 살이에요?", "note": "nansai desu ka (난사이데스카)"}, {"en": "じゅういっさいです。", "ko": "11살이에요.", "note": "juuissai desu (주-잇사이데스)"}, {"en": "じゅうにさいです。", "ko": "12살이에요.", "note": "juunisai desu (주-니사이데스)"}, {"en": "いっさい", "ko": "1살", "note": "issai (잇사이)"}, {"en": "はっさい", "ko": "8살", "note": "hassai (핫사이)"}, {"en": "じゅっさい", "ko": "10살", "note": "jussai (줏사이)"}, {"en": "ごねんせいです。", "ko": "5학년이에요.", "note": "gonensei desu (고넨세-데스)"}, {"en": "ろくねんせいです。", "ko": "6학년이에요.", "note": "rokunensei desu (로쿠넨세-데스)"}, {"en": "いち、に、さん、よん、ご", "ko": "1, 2, 3, 4, 5", "note": "ichi, ni, san, yon, go (이치, 니, 상, 용, 고)"}, {"en": "ろく、なな、はち、きゅう、じゅう", "ko": "6, 7, 8, 9, 10", "note": "roku, nana, hachi, kyuu, juu (로쿠, 나나, 하치, 큐-, 주-)"}]}$j$::jsonb where slug='j5-03';
update public.lessons set content=$j${"quiz": [{"q": "すきです。의 뜻은?", "answer": 0, "choices": ["좋아해요.", "싫어해요.", "먹어요.", "몰라요."], "explain": "すき는 '좋아함', です는 '~해요'예요."}, {"q": "'고양이를 좋아해요.'에서 ねこ 뒤에 들어갈 말은?\nねこ[  ] すきです。", "answer": 1, "choices": ["を", "が", "は", "も"], "explain": "좋아하는 대상 뒤에는 が를 붙여요. ねこが すきです예요."}, {"q": "친구가 \"なにが すきですか。\"라고 물었어요. 알맞은 대답은?", "answer": 2, "choices": ["じゅうにさいです。", "はじめまして。", "サッカーが すきです。", "これは ほんです。"], "explain": "무엇을 좋아하는지 물었으니 '○○が すきです'로 대답해요."}, {"q": "'나도 좋아해요.'를 일본어로 바르게 쓴 것은?", "answer": 3, "choices": ["わたしは すきです。", "わたしが すきです。", "だいすきです。", "わたしも すきです。"], "explain": "'~도'는 も예요. わたしも すきです예요."}, {"q": "사과를 '아주' 좋아할 때 알맞은 말은?", "answer": 1, "choices": ["りんごが きらいです。", "りんごが だいすきです。", "りんごが あまり すきじゃないです。", "りんごは なんですか。"], "explain": "だいすき는 '아주 좋아함'이에요."}], "intro": "일본 친구와 좋아하는 것이 같다면 금방 친해질 수 있어요. \"나는 고양이를 좋아해!\", \"너는 뭘 좋아해?\" 오늘은 좋아하는 것을 묻고 답하는 말 すきです를 배워요.", "summary": ["'○○을 좋아해요'는 ○○が すきです(가 스키데스)예요. を가 아니라 が를 써요.", "なにが すきですか(나니가 스키데스카)로 묻고, 같으면 わたしも すきです라고 해요.", "아주 좋아하면 だいすきです, 별로면 あまり すきじゃないです라고 해요."], "keywords": [{"word": "すき", "meaning": "좋아함 (suki, 스키)"}, {"word": "が", "meaning": "좋아하는 대상 뒤에 붙는 말 (ga, 가). '~을/를'처럼 해석해요"}, {"word": "なに", "meaning": "무엇 (nani, 나니)"}, {"word": "も", "meaning": "~도 (mo, 모)"}, {"word": "ー", "meaning": "가타카나에서 앞 소리를 길게 늘이는 표시"}], "sections": [{"paras": ["'○○을 좋아해요'는 ○○が すきです(ga suki desu, 가 스키데스)라고 해요. すき는 '좋아함', が는 좋아하는 대상 뒤에 붙어요.", "한국어는 '고양이를 좋아해요'라고 '을/를'을 쓰지만, 일본어는 を가 아니라 が를 쓰는 것이 특징이에요.", "すき의 す도 약하게 소리 내서 '스키'의 '스'가 거의 들리지 않아요."], "figure": "고양이를 꼭 안고 웃는 아이", "example": "ねこが すきです。(neko ga suki desu, 네코가 스키데스) → 고양이를 좋아해요.", "heading": "~が すきです 좋아해요"}, {"paras": ["음식: すし(sushi, 스시) 초밥, りんご(ringo, 링고) 사과, アイスクリーム(aisukuriimu, 아이스쿠리-무) 아이스크림", "활동: サッカー(sakkaa, 삿카-) 축구, ゲーム(geemu, 게-무) 게임, おんがく(ongaku, 옹가쿠) 음악", "가타카나 낱말에 있는 ー는 앞 소리를 길게 늘이라는 표시예요. サッカー는 '삿카아'처럼 끝을 길게 읽어요."], "figure": "축구공, 사과, 게임기, 아이스크림이 놓인 테이블", "example": "サッカーが すきです。(sakkaa ga suki desu, 삿카-가 스키데스) → 축구를 좋아해요.", "heading": "좋아하는 것을 말해 봐요"}, {"paras": ["상대에게 묻고 싶으면 なにが すきですか(nani ga suki desu ka, 나니가 스키데스카)라고 해요. なに는 '무엇'이에요.", "친구가 나와 같은 것을 좋아한다면 わたしも すきです(watashi mo suki desu, 와타시모 스키데스) '나도 좋아해요'라고 말해요. も는 '~도'라는 뜻이에요."], "figure": "두 아이가 하이파이브하는 모습", "example": "A: なにが すきですか。 B: ゲームが すきです。 A: わたしも すきです！", "heading": "なにが すきですか? 뭘 좋아해요?"}, {"paras": ["정말 정말 좋아하면 だいすきです(daisuki desu, 다이스키데스) '아주 좋아해요'라고 해요.", "별로 좋아하지 않을 때는 あまり すきじゃないです(amari suki ja nai desu, 아마리 스키자나이데스) '별로 안 좋아해요'라고 해요.", "きらいです(kirai desu, 키라이데스)는 '싫어해요'라는 뜻인데, 조금 강하게 들릴 수 있어서 친구에게는 あまり すきじゃないです가 더 부드러워요."], "figure": "하트를 그린 손과 고개를 젓는 손", "example": "りんごが だいすきです。 (사과를 아주 좋아해요.)", "heading": "아주 좋아하면 だいすき, 별로면 すきじゃない"}], "parent_tip": "부모님께: 한국어 '~을 좋아해요'에 끌려 아이들이 を를 쓰기 쉬운데, すき 앞에는 が를 씁니다. 아이가 좋아하는 음식·놀이를 가타카나 낱말과 함께 말해 보게 하고, 부모님이 \"なにが すきですか。\"라고 묻고 아이가 답하는 놀이를 해 보세요. 가타카나의 장음 표시 ー를 길게 읽는지도 들어 봐 주세요.", "expressions": [{"en": "すきです。", "ko": "좋아해요.", "note": "suki desu (스키데스)"}, {"en": "ねこが すきです。", "ko": "고양이를 좋아해요.", "note": "neko ga suki desu (네코가 스키데스)"}, {"en": "なにが すきですか。", "ko": "무엇을 좋아해요?", "note": "nani ga suki desu ka (나니가 스키데스카)"}, {"en": "わたしも すきです。", "ko": "나도 좋아해요.", "note": "watashi mo suki desu (와타시모 스키데스)"}, {"en": "だいすきです。", "ko": "아주 좋아해요.", "note": "daisuki desu (다이스키데스)"}, {"en": "あまり すきじゃないです。", "ko": "별로 안 좋아해요.", "note": "amari suki ja nai desu (아마리 스키자나이데스)"}, {"en": "きらいです。", "ko": "싫어해요.", "note": "kirai desu (키라이데스)"}, {"en": "サッカー", "ko": "축구", "note": "sakkaa (삿카-)"}, {"en": "ゲーム", "ko": "게임", "note": "geemu (게-무)"}, {"en": "すし", "ko": "초밥", "note": "sushi (스시)"}, {"en": "りんご", "ko": "사과", "note": "ringo (링고)"}, {"en": "アイスクリーム", "ko": "아이스크림", "note": "aisukuriimu (아이스쿠리-무)"}]}$j$::jsonb where slug='j5-04';
update public.lessons set content=$j${"quiz": [{"q": "いま なんじですか。의 뜻은?", "answer": 0, "choices": ["지금 몇 시예요?", "오늘은 무슨 요일이에요?", "몇 살이에요?", "지금 어디예요?"], "explain": "いま는 '지금', なんじ는 '몇 시'예요."}, {"q": "'4시'를 일본어로 바르게 말한 것은?", "answer": 1, "choices": ["よんじ", "よじ", "しじ", "よっじ"], "explain": "4시는 특별하게 よじ(요지)라고 해요."}, {"q": "すいようび는 무슨 요일일까요?", "answer": 2, "choices": ["월요일", "화요일", "수요일", "목요일"], "explain": "水(すい)는 '물 수' 자, すいようび는 수요일이에요."}, {"q": "'7시 반'을 일본어로 바르게 말한 것은?", "answer": 3, "choices": ["はちじはん", "しちじ", "はんしちじ", "しちじはん"], "explain": "7시는 しちじ, 반은 はん이에요. 그래서 しちじはん이에요."}, {"q": "오늘이 금요일이면, あした(내일)는 무슨 요일일까요?", "answer": 1, "choices": ["にちようび", "どようび", "もくようび", "げつようび"], "explain": "금요일 다음 날은 토요일, どようび예요."}], "intro": "일본 친구와 놀기로 약속했어요. \"몇 시에 만날까?\", \"토요일 어때?\" 시간과 요일을 말할 수 있어야 약속을 잡을 수 있겠죠? 오늘은 일본어로 시간과 요일을 말하는 법을 배워요.", "summary": ["시간은 숫자 + じ. 4시 よじ, 7시 しちじ, 9시 くじ는 특별해요. 30분은 はん이에요.", "요일은 月(げつ)・火(か)・水(すい)・木(もく)・金(きん)・土(ど)・日(にち) + ようび, 한국어와 순서가 같아요.", "いま なんじですか(몇 시?), きょうは なんようびですか(무슨 요일?)로 물어요."], "keywords": [{"word": "じ", "meaning": "~시 (ji, 지)"}, {"word": "はん", "meaning": "반, 30분 (han, 항)"}, {"word": "ようび", "meaning": "요일 (youbi, 요-비)"}, {"word": "いま", "meaning": "지금 (ima, 이마)"}, {"word": "きょう・あした・きのう", "meaning": "오늘・내일・어제"}], "sections": [{"paras": ["시간을 말할 때는 숫자 뒤에 じ(ji, 지)를 붙여요. 1시는 いちじ(ichiji, 이치지), 3시는 さんじ(sanji, 산지)예요.", "'지금 몇 시예요?'는 いま なんじですか(ima nanji desu ka, 이마 난지데스카)예요. いま는 '지금', なんじ는 '몇 시'예요."], "figure": "벽시계가 3시를 가리키는 거실", "example": "A: いま なんじですか。 B: さんじです。 (지금 몇 시예요? / 3시예요.)", "heading": "いま なんじですか? 지금 몇 시예요?"}, {"paras": ["대부분은 숫자 + じ지만, 세 개는 특별해요. 4시는 よじ(yoji, 요지), 7시는 しちじ(shichiji, 시치지), 9시는 くじ(kuji, 쿠지)예요.", "'반', 즉 30분은 はん(han, 항)이에요. 3시 반은 さんじはん(sanjihan, 산지항)이에요."], "figure": "아침 7시 반을 가리키는 알람시계", "example": "4시 よじ · 7시 しちじ · 9시 くじ / 7시 반 しちじはん", "heading": "조심해야 할 시간 세 개"}, {"paras": ["일본어 요일 이름은 한국어처럼 '월・화・수・목・금・토・일'을 뜻하는 한자를 써요. 뒤에 ようび(youbi, 요-비)를 붙이면 '요일'이에요.", "月(げつ) 월요일 げつようび(getsuyoubi, 게츠요-비), 火(か) 화요일 かようび(kayoubi, 카요-비), 水(すい) 수요일 すいようび(suiyoubi, 스이요-비), 木(もく) 목요일 もくようび(mokuyoubi, 모쿠요-비)", "金(きん) 금요일 きんようび(kin'youbi, 킨요-비), 土(ど) 토요일 どようび(doyoubi, 도요-비), 日(にち) 일요일 にちようび(nichiyoubi, 니치요-비)예요."], "figure": "월요일부터 일요일까지 칸이 있는 달력 한 줄", "example": "月(げつ)・火(か)・水(すい)・木(もく)・金(きん)・土(ど)・日(にち) + ようび", "heading": "요일은 한국어와 똑같은 순서!"}, {"paras": ["きょう(kyou, 쿄-)는 '오늘', あした(ashita, 아시타)는 '내일', きのう(kinou, 키노-)는 '어제'예요.", "'무슨 요일'은 なんようび(nan'youbi, 난요-비)예요. 대답은 요일 뒤에 です를 붙이면 돼요."], "figure": "금요일에 동그라미를 친 달력", "example": "A: きょうは なんようびですか。 B: きんようびです。 (오늘은 무슨 요일이에요? / 금요일이에요.)", "heading": "きょうは なんようびですか? 오늘은 무슨 요일이에요?"}], "parent_tip": "부모님께: 요일은 한자 뜻이 한국어와 같아 아이들이 금방 익힙니다. 반대로 4시(よじ)・7시(しちじ)・9시(くじ)는 숫자 읽기와 달라 자주 틀리니, 집 시계를 보며 하루에 한두 번 \"いま なんじですか。\"라고 물어봐 주세요. 이 단원에서는 '몇 분'은 다루지 않고 정각과 반(はん)만 연습합니다.", "expressions": [{"en": "いま なんじですか。", "ko": "지금 몇 시예요?", "note": "ima nanji desu ka (이마 난지데스카)"}, {"en": "さんじです。", "ko": "3시예요.", "note": "sanji desu (산지데스)"}, {"en": "よじ", "ko": "4시", "note": "yoji (요지)"}, {"en": "しちじはん", "ko": "7시 반", "note": "shichijihan (시치지항)"}, {"en": "くじ", "ko": "9시", "note": "kuji (쿠지)"}, {"en": "きょうは なんようびですか。", "ko": "오늘은 무슨 요일이에요?", "note": "kyou wa nan'youbi desu ka (쿄-와 난요-비데스카)"}, {"en": "げつようび", "ko": "월요일", "note": "getsuyoubi (게츠요-비)"}, {"en": "すいようび", "ko": "수요일", "note": "suiyoubi (스이요-비)"}, {"en": "きんようび", "ko": "금요일", "note": "kin'youbi (킨요-비)"}, {"en": "どようび", "ko": "토요일", "note": "doyoubi (도요-비)"}, {"en": "にちようび", "ko": "일요일", "note": "nichiyoubi (니치요-비)"}, {"en": "あした", "ko": "내일", "note": "ashita (아시타)"}]}$j$::jsonb where slug='j5-05';
update public.lessons set content=$j${"quiz": [{"q": "'라멘 주세요.'를 일본어로 바르게 말한 것은?", "answer": 0, "choices": ["ラーメンを ください。", "ラーメンが すきです。", "ラーメンは なんですか。", "ラーメンです。"], "explain": "'○○ 주세요'는 ○○を ください예요."}, {"q": "가게 직원이 손님에게 하는 いらっしゃいませ의 뜻은?", "answer": 1, "choices": ["잘 먹었습니다.", "어서 오세요.", "얼마예요?", "맛있어요."], "explain": "いらっしゃいませ는 '어서 오세요'예요."}, {"q": "'우동과 차'에서 '~과'에 해당하는 말은?\nうどん[  ] おちゃ", "answer": 2, "choices": ["を", "が", "と", "も"], "explain": "두 가지를 이을 때는 と를 써요."}, {"q": "밥을 먹기 __전에__ 하는 인사는?", "answer": 3, "choices": ["ごちそうさまでした", "すみません", "いらっしゃいませ", "いただきます"], "explain": "먹기 전에는 いただきます, 먹은 뒤에는 ごちそうさまでした예요."}, {"q": "おにぎりを ふたつ ください。는 무슨 뜻일까요?", "answer": 1, "choices": ["주먹밥 세 개 주세요.", "주먹밥 두 개 주세요.", "주먹밥 한 개 주세요.", "주먹밥을 좋아해요."], "explain": "ふたつ는 '두 개'예요."}], "intro": "일본 여행 중 라멘 가게에 들어갔어요. 맛있는 라멘을 먹으려면 주문을 해야겠죠? 오늘은 \"○○ 주세요!\"라고 말하는 ~を ください를 배워요.", "summary": ["'○○ 주세요'는 ○○を ください(오 쿠다사이)예요. を는 '오'로 읽어요.", "두 가지는 と로 잇고, 개수 ひとつ・ふたつ・みっつ는 ください 앞에 넣어요.", "먹기 전 いただきます, 먹은 뒤 ごちそうさまでした라고 인사해요."], "keywords": [{"word": "ください", "meaning": "주세요 (kudasai, 쿠다사이)"}, {"word": "を", "meaning": "'~을/를'. 소리는 お와 같은 '오(o)'"}, {"word": "と", "meaning": "'~와/과' (to, 토). 두 가지를 이어요"}, {"word": "ひとつ・ふたつ・みっつ", "meaning": "한 개・두 개・세 개"}, {"word": "いただきます", "meaning": "잘 먹겠습니다 (먹기 전 인사)"}], "sections": [{"paras": ["일본 가게에 들어가면 직원이 いらっしゃいませ(irasshaimase, 이랏샤이마세)라고 말해요. '어서 오세요'라는 뜻이에요.", "직원을 부를 때는 손을 살짝 들고 すみません(sumimasen, 스미마셍)이라고 해요. '저기요'라는 뜻으로 쓸 수 있어요."], "figure": "식당 입구에서 인사하는 직원과 손을 든 아이", "example": "てんいん(직원): いらっしゃいませ。 / わたし: すみません、メニューを ください。", "heading": "가게에 들어가면 いらっしゃいませ"}, {"paras": ["'○○ 주세요'는 ○○を ください(o kudasai, 오 쿠다사이)라고 해요. ください는 '주세요'예요.", "を는 글자 이름이 '오'이고, 소리도 お와 똑같이 '오(o)'예요. 물건 뒤에 붙여서 '~을/를'이라는 뜻이 돼요."], "figure": "김이 나는 라멘 한 그릇", "example": "ラーメンを ください。(raamen o kudasai, 라-멩오 쿠다사이) → 라멘 주세요.", "heading": "~を ください ○○ 주세요"}, {"paras": ["음식: ラーメン(raamen, 라-멩) 라멘, うどん(udon, 우동) 우동, カレー(karee, 카레-) 카레, おにぎり(onigiri, 오니기리) 주먹밥", "마실 것: おみず(omizu, 오미즈) 물, おちゃ(ocha, 오차) 차, ジュース(juusu, 주-스) 주스", "두 가지를 함께 시킬 때는 と(to, 토) '~와/과'로 이어요. うどんと おちゃを ください는 '우동과 차 주세요'예요."], "figure": "우동, 카레, 주먹밥, 주스가 놓인 식탁", "example": "カレーと ジュースを ください。 (카레와 주스 주세요.)", "heading": "메뉴 이름을 알아봐요"}, {"paras": ["개수를 말할 때는 ひとつ(hitotsu, 히토츠) 한 개, ふたつ(futatsu, 후타츠) 두 개, みっつ(mittsu, 밋츠) 세 개를 써요.", "개수는 ください 바로 앞에 넣어요. 'ラーメンを ふたつ ください'는 '라멘 두 개 주세요'예요."], "figure": "주먹밥 세 개가 놓인 접시", "example": "おにぎりを みっつ ください。(onigiri o mittsu kudasai, 오니기리오 밋츠 쿠다사이) → 주먹밥 세 개 주세요.", "heading": "몇 개인지도 말해요"}, {"paras": ["먹기 전에는 두 손을 모으고 いただきます(itadakimasu, 이타다키마스) '잘 먹겠습니다'라고 해요.", "다 먹은 뒤에는 ごちそうさまでした(gochisousama deshita, 고치소-사마데시타) '잘 먹었습니다'라고 해요. 맛있으면 おいしい(oishii, 오이시-) '맛있다'라고 말해 봐요!"], "figure": "두 손을 모으고 식사 인사를 하는 아이", "example": "いただきます。 → (냠냠) おいしい！ → ごちそうさまでした。", "heading": "먹기 전과 먹은 뒤의 인사"}], "parent_tip": "부모님께: を는 '워'가 아니라 お와 같은 '오' 소리로 읽습니다. 집에서 식사할 때 아이가 \"おみずを ください。\"로 물을 달라고 하거나, 식사 전후 인사를 일본어로 해 보는 것만으로도 금방 익숙해집니다. 숫자 ひとつ・ふたつ・みっつ는 앞에서 배운 いち・に・さん과 다른 '개수 세기'라는 점을 짚어 주세요.", "expressions": [{"en": "いらっしゃいませ。", "ko": "어서 오세요. (가게 직원이 하는 말)", "note": "irasshaimase (이랏샤이마세)"}, {"en": "すみません。", "ko": "저기요. / 죄송합니다.", "note": "sumimasen (스미마셍)"}, {"en": "ラーメンを ください。", "ko": "라멘 주세요.", "note": "raamen o kudasai (라-멩오 쿠다사이)"}, {"en": "おみずを ください。", "ko": "물 주세요.", "note": "omizu o kudasai (오미즈오 쿠다사이)"}, {"en": "うどんと おちゃを ください。", "ko": "우동과 차 주세요.", "note": "udon to ocha o kudasai (우동토 오차오 쿠다사이)"}, {"en": "ひとつ", "ko": "한 개", "note": "hitotsu (히토츠)"}, {"en": "ふたつ", "ko": "두 개", "note": "futatsu (후타츠)"}, {"en": "みっつ", "ko": "세 개", "note": "mittsu (밋츠)"}, {"en": "いただきます。", "ko": "잘 먹겠습니다.", "note": "itadakimasu (이타다키마스)"}, {"en": "ごちそうさまでした。", "ko": "잘 먹었습니다.", "note": "gochisousama deshita (고치소-사마데시타)"}, {"en": "おいしい！", "ko": "맛있다!", "note": "oishii (오이시-)"}]}$j$::jsonb where slug='j5-06';
update public.lessons set content=$j${"quiz": [{"q": "いくらですか。의 뜻은?", "answer": 0, "choices": ["얼마예요?", "몇 살이에요?", "몇 시예요?", "무엇이에요?"], "explain": "いくら는 '얼마'예요."}, {"q": "ごひゃくえん은 얼마일까요?", "answer": 1, "choices": ["50엔", "500엔", "5000엔", "150엔"], "explain": "ご(5) + ひゃく(100) = 500, ごひゃくえん은 500엔이에요."}, {"q": "'300엔'을 일본어로 바르게 말한 것은?", "answer": 2, "choices": ["さんひゃくえん", "さんぜんえん", "さんびゃくえん", "さんじゅうえん"], "explain": "300은 소리가 바뀌어 さんびゃく예요."}, {"q": "물건이 너무 비쌀 때 하는 말은?", "answer": 3, "choices": ["やすい", "おいしい", "すき", "たかい"], "explain": "たかい는 '비싸다', やすい는 '싸다'예요."}, {"q": "100엔짜리 지우개 2개를 샀어요. 전부 얼마일까요?", "answer": 1, "choices": ["ひゃくえん", "にひゃくえん", "さんびゃくえん", "せんえん"], "explain": "100 × 2 = 200, にひゃくえん이에요."}], "intro": "일본 문구점에서 귀여운 지우개를 발견했어요. 값이 얼마인지 궁금할 때는 어떻게 물어볼까요? 오늘은 값을 묻는 いくら와 일본 돈 えん(엥)을 세는 법을 배워요.", "summary": ["값은 いくらですか(이쿠라데스카)로 묻고, ○○えんです로 대답해요.", "100은 ひゃく, 1000은 せん. 300 さんびゃく, 600 ろっぴゃく, 800 はっぴゃく는 소리가 바뀌어요.", "사고 싶으면 これを ください, 비싸면 たかい, 싸면 やすい라고 해요."], "keywords": [{"word": "いくら", "meaning": "얼마 (ikura, 이쿠라)"}, {"word": "えん", "meaning": "일본 돈의 단위, 엔 (en)"}, {"word": "ひゃく・せん", "meaning": "100(hyaku, 햐쿠)・1000(sen, 셍)"}, {"word": "たかい・やすい", "meaning": "비싸다(takai, 타카이)・싸다(yasui, 야스이)"}, {"word": "ぜんぶで", "meaning": "전부 해서, 모두 합쳐서 (zenbu de, 젬부데)"}], "sections": [{"paras": ["값을 물을 때는 いくらですか(ikura desu ka, 이쿠라데스카)라고 해요. いくら는 '얼마'라는 뜻이에요.", "물건을 가리키며 これは いくらですか(코레와 이쿠라데스카)라고 하면 '이것은 얼마예요?'가 돼요. 앞에서 배운 これ・それ・あれ를 함께 써 보세요."], "figure": "지우개를 들고 직원에게 묻는 아이", "example": "これは いくらですか。(kore wa ikura desu ka, 코레와 이쿠라데스카) → 이것은 얼마예요?", "heading": "これは いくらですか? 이건 얼마예요?"}, {"paras": ["일본 돈의 단위는 えん(en, 엥)이에요. 숫자 뒤에 えん을 붙여요.", "100은 ひゃく(hyaku, 햐쿠), 1000은 せん(sen, 셍)이에요. 그래서 100엔은 ひゃくえん(햐쿠엥), 1000엔은 せんえん(센엥)이에요."], "figure": "동전과 지폐가 놓인 작은 접시", "example": "ひゃくえん(100엔) · ごひゃくえん(500엔) · せんえん(1000엔)", "heading": "일본 돈은 えん(엥)"}, {"paras": ["200 にひゃく(nihyaku, 니햐쿠), 400 よんひゃく(yonhyaku, 용햐쿠), 500 ごひゃく(gohyaku, 고햐쿠), 700 ななひゃく(nanahyaku, 나나햐쿠), 900 きゅうひゃく(kyuuhyaku, 큐-햐쿠)는 숫자 + ひゃく예요.", "하지만 300은 さんびゃく(sanbyaku, 삼뱌쿠), 600은 ろっぴゃく(roppyaku, 롯퍄쿠), 800은 はっぴゃく(happyaku, 핫퍄쿠)로 소리가 바뀌어요.", "150처럼 10 단위가 붙으면 뒤에 이어 말해요. 50은 ごじゅう(gojuu, 고주-)니까 150엔은 ひゃくごじゅうえん(햐쿠고주-엥)이에요."], "figure": "", "example": "300 さんびゃく · 600 ろっぴゃく · 800 はっぴゃく / 150えん ひゃくごじゅうえん", "heading": "100 단위 숫자, 소리가 바뀌는 것 조심!"}, {"paras": ["직원은 ○○えんです라고 대답해요. 사고 싶으면 앞에서 배운 ~を ください를 써서 これを ください(코레오 쿠다사이) '이거 주세요'라고 해요.", "값이 비싸면 たかい(takai, 타카이), 싸면 やすい(yasui, 야스이)라고 해요. 여러 개를 사면 ぜんぶで いくらですか(zenbu de ikura desu ka, 젬부데 이쿠라데스카) '전부 얼마예요?'라고 물어요."], "figure": "계산대 위에 지우개와 연필이 놓인 문구점", "example": "A: これは いくらですか。 B: ひゃくえんです。 A: やすい！ これを ください。", "heading": "대답을 듣고 사기"}], "parent_tip": "부모님께: 100 단위의 소리 변화(さんびゃく・ろっぴゃく・はっぴゃく)는 일본 아이들도 따로 외우는 부분이니 천천히 반복해 주세요. 집에 있는 물건에 100엔, 300엔처럼 가격표를 붙이고 가게 놀이를 하면 いくらですか → ○○えんです → これを ください 흐름을 자연스럽게 연습할 수 있습니다. 환율은 자주 바뀌므로 원화 환산은 다루지 않았습니다.", "expressions": [{"en": "いくらですか。", "ko": "얼마예요?", "note": "ikura desu ka (이쿠라데스카)"}, {"en": "これは いくらですか。", "ko": "이것은 얼마예요?", "note": "kore wa ikura desu ka (코레와 이쿠라데스카)"}, {"en": "ひゃくえんです。", "ko": "100엔이에요.", "note": "hyakuen desu (햐쿠엔데스)"}, {"en": "さんびゃくえん", "ko": "300엔", "note": "sanbyakuen (삼뱌쿠엥)"}, {"en": "ろっぴゃくえん", "ko": "600엔", "note": "roppyakuen (롯퍄쿠엥)"}, {"en": "はっぴゃくえん", "ko": "800엔", "note": "happyakuen (핫퍄쿠엥)"}, {"en": "せんえん", "ko": "1000엔", "note": "sen'en (센엥)"}, {"en": "ひゃくごじゅうえん", "ko": "150엔", "note": "hyakugojuuen (햐쿠고주-엥)"}, {"en": "これを ください。", "ko": "이거 주세요.", "note": "kore o kudasai (코레오 쿠다사이)"}, {"en": "たかい", "ko": "비싸다", "note": "takai (타카이)"}, {"en": "やすい", "ko": "싸다", "note": "yasui (야스이)"}, {"en": "ぜんぶで いくらですか。", "ko": "전부 얼마예요?", "note": "zenbu de ikura desu ka (젬부데 이쿠라데스카)"}]}$j$::jsonb where slug='j5-07';
update public.lessons set content=$j${"quiz": [{"q": "どこですか。의 뜻은?", "answer": 0, "choices": ["어디예요?", "얼마예요?", "몇 시예요?", "무엇이에요?"], "explain": "どこ는 '어디'예요."}, {"q": "'저기'를 일본어로 바르게 쓴 것은?", "answer": 1, "choices": ["あこ", "あそこ", "あれ", "あの"], "explain": "장소 '저기'는 あそこ예요. あれ는 '저것'이에요."}, {"q": "'역은 어디예요?'를 일본어로 바르게 말한 것은?", "answer": 2, "choices": ["えきは なんですか。", "えきは いくらですか。", "えきは どこですか。", "えきが すきです。"], "explain": "장소를 물을 때는 ~は どこですか예요."}, {"q": "つくえの うえ는 어디일까요?", "answer": 3, "choices": ["책상 아래", "책상 안", "책상 옆", "책상 위"], "explain": "うえ는 '위'예요. の는 '~의'예요."}, {"q": "びょういん(byouin)은 어떤 곳일까요?", "answer": 0, "choices": ["병원", "미용실", "공원", "학교"], "explain": "びょういん은 병원이에요. 미용실 びよういん과 헷갈리지 않게 조심해요."}], "intro": "일본 여행 중 화장실이 급해졌어요! 이럴 때 \"화장실이 어디예요?\"라고 물을 수 있다면 정말 든든하겠죠? 오늘은 장소를 묻는 どこ와 위치를 말하는 법을 배워요.", "summary": ["장소는 ここ(여기)・そこ(거기)・あそこ(저기)・どこ(어디)로 말해요.", "'○○은 어디예요?'는 ○○は どこですか(와 도코데스카)예요.", "위치는 ○○の うえ/した/なか/となり, 방향은 みぎ・ひだり로 말해요."], "keywords": [{"word": "どこ", "meaning": "어디 (doko, 도코)"}, {"word": "ここ・そこ・あそこ", "meaning": "여기・거기・저기"}, {"word": "の", "meaning": "~의 (no, 노). つくえの うえ = 책상 위"}, {"word": "うえ・した・なか・となり", "meaning": "위・아래・안・옆"}, {"word": "みぎ・ひだり", "meaning": "오른쪽・왼쪽"}], "sections": [{"paras": ["앞에서 배운 これ・それ・あれ・どれ 기억나요? 장소를 말할 때는 ここ(koko, 코코) '여기', そこ(soko, 소코) '거기', あそこ(asoko, 아소코) '저기', どこ(doko, 도코) '어디'를 써요.", "こ・そ・あ・ど 규칙은 똑같아요. 저기만 あこ가 아니라 あそこ라는 것을 조심해요."], "figure": "아이가 가까운 곳, 친구 쪽, 먼 곳을 차례로 가리키는 모습", "example": "ここ(여기) · そこ(거기) · あそこ(저기) · どこ(어디)", "heading": "ここ・そこ・あそこ・どこ"}, {"paras": ["'○○은 어디예요?'는 ○○は どこですか(wa doko desu ka, 와 도코데스카)라고 해요.", "길을 물을 때는 먼저 すみません(스미마셍) '실례합니다'라고 말을 걸면 예의 바르게 들려요."], "figure": "길에서 어른에게 공손하게 길을 묻는 아이", "example": "すみません、トイレは どこですか。(sumimasen, toire wa doko desu ka, 스미마셍 토이레와 도코데스카) → 실례합니다, 화장실은 어디예요?", "heading": "~は どこですか? ~은 어디예요?"}, {"paras": ["トイレ(toire, 토이레) 화장실, えき(eki, 에키) 역, がっこう(gakkou, 갓코-) 학교, コンビニ(konbini, 콤비니) 편의점, こうえん(kouen, 코-엥) 공원, びょういん(byouin, 뵤-잉) 병원", "びょういん(byouin, 뵤-잉) 병원과 びよういん(biyouin, 비요-잉) 미용실은 아주 비슷해요. 작은 ょ인지 큰 よ인지 잘 봐요!"], "figure": "역, 공원, 편의점이 보이는 거리 풍경", "example": "えきは あそこです。(eki wa asoko desu, 에키와 아소코데스) → 역은 저기예요.", "heading": "장소 이름을 알아봐요"}, {"paras": ["물건이 어디 있는지 말할 때는 ○○の うえ(no ue, 노 우에) '○○ 위', ○○の した(shita, 시타) '아래', ○○の なか(naka, 나카) '안', ○○の となり(tonari, 토나리) '옆'을 써요.", "の는 '~의'라는 뜻이에요. つくえの うえ는 '책상의 위', 즉 '책상 위'예요."], "figure": "책상 아래에 숨은 고양이", "example": "A: ねこは どこですか。 B: つくえの したです。 (고양이는 어디예요? / 책상 아래예요.)", "heading": "위・아래・안・옆"}, {"paras": ["방향은 みぎ(migi, 미기) '오른쪽', ひだり(hidari, 히다리) '왼쪽'이에요. トイレは みぎです는 '화장실은 오른쪽이에요'예요.", "길을 알려 주면 ありがとうございます(arigatou gozaimasu, 아리가토- 고자이마스) '고맙습니다'라고 꼭 인사해요."], "figure": "", "example": "A: コンビニは どこですか。 B: ひだりです。 A: ありがとうございます。", "heading": "みぎ・ひだり 그리고 고맙습니다"}], "parent_tip": "부모님께: これ・それ・あれ・どれ(물건)와 ここ・そこ・あそこ・どこ(장소)를 짝지어 보여 주면 아이가 규칙을 금방 찾습니다. 집 안에서 장난감을 숨기고 \"○○は どこですか。\"라고 물으면 아이가 \"つくえの したです。\"처럼 위치로 답하는 놀이를 해 보세요. 실제 여행에서는 'トイレは どこですか。' 한 문장만 알아도 큰 도움이 됩니다.", "expressions": [{"en": "どこですか。", "ko": "어디예요?", "note": "doko desu ka (도코데스카)"}, {"en": "トイレは どこですか。", "ko": "화장실은 어디예요?", "note": "toire wa doko desu ka (토이레와 도코데스카)"}, {"en": "えきは あそこです。", "ko": "역은 저기예요.", "note": "eki wa asoko desu (에키와 아소코데스)"}, {"en": "ここ", "ko": "여기", "note": "koko (코코)"}, {"en": "そこ", "ko": "거기", "note": "soko (소코)"}, {"en": "あそこ", "ko": "저기", "note": "asoko (아소코)"}, {"en": "つくえの うえ", "ko": "책상 위", "note": "tsukue no ue (츠쿠에노 우에)"}, {"en": "みぎ", "ko": "오른쪽", "note": "migi (미기)"}, {"en": "ひだり", "ko": "왼쪽", "note": "hidari (히다리)"}, {"en": "コンビニ", "ko": "편의점", "note": "konbini (콤비니)"}, {"en": "びょういん", "ko": "병원", "note": "byouin (뵤-잉)"}, {"en": "ありがとうございます。", "ko": "고맙습니다.", "note": "arigatou gozaimasu (아리가토- 고자이마스)"}]}$j$::jsonb where slug='j5-08';
update public.lessons set content=$j${"quiz": [{"q": "たべます。의 뜻은?", "answer": 0, "choices": ["먹어요.", "마셔요.", "가요.", "자요."], "explain": "たべます는 '먹어요'예요."}, {"q": "'학교에 가요.'에서 빈칸에 알맞은 글자는?\nがっこう[  ] いきます。", "answer": 1, "choices": ["を", "に", "で", "が"], "explain": "가는 곳 뒤에는 に를 붙여요."}, {"q": "'공원에서 놀아요.'를 바르게 말한 것은?", "answer": 2, "choices": ["こうえんを あそびます。", "こうえんに あそびます。", "こうえんで あそびます。", "こうえんが あそびます。"], "explain": "무엇을 하는 장소 뒤에는 で를 붙여요."}, {"q": "みません。의 뜻은?", "answer": 3, "choices": ["봐요.", "봤어요.", "볼까요?", "안 봐요."], "explain": "ます를 ません으로 바꾸면 '안 해요'예요. みません은 '안 봐요'예요."}, {"q": "'먹었어요'를 일본어로 바르게 쓴 것은?", "answer": 1, "choices": ["たべます", "たべました", "たべません", "たべますか"], "explain": "ます → ました로 바꾸면 '했어요'가 돼요."}], "intro": "\"나는 빵을 먹어요.\", \"학교에 가요.\" 내가 하는 일을 말하려면 움직임을 나타내는 말(동사)이 필요해요. 오늘은 일본어 동사를 공손하게 말하는 ~ます를 배워요.", "summary": ["동사를 공손하게 말할 때는 ~ます(마스): たべます, いきます, みます", "무엇을 → を, 어디로・몇 시에 → に, 어디에서 → で", "안 해요는 ~ません, 했어요는 ~ました, 질문은 끝에 か를 붙여요."], "keywords": [{"word": "~ます", "meaning": "동사를 공손하게 말하는 끝 '~해요' (masu, 마스)"}, {"word": "~ません", "meaning": "'~안 해요' (masen, 마셍)"}, {"word": "~ました", "meaning": "'~했어요' (mashita, 마시타)"}, {"word": "を", "meaning": "무엇을 하는지 (o, 오)"}, {"word": "に", "meaning": "어디로 가는지, 몇 시에 (ni, 니)"}, {"word": "で", "meaning": "어디에서 하는지 (de, 데)"}], "sections": [{"paras": ["일본어 동사를 공손하게 말할 때는 끝이 ~ます(masu, 마스)로 끝나요. 한국어의 '~해요'와 비슷해요.", "たべます(tabemasu, 타베마스) 먹어요, のみます(nomimasu, 노미마스) 마셔요, いきます(ikimasu, 이키마스) 가요, みます(mimasu, 미마스) 봐요.", "ます의 す는 아주 약하게 소리 내서 '마ㅅ'에 가깝게 들려요."], "figure": "빵을 먹는 아이, 우유를 마시는 아이, 걸어가는 아이", "example": "たべます 먹어요 · のみます 마셔요 · いきます 가요 · みます 봐요", "heading": "~ます 는 '~해요'"}, {"paras": ["おきます(okimasu, 오키마스) 일어나요, ねます(nemasu, 네마스) 자요, あそびます(asobimasu, 아소비마스) 놀아요, べんきょうします(benkyou shimasu, 벵쿄- 시마스) 공부해요.", "시간 뒤에 に(ni, 니)를 붙이면 '~시에'가 돼요. しちじに おきます는 '7시에 일어나요'예요."], "figure": "아침에 알람시계를 끄며 일어나는 아이", "example": "しちじに おきます。(shichiji ni okimasu, 시치지니 오키마스) → 7시에 일어나요.", "heading": "하루 생활을 말해 봐요"}, {"paras": ["무엇을 하는지는 を(o, 오): パンを たべます(팡오 타베마스) '빵을 먹어요'.", "어디로 가는지는 に(ni, 니): がっこうに いきます(갓코-니 이키마스) '학교에 가요'.", "어디에서 하는지는 で(de, 데): こうえんで あそびます(코-엔데 아소비마스) '공원에서 놀아요'."], "figure": "공원에서 공놀이하는 아이들", "example": "テレビを みます。(terebi o mimasu, 테레비오 미마스) → 텔레비전을 봐요.", "heading": "を・に・で 짝꿍 글자"}, {"paras": ["ます를 ません(masen, 마셍)으로 바꾸면 '안 해요'가 돼요. たべません은 '안 먹어요'예요.", "ます를 ました(mashita, 마시타)로 바꾸면 '했어요'가 돼요. たべました는 '먹었어요'예요.", "질문은 끝에 か를 붙여요. なにを たべますか(나니오 타베마스카)는 '무엇을 먹어요?'예요."], "figure": "", "example": "たべます(먹어요) → たべません(안 먹어요) → たべました(먹었어요)", "heading": "안 해요는 ~ません, 했어요는 ~ました"}], "parent_tip": "부모님께: 아이들이 가장 헷갈리는 것은 に(가는 곳)와 で(하는 곳)의 구분입니다. '학교에 가요'는 に, '학교에서 공부해요'는 で라는 짝을 반복해 주세요. 하루 일과를 시간 순서대로 \"しちじに おきます。 パンを たべます。 がっこうに いきます。\"처럼 말해 보는 '나의 하루 말하기'가 좋은 연습이 됩니다.", "expressions": [{"en": "たべます。", "ko": "먹어요.", "note": "tabemasu (타베마스)"}, {"en": "のみます。", "ko": "마셔요.", "note": "nomimasu (노미마스)"}, {"en": "いきます。", "ko": "가요.", "note": "ikimasu (이키마스)"}, {"en": "みます。", "ko": "봐요.", "note": "mimasu (미마스)"}, {"en": "おきます。", "ko": "일어나요.", "note": "okimasu (오키마스)"}, {"en": "ねます。", "ko": "자요.", "note": "nemasu (네마스)"}, {"en": "べんきょうします。", "ko": "공부해요.", "note": "benkyou shimasu (벵쿄- 시마스)"}, {"en": "パンを たべます。", "ko": "빵을 먹어요.", "note": "pan o tabemasu (팡오 타베마스)"}, {"en": "がっこうに いきます。", "ko": "학교에 가요.", "note": "gakkou ni ikimasu (갓코-니 이키마스)"}, {"en": "こうえんで あそびます。", "ko": "공원에서 놀아요.", "note": "kouen de asobimasu (코-엔데 아소비마스)"}, {"en": "たべません。", "ko": "안 먹어요.", "note": "tabemasen (타베마셍)"}, {"en": "たべました。", "ko": "먹었어요.", "note": "tabemashita (타베마시타)"}]}$j$::jsonb where slug='j5-09';
update public.lessons set content=$j${"quiz": [{"q": "あついです。의 뜻은?", "answer": 0, "choices": ["더워요.", "추워요.", "시원해요.", "따뜻해요."], "explain": "あつい는 '덥다'예요."}, {"q": "'오늘은 눈이 와요.'를 바르게 말한 것은?", "answer": 1, "choices": ["きょうは あめです。", "きょうは ゆきです。", "きょうは はれです。", "きょうは くもりです。"], "explain": "ゆき는 '눈'이에요."}, {"q": "いい てんきですね。라는 말을 들었을 때 알맞은 대답은?", "answer": 2, "choices": ["いただきます。", "はじめまして。", "そうですね。", "いくらですか。"], "explain": "そうですね(그렇네요)로 맞장구를 쳐요."}, {"q": "'안 추워요.'를 바르게 말한 것은?", "answer": 3, "choices": ["さむいです。", "さむいないです。", "さむいくないです。", "さむくないです。"], "explain": "い를 빼고 くない를 붙여요. さむ + くないです."}, {"q": "가을(あき)과 가장 잘 어울리는 말은?", "answer": 0, "choices": ["すずしい", "あつい", "さむい", "ゆき"], "explain": "가을은 시원해요. すずしい(시원하다)예요."}], "intro": "일본 사람들은 만나면 날씨 이야기로 인사를 자주 나눠요. \"날씨 좋네요!\", \"오늘 덥네요!\" 오늘은 날씨를 말하는 낱말과 '덥다, 춥다'처럼 성질이나 상태를 나타내는 말(형용사)을 배워요.", "summary": ["날씨: はれ(맑음)・くもり(흐림)・あめ(비)・ゆき(눈), '오늘은 ~예요'는 きょうは ~です.", "あつい(덥다)・さむい(춥다)・あたたかい(따뜻하다)・すずしい(시원하다)는 い형용사예요.", "'안 ~해요'는 い를 빼고 くないです. いい는 よくないです로 특별하게 바뀌어요."], "keywords": [{"word": "てんき", "meaning": "날씨 (tenki, 텡키)"}, {"word": "はれ・くもり・あめ・ゆき", "meaning": "맑음・흐림・비・눈"}, {"word": "い형용사", "meaning": "あつい, さむい처럼 성질이나 상태를 나타내고 끝이 い로 끝나는 말"}, {"word": "~くないです", "meaning": "'안 ~해요' (い를 빼고 붙여요)"}, {"word": "ね", "meaning": "'~네요'처럼 맞장구를 구하는 말 (ne, 네)"}], "sections": [{"paras": ["날씨 낱말은 はれ(hare, 하레) 맑음, くもり(kumori, 쿠모리) 흐림, あめ(ame, 아메) 비, ゆき(yuki, 유키) 눈이에요.", "'오늘은 ○○예요'는 きょうは ○○です라고 해요. 앞에서 배운 きょう(오늘)를 기억하죠?"], "figure": "창밖으로 비가 내리고 우산이 세워진 현관", "example": "きょうは あめです。(kyou wa ame desu, 쿄-와 아메데스) → 오늘은 비가 와요.", "heading": "맑음・흐림・비・눈"}, {"paras": ["てんき(tenki, 텡키)는 '날씨', いい(ii, 이-)는 '좋다'예요. いい てんきですね(ii tenki desu ne, 이- 텡키데스네)는 '날씨가 좋네요'라는 인사예요.", "문장 끝의 ね(ne, 네)는 '~네요'처럼 상대에게 맞장구를 구하는 말이에요. 대답은 そうですね(sou desu ne, 소-데스네) '그렇네요'라고 해요."], "figure": "맑은 하늘 아래 두 사람이 인사하는 모습", "example": "A: いい てんきですね。 B: そうですね。", "heading": "いい てんきですね 날씨 좋네요"}, {"paras": ["あつい(atsui, 아츠이) 덥다, さむい(samui, 사무이) 춥다, あたたかい(atatakai, 아타타카이) 따뜻하다, すずしい(suzushii, 스즈시-) 시원하다.", "이 낱말들은 모두 끝이 い로 끝나요. 이런 형용사를 'い형용사'라고 불러요. 뒤에 です를 붙이면 공손한 말이 돼요.", "계절과 짝지어 외워 봐요. はる(haru, 하루) 봄은 あたたかい, なつ(natsu, 나츠) 여름은 あつい, あき(aki, 아키) 가을은 すずしい, ふゆ(fuyu, 후유) 겨울은 さむい."], "figure": "봄꽃, 여름 바다, 가을 낙엽, 겨울 눈사람 네 장면", "example": "なつは あついです。(natsu wa atsui desu, 나츠와 아츠이데스) → 여름은 더워요.", "heading": "あつい・さむい 덥다・춥다"}, {"paras": ["'안 ~해요'라고 말할 때는 끝의 い를 빼고 くない를 붙여요. さむい → さむくないです(samukunai desu, 사무쿠나이데스) '안 추워요'.", "あつい → あつくないです(아츠쿠나이데스) '안 더워요'. 단, いい(좋다)는 특별해서 よくないです(yokunai desu, 요쿠나이데스) '안 좋아요'라고 해요."], "figure": "", "example": "きょうは さむくないです。 (오늘은 안 추워요.)", "heading": "안 추워요는 さむくないです"}, {"paras": ["おおきい(ookii, 오-키-) 크다, ちいさい(chiisai, 치-사이) 작다, たのしい(tanoshii, 타노시-) 즐겁다도 い형용사예요.", "형용사를 낱말 앞에 두면 꾸며 줄 수 있어요. おおきい いぬ는 '큰 개', たのしい なつ는 '즐거운 여름'이에요."], "figure": "눈사람을 만들며 웃는 아이들", "example": "ゆきの ひは たのしいです。 (눈 오는 날은 즐거워요.)", "heading": "날씨 말고도 쓰는 い형용사"}], "parent_tip": "부모님께: い형용사의 부정형은 끝의 い를 떼고 くない를 붙이는데, 아이들은 'さむいないです'처럼 い를 남기는 실수를 자주 합니다. 매일 아침 창밖을 보며 \"きょうは はれです。 さむいです。\"처럼 날씨 두 문장을 말하는 습관을 들이면 좋습니다. いい→よくない는 예외라는 점도 함께 짚어 주세요.", "expressions": [{"en": "いい てんきですね。", "ko": "날씨가 좋네요.", "note": "ii tenki desu ne (이- 텡키데스네)"}, {"en": "そうですね。", "ko": "그렇네요.", "note": "sou desu ne (소-데스네)"}, {"en": "はれ", "ko": "맑음", "note": "hare (하레)"}, {"en": "くもり", "ko": "흐림", "note": "kumori (쿠모리)"}, {"en": "あめ", "ko": "비", "note": "ame (아메)"}, {"en": "ゆき", "ko": "눈", "note": "yuki (유키)"}, {"en": "あついです。", "ko": "더워요.", "note": "atsui desu (아츠이데스)"}, {"en": "さむいです。", "ko": "추워요.", "note": "samui desu (사무이데스)"}, {"en": "あたたかいです。", "ko": "따뜻해요.", "note": "atatakai desu (아타타카이데스)"}, {"en": "すずしいです。", "ko": "시원해요.", "note": "suzushii desu (스즈시-데스)"}, {"en": "さむくないです。", "ko": "안 추워요.", "note": "samukunai desu (사무쿠나이데스)"}, {"en": "きょうは あめです。", "ko": "오늘은 비가 와요.", "note": "kyou wa ame desu (쿄-와 아메데스)"}]}$j$::jsonb where slug='j5-10';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/k1-03_kw.mp3", "q0": "assets/audio/n/k1-03_q0.mp3", "q1": "assets/audio/n/k1-03_q1.mp3", "q2": "assets/audio/n/k1-03_q2.mp3", "q3": "assets/audio/n/k1-03_q3.mp3", "q4": "assets/audio/n/k1-03_q4.mp3", "s0": "assets/audio/n/k1-03_s0.mp3", "s1": "assets/audio/n/k1-03_s1.mp3", "s2": "assets/audio/n/k1-03_s2.mp3", "s3": "assets/audio/n/k1-03_s3.mp3", "sum": "assets/audio/n/k1-03_sum.mp3", "cover": "assets/audio/n/k1-03_cover.mp3"}, "quiz": [{"q": "ㄱ의 이름은?", "answer": 0, "choices": ["기역", "니은", "디귿", "리을"], "explain": "ㄱ은 '기역'이라고 불러요."}, {"q": "🦆 그림에 맞는 낱말은?", "answer": 2, "choices": ["오기", "오니", "오리", "오두"], "explain": "꽥꽥 우는 새는 '오리'예요."}, {"q": "ㄴ 위에 줄을 하나 그으면 어떤 자음?", "answer": 3, "choices": ["ㄱ", "ㄹ", "ㅇ", "ㄷ"], "explain": "ㄴ 위에 줄을 더하면 ㄷ이 돼요."}, {"q": "ㄷ과 ㅏ가 만나면?", "answer": 1, "choices": ["가", "다", "나", "라"], "explain": "ㄷ+ㅏ=다예요."}, {"q": "'리을'은 어떤 자음의 이름?", "answer": 0, "choices": ["ㄹ", "ㄷ", "ㄴ", "ㄱ"], "explain": "꼬불꼬불한 ㄹ의 이름이 '리을'이에요."}], "intro": "🦆 \"오리\"를 읽어 봐요. '리'에는 모음 말고 다른 글자가 있어요. 오늘은 모음과 짝을 이루는 자음 네 개를 만나요.", "summary": ["자음은 모음과 만나 글자가 돼요.", "ㄱ 기역, ㄴ 니은, ㄷ 디귿, ㄹ 리을.", "가 나 다 라처럼 자음 + 모음으로 글자를 만들어요."], "keywords": [{"word": "자음", "meaning": "모음과 만나야 소리가 나는 글자예요."}, {"word": "기역 · 니은", "meaning": "ㄱ과 ㄴ의 이름이에요."}, {"word": "디귿 · 리을", "meaning": "ㄷ과 ㄹ의 이름이에요."}, {"word": "글자 만들기", "meaning": "자음 + 모음 = 글자 (ㄱ+ㅏ=가)."}], "sections": [{"paras": ["자음은 모음과 만나 글자가 돼요.", "ㅇ 자리에 자음을 넣어 보세요.", "자음마다 이름이 있어요."], "figure": "'아' 카드의 ㅇ 자리에 ㄱ 카드를 끼워 넣는 그림", "example": "ㅇ+ㅏ=아 → ㄱ+ㅏ=가", "heading": "자음은 모음의 짝꿍"}, {"paras": ["ㄱ의 이름은 '기역'이에요.", "ㄴ의 이름은 '니은'이에요.", "ㄱ은 아래로 꺾이고, ㄴ은 위에서 내려와 옆으로 가요."], "figure": "ㄱ과 ㄴ의 꺾이는 방향을 화살표로 보여 주는 그림", "example": "ㄱ+ㅏ=가 · ㄴ+ㅏ=나", "heading": "ㄱ 기역, ㄴ 니은"}, {"paras": ["ㄷ의 이름은 '디귿'이에요.", "ㄴ 위에 줄을 하나 그으면 ㄷ이에요. 쓸 때는 위의 가로줄을 먼저 긋고, 그다음 ㄴ을 써요.", "ㄹ의 이름은 '리을'이에요. 꼬불꼬불해요."], "figure": "ㄴ 위에 가로줄을 더해 ㄷ이 되는 그림, 꼬불꼬불한 ㄹ", "example": "ㄷ+ㅏ=다 · ㄹ+ㅏ=라", "heading": "ㄷ 디귿, ㄹ 리을"}, {"paras": ["배운 자음과 모음으로 낱말을 읽어요.", "글자를 하나씩 천천히 읽어 봐요."], "figure": "책상 위의 오리 인형과 작은 구두", "example": "🦆 오리 · 🦵 다리 · 🍖 고기 · 👞 구두 · 📻 라디오", "heading": "낱말을 읽어요"}], "parent_tip": "부모님께: 아이가 ㄱ과 ㄴ의 방향을 거꾸로 쓰는 일이 많습니다. 손가락으로 공중에 크게 써 보게 해 주세요. 자음 이름(기역·디귿)은 소리와 달라 어려워하니 \"가나다라\" 노래로 먼저 익힌 뒤 이름을 붙이면 좋습니다.", "expressions": [{"en": "기역", "ko": "자음 ㄱ의 이름"}, {"en": "니은", "ko": "자음 ㄴ의 이름"}, {"en": "디귿", "ko": "자음 ㄷ의 이름", "note": "[디귿]"}, {"en": "리을", "ko": "자음 ㄹ의 이름"}, {"en": "가 나 다 라", "ko": "ㄱ ㄴ ㄷ ㄹ에 ㅏ를 붙인 글자"}, {"en": "고기", "ko": "🍖 먹는 고기"}, {"en": "오리", "ko": "🦆 꽥꽥 우는 새"}, {"en": "다리", "ko": "🦵 몸의 다리, 또는 강을 건너는 다리"}, {"en": "구두", "ko": "👞 가죽으로 만든 신"}, {"en": "라디오", "ko": "📻 소리를 듣는 기계"}]}$j$::jsonb where slug='k1-03';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/k1-10_kw.mp3", "q0": "assets/audio/n/k1-10_q0.mp3", "q1": "assets/audio/n/k1-10_q1.mp3", "q2": "assets/audio/n/k1-10_q2.mp3", "q3": "assets/audio/n/k1-10_q3.mp3", "q4": "assets/audio/n/k1-10_q4.mp3", "s0": "assets/audio/n/k1-10_s0.mp3", "s1": "assets/audio/n/k1-10_s1.mp3", "s2": "assets/audio/n/k1-10_s2.mp3", "s3": "assets/audio/n/k1-10_s3.mp3", "sum": "assets/audio/n/k1-10_sum.mp3", "cover": "assets/audio/n/k1-10_cover.mp3"}, "quiz": [{"q": "🦀 그림에 맞는 글자는?", "answer": 1, "choices": ["개", "게", "계", "귀"], "explain": "옆으로 걷는 🦀는 '게'예요. ㅔ를 써요."}, {"q": "ㅗ와 ㅏ가 만나면 어떤 모음이 될까요?", "answer": 2, "choices": ["ㅝ", "ㅚ", "ㅘ", "ㅟ"], "explain": "ㅗ와 ㅏ를 붙이면 ㅘ [와]가 돼요."}, {"q": "🪑 '의자'의 '의'에 들어 있는 모음은?", "answer": 0, "choices": ["ㅢ", "ㅟ", "ㅚ", "ㅐ"], "explain": "'의'는 ㅡ와 ㅣ가 만난 ㅢ를 써요."}, {"q": "🐭 그림에 맞는 낱말은?", "answer": 3, "choices": ["줘", "재", "제", "쥐"], "explain": "찍찍 우는 🐭는 '쥐'예요. ㅜ와 ㅣ가 만난 ㅟ를 써요."}, {"q": "🍎 '사과'의 '과'에 들어 있는 모음은?", "answer": 1, "choices": ["ㅝ", "ㅘ", "ㅚ", "ㅐ"], "explain": "'과'는 ㄱ과 ㅘ가 만나 만든 글자예요."}], "intro": "모음 두 개가 만나면 새 모음이 돼요. 🦀 게, 🍎 사과 속에 숨어 있어요!", "summary": ["모음 두 개가 만나 새 모음이 돼요.", "ㅐ와 ㅔ는 소리가 비슷해서 낱말로 기억해요.", "ㅘ, ㅝ, ㅟ, ㅢ는 두 소리를 빠르게 이어 읽어요. ㅚ는 [외]나 [웨]로 읽어요."], "keywords": [{"word": "모음", "meaning": "ㅏ, ㅓ, ㅗ처럼 소리를 내는 글자"}, {"word": "복잡한 모음", "meaning": "모음 두 개가 합쳐져 만든 모음(ㅐ, ㅘ, ㅢ 등)"}, {"word": "이어 읽기", "meaning": "두 소리를 끊지 않고 빠르게 붙여 읽는 것"}], "sections": [{"paras": ["ㅏ에 ㅣ를 붙이면 ㅐ예요.", "ㅓ에 ㅣ를 붙이면 ㅔ예요.", "둘은 소리가 거의 같아요. 낱말로 기억해요."], "figure": "개 인형과 게 장난감을 책상 위에 나란히 놓은 모습", "example": "🐶 개 / 🦀 게", "heading": "ㅐ와 ㅔ는 쌍둥이 소리"}, {"paras": ["ㅗ와 ㅏ가 만나면 ㅘ [와]예요.", "ㅜ와 ㅓ가 만나면 ㅝ [워]예요.", "ㅗ+ㅣ는 ㅚ, ㅜ+ㅣ는 ㅟ예요."], "figure": "사과와 참외가 담긴 바구니", "example": "🍎 사과, 🐒 원숭이, 🍈 참외, 🐭 쥐", "heading": "ㅗ, ㅜ와 만나는 모음"}, {"paras": ["ㅡ와 ㅣ를 붙이면 ㅢ예요.", "입을 옆으로 벌리고 [의] 해요."], "figure": "작은 나무 의자 하나", "example": "🪑 의자, 👩‍⚕️ 의사", "heading": "ㅡ와 ㅣ가 만나면 ㅢ"}, {"paras": ["두 소리를 빠르게 이어 읽어요.", "오+아를 빨리 하면 [와]가 돼요."], "figure": "아이가 모음 카드 두 장을 겹쳐 드는 손", "example": "오+아 → 와, 우+어 → 워, 우+이 → 위", "heading": "빠르게 이어 읽어요"}], "parent_tip": "부모님께: 요즘 말소리에서 ㅐ와 ㅔ는 거의 구별되지 않아 아이가 '개/게'를 헷갈리는 것이 자연스럽습니다. 소리보다 '🐶 개, 🦀 게'처럼 낱말 그림과 함께 기억하게 해 주세요. '오+아를 빨리 말하면?' 같은 놀이로 ㅘ, ㅝ를 익히면 좋습니다.", "expressions": [{"en": "애", "ko": "ㅇ + ㅐ (ㅏ와 ㅣ가 만났어요)", "note": "[애]"}, {"en": "에", "ko": "ㅇ + ㅔ (ㅓ와 ㅣ가 만났어요)", "note": "[에] ㅐ와 소리가 거의 같아요"}, {"en": "와", "ko": "ㅇ + ㅘ (ㅗ와 ㅏ가 만났어요)", "note": "[와]"}, {"en": "워", "ko": "ㅇ + ㅝ (ㅜ와 ㅓ가 만났어요)", "note": "[워]"}, {"en": "외", "ko": "ㅇ + ㅚ (ㅗ와 ㅣ가 만났어요)", "note": "[외] 또는 [웨]"}, {"en": "위", "ko": "ㅇ + ㅟ (ㅜ와 ㅣ가 만났어요)", "note": "[위]"}, {"en": "의", "ko": "ㅇ + ㅢ (ㅡ와 ㅣ가 만났어요)", "note": "[의]"}, {"en": "개", "ko": "🐶 멍멍 짖는 동물", "note": "[개]"}, {"en": "게", "ko": "🦀 옆으로 걷는 바다 동물", "note": "[게]"}, {"en": "사과", "ko": "🍎 빨간 과일 (과 = ㄱ + ㅘ)", "note": "[사과]"}, {"en": "쥐", "ko": "🐭 찍찍 우는 작은 동물 (쥐 = ㅈ + ㅟ)", "note": "[쥐]"}, {"en": "의자", "ko": "🪑 앉는 물건", "note": "[의자]"}]}$j$::jsonb where slug='k1-10';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/k1-12_kw.mp3", "q0": "assets/audio/n/k1-12_q0.mp3", "q1": "assets/audio/n/k1-12_q1.mp3", "q2": "assets/audio/n/k1-12_q2.mp3", "q3": "assets/audio/n/k1-12_q3.mp3", "q4": "assets/audio/n/k1-12_q4.mp3", "s0": "assets/audio/n/k1-12_s0.mp3", "s1": "assets/audio/n/k1-12_s1.mp3", "s2": "assets/audio/n/k1-12_s2.mp3", "s3": "assets/audio/n/k1-12_s3.mp3", "sum": "assets/audio/n/k1-12_sum.mp3", "cover": "assets/audio/n/k1-12_cover.mp3"}, "quiz": [{"q": "🎵 '음악'은 어떻게 읽을까요?", "answer": 1, "choices": ["[음악]", "[으막]", "[으낙]", "[음막]"], "explain": "받침 ㅁ이 뒤로 넘어가 [으막]으로 읽어요."}, {"q": "🏫 '학교'는 어떻게 소리 날까요?", "answer": 2, "choices": ["[학교]", "[하교]", "[학꾜]", "[항교]"], "explain": "'교'가 세게 소리 나서 [학꾜]가 돼요."}, {"q": "[조아요]라고 들은 말을 바르게 쓴 것은?", "answer": 3, "choices": ["조아요", "조와요", "좃아요", "좋아요"], "explain": "소리는 [조아요]지만 쓸 때는 '좋아요'라고 써요."}, {"q": "받침이 뒤로 넘어가 소리 나는 낱말은?", "answer": 0, "choices": ["놀이", "나무", "바다", "오이"], "explain": "'놀이'는 받침 ㄹ이 넘어가 [노리]로 읽어요."}, {"q": "낱말을 쓸 때는 어떻게 써야 할까요?", "answer": 1, "choices": ["소리 나는 대로", "원래 글자대로", "받침을 빼고", "마음대로"], "explain": "읽을 때는 소리대로, 쓸 때는 원래 글자대로 써요."}], "intro": "글자와 다르게 소리 나는 낱말이 있어요. 왜 그런지 함께 알아봐요.", "summary": ["받침 뒤에 ㅇ이 오면 받침이 뒤로 넘어가 소리 나요. (받침 ㅇ은 넘어가지 않아요: 강아지)", "'학교[학꾜]'처럼 소리가 세지는 낱말도 있어요.", "쓸 때는 소리가 아니라 원래 글자대로 써요."], "keywords": [{"word": "받침", "meaning": "글자 아래에 붙는 자음"}, {"word": "발음", "meaning": "말소리를 내는 것. [ ] 안에 써서 보여 줘요"}, {"word": "넘어가기", "meaning": "받침이 뒤 글자의 ㅇ 자리로 옮겨 가 소리 나는 것"}], "sections": [{"paras": ["받침 뒤에 ㅇ이 오면 받침이 뒤로 넘어가요. (받침 ㅇ은 넘어가지 않아요: 강아지)", "그래서 '음악'은 [으막]으로 읽어요."], "figure": "글자 카드 '음'의 받침 카드를 옆 칸으로 옮기는 아이 손", "example": "🎵 음악 → [으막], 🎈 놀이 → [노리], 📕 책이 → [채기]", "heading": "받침이 뒤로 넘어가요"}, {"paras": ["어떤 낱말은 뒷소리가 세져요.", "'학교'는 [학꾜]로 소리 나요."], "figure": "책가방을 멘 아이가 학교 앞에 선 모습", "example": "🏫 학교 → [학꾜], 🍜 국수 → [국쑤]", "heading": "소리가 세게 나요"}, {"paras": ["받침 ㅎ 뒤에 ㅇ이 오면 ㅎ 소리가 안 나요.", "'좋아요'는 [조아요]로 읽어요."], "figure": "엄지를 든 아이 손", "example": "👍 좋아요 → [조아요], 많이 → [마니]", "heading": "ㅎ 소리가 숨어요"}, {"paras": ["읽을 때는 소리 나는 대로 읽어요.", "쓸 때는 원래 글자로 써요."], "figure": "공책에 연필로 낱말을 쓰는 아이 손", "example": "✏️ [으막]이라고 들어도 '음악'이라고 써요.", "heading": "쓸 때는 원래대로 써요"}], "parent_tip": "부모님께: 이 시기 아이들은 '으막', '노리터'처럼 소리 나는 대로 쓰는 실수를 많이 합니다. 틀린 글자를 지적하기보다 '읽을 때는 [노리], 쓸 때는 놀이'처럼 두 가지를 나란히 보여 주세요. 받아쓰기 전에 낱말을 또박또박 끊어 읽어 주면 도움이 됩니다.", "expressions": [{"en": "음악", "ko": "🎵 노래나 연주", "note": "[으막]"}, {"en": "놀이", "ko": "🎈 즐겁게 노는 일", "note": "[노리]"}, {"en": "국어", "ko": "📖 우리말을 배우는 과목", "note": "[구거]"}, {"en": "웃음", "ko": "😄 웃는 일", "note": "[우슴]"}, {"en": "목요일", "ko": "수요일 다음 날", "note": "[모교일]"}, {"en": "꽃이", "ko": "🌸 꽃 + 이", "note": "[꼬치]"}, {"en": "책이", "ko": "📕 책 + 이", "note": "[채기]"}, {"en": "학교", "ko": "🏫 공부하는 곳", "note": "[학꾜]"}, {"en": "국수", "ko": "🍜 길고 가는 면 음식", "note": "[국쑤]"}, {"en": "좋아요", "ko": "👍 마음에 들어요", "note": "[조아요]"}, {"en": "많이", "ko": "가득, 여러 개", "note": "[마니]"}]}$j$::jsonb where slug='k1-12';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/k1-13_kw.mp3", "q0": "assets/audio/n/k1-13_q0.mp3", "q1": "assets/audio/n/k1-13_q1.mp3", "q2": "assets/audio/n/k1-13_q2.mp3", "q3": "assets/audio/n/k1-13_q3.mp3", "q4": "assets/audio/n/k1-13_q4.mp3", "s0": "assets/audio/n/k1-13_s0.mp3", "s1": "assets/audio/n/k1-13_s1.mp3", "s2": "assets/audio/n/k1-13_s2.mp3", "s3": "assets/audio/n/k1-13_s3.mp3", "sum": "assets/audio/n/k1-13_sum.mp3", "cover": "assets/audio/n/k1-13_cover.mp3"}, "quiz": [{"q": "바르게 띄어 쓴 것은?", "answer": 1, "choices": ["나는학교에 가요.", "나는 학교에 가요.", "나 는 학교 에 가요.", "나는 학교에가요."], "explain": "낱말 사이는 띄우고, '는', '에'는 앞말에 붙여 써요."}, {"q": "'가', '를' 같은 작은 말은 어떻게 쓸까요?", "answer": 0, "choices": ["앞 낱말에 붙여 써요", "띄어 써요", "쓰지 않아요", "맨 뒤에 써요"], "explain": "'가', '를'은 앞 낱말에 붙여 써요. 예: 강아지가, 사과를"}, {"q": "👜 아버지가 가방 속에 들어가는 뜻은?", "answer": 3, "choices": ["아버지가 방에 들어가신다.", "아버지가방에 들어가신다.", "아버지가 방에들어가신다.", "아버지 가방에 들어가신다."], "explain": "'아버지 가방에'로 띄어 쓰면 아버지가 가방 속에 들어가신다는 우스운 뜻이 돼요."}, {"q": "∨ 표시는 무슨 뜻일까요?", "answer": 2, "choices": ["크게 읽어요", "빨리 읽어요", "조금 쉬어 읽어요", "다시 읽어요"], "explain": "∨는 조금 쉬어 읽으라는 표시예요."}, {"q": "마침표(.) 뒤에서는 어떻게 읽을까요?", "answer": 0, "choices": ["∨보다 더 쉬어요", "쉬지 않아요", "노래하듯 읽어요", "크게 소리쳐요"], "explain": "마침표 뒤에서는 ≫ 표시처럼 조금 더 쉬어 읽어요."}], "intro": "'아버지가방에들어가신다'를 읽어 볼까요? 띄어 쓰지 않으면 뜻이 헷갈려요.", "summary": ["낱말과 낱말 사이는 한 칸 띄어 써요.", "'가, 를, 는, 에' 같은 말은 앞 낱말에 붙여 써요.", "쉼표 뒤는 조금(∨), 마침표 뒤는 더(≫) 쉬어 읽어요."], "keywords": [{"word": "띄어쓰기", "meaning": "낱말과 낱말 사이를 한 칸 비우고 쓰는 것"}, {"word": "띄어 읽기", "meaning": "알맞은 곳에서 쉬며 읽는 것"}, {"word": "쉼표", "meaning": "문장 중간에 쓰는 , 표시. 조금 쉬어 읽어요"}, {"word": "마침표", "meaning": "문장 끝에 쓰는 . 표시"}], "sections": [{"paras": ["낱말과 낱말 사이는 한 칸 띄어 써요.", "띄어 쓰면 읽기가 쉬워요."], "figure": "칸 공책에 한 칸씩 비워 가며 글씨를 쓰는 아이 손", "example": "나는학교에가요. → 나는 학교에 가요.", "heading": "낱말 사이를 띄어 써요"}, {"paras": ["'가', '를', '는', '에' 같은 말은 붙여 써요.", "앞 낱말에 꼭 붙어 다녀요."], "figure": "", "example": "🐶 강아지가 / 🍎 사과를 / 🏫 학교에", "heading": "작은 말은 붙여 써요"}, {"paras": ["띄는 곳이 다르면 뜻도 달라요.", "그래서 띄어쓰기가 중요해요."], "figure": "방문 앞에 선 아빠와 커다란 가방 그림", "example": "👨 아버지가 방에 들어가신다. / 👜 아버지 가방에 들어가신다.", "heading": "띄어 쓰면 뜻이 바뀌어요"}, {"paras": ["쉼표(,) 뒤에서는 조금 쉬어요. ∨로 표시해요.", "마침표(.) 뒤에서는 조금 더 쉬어요. ≫로 표시해요."], "figure": "그림책을 소리 내어 읽는 아이", "example": "토끼야,∨같이 놀자.≫ 응,∨좋아.≫", "heading": "쉬어 읽어요"}], "parent_tip": "부모님께: 1~2학년 아이들은 '이', '가', '를' 같은 조사를 띄어 쓰거나 모든 글자를 붙여 쓰는 실수를 자주 합니다. '아버지가 방에/아버지 가방에'처럼 띄어쓰기로 뜻이 바뀌는 문장을 함께 읽고 웃어 보면 띄어쓰기의 필요를 쉽게 느낍니다. 그림책을 읽을 때 쉼표와 마침표에서 손뼉을 한 번, 두 번 치며 쉬어 읽어 보세요.", "expressions": [{"en": "나는 학교에 가요.", "ko": "'나는', '학교에', '가요' 세 덩어리로 띄어 써요."}, {"en": "아버지가 방에 들어가신다.", "ko": "👨 아버지가 방 안으로 들어가요."}, {"en": "아버지 가방에 들어가신다.", "ko": "👜 아버지가 가방 속에 들어가요. (띄어쓰기로 뜻이 바뀌었어요)"}, {"en": "강아지가 멍멍 짖어요.", "ko": "🐶 '강아지가'는 붙여 써요.", "note": "[강아지가 멍멍 지저요]"}, {"en": "엄마가 사과를 깎아요.", "ko": "🍎 '사과를'은 붙여 써요.", "note": "[엄마가 사과를 까까요]"}, {"en": "토끼야, 같이 놀자.", "ko": "🐰 쉼표 뒤에서 조금 쉬어 읽어요.", "note": "[토끼야, 가치 놀자]"}, {"en": "오늘은 날씨가 맑아요.", "ko": "☀️ '오늘은', '날씨가'는 붙여 써요.", "note": "[오느른 날씨가 말가요]"}, {"en": "동생이 그림을 그려요.", "ko": "🖍️ '동생이', '그림을'은 붙여 써요.", "note": "[동생이 그리믈 그려요]"}]}$j$::jsonb where slug='k1-13';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/k1-14_kw.mp3", "q0": "assets/audio/n/k1-14_q0.mp3", "q1": "assets/audio/n/k1-14_q1.mp3", "q2": "assets/audio/n/k1-14_q2.mp3", "q3": "assets/audio/n/k1-14_q3.mp3", "q4": "assets/audio/n/k1-14_q4.mp3", "s0": "assets/audio/n/k1-14_s0.mp3", "s1": "assets/audio/n/k1-14_s1.mp3", "s2": "assets/audio/n/k1-14_s2.mp3", "s3": "assets/audio/n/k1-14_s3.mp3", "sum": "assets/audio/n/k1-14_sum.mp3", "cover": "assets/audio/n/k1-14_cover.mp3"}, "quiz": [{"q": "묻는 문장 끝에 쓰는 부호는?", "answer": 1, "choices": ["마침표 .", "물음표 ?", "느낌표 !", "쉼표 ,"], "explain": "묻는 문장 끝에는 물음표(?)를 써요."}, {"q": "🌈 '와, 무지개다' 끝에 알맞은 부호는?", "answer": 2, "choices": [".", "?", "!", ","], "explain": "놀라고 기쁜 마음이니 느낌표(!)를 써요."}, {"q": "끝을 올려 읽는 문장은?", "answer": 3, "choices": ["사과를 먹어요.", "사과가 맛있다!", "사과가 빨개요.", "사과를 먹어요?"], "explain": "물음표가 있는 묻는 문장은 끝을 올려 읽어요."}, {"q": "마침표를 쓰기 알맞은 문장은?", "answer": 0, "choices": ["나는 1학년이에요", "몇 살이니", "어디 가니", "누구세요"], "explain": "'나는 1학년이에요'는 알려 주는 문장이라 마침표를 써요. 나머지는 묻는 문장이에요."}, {"q": "'밥 먹어요?'는 어떤 문장일까요?", "answer": 1, "choices": ["알려 주는 문장", "묻는 문장", "놀란 문장", "부르는 문장"], "explain": "물음표가 있으니 묻는 문장이에요."}], "intro": "문장 끝에는 작은 표시가 붙어요. 표시에 따라 읽는 느낌이 달라져요.", "summary": ["알려 주는 문장 끝에는 마침표(.)를 써요.", "묻는 문장 끝에는 물음표(?)를 쓰고 끝을 올려 읽어요.", "놀라거나 기쁜 느낌에는 느낌표(!)를 써요."], "keywords": [{"word": "문장 부호", "meaning": "문장에 쓰는 여러 가지 표시"}, {"word": "마침표", "meaning": "알려 주는 문장 끝에 쓰는 ."}, {"word": "물음표", "meaning": "묻는 문장 끝에 쓰는 ?"}, {"word": "느낌표", "meaning": "놀람이나 기쁨 같은 느낌을 나타낼 때 쓰는 !"}], "sections": [{"paras": ["무엇을 알려 주는 문장 끝에 써요.", "끝을 살짝 내려 읽어요."], "figure": "공책 문장 끝에 점을 콕 찍는 연필", "example": "나는 여덟 살이에요.", "heading": "마침표( . )"}, {"paras": ["묻는 문장 끝에 써요.", "끝을 올려 읽어요."], "figure": "고개를 갸웃하며 묻는 아이", "example": "🍚 밥 먹었니?", "heading": "물음표( ? )"}, {"paras": ["놀라거나 기쁜 마음일 때 써요.", "느낌을 살려 힘 있게 읽어요."], "figure": "창밖 무지개를 보고 놀란 아이", "example": "🌈 와, 무지개다!", "heading": "느낌표( ! )"}, {"paras": ["같은 말도 부호에 따라 달라요.", "'밥 먹어요.'는 알려 주는 말이에요.", "'밥 먹어요?'는 묻는 말이에요.", "'밥 먹어요!'는 힘주어 말하는 말이에요."], "figure": "", "example": "밥 먹어요. / 밥 먹어요? / 밥 먹어요!", "heading": "부호가 바뀌면 뜻도 바뀌어요"}], "parent_tip": "부모님께: 같은 문장을 '밥 먹어요. / 밥 먹어요? / 밥 먹어요!'처럼 부호만 바꿔 읽어 주면 아이가 차이를 금방 느낍니다. 그림책을 읽을 때 문장 끝 부호를 손가락으로 짚고 목소리를 바꿔 읽는 놀이를 해 보세요. 느낌표는 쓰는 사람의 마음에 따라 마침표로도 쓸 수 있으니 너무 엄격하게 정답을 강요하지 않으셔도 됩니다.", "expressions": [{"en": "마침표", "ko": "알려 주는 문장 끝에 쓰는 ."}, {"en": "물음표", "ko": "묻는 문장 끝에 쓰는 ?", "note": "[무름표]"}, {"en": "느낌표", "ko": "느낌을 나타내는 !"}, {"en": "나는 여덟 살이에요.", "ko": "마침표 문장: 알려 주는 말", "note": "[나는 여덜 사리에요] 끝을 내려 읽어요"}, {"en": "오늘은 월요일이에요.", "ko": "마침표 문장: 알려 주는 말", "note": "[오느른 워료이리에요] 끝을 내려 읽어요"}, {"en": "이름이 뭐예요?", "ko": "물음표 문장: 묻는 말", "note": "[이르미 뭐예요] 끝을 올려 읽어요"}, {"en": "어디 가니?", "ko": "물음표 문장: 묻는 말", "note": "끝을 올려 읽어요"}, {"en": "와, 무지개다!", "ko": "🌈 느낌표 문장: 놀라고 기쁜 말", "note": "힘 있게 읽어요"}, {"en": "우아, 정말 멋지다!", "ko": "느낌표 문장: 감탄하는 말", "note": "[우아, 정말 먿찌다]"}, {"en": "밥 먹어요.", "ko": "🍚 알려 주는 말", "note": "[밤 머거요] 끝을 내려 읽어요"}, {"en": "밥 먹어요?", "ko": "🍚 묻는 말", "note": "[밤 머거요] 끝을 올려 읽어요"}]}$j$::jsonb where slug='k1-14';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/k1-18_kw.mp3", "q0": "assets/audio/n/k1-18_q0.mp3", "q1": "assets/audio/n/k1-18_q1.mp3", "q2": "assets/audio/n/k1-18_q2.mp3", "q3": "assets/audio/n/k1-18_q3.mp3", "q4": "assets/audio/n/k1-18_q4.mp3", "s0": "assets/audio/n/k1-18_s0.mp3", "s1": "assets/audio/n/k1-18_s1.mp3", "s2": "assets/audio/n/k1-18_s2.mp3", "s3": "assets/audio/n/k1-18_s3.mp3", "sum": "assets/audio/n/k1-18_sum.mp3", "cover": "assets/audio/n/k1-18_cover.mp3"}, "quiz": [{"q": "🌙 자기 전에 부모님께 하는 인사는?", "answer": 0, "choices": ["안녕히 주무세요.", "잘 먹었습니다.", "다녀오겠습니다.", "안녕히 가세요."], "explain": "잠자리에 들 때는 '안녕히 주무세요.'라고 해요."}, {"q": "친구 집에서 나올 때, 집에 남는 친구 어머니께 하는 인사는?", "answer": 1, "choices": ["안녕히 가세요.", "안녕히 계세요.", "잘 먹겠습니다.", "안녕히 주무세요."], "explain": "내가 떠나고 어머니는 남으시니 '안녕히 계세요.'라고 해요."}, {"q": "'밥'의 높임말은?", "answer": 2, "choices": ["댁", "연세", "진지", "말씀"], "explain": "어른께는 '밥' 대신 '진지'라고 해요."}, {"q": "할아버지께 알맞게 말한 것은?", "answer": 3, "choices": ["할아버지, 밥 먹어.", "할아버지, 밥 먹자.", "할아버지, 빨리 와.", "할아버지, 진지 드세요."], "explain": "'진지', '드세요'를 써서 할아버지를 높였어요."}, {"q": "🎒 학교에 가면서 가족에게 하는 인사는?", "answer": 1, "choices": ["다녀왔습니다.", "다녀오겠습니다.", "안녕히 주무세요.", "잘 먹었습니다."], "explain": "집을 나설 때는 '다녀오겠습니다.'라고 해요."}], "intro": "인사를 하면 마음이 따뜻해져요. 어른께는 높임말을 써요.", "summary": ["때와 장소에 맞는 인사말을 해요.", "떠나는 사람에게는 '안녕히 가세요', 남는 사람에게는 '안녕히 계세요'예요.", "어른께는 진지, 댁, 연세 같은 높임말과 '-요, -습니다'를 써요."], "keywords": [{"word": "인사말", "meaning": "만나거나 헤어질 때, 고마울 때 하는 말"}, {"word": "높임말", "meaning": "어른을 높여서 하는 말"}, {"word": "진지", "meaning": "'밥'의 높임말"}, {"word": "댁", "meaning": "'집'의 높임말"}, {"word": "연세", "meaning": "'나이'의 높임말"}], "sections": [{"paras": ["만나면 '안녕하세요.'라고 해요.", "밥 먹기 전에는 '잘 먹겠습니다.'라고 해요."], "figure": "현관에서 가족에게 인사하는 아이", "example": "🌙 자기 전: 안녕히 주무세요. / 🎒 학교 갈 때: 다녀오겠습니다.", "heading": "때에 맞는 인사말"}, {"paras": ["떠나는 사람에게는 '안녕히 가세요.'라고 해요.", "남는 사람에게는 '안녕히 계세요.'라고 해요."], "figure": "문 앞에서 손을 흔드는 아이", "example": "🚪 손님이 가실 때: 안녕히 가세요.", "heading": "가는 사람, 남는 사람"}, {"paras": ["고마우면 '고맙습니다.'라고 해요.", "잘못했으면 '죄송합니다.'라고 해요."], "figure": "선물을 두 손으로 받는 아이", "example": "🎁 고맙습니다. / 🙇 죄송합니다.", "heading": "고마울 때, 미안할 때"}, {"paras": ["어른께는 높이는 낱말을 써요.", "밥은 '진지', 집은 '댁'이라고 해요.", "'먹다' 대신 '드시다', '자다' 대신 '주무시다'처럼 높이는 말을 쓰고, 말끝에 '-요'나 '-습니다'를 붙여요."], "figure": "할머니께 밥그릇을 두 손으로 드리는 아이", "example": "👵 할머니, 진지 드세요.", "heading": "어른께 쓰는 높임말"}], "parent_tip": "부모님께: 아이들은 '안녕히 가세요'와 '안녕히 계세요'를 가장 많이 헷갈립니다. '누가 떠나고 누가 남지?'를 먼저 묻게 해 주세요. 높임말은 설명보다 생활 속에서 부모님이 조부모님께 쓰는 모습을 보여 주는 것이 가장 효과적입니다. 아이가 '진지 드세요'처럼 바르게 말하면 바로 칭찬해 주세요.", "expressions": [{"en": "안녕하세요", "ko": "만났을 때 하는 인사"}, {"en": "안녕히 주무세요", "ko": "🌙 자기 전에 어른께 하는 인사"}, {"en": "안녕히 가세요", "ko": "떠나는 사람에게 하는 인사"}, {"en": "안녕히 계세요", "ko": "남는 사람에게 하는 인사", "note": "[안녕히 게세요]"}, {"en": "잘 먹겠습니다", "ko": "🍚 밥 먹기 전 인사", "note": "[잘 먹껟씀니다]"}, {"en": "다녀오겠습니다", "ko": "🎒 집을 나설 때 인사", "note": "[다녀오겓씀니다]"}, {"en": "다녀왔습니다", "ko": "🏠 집에 돌아왔을 때 인사", "note": "[다녀왇씀니다]"}, {"en": "고맙습니다", "ko": "🎁 고마울 때 하는 말", "note": "[고맙씀니다]"}, {"en": "죄송합니다", "ko": "🙇 어른께 잘못을 빌 때 하는 말", "note": "[죄송함니다]"}, {"en": "진지 드세요", "ko": "'밥 먹어요'의 높임말"}, {"en": "할머니 댁", "ko": "'할머니 집'의 높임말"}, {"en": "연세", "ko": "'나이'의 높임말"}]}$j$::jsonb where slug='k1-18';
update public.lessons set content=$j${"quiz": [{"q": "문단에서 가장 중요한 생각을 담은 문장은 무엇일까요?", "answer": 1, "choices": ["뒷받침 문장", "중심 문장", "마지막 문장", "제목"], "explain": "가장 중요한 생각을 담은 문장을 중심 문장이라고 해요."}, {"q": "중심 문장이 가장 많이 나오는 위치는 어디일까요?", "answer": 0, "choices": ["문단의 처음", "문단의 가운데", "제목 바로 위", "글의 맨 끝 줄"], "explain": "중심 문장은 문단의 처음에 많이 나오고, 끝에 나오기도 해요."}, {"q": "“고양이는 밤에도 잘 봐요. 고양이 눈은 적은 빛도 잘 모아요. 그래서 어두운 곳에서도 쥐를 잡을 수 있어요.” 이 문단의 중심 문장은?", "answer": 3, "choices": ["고양이 눈은 적은 빛도 잘 모아요.", "그래서 어두운 곳에서도 쥐를 잡을 수 있어요.", "고양이는 쥐를 좋아해요.", "고양이는 밤에도 잘 봐요."], "explain": "나머지 문장은 모두 고양이가 밤에도 잘 본다는 내용을 설명하고 있어요."}, {"q": "뒷받침 문장이 하는 일로 알맞은 것은?", "answer": 0, "choices": ["중심 문장을 자세히 설명하거나 예를 든다", "글의 제목을 정한다", "새 문단을 시작한다", "중심 문장과 반대되는 말을 한다"], "explain": "뒷받침 문장은 중심 문장의 내용을 자세히 풀어 주거나 예를 들어 줘요."}, {"q": "중심 문장을 찾는 방법으로 알맞은 것은?", "answer": 2, "choices": ["가장 긴 문장을 고른다", "무조건 첫 문장을 고른다", "다른 문장들이 공통으로 설명하는 문장을 찾는다", "모르는 낱말이 있는 문장을 고른다"], "explain": "중심 문장은 다른 문장들을 모두 아우르는 문장이에요. 위치만 보고 정하면 틀릴 수 있어요."}], "intro": "글을 다 읽었는데 무슨 내용이었는지 한마디로 말하기 어려웠던 적이 있나요? 문단마다 숨어 있는 ‘중심 문장’을 찾으면 글의 내용이 한눈에 들어와요.", "summary": ["문단은 하나의 생각을 담은 문장들의 묶음이에요.", "문단은 중심 문장과 그것을 설명하는 뒷받침 문장으로 이루어져요.", "중심 문장은 주로 문단의 처음이나 끝에 있고, 다른 문장들을 모두 아우르는 문장이에요."], "keywords": [{"word": "문단", "meaning": "하나의 생각을 담고 있는 문장들의 묶음"}, {"word": "중심 문장", "meaning": "문단에서 가장 중요한 생각을 담은 문장"}, {"word": "뒷받침 문장", "meaning": "중심 문장을 자세히 설명하거나 예를 들어 주는 문장"}, {"word": "중심 생각", "meaning": "글 전체에서 글쓴이가 가장 말하고 싶은 생각"}], "sections": [{"paras": ["글은 여러 개의 문단으로 이루어져 있어요. 문단은 하나의 생각을 담고 있는 문장들의 묶음이에요.", "새 문단이 시작될 때는 줄을 바꾸고 첫 칸을 한 칸 비우고 써요. 그래서 들여 쓴 곳을 보면 문단이 어디서 시작하는지 알 수 있어요."], "figure": "공책에 쓴 글에서 문단마다 첫 칸이 들여쓰기된 모습", "example": "글 한 편 = 문단 + 문단 + 문단 … / 문단 하나 = 중심 문장 1개 + 뒷받침 문장 여러 개", "heading": "문단은 생각 하나를 담은 덩어리예요"}, {"paras": ["문단에서 가장 중요한 생각을 담은 문장을 ‘중심 문장’이라고 해요.", "중심 문장의 내용을 자세히 설명하거나 예를 들어 주는 문장은 ‘뒷받침 문장’이라고 해요. 뒷받침 문장은 중심 문장을 받쳐 주는 기둥과 같아요."], "figure": "지붕(중심 문장)을 여러 기둥(뒷받침 문장)이 받치고 있는 집 그림", "example": "[중심 문장] 개미는 서로 도우며 살아가요. [뒷받침 문장] 먹이를 찾으면 동료에게 알려 줘요. 무거운 먹이는 여럿이 함께 옮겨요. 집을 지킬 때도 힘을 모아요.", "heading": "중심 문장과 뒷받침 문장"}, {"paras": ["중심 문장은 문단의 처음에 나오는 경우가 가장 많아요. 하지만 문단의 끝에서 앞의 내용을 정리하며 나오기도 해요.", "그러니 위치만 보고 정하지 말고, 문단의 모든 문장을 아우르는 문장인지 꼭 확인해야 해요."], "figure": "문단의 첫 문장과 마지막 문장에 각각 형광펜을 칠한 종이", "example": "끝에 있는 경우: “봄에는 진달래가 피어요. 여름에는 해바라기가 피어요. 가을에는 국화가 피어요. 이처럼 계절마다 피는 꽃이 달라요.”", "heading": "중심 문장은 어디에 있을까요?"}, {"paras": ["① 문단을 끝까지 읽고 무엇에 대한 이야기인지 생각해요. ② 다른 문장들이 공통으로 설명하는 문장을 찾아요. ③ 그 문장을 빼면 문단의 내용을 알기 어려운지 확인해요.", "각 문단의 중심 문장을 모아 이으면 글 전체의 중심 생각을 짧게 정리할 수 있어요."], "figure": "연필로 문단의 한 문장에 밑줄을 긋는 아이의 손", "example": "“우리 몸에 물은 꼭 필요해요. 물은 몸속 찌꺼기를 내보내요. 땀을 흘려 체온을 조절해 줘요.” → 중심 문장: 우리 몸에 물은 꼭 필요해요.", "heading": "이렇게 찾아요"}], "parent_tip": "아이들은 중심 문장을 ‘첫 문장’이라고만 외우는 경우가 많습니다. 끝에 정리하듯 나오는 문단도 함께 보여 주시고, “이 문장들이 모두 무엇에 대해 말하고 있어?”라고 물어 주세요. 신문 기사나 동화책 한 문단을 골라 한 문장으로 줄여 말해 보게 하면 요약하는 힘도 함께 자랍니다.", "expressions": []}$j$::jsonb where slug='k3-02';
update public.lessons set content=$j${"quiz": [{"q": "국어사전에서 낱말을 찾을 때 가장 먼저 살펴보는 것은?", "answer": 1, "choices": ["첫 글자의 받침", "첫 글자의 첫 자음자", "마지막 글자", "낱말의 길이"], "explain": "첫 자음자 → 모음자 → 받침 순서로 살펴요."}, {"q": "‘달렸다’를 국어사전에서 찾으려면 어떤 모양으로 찾아야 할까요?", "answer": 2, "choices": ["달렸다", "달려", "달리다", "달"], "explain": "‘달리고, 달리니’처럼 다른 모양과 견주어 보면 바뀌지 않는 부분은 ‘달리-’예요. 여기에 ‘-다’를 붙인 ‘달리다’가 기본형이에요."}, {"q": "국어사전에 먼저 나오는 낱말은?", "answer": 2, "choices": ["하늘", "바다", "구름", "사과"], "explain": "첫 자음자를 비교하면 ㄱ(구름)이 ㅂ, ㅅ, ㅎ보다 앞이에요."}, {"q": "‘고기’와 ‘거미’ 중 국어사전에 먼저 나오는 낱말과 그 까닭으로 알맞은 것은?", "answer": 1, "choices": ["고기 - ㅗ가 ㅓ보다 앞이라서", "거미 - ㅓ가 ㅗ보다 앞이라서", "고기 - 받침이 없어서", "거미 - 글자 수가 적어서"], "explain": "첫 자음자가 ㄱ으로 같으니 모음자를 비교해요. ㅓ가 ㅗ보다 앞이라 ‘거미’가 먼저예요."}, {"q": "기본형이 ‘작다’인 낱말이 __아닌__ 것은?", "answer": 3, "choices": ["작아서", "작고", "작으니", "잡아서"], "explain": "‘잡아서’의 기본형은 ‘잡다’예요."}], "intro": "국어사전에서 ‘먹었다’를 찾아보면 아무리 넘겨도 나오지 않아요. 국어사전에는 낱말이 정해진 순서와 정해진 모양으로 실려 있기 때문이에요. 그 비밀을 알아보아요.", "summary": ["국어사전에는 낱말이 첫 자음자 → 모음자 → 받침 순서로 실려 있어요.", "받침이 없는 글자가 받침이 있는 글자보다 먼저 나와요.", "모양이 바뀌는 낱말은 바뀌지 않는 부분에 ‘-다’를 붙인 기본형으로 찾아요."], "keywords": [{"word": "국어사전", "meaning": "우리말 낱말을 순서대로 모아 뜻과 쓰임을 풀이한 책"}, {"word": "자음자", "meaning": "ㄱ, ㄴ, ㄷ처럼 자음을 나타내는 글자"}, {"word": "모음자", "meaning": "ㅏ, ㅑ, ㅓ처럼 모음을 나타내는 글자"}, {"word": "받침", "meaning": "글자의 아래에 받쳐 적는 자음자"}, {"word": "기본형", "meaning": "모양이 바뀌는 낱말에서 바뀌지 않는 부분에 ‘-다’를 붙인 모양"}], "sections": [{"paras": ["국어사전에는 낱말이 자음자와 모음자의 순서에 따라 실려 있어요. 먼저 첫 글자의 첫 자음자를 보고, 같으면 모음자, 그다음 받침을 차례로 살펴요.", "첫 글자가 모두 같으면 두 번째 글자를 같은 방법으로 비교해요."], "figure": "책상 위에 펼친 국어사전의 옆면에 자음자 색인 표시가 보이는 모습", "example": "찾는 순서: ① 첫 자음자 → ② 모음자 → ③ 받침 (받침이 없는 글자가 받침 있는 글자보다 먼저 나와요.)", "heading": "국어사전은 글자 순서대로 실려 있어요"}, {"paras": ["자음자는 ㄱ부터 ㅎ까지의 순서이고, 된소리(ㄲ, ㄸ, ㅃ, ㅆ, ㅉ)는 짝이 되는 자음자 바로 뒤에 와요.", "모음자는 ㅏ부터 ㅣ까지의 순서이고, ㅐ나 ㅘ처럼 두 모음이 합쳐진 모음자는 정해진 자리에 끼어 있어요."], "figure": "자음자 카드와 모음자 카드를 순서대로 한 줄씩 늘어놓은 책상", "example": "자음자: ㄱ ㄲ ㄴ ㄷ ㄸ ㄹ ㅁ ㅂ ㅃ ㅅ ㅆ ㅇ ㅈ ㅉ ㅊ ㅋ ㅌ ㅍ ㅎ\n모음자: ㅏ ㅐ ㅑ ㅒ ㅓ ㅔ ㅕ ㅖ ㅗ ㅘ ㅙ ㅚ ㅛ ㅜ ㅝ ㅞ ㅟ ㅠ ㅡ ㅢ ㅣ", "heading": "자음자와 모음자의 순서"}, {"paras": ["‘나무’, ‘가방’, ‘누나’를 사전 순서로 놓아 볼까요? 첫 자음자를 보면 ‘가방’의 ㄱ이 가장 앞이에요.", "‘나무’와 ‘누나’는 첫 자음자가 ㄴ으로 같으니 모음자를 비교해요. ㅏ가 ㅜ보다 앞이므로 ‘나무’가 먼저예요."], "figure": "낱말 카드 세 장을 순서대로 줄 세우는 아이의 손", "example": "가방 → 나무 → 누나 / 받침 비교: 가 → 각 → 간 (받침 없음 → ㄱ → ㄴ)", "heading": "이렇게 순서를 정해요"}, {"paras": ["‘먹었다, 먹고, 먹어서, 먹으니’처럼 쓰임에 따라 모양이 바뀌는 낱말이 있어요. 이런 낱말은 국어사전에 ‘먹다’라는 하나의 모양으로만 실려 있어요. 이 모양을 ‘기본형’이라고 해요.", "기본형은 모양이 바뀌지 않는 부분에 ‘-다’를 붙여 만들어요. ‘먹었다’에서 바뀌지 않는 부분은 ‘먹-’이니 ‘먹다’로 찾으면 돼요."], "figure": "공책에 낱말의 바뀌지 않는 부분에 동그라미를 친 모습", "example": "읽고, 읽어서, 읽으니 → 읽다 / 작아서, 작고, 작으니 → 작다 / 뛰었다, 뛰고 → 뛰다", "heading": "모양이 바뀌는 낱말은 기본형으로 찾아요"}], "parent_tip": "요즘은 인터넷 사전에 활용형을 넣어도 기본형을 찾아 주지만, 종이 사전을 찾아보면 낱말의 짜임과 순서를 확실히 익힐 수 있습니다. 아이가 ‘먹었다’를 그대로 찾으려 하면 “모양이 바뀌지 않는 부분이 어디까지일까?”라고 물어 주세요. ㅐ, ㅔ, ㅚ 같은 모음자의 순서는 아이들이 많이 헷갈리니 사전 옆면을 함께 보며 확인하면 좋습니다.", "expressions": []}$j$::jsonb where slug='k3-04';
update public.lessons set content=$j${"quiz": [{"q": "바르게 쓴 문장은?", "answer": 1, "choices": ["상처가 다 낳았어요.", "상처가 다 나았어요.", "상처가 다 낮았어요.", "상처가 다 낫았어요."], "explain": "병이나 상처가 없어지는 것은 ‘낫다’예요. ‘나았어요’로 써요."}, {"q": "“손가락으로 북쪽을 ( ).” 빈칸에 알맞은 말은?", "answer": 1, "choices": ["가르쳤어요", "가리켰어요", "가르켰어요", "가리쳤어요"], "explain": "방향을 집어 보이는 것은 ‘가리키다’예요."}, {"q": "‘안’과 ‘않’을 바르게 쓴 문장은?", "answer": 2, "choices": ["오늘은 학교에 가지 안았어요.", "나는 우유를 않 마셔요.", "숙제를 아직 안 했어요.", "동생이 울지 안는다."], "explain": "‘안 했어요’는 ‘아니 했어요’의 줄임이라 바르게 썼어요. ‘-지’ 뒤에는 ‘않’을 써요."}, {"q": "바르게 쓴 낱말은?", "answer": 3, "choices": ["몇일", "금새", "설겆이", "며칠"], "explain": "‘며칠’, ‘금세’, ‘설거지’가 바른 말이에요."}, {"q": "“퀴즈의 정답을 ( ).” 빈칸에 알맞은 말은?", "answer": 0, "choices": ["맞혔어요", "맞췄어요", "마쳤어요", "맡혔어요"], "explain": "정답을 골라내는 것은 ‘맞히다’예요. ‘맞추다’는 퍼즐처럼 제자리에 끼우거나 서로 대어 볼 때 써요."}], "intro": "“감기가 빨리 낳았으면 좋겠어.” 어디가 틀렸는지 보이나요? 소리는 비슷한데 뜻과 모양이 다른 말, 자주 틀리는 말을 바르게 쓰는 방법을 알아보아요.", "summary": ["소리가 같거나 비슷해도 뜻에 따라 낫다·낳다·낮다처럼 다르게 써요.", "가르치다·가리키다, 잃어버리다·잊어버리다, 맞히다·맞추다는 뜻을 생각해 골라 써요.", "‘안’은 빼도 말이 되고, ‘않’은 ‘-지’ 뒤에 써요. 며칠·금세·설거지처럼 바른 모양을 익혀요."], "keywords": [{"word": "맞춤법", "meaning": "말을 글자로 바르게 적는 규칙"}, {"word": "낫다", "meaning": "병이나 상처가 없어져 본래대로 되다"}, {"word": "가리키다", "meaning": "손가락 등으로 방향이나 대상을 집어 보이다"}, {"word": "가르치다", "meaning": "지식이나 기술 등을 알려 주다"}, {"word": "잊어버리다", "meaning": "알았던 것을 기억하지 못하게 되다"}], "sections": [{"paras": ["‘낫다’와 ‘낮다’는 둘 다 [낟따]처럼 소리 나고, ‘낳다’[나타]도 소리가 비슷해서 헷갈리기 쉬워요. 이런 말은 문장의 뜻을 생각해서 알맞은 낱말을 골라야 해요.", "‘낫다’는 병이나 상처가 없어진다는 뜻, ‘낳다’는 아기나 알을 몸 밖으로 내놓는다는 뜻, ‘낮다’는 높지 않다는 뜻이에요."], "figure": "책상 위에 놓인 달걀 바구니, 반창고, 낮은 블록 탑", "example": "감기가 다 나았어요. / 닭이 알을 낳았어요. / 담장이 낮아요.\n편지를 부쳐요(보내요). / 우표를 붙여요(달라붙게 해요).\n반드시(꼭) 지킬게요. / 반듯이(바르게) 앉아요.", "heading": "소리는 같은데 뜻이 다른 말"}, {"paras": ["‘가르치다’는 지식이나 기술을 알려 준다는 뜻이고, ‘가리키다’는 손가락 등으로 방향이나 대상을 집어 보인다는 뜻이에요.", "‘잃어버리다’는 물건이 없어진 것이고, ‘잊어버리다’는 기억하지 못하는 것이에요. ‘맞히다’는 정답을 골라낸다는 뜻이고, ‘맞추다’는 서로 대어 보거나 제자리에 끼운다는 뜻이에요."], "figure": "손가락으로 창밖을 가리키는 아이와 칠판 앞에서 설명하는 손", "example": "선생님께서 수학을 가르치세요. / 손가락으로 산을 가리켜요.\n지갑을 잃어버렸어요. / 숙제를 잊어버렸어요.\n퀴즈 정답을 맞혔어요. / 퍼즐 조각을 맞췄어요.", "heading": "뜻이 헷갈리는 말"}, {"paras": ["‘안’은 ‘아니’를 줄인 말로, 움직임이나 상태를 나타내는 말 앞에 써요. ‘않’은 ‘아니하’를 줄인 말로, ‘-지’ 뒤에 써요.", "헷갈릴 때는 그 낱말을 빼 보세요. ‘안’은 빼도 문장이 되지만 ‘않’은 빼면 문장이 어색해져요."], "figure": "공책에 ‘안’과 ‘않’을 두 칸으로 나누어 정리한 모습", "example": "밥을 안 먹었어요. (아니 먹었어요) / 밥을 먹지 않았어요. (먹지 아니하였어요)", "heading": "‘안’과 ‘않’ 구별하기"}, {"paras": ["소리 나는 대로 쓰다가 자주 틀리는 말들이 있어요. 바른 모양을 눈에 익혀 두면 틀리지 않아요.", "‘되’와 ‘돼’가 헷갈리면 ‘하’와 ‘해’를 넣어 보세요. ‘하’가 어울리면 ‘되’, ‘해’가 어울리면 ‘돼’예요."], "figure": "빨간 색연필로 틀린 낱말을 고친 받아쓰기 공책", "example": "몇일 ✕ → 며칠 ○ / 금새 ✕ → 금세 ○ / 설겆이 ✕ → 설거지 ○ / 어떻해 ✕ → 어떻게, 어떡해 ○\n그러면 안 돼요(안 해요 ○). / 의사가 되고 싶어요(하고 ○).", "heading": "자주 틀리는 말, 이렇게 써요"}], "parent_tip": "맞춤법은 규칙을 외우기보다 문장 속에서 자주 보고 써 보는 것이 효과적입니다. 아이의 일기나 문자 메시지에서 헷갈리는 말이 나오면 바로 고쳐 주기보다 “이 말은 무슨 뜻으로 쓴 거야?”라고 물어 스스로 고르게 해 주세요. ‘안/않’, ‘되/돼’는 빼 보기와 하/해 넣어 보기 방법을 함께 연습하면 오래 기억합니다.", "expressions": []}$j$::jsonb where slug='k3-05';
update public.lessons set content=$j${"quiz": [{"q": "편지를 쓰는 차례로 알맞은 것은?", "answer": 1, "choices": ["첫인사 → 받을 사람 → 끝인사 → 전하고 싶은 말", "받을 사람 → 첫인사 → 전하고 싶은 말 → 끝인사", "전하고 싶은 말 → 받을 사람 → 첫인사 → 끝인사", "끝인사 → 첫인사 → 받을 사람 → 전하고 싶은 말"], "explain": "받을 사람 → 첫인사 → 전하고 싶은 말 → 끝인사 → 쓴 날짜 → 쓴 사람 순서로 써요."}, {"q": "선생님께 편지를 쓸 때 쓴 사람을 바르게 적은 것은?", "answer": 2, "choices": ["제자 민준이가", "민준", "제자 민준 올림", "민준이 씀"], "explain": "웃어른께는 이름 뒤에 ‘올림’이나 ‘드림’을 붙여요."}, {"q": "마음이 가장 잘 드러나게 쓴 문장은?", "answer": 3, "choices": ["고마워.", "고마워, 고마워, 고마워.", "그냥 고맙다고 쓰는 거야.", "줄넘기를 못 해서 속상할 때 끝까지 가르쳐 줘서 정말 고마웠어."], "explain": "있었던 일과 그때의 마음을 구체적으로 쓰면 마음이 잘 전해져요."}, {"q": "상을 받은 친구에게 쓸 편지에 담을 마음으로 알맞은 것은?", "answer": 0, "choices": ["축하하는 마음", "미안한 마음", "위로하는 마음", "걱정하는 마음"], "explain": "좋은 일이 생긴 친구에게는 축하하는 마음을 전해요."}], "intro": "얼굴을 보고 “고마워.”라고 말하기 쑥스러울 때가 있지요? 그럴 때 편지를 쓰면 내 마음을 차분하고 진심 있게 전할 수 있어요.", "summary": ["편지에는 고마움, 미안함, 축하, 위로 같은 마음을 담을 수 있어요.", "편지는 받을 사람 → 첫인사 → 전하고 싶은 말 → 끝인사 → 쓴 날짜 → 쓴 사람 순서로 써요.", "있었던 일과 그때의 마음을 구체적으로 쓰고, 받는 사람에 맞는 말을 골라 써요."], "keywords": [{"word": "첫인사", "meaning": "편지의 처음에 받는 사람에게 건네는 인사"}, {"word": "끝인사", "meaning": "편지를 마무리하며 건네는 인사"}, {"word": "올림", "meaning": "웃어른께 편지를 쓸 때 쓴 사람의 이름 뒤에 붙이는 말"}, {"word": "위로", "meaning": "따뜻한 말이나 행동으로 괴로움이나 슬픔을 달래 줌"}], "sections": [{"paras": ["편지에는 여러 가지 마음을 담을 수 있어요. 도움을 받았을 때의 고마운 마음, 잘못했을 때의 미안한 마음, 좋은 일이 생겼을 때의 축하하는 마음, 힘든 일을 겪은 사람을 위로하는 마음이 있어요.", "어떤 마음을 전할지 먼저 정하면 편지에 쓸 내용이 또렷해져요."], "figure": "책상 위에 색깔이 다른 편지 봉투 네 장이 놓여 있는 모습", "example": "고마운 마음: 우산을 함께 써 준 친구에게 / 미안한 마음: 말다툼한 동생에게 / 축하하는 마음: 대회에서 상을 받은 형에게 / 위로하는 마음: 다리를 다친 친구에게", "heading": "편지로 전할 수 있는 마음"}, {"paras": ["편지는 정해진 차례에 따라 써요. ① 받을 사람 ② 첫인사 ③ 전하고 싶은 말 ④ 끝인사 ⑤ 쓴 날짜 ⑥ 쓴 사람 순서예요.", "쓴 사람을 적을 때 친구에게는 ‘○○가’나 ‘○○이가’, 웃어른께는 ‘○○ 올림’이나 ‘○○ 드림’이라고 써요."], "figure": "편지지 한 장 위에 차례를 나타내는 번호 스티커가 붙어 있는 모습", "example": "① 사랑하는 할머니께 ② 할머니, 안녕하세요? 저 지호예요. ③ (전하고 싶은 말) ④ 할머니, 건강하세요. ⑤ 20○○년 5월 8일 ⑥ 손자 지호 올림", "heading": "편지의 형식을 알아요"}, {"paras": ["‘고마워’라는 말만 쓰기보다 어떤 일이 있었는지 구체적으로 쓰면 마음이 더 잘 전해져요. 그때 내 기분이 어땠는지도 함께 써 보세요.", "받는 사람에 맞게 말을 골라야 해요. 웃어른께는 높임 표현을 쓰고, 친구에게는 다정한 말로 써요."], "figure": "아이가 연필로 편지지에 정성껏 글씨를 쓰는 손", "example": "✕ 서연아, 고마워.\n○ 서연아, 지난주 비 오는 날 우산을 같이 써 줘서 정말 고마워. 비에 젖을까 봐 걱정했는데 네 덕분에 마음이 따뜻해졌어.", "heading": "마음이 잘 드러나게 쓰는 방법"}, {"paras": ["편지를 다 쓰면 받는 사람이 되었다고 생각하고 소리 내어 읽어 보세요. 형식을 빠뜨리지 않았는지, 맞춤법이 틀린 곳은 없는지 살펴요.", "편지를 받은 사람이 기분 좋게 읽을 수 있도록 글씨도 또박또박 써요."], "figure": "봉투에 편지를 넣고 스티커를 붙이는 손", "example": "확인할 것: 받을 사람·첫인사·끝인사·날짜·쓴 사람이 다 있나요? / 겪은 일과 내 마음이 드러나나요? / 높임 표현은 알맞나요?", "heading": "다 쓴 뒤에는 다시 읽어요"}], "parent_tip": "아이들은 편지에 ‘고마워, 사랑해’만 반복해서 쓰는 경우가 많습니다. “언제, 어떤 일 때문에 고마웠어?”라고 물어 구체적인 장면을 떠올리게 해 주세요. 어버이날이나 생일처럼 실제로 편지를 보낼 기회를 만들고, 받은 편지에 답장해 주시면 아이가 글로 마음을 전하는 즐거움을 느낄 수 있습니다.", "expressions": []}$j$::jsonb where slug='k3-08';
update public.lessons set content=$j${"quiz": [{"q": "다음 중 방송 매체에 해당하는 것은?", "answer": 1, "choices": ["신문", "텔레비전", "잡지", "책"], "explain": "텔레비전과 라디오는 방송 매체예요. 나머지는 인쇄 매체예요."}, {"q": "뉴스 화면에서 숫자 자료를 한눈에 보여 주기 위해 주로 쓰는 표현 방법은?", "answer": 2, "choices": ["효과음", "배경 음악", "그래프나 도표", "기자의 표정"], "explain": "그래프나 도표는 숫자 자료를 한눈에 비교하게 해 줘요."}, {"q": "광고를 볼 때의 태도로 가장 알맞은 것은?", "answer": 2, "choices": ["광고에 나온 말은 모두 사실이므로 그대로 믿는다.", "유명한 사람이 나오면 꼭 산다.", "과장된 표현은 없는지, 정말 필요한지 따져 본다.", "광고 음악이 신나면 좋은 상품이다."], "explain": "광고는 설득하려는 목적이 있으므로 비판하며 봐야 해요."}, {"q": "인터넷 정보가 믿을 만한지 확인하는 방법으로 알맞지 __않은__ 것은?", "answer": 3, "choices": ["글쓴이나 기관이 누구인지 확인한다.", "글을 쓴 날짜를 확인한다.", "다른 믿을 만한 자료와 비교한다.", "조회 수가 많으면 무조건 믿는다."], "explain": "조회 수가 많다고 해서 정보가 정확한 것은 아니에요."}], "intro": "우리는 하루에도 수없이 많은 뉴스, 광고, 영상, 인터넷 글을 만나요. 그런데 그 내용이 모두 정확할까요? 매체 자료가 어떻게 정보를 전하는지 알고, 믿을 만한지 따져 보며 읽는 방법을 배워요.", "summary": ["매체는 정보를 전달하는 수단이고, 매체 자료는 글·그림·소리·영상 등 여러 표현 방법을 함께 써요.", "뉴스는 사실과 의견을 구별하고, 광고는 과장된 표현이 없는지 따져 보며 읽어요.", "인터넷 정보는 출처, 날짜, 근거를 확인하고 함부로 퍼뜨리지 않아요."], "keywords": [{"word": "매체", "meaning": "정보나 생각을 전달하는 수단(신문, 텔레비전, 인터넷 등)"}, {"word": "매체 자료", "meaning": "매체로 전달되는 뉴스, 광고, 기사, 영상 같은 자료"}, {"word": "자막", "meaning": "영상 화면에 글자로 나타낸 내용"}, {"word": "공익 광고", "meaning": "사회에 도움이 되는 생각이나 행동을 알리는 광고"}, {"word": "출처", "meaning": "정보나 자료가 나온 곳"}, {"word": "신뢰성", "meaning": "정보를 믿을 수 있는 정도"}], "sections": [{"paras": ["매체는 정보나 생각을 전달하는 수단이에요. 책·신문·잡지 같은 인쇄 매체, 텔레비전·라디오 같은 방송 매체, 누리집·누리 소통망(SNS)·동영상 사이트 같은 인터넷 매체가 있어요.", "매체 자료는 이런 매체로 전달되는 뉴스, 광고, 기사, 영상, 게시글 같은 자료를 말해요.", "매체마다 정보를 전하는 방법이 달라요. 인쇄 매체는 글과 사진, 라디오는 소리, 텔레비전과 동영상은 영상·소리·자막을 함께 써요."], "figure": "책상 위에 신문, 라디오, 태블릿 화면이 나란히 놓여 있는 모습", "example": "인쇄 매체: 신문, 잡지, 책 / 방송 매체: 텔레비전 뉴스, 라디오 / 인터넷 매체: 누리집 기사, 블로그, 동영상", "heading": "매체와 매체 자료란?"}, {"paras": ["영상 매체 자료에서는 글(자막), 사진, 그림, 도표, 소리(말, 음악, 효과음), 움직이는 영상이 함께 쓰여요.", "예를 들어 텔레비전 뉴스는 기자의 말로 내용을 전하고, 자막으로 핵심을 정리하며, 그래프로 숫자를 한눈에 보여 주고, 현장 영상으로 생생함을 더해요.", "매체 자료를 읽을 때는 각 표현 방법이 어떤 효과를 주는지 생각하면 내용을 더 깊이 이해할 수 있어요."], "figure": "뉴스 화면을 자막·그래프·현장 영상 부분으로 나누어 표시한 도식", "example": "뉴스 화면 예: 자막 \"올여름 열대야 일수 지난해의 두 배\" + 막대그래프 + 밤에 공원에서 더위를 식히는 시민들 영상", "heading": "매체 자료는 여러 가지 표현 방법을 함께 써요"}, {"paras": ["뉴스는 사회에서 일어난 일을 사실에 따라 전하는 매체 자료예요. 그래도 만드는 사람이 어떤 내용을 고르고 어떻게 보여 주느냐에 따라 받아들이는 느낌이 달라질 수 있어요.", "뉴스를 볼 때는 ① 사실과 의견을 구별하고 ② 근거 자료(조사 결과, 인터뷰)가 믿을 만한지 ③ 한쪽 입장만 전하지 않았는지 살펴봐요.", "같은 일을 다룬 다른 뉴스와 비교해 보면 더 정확하게 알 수 있어요."], "figure": "같은 공원 사진에 서로 다른 제목이 붙은 두 개의 신문 기사", "example": "뉴스 A: \"새 공원 개장, 주민들 크게 반겨\" / 뉴스 B: \"새 공원 개장… 주차 공간 부족해 불편 호소도\"\n→ 같은 일이라도 어떤 면을 강조했는지에 따라 느낌이 달라요.", "heading": "뉴스를 읽을 때는 이렇게"}, {"paras": ["광고는 상품이나 생각을 알리고 사람들이 사거나 행동하도록 설득하는 매체 자료예요.", "광고는 짧고 기억하기 쉬운 문구, 눈에 띄는 색깔과 그림, 신나는 음악, 유명한 사람 등을 이용해 관심을 끌어요.", "그래서 광고를 볼 때는 과장된 표현이 없는지, 정말 필요한 물건인지, 광고에서 말하지 않은 단점은 없는지 따져 봐야 해요. 공익 광고처럼 좋은 생각이나 행동을 알리는 광고도 있어요."], "figure": "음료 광고 포스터를 보며 고개를 갸웃하는 아이", "example": "상품 광고: \"마시기만 하면 키가 쑥쑥! 친구들 모두 마시는 바로 그 음료!\"(과장된 표현)\n공익 광고: \"양치할 때 컵을 쓰면 물을 크게 아낄 수 있어요.\"(물 절약 권유)", "heading": "광고는 '사고 싶게' 만들어요"}, {"paras": ["인터넷에는 누구나 글을 올릴 수 있어서 잘못된 정보나 일부러 꾸며 낸 가짜 정보도 섞여 있어요.", "인터넷 정보를 볼 때는 ① 누가 썼는지(출처) ② 언제 쓴 글인지(최신 정보인지) ③ 근거가 있는지 ④ 다른 믿을 만한 자료에도 같은 내용이 있는지 확인해요.", "확인하지 않은 정보를 다른 사람에게 함부로 퍼뜨리지 않는 것도 중요한 매체 예절이에요."], "figure": "태블릿 화면 옆에 체크 표시가 된 점검표 종이", "example": "점검표: □ 글쓴이나 기관이 밝혀져 있나요? □ 날짜가 최근인가요? □ 근거 자료가 있나요? □ 다른 곳에서도 같은 내용을 확인했나요?", "heading": "인터넷 정보, 믿을 만한지 따져 봐요"}], "parent_tip": "아이들은 영상이나 인터넷에 나온 내용을 그대로 믿는 경향이 있습니다. 함께 광고를 보며 \"이 광고가 말하지 않은 것은 무엇일까?\", 뉴스를 보며 \"이 내용은 누가 말한 거야? 다른 뉴스에서도 같은 말을 할까?\"라고 질문해 보세요. 아이가 친구에게 들은 '놀라운 소식'을 함께 검색해 사실인지 확인해 보는 경험도 좋습니다.", "expressions": []}$j$::jsonb where slug='k5-07';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/m1-02_kw.mp3", "q0": "assets/audio/n/m1-02_q0.mp3", "q1": "assets/audio/n/m1-02_q1.mp3", "q2": "assets/audio/n/m1-02_q2.mp3", "q3": "assets/audio/n/m1-02_q3.mp3", "s0": "assets/audio/n/m1-02_s0.mp3", "s1": "assets/audio/n/m1-02_s1.mp3", "s2": "assets/audio/n/m1-02_s2.mp3", "s3": "assets/audio/n/m1-02_s3.mp3", "sum": "assets/audio/n/m1-02_sum.mp3", "cover": "assets/audio/n/m1-02_cover.mp3"}, "quiz": [{"q": "🎲 주사위는 어떤 모양일까요?", "answer": 1, "choices": ["공 모양", "상자 모양", "둥근기둥 모양", "○ 모양"], "explain": "주사위는 평평한 부분만 있는 상자 모양이에요."}, {"q": "어느 쪽으로 굴려도 잘 굴러가는 모양은?", "answer": 2, "choices": ["📦 상자 모양", "🥫 둥근기둥 모양", "⚽ 공 모양", "△ 모양"], "explain": "공 모양은 모든 부분이 둥글어서 어느 쪽으로도 잘 굴러가요."}, {"q": "🥫 캔 바닥을 종이에 대고 따라 그리면 어떤 모양이 나올까요?", "answer": 0, "choices": ["○ 모양", "△ 모양", "□ 모양", "상자 모양"], "explain": "캔 바닥은 둥글어서 ○ 모양이 나와요."}, {"q": "삼각형의 꼭짓점은 몇 개일까요?", "answer": 3, "choices": ["2개", "4개", "5개", "3개"], "explain": "삼각형은 뾰족한 꼭짓점이 3개예요."}], "intro": "📦 상자, ⚽ 공, 🥫 캔. 우리 집 물건은 어떤 모양일까요? 손으로 만져 보며 모양을 찾아봐요.", "summary": ["📦 상자 모양은 잘 쌓이고, ⚽ 공 모양은 잘 굴러가요.", "🥫 둥근기둥 모양은 세우면 쌓이고 눕히면 굴러가요.", "삼각형은 변·꼭짓점 3개, 사각형은 4개, 원은 없어요."], "keywords": [{"word": "상자 모양", "meaning": "평평한 부분만 있어 잘 쌓이는 모양"}, {"word": "둥근기둥 모양", "meaning": "평평한 부분과 둥근 부분이 있는 모양"}, {"word": "공 모양", "meaning": "모든 부분이 둥글어 잘 굴러가는 모양"}, {"word": "변", "meaning": "도형을 이루는 곧은 선"}, {"word": "꼭짓점", "meaning": "두 변이 만나는 뾰족한 점"}], "sections": [{"paras": ["📦 상자 모양은 평평한 부분만 있어요.", "🥫 둥근기둥 모양은 평평한 부분과 둥근 부분이 있어요.", "⚽ 공 모양은 모든 부분이 둥글어요."], "figure": "책상 위에 상자, 음료 캔, 공이 나란히 놓인 모습", "example": "📦 휴지 상자·🎲 주사위 → 상자 모양 / 🥫 캔·🧻 두루마리 휴지 → 둥근기둥 모양 / ⚽ 공·🍊 귤 → 공 모양", "heading": "상자 모양, 둥근기둥 모양, 공 모양"}, {"paras": ["📦 상자 모양은 잘 쌓이고 굴러가지 않아요.", "🥫 둥근기둥 모양은 세우면 쌓을 수 있고, 눕히면 굴러가요.", "⚽ 공 모양은 어느 쪽으로도 잘 굴러가서 쌓기 어려워요."], "figure": "아이가 상자를 쌓고, 옆에서 공이 굴러가는 모습", "example": "블록 탑을 쌓을 때는 📦 상자 모양이 가장 좋아요.", "heading": "쌓아 보고 굴려 봐요"}, {"paras": ["물건을 종이에 대고 본뜨면 평평한 모양이 나와요.", "네모(□), 세모(△), 동그라미(○) 모양이에요.", "□는 사각형, △는 삼각형, ○는 원이라고 불러요."], "figure": "종이 위에 컵 바닥을 대고 연필로 동그라미를 따라 그리는 아이 손", "example": "📦 상자 바닥을 본뜨면 □, 🧀 세모 모양 치즈 조각 바닥을 본뜨면 △, 🥫 캔 바닥을 본뜨면 ○", "heading": "□ △ ○ 모양"}, {"paras": ["곧은 선을 '변'이라고 해요.", "두 변이 만나는 뾰족한 점을 '꼭짓점'이라고 해요.", "하나씩 표시하며 세면 빠뜨리지 않아요."], "figure": "색종이로 오린 삼각형과 사각형의 꼭짓점에 스티커를 붙인 모습", "example": "① 삼각형의 곧은 선에 ✔ 표시 → 3개 ② 뾰족한 점에 ● 표시 → 3개 ③ 삼각형: 변 3개, 꼭짓점 3개 (사각형은 변 4개, 꼭짓점 4개 / 원은 변과 꼭짓점이 없어요)", "heading": "이렇게 풀어요: 변과 꼭짓점 세기"}], "parent_tip": "아이들은 모양을 색깔이나 크기로 구분하려는 경우가 많습니다. '평평한 곳이 있니? 굴러가니?'처럼 성질로 묻게 해 주세요. 집 안에서 상자·캔·공 모양 물건을 찾아 모아 보고, 직접 쌓고 굴려 보게 하면 오래 기억합니다.", "expressions": []}$j$::jsonb where slug='m1-02';
update public.lessons set content=$j${"narr": {"kw": "assets/audio/n/m1-07_kw.mp3", "q0": "assets/audio/n/m1-07_q0.mp3", "q1": "assets/audio/n/m1-07_q1.mp3", "q2": "assets/audio/n/m1-07_q2.mp3", "q3": "assets/audio/n/m1-07_q3.mp3", "q4": "assets/audio/n/m1-07_q4.mp3", "s0": "assets/audio/n/m1-07_s0.mp3", "s1": "assets/audio/n/m1-07_s1.mp3", "s2": "assets/audio/n/m1-07_s2.mp3", "s3": "assets/audio/n/m1-07_s3.mp3", "sum": "assets/audio/n/m1-07_sum.mp3", "cover": "assets/audio/n/m1-07_cover.mp3"}, "quiz": [{"q": "🕘 짧은바늘이 9, 긴바늘이 12를 가리켜요. 몇 시일까요?", "answer": 2, "choices": ["12시", "9시 30분", "9시", "3시"], "explain": "긴바늘이 12이면 '몇 시'예요. 짧은바늘이 9이니 9시예요."}, {"q": "긴바늘이 6을 가리키면 몇 분일까요?", "answer": 0, "choices": ["30분", "6분", "60분", "12분"], "explain": "숫자 하나에 5분씩, 6칸이면 30분이에요."}, {"q": "🕞 3시 30분일 때 짧은바늘은 어디에 있을까요?", "answer": 1, "choices": ["3", "3과 4 사이", "6", "12"], "explain": "30분일 때 짧은바늘은 3과 4의 가운데쯤에 있어요."}, {"q": "긴바늘이 11을 가리키면 몇 분일까요?", "answer": 3, "choices": ["11분", "50분", "60분", "55분"], "explain": "5씩 11번 뛰어 세면 55분이에요."}, {"q": "1시간은 몇 분일까요?", "answer": 1, "choices": ["10분", "60분", "100분", "30분"], "explain": "긴바늘이 한 바퀴 도는 60분이 1시간이에요."}], "intro": "⏰ 학교 가는 시각, 잠자는 시각. 시계를 보면 알 수 있어요. 짧은바늘과 긴바늘을 읽는 법을 배워요.", "summary": ["짧은바늘은 시, 긴바늘은 분을 알려 줘요.", "긴바늘 12는 '몇 시', 6은 '30분', 한 칸은 5분이에요.", "긴바늘이 한 바퀴 돌면 60분 = 1시간이에요."], "keywords": [{"word": "짧은바늘", "meaning": "'시'를 알려 주는 짧은 바늘"}, {"word": "긴바늘", "meaning": "'분'을 알려 주는 긴 바늘"}, {"word": "30분", "meaning": "긴바늘이 6을 가리킬 때, 1시간의 반"}, {"word": "1시간", "meaning": "긴바늘이 한 바퀴 도는 동안, 60분"}, {"word": "오전·오후", "meaning": "전날 밤 12시부터 낮 12시까지는 오전, 낮 12시부터 밤 12시까지는 오후"}], "sections": [{"paras": ["시계에는 바늘이 두 개 있어요.", "짧은바늘은 '시'를 알려 줘요.", "긴바늘은 '분'을 알려 줘요."], "figure": "벽에 걸린 둥근 아날로그 시계를 아이가 손가락으로 가리키는 모습", "example": "🕒 짧은바늘 3, 긴바늘 12 → 3시", "heading": "짧은바늘과 긴바늘"}, {"paras": ["긴바늘이 12를 가리키면 '몇 시'예요.", "긴바늘이 6을 가리키면 '몇 시 30분'이에요.", "30분일 때 짧은바늘은 두 숫자 사이에 있어요."], "figure": "장난감 시계의 바늘을 6시 30분에 맞춘 모습", "example": "🕖 7시: 짧은바늘 7, 긴바늘 12 / 🕡 6시 30분: 짧은바늘 6과 7 사이, 긴바늘 6", "heading": "몇 시, 몇 시 30분"}, {"paras": ["긴바늘이 숫자 한 칸을 가면 5분이에요.", "긴바늘이 가리키는 숫자에 5씩 뛰어 세요.", "짧은바늘은 지나온 숫자를 읽어요."], "figure": "시계 숫자 옆에 5, 10, 15……를 작은 스티커로 붙인 모습", "example": "① 짧은바늘 2와 3 사이 → 2시 ② 긴바늘 4 → 5, 10, 15, 20 → 20분 ③ 2시 20분", "heading": "이렇게 풀어요: 몇 시 몇 분 읽기"}, {"paras": ["긴바늘이 한 바퀴 돌면 60분이 지나요.", "60분은 1시간이에요.", "낮 12시 전은 오전, 낮 12시 후는 오후예요."], "figure": "아침 식탁 옆 시계와 저녁 창밖 노을이 함께 보이는 모습", "example": "🕗 8시 → 1시간 뒤 → 🕘 9시 / 1시간 30분 = 90분", "heading": "1시간은 60분"}], "parent_tip": "아이들은 두 바늘을 바꿔 읽거나, 짧은바늘이 숫자 사이에 있을 때 다음 숫자로 읽는 실수(2시 50분을 3시 50분)를 자주 합니다. 디지털시계보다 바늘 시계를 집에 두고 '밥 먹는 시각', '잠자는 시각'을 함께 읽어 보세요.", "expressions": []}$j$::jsonb where slug='m1-07';
update public.lessons set content=$j${"quiz": [{"q": "18의 1/3은 얼마일까요?", "answer": 1, "choices": ["5", "6", "9", "3"], "explain": "18을 똑같이 3묶음으로 나누면 한 묶음에 6개씩이에요."}, {"q": "다음 중 가장 큰 분수는 무엇일까요?", "answer": 3, "choices": ["2/7", "3/7", "4/7", "5/7"], "explain": "분모가 같으면 분자가 클수록 커요. 분자 5가 가장 커요."}, {"q": "11/4을 대분수로 바르게 나타낸 것은?", "answer": 2, "choices": ["1과 3/4", "2와 1/4", "2와 3/4", "3과 1/4"], "explain": "1/4이 4개면 1이므로 11개는 1이 2개, 1/4이 3개 남아 2와 3/4이에요."}, {"q": "다음 단위분수 중 가장 큰 것은?", "answer": 0, "choices": ["1/2", "1/5", "1/8", "1/3"], "explain": "단위분수는 분모가 작을수록 한 조각이 커서 1/2이 가장 커요."}, {"q": "다음 중 가분수는 무엇일까요?", "answer": 2, "choices": ["2/5", "1/3", "7/4", "4/9"], "explain": "분자 7이 분모 4보다 크므로 7/4은 가분수예요."}], "intro": "피자 한 판을 4명이 똑같이 나눠 먹으면 한 사람은 얼마만큼 먹는 걸까요? 이럴 때 쓰는 수가 바로 분수예요.", "summary": ["분수는 전체를 똑같이 나눈 것 중의 몇 개를 나타내요.", "분모는 나눈 개수, 분자는 그중 몇 개인지를 알려 줘요.", "분모가 같으면 분자가 클수록, 단위분수는 분모가 작을수록 커요."], "keywords": [{"word": "분수", "meaning": "전체를 똑같이 나눈 것 중의 몇 개를 나타내는 수"}, {"word": "분모", "meaning": "가로선 아래의 수, 전체를 몇으로 나누었는지"}, {"word": "분자", "meaning": "가로선 위의 수, 그중 몇 개인지"}, {"word": "단위분수", "meaning": "분자가 1인 분수"}, {"word": "가분수", "meaning": "분자가 분모와 같거나 큰 분수"}, {"word": "대분수", "meaning": "자연수와 진분수로 이루어진 분수"}], "sections": [{"paras": ["분수는 전체를 '똑같이' 나눈 것 중의 몇 개인지 나타내는 수예요. 크기가 서로 다르게 나누면 분수로 말할 수 없어요.", "피자 한 판을 똑같이 4조각으로 나눈 것 중 1조각은 4분의 1이라고 읽고 1/4이라고 써요."], "figure": "똑같이 4조각으로 나눈 피자에서 1조각만 색칠된 그림", "example": "피자 1판을 똑같이 4조각으로 나눈 것 중 1조각 → 1/4 (4분의 1)", "heading": "똑같이 나누어야 분수예요"}, {"paras": ["분수에서 가로선 아래에 있는 수를 분모, 위에 있는 수를 분자라고 해요.", "분모는 전체를 몇 개로 똑같이 나누었는지, 분자는 그중 몇 개인지를 알려 줘요. 분자가 1인 1/2, 1/3, 1/4 같은 분수를 단위분수라고 해요."], "figure": "막대를 5칸으로 똑같이 나누고 3칸을 색칠한 뒤 분모·분자에 화살표로 이름을 붙인 그림", "example": "3/5 → 전체를 똑같이 5로 나눈 것 중 3개 (분모 5, 분자 3)", "heading": "분모와 분자"}, {"paras": ["분자가 분모보다 작은 분수는 진분수예요(예: 2/3). 분자가 분모와 같거나 분모보다 큰 분수는 가분수예요(예: 4/4, 7/4).", "1과 3/4처럼 자연수와 진분수로 이루어진 분수는 대분수라고 해요. 가분수는 대분수로, 대분수는 가분수로 바꿀 수 있어요."], "figure": "1/4 조각 7개 중 4개가 모여 원 하나를 이루고 3개가 남은 그림", "example": "7/4 → 1/4이 7개 → 4개가 모이면 1이 되므로 1과 3/4", "heading": "진분수, 가분수, 대분수"}, {"paras": ["12의 2/3가 얼마인지 구해 볼까요? ① 12를 똑같이 3묶음으로 나눠요. ② 한 묶음에는 4개가 있어요. 이것이 12의 1/3이에요.", "③ 2/3는 그런 묶음 2개이므로 4 + 4 = 8이에요. 분모만큼 묶음을 만들고, 분자만큼 묶음을 세면 돼요."], "figure": "사탕 12개를 4개씩 3묶음으로 나누고 그중 2묶음에 동그라미를 친 그림", "example": "12의 1/3 = 4, 12의 2/3 = 8", "heading": "이렇게 풀어요: 어떤 수의 분수만큼 구하기"}, {"paras": ["분모가 같은 분수는 분자가 클수록 더 큰 분수예요. 2/7보다 5/7가 더 커요.", "단위분수는 분모가 클수록 한 조각이 작아져서 더 작은 분수가 돼요. 그래서 1/3이 1/5보다 커요."], "figure": "같은 길이의 막대 두 개를 3칸과 5칸으로 나누어 한 칸씩 색칠해 비교한 그림", "example": "1/3 > 1/5 (3조각으로 나눈 한 조각이 5조각으로 나눈 한 조각보다 커요)", "heading": "분수의 크기 비교"}], "parent_tip": "아이들은 '분모가 크면 더 큰 분수'라고 착각하기 쉽습니다. 피자나 종이띠를 실제로 3조각, 5조각으로 나눠 보게 하면 금방 이해합니다. \"케이크를 8명이 나눌 때와 4명이 나눌 때 어느 쪽 조각이 더 클까?\"처럼 물어봐 주세요.", "expressions": []}$j$::jsonb where slug='m3-01';
update public.lessons set content=$j${"quiz": [{"q": "368 + 457은 얼마일까요?", "answer": 2, "choices": ["715", "815", "825", "725"], "explain": "8 + 7 = 15, 6 + 5 + 1 = 12, 3 + 4 + 1 = 8이라서 825예요."}, {"q": "702 − 358은 얼마일까요?", "answer": 0, "choices": ["344", "354", "456", "444"], "explain": "백의 자리에서 받아내려 계산하면 344예요. 344 + 358 = 702로 검산할 수 있어요."}, {"q": "512 − 289 = 223을 검산하는 식으로 알맞은 것은?", "answer": 0, "choices": ["223 + 289 = 512", "512 + 289 = 801", "289 − 223 = 66", "512 − 223 = 279"], "explain": "뺄셈의 답과 빼는 수를 더하면 처음 수가 나와요."}, {"q": "어제 줄넘기를 245번, 오늘 186번 했어요. 모두 몇 번 했을까요?", "answer": 1, "choices": ["421번", "431번", "331번", "441번"], "explain": "245 + 186 = 431번이에요."}, {"q": "색종이 600장 중 247장을 썼어요. 남은 색종이는 몇 장일까요?", "answer": 0, "choices": ["353장", "363장", "453장", "347장"], "explain": "600 − 247 = 353장이에요."}], "intro": "도서관에 동화책 456권과 과학책 278권이 있어요. 모두 몇 권일까요? 세 자리 수끼리 더하고 빼는 방법을 알아봐요.", "summary": ["자리를 맞추어 쓰고 일의 자리부터 계산해요.", "덧셈에서 같은 자리의 합이 10이거나 10보다 크면 받아올림, 뺄셈에서 뺄 수 없으면 받아내림을 해요.", "어림으로 답을 짐작하고, 뺄셈은 덧셈으로 검산해요."], "keywords": [{"word": "받아올림", "meaning": "같은 자리의 합이 10이거나 10보다 클 때 윗자리로 1을 올리는 것"}, {"word": "받아내림", "meaning": "뺄 수 없을 때 윗자리에서 10을 빌려 오는 것"}, {"word": "어림", "meaning": "대강 짐작해서 셈하는 것"}, {"word": "검산", "meaning": "계산이 맞는지 다시 확인하는 것"}], "sections": [{"paras": ["세 자리 수를 계산할 때는 백, 십, 일의 자리를 세로로 맞추어 쓰고 일의 자리부터 계산해요.", "같은 자리끼리 계산해야 하는 이유는 같은 숫자라도 자리에 따라 나타내는 값이 다르기 때문이에요. 324에서 3은 300, 2는 20, 4는 4예요."], "figure": "백·십·일 자리 칸에 숫자를 맞추어 쓴 세로셈 그림", "example": "324 + 152 = 476 (일 4+2=6, 십 2+5=7, 백 3+1=4)", "heading": "자리를 맞추어 일의 자리부터"}, {"paras": ["456 + 278을 풀어 볼까요? ① 일의 자리 6 + 8 = 14예요. 4를 쓰고, 10은 십의 자리 1로 올려 써요.", "② 십의 자리 5 + 7 + 1 = 13, 3을 쓰고 백의 자리로 1을 올려요. ③ 백의 자리 4 + 2 + 1 = 7이에요. 답은 734예요."], "figure": "456 + 278 세로셈에서 받아올린 1을 작게 위에 적은 그림", "example": "456 + 278 = 734", "heading": "이렇게 풀어요: 받아올림이 있는 덧셈"}, {"paras": ["503 − 267을 풀어 볼까요? 일의 자리 3에서 7을 뺄 수 없어요. 십의 자리가 0이라서 백의 자리에서 먼저 받아내려요.", "백의 자리 5는 4가 되고 십의 자리는 10이 돼요. 다시 십의 자리에서 10을 일의 자리로 받아내리면 십은 9, 일은 13이에요. 13 − 7 = 6, 9 − 6 = 3, 4 − 2 = 2라서 236이에요."], "figure": "503 − 267 세로셈에서 받아내린 숫자를 고쳐 쓴 그림", "example": "503 − 267 = 236", "heading": "이렇게 풀어요: 받아내림이 있는 뺄셈"}, {"paras": ["계산하기 전에 어림하면 답이 맞는지 짐작할 수 있어요. 312 + 289는 약 300 + 300 = 600쯤이고, 실제로는 601이에요.", "뺄셈은 덧셈으로 검산할 수 있어요. 503 − 267 = 236이 맞는지 236 + 267을 계산하면 503이 나와요."], "figure": "뺄셈식과 검산 덧셈식을 화살표로 이은 그림", "example": "검산: 236 + 267 = 503 → 503 − 267 = 236이 맞아요", "heading": "어림하고 검산해요"}], "parent_tip": "703 − 268처럼 십의 자리가 0인 뺄셈에서 받아내림을 두 번 해야 하는 경우를 가장 어려워합니다. 동전(100원, 10원, 1원)으로 실제로 바꿔 주며 계산해 보면 이해가 빠릅니다. 답을 낸 뒤 \"덧셈으로 확인해 볼까?\"라고 검산 습관을 길러 주세요.", "expressions": []}$j$::jsonb where slug='m3-04';
update public.lessons set content=$j${"quiz": [{"q": "42 ÷ 6의 몫은 얼마일까요?", "answer": 1, "choices": ["6", "7", "8", "9"], "explain": "6 × 7 = 42이므로 몫은 7이에요."}, {"q": "29 ÷ 4의 몫과 나머지는?", "answer": 1, "choices": ["몫 6, 나머지 5", "몫 7, 나머지 1", "몫 7, 나머지 2", "몫 8, 나머지 1"], "explain": "4 × 7 = 28이고 1이 남아요. 나머지 5는 4보다 커서 틀려요."}, {"q": "84 ÷ 4는 얼마일까요?", "answer": 0, "choices": ["21", "22", "24", "12"], "explain": "8 ÷ 4 = 2, 4 ÷ 4 = 1이라서 21이에요."}, {"q": "사탕 50개를 7명이 똑같이 나누면 한 명에 몇 개씩 주고 몇 개가 남을까요?", "answer": 1, "choices": ["6개씩, 8개 남음", "7개씩, 1개 남음", "7개씩, 2개 남음", "8개씩, 1개 남음"], "explain": "7 × 7 = 49이므로 7개씩 주고 1개가 남아요."}, {"q": "38 ÷ 5 = 7 … 3이 맞는지 확인하는 식은?", "answer": 0, "choices": ["5 × 7 + 3 = 38", "5 × 3 + 7 = 22", "38 × 5 = 190", "7 × 3 + 5 = 26"], "explain": "나누는 수 × 몫 + 나머지 = 나누어지는 수로 확인해요."}], "intro": "쿠키 12개를 친구 3명이 똑같이 나눠 먹으려면 한 명이 몇 개씩 먹어야 할까요? 이럴 때 나눗셈을 써요.", "summary": ["나눗셈은 똑같이 나누거나 똑같이 묶을 때 써요.", "나눗셈의 몫은 곱셈구구로 찾을 수 있어요.", "나머지는 나누는 수보다 작아야 하고, 나누는 수 × 몫 + 나머지로 확인해요."], "keywords": [{"word": "나눗셈", "meaning": "어떤 수를 똑같이 나누는 계산"}, {"word": "몫", "meaning": "나눗셈을 해서 나온 값"}, {"word": "나머지", "meaning": "똑같이 나누고 남은 수, 나누는 수보다 작아요"}, {"word": "나누어떨어진다", "meaning": "나머지가 0인 것"}], "sections": [{"paras": ["12 ÷ 3은 '12를 3명에게 똑같이 나누면 한 명에 몇 개?'라는 뜻도 되고, '12를 3개씩 묶으면 몇 묶음?'이라는 뜻도 돼요.", "12 ÷ 3 = 4에서 12는 나누어지는 수, 3은 나누는 수, 4는 몫이라고 해요."], "figure": "쿠키 12개를 접시 3개에 4개씩 나누어 담은 그림", "example": "12 ÷ 3 = 4 (쿠키 12개를 3명이 나누면 한 명에 4개)", "heading": "나눗셈의 두 가지 뜻"}, {"paras": ["나눗셈의 몫은 곱셈구구로 찾을 수 있어요. 12 ÷ 3의 몫은 3 × □ = 12에서 □를 찾으면 돼요.", "그래서 4 × 3 = 12라는 곱셈식 하나로 12 ÷ 3 = 4, 12 ÷ 4 = 3이라는 나눗셈식 두 개를 만들 수 있어요."], "figure": "곱셈식 하나에서 나눗셈식 두 개로 화살표가 뻗어 나가는 그림", "example": "4 × 3 = 12 → 12 ÷ 3 = 4, 12 ÷ 4 = 3", "heading": "곱셈과 나눗셈은 친구예요"}, {"paras": ["29 ÷ 4는 4씩 7묶음을 만들면 28이 되고 1이 남아요. 이것을 29 ÷ 4 = 7 … 1이라고 쓰고, 1을 나머지라고 해요.", "나머지는 항상 나누는 수보다 작아야 해요. 계산이 맞는지는 '나누는 수 × 몫 + 나머지 = 나누어지는 수'로 확인해요."], "figure": "구슬 29개를 4개씩 7묶음으로 묶고 1개가 남은 그림", "example": "29 ÷ 4 = 7 … 1 → 확인: 4 × 7 + 1 = 29", "heading": "나머지가 있는 나눗셈"}, {"paras": ["75 ÷ 3을 풀어 볼까요? ① 십의 자리 7을 3으로 나누면 몫 2, 나머지 1이에요. 몫 2를 십의 자리에 써요.", "② 남은 1(10을 뜻해요)과 일의 자리 5를 합쳐 15를 만들어요. ③ 15 ÷ 3 = 5, 몫 5를 일의 자리에 써요. 답은 25예요."], "figure": "75 ÷ 3 나눗셈 세로식에서 단계별로 몫을 쓰는 그림", "example": "75 ÷ 3 = 25", "heading": "이렇게 풀어요: 세로로 나누기"}], "parent_tip": "나머지가 나누는 수보다 큰데도 그대로 답하는 실수가 흔합니다. \"남은 걸로 한 명에게 하나씩 더 줄 수 있지 않을까?\"라고 물어 스스로 고치게 해 주세요. 간식을 가족 수대로 나누어 보는 활동이 가장 좋은 연습입니다.", "expressions": []}$j$::jsonb where slug='m3-05';
update public.lessons set content=$j${"quiz": [{"q": "2L 50mL는 몇 mL일까요?", "answer": 1, "choices": ["250mL", "2050mL", "2500mL", "2005mL"], "explain": "2L = 2000mL이므로 2000 + 50 = 2050mL예요."}, {"q": "4500g은 몇 kg 몇 g일까요?", "answer": 0, "choices": ["4kg 500g", "45kg", "4kg 50g", "450kg"], "explain": "4000g = 4kg이고 500g이 남아 4kg 500g이에요."}, {"q": "1L 600mL + 700mL는 얼마일까요?", "answer": 1, "choices": ["1L 1300mL", "2L 300mL", "2L 30mL", "8L 600mL"], "explain": "600 + 700 = 1300mL = 1L 300mL이므로 모두 2L 300mL예요."}, {"q": "5kg − 2kg 300g은 얼마일까요?", "answer": 1, "choices": ["3kg 300g", "2kg 700g", "3kg 700g", "2kg 300g"], "explain": "5kg을 4kg 1000g으로 바꾸면 1000 − 300 = 700g, 4 − 2 = 2kg이에요."}, {"q": "트럭의 무게를 나타내기에 가장 알맞은 단위는?", "answer": 2, "choices": ["mL", "g", "t", "L"], "explain": "트럭처럼 아주 무거운 것은 t(톤) 단위를 써요."}], "intro": "우유갑과 물통 중 어느 쪽에 물이 더 많이 들어갈까요? 수박과 사과 중 어느 쪽이 더 무거울까요? 들이와 무게를 재는 단위를 알아봐요.", "summary": ["들이는 담을 수 있는 양이고 1L = 1000mL예요.", "무게의 단위는 g, kg, t이고 1kg = 1000g, 1t = 1000kg이에요.", "같은 단위끼리 계산하고, 1000이거나 1000보다 크면 1000을 큰 단위 1로 바꿔요."], "keywords": [{"word": "들이", "meaning": "그릇 안에 담을 수 있는 양"}, {"word": "L와 mL", "meaning": "들이의 단위, 1L = 1000mL"}, {"word": "무게", "meaning": "물건이 무거운 정도"}, {"word": "kg과 g", "meaning": "무게의 단위, 1kg = 1000g"}, {"word": "t(톤)", "meaning": "1000kg을 나타내는 무게 단위"}], "sections": [{"paras": ["그릇 안에 담을 수 있는 양을 '들이'라고 해요. 들이의 단위에는 L(리터)와 mL(밀리리터)가 있어요.", "1L = 1000mL예요. 1L보다 300mL 더 많은 들이는 1L 300mL이고, 1300mL와 같아요."], "figure": "1L 우유갑과 200mL 우유갑을 나란히 놓고 들이를 표시한 그림", "example": "1L 300mL = 1000mL + 300mL = 1300mL", "heading": "들이와 단위 L, mL"}, {"paras": ["물건이 무거운 정도를 무게라고 해요. 무게의 단위에는 g(그램), kg(킬로그램), t(톤)이 있어요.", "1kg = 1000g이고, 아주 무거운 트럭 같은 것은 1t = 1000kg을 써요. 2kg 500g은 2500g과 같아요."], "figure": "저울 위에 사과(g), 수박(kg), 트럭(t)을 그려 단위를 비교한 그림", "example": "2kg 500g = 2000g + 500g = 2500g", "heading": "무게와 단위 kg, g, t"}, {"paras": ["1L 300mL + 2L 800mL를 풀어 볼까요? ① mL끼리 더하면 300 + 800 = 1100mL. ② 1000mL는 1L이므로 1100mL = 1L 100mL.", "③ L끼리 더하면 1 + 2 = 3L이고, 올라온 1L를 더해 4L. 답은 4L 100mL예요."], "figure": "L와 mL를 따로 세로셈으로 계산하고 1000mL를 1L로 올리는 그림", "example": "1L 300mL + 2L 800mL = 4L 100mL", "heading": "이렇게 풀어요: 들이의 덧셈"}, {"paras": ["3kg 200g − 1kg 500g을 풀어 볼까요? 200g에서 500g을 뺄 수 없어요. 1kg을 1000g으로 바꿔 2kg 1200g으로 생각해요.", "1200 − 500 = 700g, 2 − 1 = 1kg이라서 답은 1kg 700g이에요. 들이의 뺄셈도 1L를 1000mL로 바꾸어 같은 방법으로 해요."], "figure": "kg과 g 세로셈에서 1kg을 1000g으로 받아내린 그림", "example": "3kg 200g − 1kg 500g = 1kg 700g", "heading": "이렇게 풀어요: 무게의 뺄셈"}], "parent_tip": "들이와 무게를 헷갈리는 아이가 많습니다. 부엌의 계량컵과 저울로 직접 재 보며 \"이건 양을 재는 걸까, 무거운 정도를 재는 걸까?\"라고 물어봐 주세요. 우유갑, 생수병에 적힌 mL와 과자 봉지의 g을 찾아보는 것도 좋은 연습입니다.", "expressions": []}$j$::jsonb where slug='m3-07';
update public.lessons set content=$j${"quiz": [{"q": "10000에 대한 설명으로 __틀린__ 것은 무엇일까요?", "answer": 2, "choices": ["1000이 10개인 수", "9999보다 1 큰 수", "100이 10개인 수", "9000보다 1000 큰 수"], "explain": "100이 10개면 1000이에요. 10000은 100이 100개인 수예요."}, {"q": "47053을 바르게 읽은 것은 무엇일까요?", "answer": 1, "choices": ["사만 칠천영백오십삼", "사만 칠천오십삼", "사천칠백오십삼", "사만 칠천오백삼"], "explain": "0인 백의 자리는 읽지 않아요. 사만 칠천오십삼이에요."}, {"q": "'삼백오십만'을 숫자로 바르게 쓴 것은 무엇일까요?", "answer": 0, "choices": ["3500000", "350000", "35000000", "3050000"], "explain": "삼백오십만은 350만이에요. 350 뒤에 만을 뜻하는 0 네 개를 붙이면 3500000이에요."}, {"q": "1억은 천만이 몇 개인 수일까요?", "answer": 3, "choices": ["100개", "1000개", "1개", "10개"], "explain": "천만이 10개면 1억이에요."}, {"q": "다음 중 가장 큰 수는 무엇일까요?", "answer": 1, "choices": ["989999", "1000100", "999990", "1000010"], "explain": "일곱 자리 수 두 개 중에서 백의 자리가 1인 1000100이 십의 자리가 1인 1000010보다 커요."}], "intro": "신문에서 '관객 1250만 명', '나라 살림 600조 원' 같은 말을 본 적 있나요? 9999보다 더 큰 수를 읽고 쓰는 방법을 알면 세상의 큰 숫자들이 한눈에 들어와요.", "summary": ["1000이 10개면 10000(만), 천만이 10개면 1억, 천억이 10개면 1조예요.", "큰 수는 일의 자리부터 네 자리씩 끊어 만, 억, 조를 붙여 읽어요.", "크기 비교는 자리 수를 먼저 보고, 같으면 높은 자리부터 비교해요."], "keywords": [{"word": "만", "meaning": "1000이 10개인 수, 10000"}, {"word": "자릿값", "meaning": "숫자가 놓인 자리에 따라 나타내는 값"}, {"word": "억", "meaning": "천만이 10개인 수, 100000000"}, {"word": "조", "meaning": "천억이 10개인 수, 1 뒤에 0이 12개 붙은 수(1000000000000)"}, {"word": "뛰어 세기", "meaning": "일정한 크기만큼 계속 더해 가며 세는 것"}], "sections": [{"paras": ["9999보다 1 큰 수를 10000이라고 써요. 읽을 때는 '만' 또는 '일만'이라고 해요.", "10000은 1000이 10개, 100이 100개, 10이 1000개 모인 수예요. 그래서 9000보다 1000 큰 수, 9990보다 10 큰 수도 모두 10000이에요."], "figure": "천 원짜리 지폐 10장을 한 줄로 늘어놓고 옆에 만 원짜리 지폐 한 장을 놓은 모습", "example": "1000원짜리 지폐 10장 = 10000원 = 만 원", "heading": "1000이 10개면 10000, 만이에요"}, {"paras": ["10000이 3개, 1000이 5개, 100이 2개, 10이 7개, 1이 4개인 수는 35274예요. 맨 앞자리부터 만의 자리, 천의 자리, 백의 자리, 십의 자리, 일의 자리라고 해요.", "같은 숫자라도 어느 자리에 있느냐에 따라 나타내는 값이 달라요. 35274에서 3은 30000을, 7은 70을 나타내요.", "읽을 때는 앞에서부터 숫자와 자리 이름을 함께 읽어요. 숫자가 0인 자리는 읽지 않고, 숫자가 1이면 '일'을 빼고 자리 이름만 읽어요."], "figure": "만, 천, 백, 십, 일 칸이 그려진 자릿값 표에 숫자 카드 3, 5, 2, 7, 4를 하나씩 넣은 모습", "example": "35274 = 30000 + 5000 + 200 + 70 + 4 → 삼만 오천이백칠십사 / 40508 → 사만 오백팔", "heading": "다섯 자리 수의 자릿값"}, {"paras": ["10000이 10개면 십만(100000), 100개면 백만(1000000), 1000개면 천만(10000000)이에요.", "천만이 10개면 1억(100000000)이에요. 1억은 0이 8개나 붙어요. 천억이 10개면 1조로, 0이 12개예요.", "큰 수는 일의 자리부터 네 자리씩 끊으면 쉽게 읽을 수 있어요. 끊은 곳마다 '만', '억', '조'를 붙여 읽어요."], "figure": "긴 숫자 띠 위에 네 자리마다 연필로 세로 금을 긋고 그 위에 만, 억, 조라고 적은 모습", "example": "520340000 → 5|2034|0000 → 5억 2034만 → 오억 이천삼십사만", "heading": "십만, 백만, 천만, 그리고 억과 조"}, {"paras": ["10000씩 뛰어 세면 만의 자리 숫자가 1씩 커져요. 10만씩 뛰어 세면 십만의 자리 숫자가 1씩 커지고요.", "어느 자리 숫자가 바뀌는지 살펴보면 얼마씩 뛰어 세었는지 알 수 있어요. 9 다음에는 윗자리로 1이 올라가는 것도 잊지 마세요."], "figure": "수직선 위에 같은 간격으로 화살표를 그리며 25000, 35000, 45000을 적은 공책", "example": "25000 - 35000 - 45000 - 55000 (만의 자리가 1씩 커져요 → 10000씩) / 1억 9000만 - 2억 - 2억 1000만 (1000만씩)", "heading": "뛰어 세기로 수의 순서 알기"}, {"paras": ["먼저 두 수의 자리 수를 세어 봐요. 자리 수가 많은 수가 더 커요.", "자리 수가 같으면 가장 높은 자리 숫자부터 차례로 비교해요. 처음으로 다른 숫자가 나온 자리에서 숫자가 큰 쪽이 더 큰 수예요."], "figure": "두 수를 위아래로 자리 맞춰 쓰고, 처음으로 다른 숫자에 동그라미를 친 모습", "example": "① 382540(여섯 자리)과 98960(다섯 자리) → 382540 > 98960 ② 572031과 571999 → 십만, 만의 자리는 같고 천의 자리 2 > 1 → 572031 > 571999", "heading": "이렇게 풀어요: 큰 수의 크기 비교"}], "parent_tip": "아이들은 0이 있는 수를 읽고 쓸 때(예: 사만 오백팔 → 40508) 가장 많이 실수합니다. 일의 자리부터 네 자리씩 끊는 습관을 들이고, 뉴스나 마트 가격표에서 큰 수를 찾아 함께 읽어 보세요. '1억은 만 원짜리가 몇 장일까?'처럼 물어보면 수의 크기를 느끼는 데 도움이 됩니다.", "expressions": []}$j$::jsonb where slug='m4-01';
update public.lessons set content=$j${"quiz": [{"q": "2, 5, 8, 11, □ 에서 □ 안에 알맞은 수는 무엇일까요?", "answer": 1, "choices": ["13", "14", "15", "12"], "explain": "3씩 커지는 규칙이므로 11 + 3 = 14예요."}, {"q": "의자 1개에 다리가 4개 있어요. 의자 7개의 다리는 모두 몇 개일까요?", "answer": 2, "choices": ["11개", "24개", "28개", "32개"], "explain": "의자 수에 4를 곱하면 다리 수예요. 7 × 4 = 28(개)예요."}, {"q": "101 × 11 = 1111, 102 × 11 = 1122, 103 × 11 = 1133 다음에 올 식은 무엇일까요?", "answer": 0, "choices": ["104 × 11 = 1144", "104 × 12 = 1144", "103 × 12 = 1144", "104 × 11 = 1134"], "explain": "앞의 수가 1씩 커지면 결과는 11씩 커져요. 104 × 11 = 1144예요."}, {"q": "등호(=)를 바르게 쓴 식은 무엇일까요?", "answer": 3, "choices": ["9 + 6 = 10 + 6", "12 − 4 = 10 − 4", "20 + 5 = 20 − 5", "9 + 6 = 10 + 5"], "explain": "9 + 6 = 15, 10 + 5 = 15로 양쪽 크기가 같아요."}, {"q": "25 + 38 = 30 + □ 에서 □ 안에 알맞은 수는 무엇일까요?", "answer": 1, "choices": ["43", "33", "38", "28"], "explain": "25가 30으로 5만큼 커졌으니 38은 5만큼 작아져야 해요. 38 − 5 = 33이에요."}], "intro": "계단을 한 칸 오를 때마다 높이가 똑같이 높아지듯, 우리 주변에는 일정하게 변하는 것이 많아요. 규칙을 찾으면 다음에 올 수도 미리 알 수 있어요.", "summary": ["함께 변하는 두 양은 표로 정리하면 규칙이 잘 보여요.", "수나 모양, 계산식의 배열에서 규칙을 찾으면 다음을 추측할 수 있어요.", "등호(=)는 양쪽의 크기가 같다는 뜻이에요."], "keywords": [{"word": "규칙", "meaning": "수나 모양이 일정하게 바뀌는 약속"}, {"word": "배열", "meaning": "수나 모양을 차례대로 늘어놓은 것"}, {"word": "계산식", "meaning": "덧셈, 뺄셈, 곱셈, 나눗셈 기호를 써서 계산을 나타낸 식"}, {"word": "등호(=)", "meaning": "왼쪽과 오른쪽의 크기가 같다는 것을 나타내는 기호"}], "sections": [{"paras": ["세발자전거가 1대 늘어날 때마다 바퀴는 3개씩 늘어나요. 이처럼 한 양이 변하면 다른 양도 따라 변하는 경우가 많아요.", "두 양을 표로 정리하면 어떻게 변하는지 쉽게 보여요. 표를 보고 '세발자전거 수에 3을 곱하면 바퀴 수가 돼요.'처럼 규칙을 말로 설명해요."], "figure": "세발자전거 장난감을 한 대, 두 대, 세 대씩 줄지어 놓은 모습", "example": "세발자전거 1대 → 바퀴 3개, 2대 → 6개, 3대 → 9개, 4대 → 12개 → 세발자전거가 6대면 바퀴는 6 × 3 = 18(개)예요.", "heading": "함께 변하는 두 양에서 규칙을 찾아요"}, {"paras": ["수가 놓인 표에서 오른쪽, 아래쪽, 비스듬한 방향으로 수가 어떻게 변하는지 살펴봐요.", "수가 일정하게 커지거나 작아지면 얼마씩 변하는지 찾아요. 어떤 배열은 같은 수를 곱해 가며 커지기도 해요.", "찾은 규칙을 이용하면 빈칸에 들어갈 수를 알 수 있어요."], "figure": "가로와 세로로 수가 적힌 수 배열표에서 한 줄을 형광펜으로 칠한 모습", "example": "1025, 1125, 1225, 1325, □ → 100씩 커지므로 □ = 1425 / 3, 6, 12, 24, □ → 2씩 곱하므로 □ = 48", "heading": "수의 배열에서 규칙을 찾아요"}, {"paras": ["바둑돌을 놓는 모양이 규칙적으로 바뀌면 바둑돌의 수도 규칙적으로 변해요.", "순서마다 바둑돌 수를 식으로 써 보면 규칙이 더 잘 보여요. 첫째 1, 둘째 1 + 2, 셋째 1 + 2 + 2처럼 쓰면 2개씩 늘어난다는 것을 알 수 있어요."], "figure": "바둑돌을 ㄱ자 모양으로 1개, 3개, 5개씩 늘려 놓은 모습", "example": "첫째 1개, 둘째 3개, 셋째 5개, 넷째 7개 → 2개씩 늘어나므로 다섯째는 7 + 2 = 9(개)예요.", "heading": "모양의 배열을 수와 식으로 나타내요"}, {"paras": ["계산식이 차례로 놓여 있으면 식의 수가 어떻게 바뀌고, 계산 결과가 어떻게 바뀌는지 함께 살펴봐요.", "① 곱하는 수가 얼마씩 커지는지 봐요. ② 계산 결과가 얼마씩 변하는지 봐요. ③ 찾은 규칙으로 다음 식과 결과를 추측하고, 직접 계산해서 맞는지 확인해요."], "figure": "공책에 계산식을 위아래로 나란히 쓰고 바뀌는 수에 동그라미를 친 모습", "example": "37 × 3 = 111, 37 × 6 = 222, 37 × 9 = 333 → 곱하는 수가 3씩 커지면 결과는 111씩 커져요. 다음 식은 37 × 12 = 444예요.", "heading": "이렇게 풀어요: 계산식 배열의 규칙"}, {"paras": ["등호(=)는 '답을 쓰세요.'라는 표시가 아니라, 왼쪽과 오른쪽의 크기가 같다는 표시예요. 그래서 7 + 8 = 10 + 5처럼 양쪽에 모두 식이 올 수도 있어요.", "등호가 있는 식이 옳은지 알아볼 때는 양쪽을 각각 계산해 비교해요. 수가 어떻게 바뀌었는지 살피면 계산하지 않고도 알 수 있어요.", "한쪽에서 한 수가 4만큼 커지면, 크기가 같아지도록 다른 수는 4만큼 작아져야 해요."], "figure": "양팔 저울 양쪽에 수 카드 묶음을 올려 수평을 이룬 모습", "example": "16 + 27 = 20 + □ → 16이 20으로 4만큼 커졌으니 27은 4만큼 작아져야 해요. □ = 23 (확인: 16 + 27 = 43, 20 + 23 = 43)", "heading": "등호(=)는 양쪽이 같다는 뜻이에요"}], "parent_tip": "많은 아이가 등호를 '답을 쓰는 자리'로만 생각해서 16 + 27 = □ + 25 같은 식에서 □에 43을 쓰는 실수를 합니다. '등호 양쪽이 저울처럼 같아야 해.'라고 설명해 주세요. 계단 수와 높이, 자동차 수와 바퀴 수처럼 생활 속에서 함께 변하는 두 양을 찾아 표로 만들어 보는 놀이도 좋습니다.", "expressions": []}$j$::jsonb where slug='m4-06';
update public.lessons set content=$j${"quiz": [{"q": "직육면체의 꼭짓점은 몇 개일까요?", "answer": 1, "choices": ["6개", "8개", "12개", "4개"], "explain": "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요."}, {"q": "직육면체의 겨냥도에서 점선으로 그리는 모서리는 몇 개일까요?", "answer": 2, "choices": ["1개", "2개", "3개", "9개"], "explain": "보이지 않는 모서리 3개를 점선으로 그려요."}, {"q": "직육면체에서 한 면과 수직인 면은 몇 개일까요?", "answer": 2, "choices": ["1개", "2개", "4개", "5개"], "explain": "마주 보는 면 1개를 뺀 나머지 4개의 면이 수직이에요."}, {"q": "한 모서리가 7cm인 정육면체의 모든 모서리 길이의 합은?", "answer": 2, "choices": ["42cm", "56cm", "84cm", "49cm"], "explain": "정육면체 모서리 12개의 길이가 모두 같아서 7 × 12 = 84cm예요."}, {"q": "직육면체에서 서로 평행한 면은 모두 몇 쌍일까요?", "answer": 1, "choices": ["2쌍", "3쌍", "4쌍", "6쌍"], "explain": "마주 보는 면끼리 평행하고 3쌍이 있어요."}], "intro": "과자 상자, 주사위, 벽돌은 모두 비슷한 모양이에요. 면과 모서리, 꼭짓점을 세어 보며 이 입체도형의 특징을 알아봐요.", "summary": ["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있어요.", "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.", "겨냥도는 보이지 않는 모서리 3개를 점선으로, 전개도는 펼친 모양으로 나타내요."], "keywords": [{"word": "직육면체", "meaning": "직사각형 6개로 둘러싸인 도형"}, {"word": "정육면체", "meaning": "정사각형 6개로 둘러싸인 도형"}, {"word": "모서리", "meaning": "면과 면이 만나는 선분"}, {"word": "꼭짓점", "meaning": "모서리와 모서리가 만나는 점"}, {"word": "겨냥도", "meaning": "입체도형의 모양을 알 수 있게 그린 그림"}, {"word": "전개도", "meaning": "입체도형의 모서리를 잘라 평면에 펼친 그림"}], "sections": [{"paras": ["직사각형 6개로 둘러싸인 도형을 직육면체라고 해요. 정사각형 6개로 둘러싸인 도형은 정육면체예요.", "정사각형은 직사각형이기도 하니까 정육면체도 직육면체라고 할 수 있어요. 하지만 모든 직육면체가 정육면체는 아니에요."], "figure": "과자 상자 모양 직육면체와 주사위 모양 정육면체를 나란히 놓은 그림", "example": "과자 상자 → 직육면체, 주사위 → 정육면체", "heading": "직육면체와 정육면체"}, {"paras": ["선분으로 둘러싸인 부분을 면, 면과 면이 만나는 선분을 모서리, 모서리와 모서리가 만나는 점을 꼭짓점이라고 해요.", "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요. 마주 보는 두 면은 서로 평행하고 이런 면이 3쌍 있어요. 한 면과 만나는 4개의 면은 그 면과 수직이에요."], "figure": "직육면체에서 면, 모서리, 꼭짓점에 이름표를 붙인 그림", "example": "직육면체: 면 6개, 모서리 12개, 꼭짓점 8개, 평행한 면 3쌍", "heading": "면, 모서리, 꼭짓점"}, {"paras": ["직육면체 모양을 잘 알 수 있게 그린 그림을 겨냥도라고 해요. 보이는 모서리 9개는 실선으로, 보이지 않는 모서리 3개는 점선으로 그려요.", "직육면체의 모서리를 잘라 평면 위에 펼친 그림은 전개도예요. 전개도를 접었을 때 겹치는 면이 없고, 마주 보는 면 3쌍의 모양과 크기가 같으며, 서로 맞닿는 모서리의 길이가 같아야 해요."], "figure": "직육면체 겨냥도(실선과 점선)와 펼친 전개도를 함께 그린 그림", "example": "겨냥도: 실선 9개 + 점선 3개 = 모서리 12개", "heading": "겨냥도와 전개도"}, {"paras": ["가로 4cm, 세로 3cm, 높이 2cm인 직육면체의 모든 모서리 길이의 합을 구해 볼까요? ① 길이가 같은 모서리가 4개씩 3묶음 있어요.", "② 가로, 세로, 높이를 하나씩 더하면 4 + 3 + 2 = 9cm. ③ 길이가 같은 모서리가 4개씩 있으니 9 × 4 = 36cm예요. 정육면체는 모서리 12개의 길이가 모두 같아서 한 모서리가 5cm면 5 × 12 = 60cm예요."], "figure": "같은 길이의 모서리 4개씩을 같은 색으로 칠한 직육면체 그림", "example": "(4 + 3 + 2) × 4 = 36cm, 정육면체 한 모서리 5cm → 5 × 12 = 60cm", "heading": "이렇게 풀어요: 모든 모서리 길이의 합"}], "parent_tip": "겨냥도에서 보이지 않는 모서리를 빠뜨리거나 전개도에서 겹치는 면을 찾지 못하는 경우가 많습니다. 빈 과자 상자를 모서리를 따라 직접 잘라 펼쳐 보면 효과적입니다. \"이 면과 마주 보는 면은 어디일까?\"라고 물어봐 주세요.", "expressions": []}$j$::jsonb where slug='m5-01';
update public.lessons set content=$j${"quiz": [{"q": "20의 약수는 모두 몇 개일까요?", "answer": 0, "choices": ["6개", "4개", "5개", "8개"], "explain": "20의 약수는 1, 2, 4, 5, 10, 20으로 6개예요."}, {"q": "30과 45의 최대공약수는?", "answer": 3, "choices": ["5", "10", "90", "15"], "explain": "30과 45를 둘 다 나누어떨어지게 하는 가장 큰 수는 15예요."}, {"q": "6과 8의 최소공배수는?", "answer": 1, "choices": ["2", "24", "14", "48"], "explain": "6의 배수와 8의 배수에서 처음으로 같은 수는 24예요."}, {"q": "다음 중 7의 배수가 __아닌__ 것은?", "answer": 3, "choices": ["14", "21", "49", "36"], "explain": "36 ÷ 7 = 5 … 1로 나누어떨어지지 않아요."}, {"q": "A 버스는 12분마다, B 버스는 18분마다 출발해요. 두 버스가 동시에 출발한 뒤 다음에 동시에 출발하는 것은 몇 분 후일까요?", "answer": 2, "choices": ["6분 후", "30분 후", "36분 후", "216분 후"], "explain": "12와 18의 최소공배수인 36분 후예요."}], "intro": "사탕 12개를 남김없이 똑같이 나누려면 몇 명에게 나눌 수 있을까요? 이 질문의 답을 찾다 보면 약수와 배수를 만나게 돼요.", "summary": ["약수는 어떤 수를 나누어떨어지게 하는 수, 배수는 어떤 수를 몇 배 한 수예요.", "최대공약수는 공약수 중 가장 큰 수, 최소공배수는 공배수 중 가장 작은 수예요.", "공약수는 최대공약수의 약수이고, 공배수는 최소공배수의 배수예요."], "keywords": [{"word": "약수", "meaning": "어떤 수를 나누어떨어지게 하는 수"}, {"word": "배수", "meaning": "어떤 수를 1배, 2배, 3배…한 수"}, {"word": "공약수", "meaning": "두 수의 공통된 약수"}, {"word": "최대공약수", "meaning": "공약수 중 가장 큰 수"}, {"word": "공배수", "meaning": "두 수의 공통된 배수"}, {"word": "최소공배수", "meaning": "공배수 중 가장 작은 수"}], "sections": [{"paras": ["어떤 수를 나누어떨어지게 하는 수를 그 수의 약수라고 해요. 12는 1, 2, 3, 4, 6, 12로 나누면 나누어떨어지므로 이 수들이 12의 약수예요.", "1은 모든 수의 약수이고, 어떤 수 자신도 항상 그 수의 약수예요."], "figure": "사탕 12개를 1명, 2명, 3명, 4명, 6명, 12명에게 남김없이 나누는 모습을 표로 정리한 그림", "example": "12의 약수: 1, 2, 3, 4, 6, 12", "heading": "약수: 나누어떨어지게 하는 수"}, {"paras": ["어떤 수를 1배, 2배, 3배…한 수를 그 수의 배수라고 해요. 4의 배수는 4, 8, 12, 16…처럼 끝없이 이어져요.", "4 × 3 = 12에서 12는 4와 3의 배수이고, 4와 3은 12의 약수예요. 약수와 배수는 곱셈식 하나로 연결되어 있어요."], "figure": "수직선 위에 4씩 뛰어 센 자리에 표시를 한 그림", "example": "4의 배수: 4, 8, 12, 16, …", "heading": "배수: 몇 배 한 수"}, {"paras": ["두 수의 공통된 약수를 공약수, 그중 가장 큰 수를 최대공약수라고 해요.", "18의 약수는 1, 2, 3, 6, 9, 18이고 24의 약수는 1, 2, 3, 4, 6, 8, 12, 24예요. 공약수는 1, 2, 3, 6이고 최대공약수는 6이에요. 공약수는 최대공약수의 약수와 같아요."], "figure": "18의 약수와 24의 약수를 두 원에 넣고 겹치는 부분에 공약수를 쓴 그림", "example": "18과 24의 최대공약수 = 6", "heading": "공약수와 최대공약수"}, {"paras": ["두 수의 공통된 배수를 공배수, 그중 가장 작은 수를 최소공배수라고 해요. ① 18과 24를 둘 다 나눌 수 있는 수로 나눠요: 2로 나누면 9와 12, 3으로 나누면 3과 4.", "② 더 이상 공통으로 나눌 수 없으면 멈춰요. ③ 나눈 수를 곱하면 최대공약수 2 × 3 = 6, 나눈 수와 남은 수를 모두 곱하면 최소공배수 2 × 3 × 3 × 4 = 72예요."], "figure": "18과 24를 공약수로 차례로 나누는 거꾸로 된 나눗셈 그림(ㄴ자 모양)", "example": "18과 24의 최소공배수 = 2 × 3 × 3 × 4 = 72", "heading": "이렇게 풀어요: 최소공배수 구하기"}], "parent_tip": "약수와 배수의 뜻을 서로 바꿔 말하는 실수가 많습니다. \"12와 4 중 누가 누구의 약수야?\"처럼 짧게 자주 물어 주세요. 문장제에서 최대공약수와 최소공배수 중 무엇을 써야 할지 헷갈려 하면 \"똑같이 나누는 문제인지, 다시 만나는 문제인지\"를 먼저 생각하게 해 주세요.", "expressions": []}$j$::jsonb where slug='m5-03';
update public.lessons set content=$j${"quiz": [{"q": "2/3 + 1/4은 얼마일까요?", "answer": 2, "choices": ["3/7", "3/12", "11/12", "9/12"], "explain": "12로 통분하면 8/12 + 3/12 = 11/12이에요."}, {"q": "5/6 − 1/4은 얼마일까요?", "answer": 1, "choices": ["4/2", "7/12", "1/3", "4/12"], "explain": "12로 통분하면 10/12 − 3/12 = 7/12이에요."}, {"q": "1과 2/5 + 2와 1/2은 얼마일까요?", "answer": 1, "choices": ["3과 3/7", "3과 9/10", "4와 1/10", "3과 3/10"], "explain": "자연수 1 + 2 = 3, 분수 4/10 + 5/10 = 9/10이라 3과 9/10예요."}, {"q": "4와 1/3 − 2와 1/2은 얼마일까요?", "answer": 1, "choices": ["2와 1/6", "1과 5/6", "2와 5/6", "1과 1/6"], "explain": "2/6 − 3/6은 뺄 수 없어 3과 8/6 − 2와 3/6 = 1과 5/6예요."}, {"q": "12/18를 기약분수로 나타내면?", "answer": 2, "choices": ["6/9", "4/6", "2/3", "3/4"], "explain": "12와 18의 최대공약수 6으로 나누면 2/3예요."}], "intro": "피자 1/2판과 1/3판을 합치면 얼마일까요? 조각 크기가 다르면 바로 더할 수 없어요. 조각 크기를 똑같이 맞추는 방법을 알아봐요.", "summary": ["분모와 분자에 같은 수를 곱하거나 나누면 크기가 같은 분수가 돼요.", "분모가 다른 분수는 통분한 뒤 분자끼리 더하거나 빼요.", "답은 약분해서 기약분수로 나타내요."], "keywords": [{"word": "약분", "meaning": "분모와 분자를 공약수로 나누어 간단히 하는 것"}, {"word": "기약분수", "meaning": "더 이상 약분할 수 없는 분수"}, {"word": "통분", "meaning": "분모가 다른 분수의 분모를 같게 만드는 것"}, {"word": "공통분모", "meaning": "통분하여 같게 만든 분모"}], "sections": [{"paras": ["분모와 분자에 0이 아닌 같은 수를 곱하거나 같은 수로 나누면 크기가 같은 분수가 돼요. 1/2 = 2/4 = 3/6이에요.", "분모와 분자를 공약수로 나누어 간단하게 만드는 것을 약분이라고 해요. 6/8을 2로 약분하면 3/4이에요. 더 이상 약분할 수 없는 분수를 기약분수라고 해요."], "figure": "같은 크기의 막대를 2칸, 4칸, 6칸으로 나누어 1/2, 2/4, 3/6을 비교한 그림", "example": "6/8 = 3/4 (분모와 분자를 2로 나눔)", "heading": "크기가 같은 분수와 약분"}, {"paras": ["분모가 다른 분수의 분모를 같게 만드는 것을 통분이라고 해요. 이때 같게 만든 분모를 공통분모라고 해요.", "공통분모는 두 분모의 최소공배수를 쓰면 수가 작아서 계산이 편해요. 1/2과 1/3은 최소공배수 6을 공통분모로 해서 3/6과 2/6로 통분해요."], "figure": "1/2과 1/3을 각각 6칸 막대로 다시 나누어 조각 크기를 맞춘 그림", "example": "1/2 = 3/6, 1/3 = 2/6", "heading": "통분: 분모를 같게 만들기"}, {"paras": ["1/2 + 1/3: ① 통분하면 3/6 + 2/6. ② 분모는 그대로 두고 분자끼리 더하면 5/6예요.", "3/4 − 1/6: ① 4와 6의 최소공배수 12로 통분하면 9/12 − 2/12. ② 분자끼리 빼면 7/12이에요. 답이 약분되면 기약분수로 나타내요."], "figure": "통분한 두 분수의 조각을 이어 붙이고 떼어 내는 모습을 막대로 나타낸 그림", "example": "1/2 + 1/3 = 3/6 + 2/6 = 5/6, 3/4 − 1/6 = 9/12 − 2/12 = 7/12", "heading": "이렇게 풀어요: 진분수의 덧셈과 뺄셈"}, {"paras": ["2와 1/3 + 1과 3/4: 자연수끼리 2 + 1 = 3, 분수끼리 4/12 + 9/12 = 13/12 = 1과 1/12. 합치면 4와 1/12이에요.", "3과 1/5 − 1과 1/2: 분수끼리 2/10 − 5/10는 뺄 수 없으니 자연수 1을 10/10으로 바꿔 2와 12/10 − 1과 5/10 = 1과 7/10이에요. 대분수를 가분수로 바꿔 계산해도 돼요."], "figure": "자연수 부분과 분수 부분을 나누어 계산하는 과정을 칸으로 정리한 그림", "example": "2와 1/3 + 1과 3/4 = 4와 1/12, 3과 1/5 − 1과 1/2 = 1과 7/10", "heading": "이렇게 풀어요: 대분수의 덧셈과 뺄셈"}], "parent_tip": "분모끼리, 분자끼리 더하는 실수(1/2 + 1/3 = 2/5)가 가장 흔합니다. 피자나 종이띠로 \"2/5가 1/2보다 작은데 더한 게 더 작아질 수 있을까?\"라고 물어 스스로 모순을 발견하게 해 주세요. 계산 후 약분을 잊지 않도록 마지막 확인 습관을 들여 주세요.", "expressions": []}$j$::jsonb where slug='m5-04';
update public.lessons set content=$j${"quiz": [{"q": "0.8 × 6은 얼마일까요?", "answer": 2, "choices": ["0.48", "48", "4.8", "6.8"], "explain": "8 × 6 = 48이고 소수 한 자리라서 4.8이에요."}, {"q": "2.4 × 0.5는 얼마일까요?", "answer": 0, "choices": ["1.2", "0.12", "12", "2.9"], "explain": "24 × 5 = 120이고 소수 두 자리를 만들면 1.20 = 1.2예요."}, {"q": "1.25 × 100은 얼마일까요?", "answer": 3, "choices": ["12.5", "1250", "0.0125", "125"], "explain": "100을 곱하면 소수점이 오른쪽으로 두 칸 옮겨 가서 125예요."}, {"q": "0.3 × 0.07은 얼마일까요?", "answer": 1, "choices": ["0.21", "0.021", "2.1", "0.0021"], "explain": "3 × 7 = 21이고 소수점 아래 자리 수가 1 + 2 = 3자리라서 0.021이에요."}, {"q": "물이 1.5L씩 든 병이 4개 있어요. 물은 모두 몇 L일까요?", "answer": 0, "choices": ["6L", "5.5L", "6.5L", "0.6L"], "explain": "1.5 × 4 = 6.0이므로 6L예요."}], "intro": "주스 한 컵이 0.3L인데 4컵을 마시면 모두 몇 L일까요? 소수의 곱셈은 자연수의 곱셈과 소수점 위치만 알면 쉽게 풀 수 있어요.", "summary": ["소수의 곱셈은 자연수처럼 곱한 뒤 소수점을 찍어요.", "곱의 소수점 아래 자리 수는 곱하는 두 수의 소수점 아래 자리 수의 합이에요.", "10, 100, 1000을 곱하면 소수점이 0의 개수만큼 오른쪽으로 옮겨 가요."], "keywords": [{"word": "소수", "meaning": "0.1, 2.35처럼 소수점을 사용해 나타낸 수"}, {"word": "소수점", "meaning": "자연수 부분과 소수 부분 사이에 찍는 점"}, {"word": "소수 한 자리 수", "meaning": "소수점 아래 숫자가 하나인 소수(예: 0.7)"}, {"word": "곱", "meaning": "곱셈을 해서 나온 값"}], "sections": [{"paras": ["0.3 × 4는 0.3을 4번 더한 것과 같아요. 0.3 + 0.3 + 0.3 + 0.3 = 1.2예요.", "0.3은 0.1이 3개이므로 0.3 × 4는 0.1이 12개, 즉 1.2라고 생각할 수도 있어요. 1.25 × 3도 자연수처럼 125 × 3 = 375를 구한 뒤 소수 두 자리로 맞추면 3.75예요."], "figure": "0.3L 주스 컵 4개를 모아 1.2L 병에 붓는 그림", "example": "0.3 × 4 = 1.2, 1.25 × 3 = 3.75", "heading": "(소수) × (자연수)"}, {"paras": ["6 × 0.7은 6의 0.7배라는 뜻이에요. 1보다 작은 수를 곱하면 곱은 처음 수보다 작아져요.", "6 × 7 = 42를 구하고, 곱하는 소수가 소수 한 자리이므로 곱도 소수 한 자리로 나타내면 4.2예요."], "figure": "길이 6m 막대를 10칸으로 나누어 그중 7칸을 색칠한 그림", "example": "6 × 0.7 = 4.2 (6보다 작아져요)", "heading": "(자연수) × (소수)"}, {"paras": ["1.5 × 2.3을 풀어 볼까요? ① 소수점을 없애고 자연수처럼 15 × 23 = 345를 구해요.", "② 곱하는 두 수의 소수점 아래 자리 수를 더해요. 1.5는 한 자리, 2.3도 한 자리라서 1 + 1 = 2자리예요. ③ 345에서 소수 두 자리를 만들면 3.45예요. 0.4 × 0.6도 4 × 6 = 24에서 소수 두 자리를 만들어 0.24예요."], "figure": "가로 1을 10칸, 세로 1을 10칸으로 나눈 모눈에서 4칸 × 6칸을 색칠해 0.24를 나타낸 그림", "example": "1.5 × 2.3 = 3.45, 0.4 × 0.6 = 0.24", "heading": "이렇게 풀어요: (소수) × (소수)"}, {"paras": ["소수에 10, 100, 1000을 곱하면 곱하는 수의 0의 개수만큼 소수점이 오른쪽으로 옮겨 가요. 3.25 × 10 = 32.5, 3.25 × 100 = 325예요.", "반대로 0.1, 0.01을 곱하면 소수점 아래 자리 수만큼 소수점이 왼쪽으로 옮겨 가요. 3.25 × 0.1 = 0.325예요."], "figure": "소수점이 오른쪽, 왼쪽으로 한 칸씩 이동하는 모습을 화살표로 나타낸 그림", "example": "3.25 × 10 = 32.5, 3.25 × 100 = 325, 3.25 × 1000 = 3250, 3.25 × 0.1 = 0.325", "heading": "곱의 소수점 위치 규칙"}], "parent_tip": "2.4 × 0.5 = 1.20처럼 끝자리 0을 지우는 과정에서 소수점 위치를 헷갈리는 경우가 많습니다. 계산 전에 \"2.4의 반쯤이니 1 근처겠지?\"라고 어림하게 하면 실수를 줄일 수 있습니다. 마트 가격표(100g당 가격)로 곱셈을 해 보는 것도 좋습니다.", "expressions": []}$j$::jsonb where slug='m5-05';
update public.lessons set content=$j${"quiz": [{"q": "다음 중 자석에 붙는 물체는?", "answer": 1, "choices": ["플라스틱 자", "철 클립", "나무젓가락", "고무지우개"], "explain": "자석은 철로 된 물체를 끌어당겨요."}, {"q": "막대자석에서 클립이 가장 많이 붙는 곳은?", "answer": 1, "choices": ["가운데", "양쪽 끝", "모든 곳에 똑같이", "아무 곳에도 안 붙는다"], "explain": "자석의 극은 막대자석의 양쪽 끝에 있어서 클립이 가장 많이 붙어요."}, {"q": "두 자석의 N극과 N극을 가까이하면 어떻게 될까요?", "answer": 2, "choices": ["끌어당긴다", "아무 일도 없다", "서로 밀어낸다", "색이 변한다"], "explain": "같은 극끼리는 서로 밀어내요."}, {"q": "물에 띄운 막대자석의 N극은 어느 쪽을 가리키며 멈출까요?", "answer": 0, "choices": ["북쪽", "남쪽", "동쪽", "서쪽"], "explain": "자석의 N극은 북쪽, S극은 남쪽을 가리켜요."}, {"q": "다음 중 자석에 붙지 __않는__ 금속은?", "answer": 3, "choices": ["철 못", "철 숟가락", "철 캔", "알루미늄 캔"], "explain": "금속이라도 철이 아니면 자석에 붙지 않아요."}], "intro": "냉장고 문에 붙은 자석, 필통 뚜껑의 자석! 자석은 왜 어떤 것은 붙고 어떤 것은 안 붙을까요?", "summary": ["자석은 철로 된 물체를 끌어당겨요.", "자석에는 N극과 S극이 있고, 같은 극은 밀고 다른 극은 당겨요.", "자석의 N극은 북쪽을 가리키며, 이를 이용한 것이 나침반이에요."], "keywords": [{"word": "자석", "meaning": "철로 된 물체를 끌어당기는 물체"}, {"word": "자석의 극", "meaning": "자석에서 철을 가장 세게 끌어당기는 부분"}, {"word": "N극", "meaning": "자유롭게 움직이게 두면 북쪽을 가리키는 자석의 극"}, {"word": "S극", "meaning": "자유롭게 움직이게 두면 남쪽을 가리키는 자석의 극"}, {"word": "나침반", "meaning": "자석 바늘로 방향을 알려 주는 도구"}], "sections": [{"paras": ["자석은 철로 된 물체를 끌어당겨요. 클립, 철 못, 철 숟가락처럼 철로 만든 물체는 자석에 붙어요.", "나무, 플라스틱, 유리, 종이, 고무로 만든 물체는 자석에 붙지 않아요. 알루미늄 캔이나 동전처럼 '금속'이어도 철이 아니면 붙지 않아요."], "figure": "자석에 붙는 물체(클립, 철 못)와 붙지 않는 물체(지우개, 연필, 알루미늄 캔)를 나누어 놓은 그림", "example": "철 캔은 자석에 붙지만 알루미늄 캔은 붙지 않아서, 재활용 공장에서는 자석으로 두 캔을 골라내요.", "heading": "자석에 붙는 물체, 붙지 않는 물체"}, {"paras": ["자석에서 철로 된 물체가 가장 많이 붙는 부분을 '자석의 극'이라고 해요. 막대자석은 양쪽 끝이 극이에요.", "자석에는 N극과 S극, 두 개의 극이 있어요. 자석을 아무리 잘라도 조각마다 다시 N극과 S극이 생겨요."], "figure": "막대자석의 양쪽 끝에 클립이 잔뜩 붙고 가운데는 거의 붙지 않은 모습", "example": "막대자석을 클립 상자에 넣었다 빼면 양쪽 끝에 클립이 가장 많이 붙어 나와요.", "heading": "자석의 극"}, {"paras": ["두 자석을 가까이 가져가면, 같은 극끼리는 서로 밀어내고 다른 극끼리는 서로 끌어당겨요.", "즉 N극과 N극, S극과 S극은 밀어내고 N극과 S극은 끌어당겨요."], "figure": "N극-S극은 당기는 화살표, N극-N극은 밀어내는 화살표로 표시한 두 막대자석 그림", "example": "자석 장난감 기차는 다른 극끼리 마주 보게 해야 착 붙어요.", "heading": "밀고 당기는 자석"}, {"paras": ["막대자석을 물에 띄운 접시에 올려놓으면 빙글 돌다가 N극은 북쪽, S극은 남쪽을 가리키며 멈춰요.", "이 성질을 이용한 것이 '나침반'이에요. 나침반 바늘도 자석이라서 늘 북쪽과 남쪽을 가리키지요. 그래서 나침반 가까이에 자석을 대면 바늘이 엉뚱한 쪽으로 움직여요."], "figure": "나침반 바늘의 N극이 북쪽을 가리키는 모습", "example": "길을 잃었을 때 나침반으로 북쪽을 찾을 수 있어요.", "heading": "자석은 방향을 알려 줘요"}, {"paras": ["자석은 우리 생활 곳곳에서 쓰여요. 냉장고 문, 자석 칠판, 가방 여밈 장치, 자석 다트 등이 있어요.", "자석은 사이에 다른 물체가 있어도 철로 된 물체를 끌어당길 수 있어요. 그래서 종이를 사이에 두고도 자석으로 칠판에 붙일 수 있어요."], "figure": "냉장고 문, 자석 칠판, 가방 자석 단추 등 생활 속 자석 사진 모음", "example": "", "heading": "생활 속 자석"}], "parent_tip": "부모님께: 아이들은 '금속은 모두 자석에 붙는다'고 생각하기 쉽습니다. 집에 있는 동전, 알루미늄 포일, 철 숟가락, 스테인리스 그릇 등을 자석에 대 보며 '왜 이건 안 붙을까?'를 함께 이야기해 보세요(스테인리스는 종류에 따라 붙기도 하고 안 붙기도 합니다).", "expressions": []}$j$::jsonb where slug='s3-02';
update public.lessons set content=$j${"quiz": [{"q": "그림자가 생기는 까닭과 가장 관계있는 빛의 성질은?", "answer": 0, "choices": ["빛이 곧게 나아간다", "빛은 따뜻하다", "빛은 여러 색이다", "빛은 소리를 낸다"], "explain": "빛이 곧게 나아가다 물체에 막혀 뒤쪽에 그림자가 생겨요."}, {"q": "진한 그림자가 생기는 물체는?", "answer": 2, "choices": ["유리컵", "투명 비닐", "도자기 컵", "투명 플라스틱 판"], "explain": "빛이 통과하지 못하는 불투명한 물체는 진한 그림자가 생겨요."}, {"q": "손전등과 스크린은 그대로 두고 물체를 손전등에 가까이 하면 그림자는?", "answer": 1, "choices": ["작아진다", "커진다", "사라진다", "색이 변한다"], "explain": "물체가 손전등에 가까울수록 빛을 더 많이 가려 그림자가 커져요."}, {"q": "거울 앞에서 오른손을 들면 거울 속 나는 어느 손을 든 것처럼 보일까요?", "answer": 3, "choices": ["오른손", "양손", "손을 안 든다", "왼손"], "explain": "거울에 비친 모습은 좌우가 바뀌어 보여요."}, {"q": "그림자가 생기는 데 꼭 필요하지 __않은__ 것은?", "answer": 3, "choices": ["빛", "물체", "스크린", "소리"], "explain": "그림자는 빛, 물체, 스크린이 있으면 생겨요."}], "intro": "햇빛 좋은 날 운동장에 서면 내 발밑에 까만 그림자가 따라다녀요. 그림자는 어떻게 생기는 걸까요?", "summary": ["빛은 곧게 나아가고, 물체에 막히면 그림자가 생겨요.", "불투명한 물체는 진한 그림자, 투명한 물체는 연한 그림자가 생겨요.", "물체가 빛에 가까울수록 그림자가 커지고, 거울은 빛을 반사해요."], "keywords": [{"word": "빛의 직진", "meaning": "빛이 곧게 나아가는 성질"}, {"word": "그림자", "meaning": "빛이 물체에 막혀 물체 뒤에 생기는 어두운 부분"}, {"word": "투명한 물체", "meaning": "빛이 대부분 통과하는 물체"}, {"word": "불투명한 물체", "meaning": "빛이 통과하지 못하는 물체"}, {"word": "빛의 반사", "meaning": "빛이 거울 같은 물체에 부딪쳐 방향이 바뀌어 나아가는 것"}], "sections": [{"paras": ["손전등을 켜면 빛이 똑바로 뻗어 나가요. 이렇게 빛이 곧게 나아가는 성질을 '빛의 직진'이라고 해요.", "빛이 곧게 나아가다가 물체에 막히면, 물체 뒤쪽으로는 빛이 가지 못해요."], "figure": "어두운 방에서 손전등 빛이 곧은 줄기로 뻗어 나가는 모습", "example": "구름 사이로 햇빛이 쭉쭉 곧은 줄처럼 내려오는 모습을 볼 수 있어요.", "heading": "빛은 곧게 나아가요"}, {"paras": ["그림자가 생기려면 빛, 물체, 그리고 그림자가 비칠 스크린(벽, 땅 등)이 필요해요.", "빛이 곧게 나아가다 물체에 막히면 물체 뒤쪽 스크린에 빛이 닿지 않아 어두운 그림자가 생겨요. 그래서 그림자 모양은 물체 모양과 비슷해요."], "figure": "손전등-손-벽 순서로 놓고 벽에 손 그림자가 생긴 그림", "example": "손으로 강아지 모양을 만들어 벽에 비추면 강아지 그림자가 생겨요.", "heading": "그림자가 생기는 까닭"}, {"paras": ["유리컵처럼 빛이 대부분 통과하는 물체는 연한 그림자가 생겨요. 도자기 컵처럼 빛이 통과하지 못하는 물체는 진한 그림자가 생겨요.", "그림자의 진하기는 물체가 빛을 얼마나 통과시키는지에 따라 달라져요."], "figure": "유리컵의 연한 그림자와 도자기 컵의 진한 그림자를 나란히 비교한 그림", "example": "투명한 비닐우산 아래는 밝고, 검은 우산 아래는 어두워요.", "heading": "투명한 물체와 불투명한 물체"}, {"paras": ["손전등과 스크린은 그대로 두고 물체를 손전등에 가까이 가져가면 그림자가 커지고, 멀리 하면 그림자가 작아져요.", "또 같은 물체라도 놓는 방향을 바꾸면 그림자 모양이 달라질 수 있어요. 원기둥을 세워 옆에서 빛을 비추면 네모, 눕혀서 둥근 밑면 쪽에서 비추면 동그라미 그림자가 생겨요."], "figure": "물체가 손전등에 가까울 때 큰 그림자, 멀 때 작은 그림자가 생기는 두 장면 비교", "example": "인형극에서 인형을 불빛 가까이 대면 무대에 거인처럼 큰 그림자가 생겨요.", "heading": "그림자의 크기 바꾸기"}, {"paras": ["빛이 나아가다 거울에 부딪치면 방향이 바뀌어 되돌아 나와요. 이것을 '빛의 반사'라고 해요.", "거울에 비친 모습은 실제와 좌우가 바뀌어 보여요. 오른손을 들면 거울 속 나는 왼손을 든 것처럼 보이지요."], "figure": "거울에 부딪친 빛의 방향이 꺾여 나가는 화살표 그림", "example": "구급차 앞에 글자를 좌우로 바꿔 써 두면, 앞차 운전자가 뒤를 보는 거울로 볼 때 바르게 읽혀요.", "heading": "거울은 빛을 되돌려요"}], "parent_tip": "부모님께: 아이들은 그림자가 물체에 '붙어 있는' 것이라 생각하기도 합니다. 밤에 손전등과 인형으로 그림자 놀이를 하며 '그림자를 크게 만들려면 어떻게 할까?', '그림자 모양을 동그라미로 바꿀 수 있을까?'를 물어보면 좋습니다.", "expressions": []}$j$::jsonb where slug='s3-03';
update public.lessons set content=$j${"quiz": [{"q": "무게는 무엇일까요?", "answer": 2, "choices": ["물체의 크기", "물체의 색깔", "지구가 물체를 끌어당기는 힘의 크기", "물체의 온도"], "explain": "지구가 물체를 끌어당기는 힘의 크기를 무게라고 해요."}, {"q": "추 1개를 걸면 3cm 늘어나는 용수철에 같은 추 4개를 걸면 몇 cm 늘어날까요?", "answer": 1, "choices": ["7cm", "12cm", "4cm", "9cm"], "explain": "추 1개마다 3cm씩 일정하게 늘어나므로 3 × 4 = 12(cm)예요."}, {"q": "시소에서 몸무게가 다른 두 사람이 수평을 잡으려면?", "answer": 0, "choices": ["무거운 사람이 받침점에 더 가깝게 앉는다", "가벼운 사람이 받침점에 더 가깝게 앉는다", "둘 다 끝에 앉는다", "둘 다 일어선다"], "explain": "무거운 물체는 받침점에 더 가깝게 놓아야 수평이 돼요."}, {"q": "양팔저울에서 왼쪽 접시가 아래로 내려갔어요. 어느 쪽이 더 무거울까요?", "answer": 1, "choices": ["오른쪽", "왼쪽", "둘이 같다", "알 수 없다"], "explain": "양팔저울은 더 무거운 쪽이 아래로 내려가요."}, {"q": "무게가 같은 두 물체로 수평을 잡으려면?", "answer": 2, "choices": ["한 물체를 받침점 위에 놓는다", "한쪽에만 놓는다", "받침점에서 같은 거리에 놓는다", "아무 데나 놓는다"], "explain": "무게가 같으면 받침점에서 같은 거리에 놓아야 수평이 돼요."}], "intro": "몸무게를 잴 때 체중계에 올라가요. 그런데 '무게'란 정확히 무엇이고, 저울은 어떻게 무게를 알아낼까요?", "summary": ["무게는 지구가 물체를 끌어당기는 힘의 크기예요.", "용수철은 무게에 따라 일정하게 늘어나며, 이를 이용해 무게를 재요.", "무거운 물체는 받침점에 가깝게 놓아야 수평이 잡혀요."], "keywords": [{"word": "무게", "meaning": "지구가 물체를 끌어당기는 힘의 크기"}, {"word": "용수철저울", "meaning": "용수철이 늘어나는 길이로 무게를 재는 저울"}, {"word": "받침점", "meaning": "수평 잡기에서 물체를 받치는 가운데 점"}, {"word": "수평", "meaning": "어느 쪽으로도 기울지 않은 상태"}, {"word": "양팔저울", "meaning": "수평 잡기 원리로 두 물체의 무게를 비교하는 저울"}], "sections": [{"paras": ["지구는 물체를 지구 쪽으로 끌어당겨요. 그래서 공을 던져도 다시 땅으로 떨어지지요.", "지구가 물체를 끌어당기는 힘의 크기를 '무게'라고 해요. 무거운 물체일수록 지구가 더 세게 끌어당겨요."], "figure": "나무에서 떨어지는 사과와 아래로 향한 화살표", "example": "사과가 나무에서 땅으로 떨어지는 것은 지구가 사과를 끌어당기기 때문이에요.", "heading": "무게란 무엇일까요?"}, {"paras": ["용수철에 물체를 걸면 용수철이 늘어나요. 무거운 물체를 걸수록 용수철이 더 많이 늘어나요.", "추를 하나씩 더 걸 때마다 용수철은 일정한 길이만큼씩 늘어나요. 이 성질을 이용해 무게를 재는 도구가 '용수철저울'이에요. 무게의 단위로는 g중, kg중, N(뉴턴) 등을 써요."], "figure": "용수철에 추를 1개, 2개, 3개 걸었을 때 일정하게 늘어나는 모습을 나란히 그린 그림", "example": "추 1개에 2cm 늘어나는 용수철은 추 3개를 걸면 6cm 늘어나요.", "heading": "용수철로 무게 재기"}, {"paras": ["널빤지 가운데를 받침점 위에 올려놓고 양쪽에 물체를 올려 기울지 않게 하는 것을 '수평 잡기'라고 해요.", "무게가 같은 물체는 받침점에서 같은 거리에 놓아야 수평이 돼요. 무게가 다르면 무거운 물체를 받침점에 더 가깝게 놓아야 수평을 잡을 수 있어요."], "figure": "시소 가운데 받침점 가까이 어른, 끝에 아이가 앉아 수평을 이룬 그림", "example": "시소를 탈 때 몸무게가 무거운 아빠는 가운데 쪽으로, 가벼운 아이는 끝 쪽에 앉으면 균형이 맞아요.", "heading": "수평 잡기의 원리"}, {"paras": ["양팔저울은 수평 잡기의 원리로 두 물체의 무게를 비교해요. 내려간 쪽 물체가 더 무거워요.", "체중계, 가정용 저울, 전자저울처럼 생활에서 쓰는 저울도 많아요. 물건을 사고팔 때나 요리할 때, 몸무게를 잴 때 저울로 정확한 무게를 알 수 있어요."], "figure": "양팔저울 한쪽에 사과, 다른 쪽에 귤을 올려 사과 쪽이 내려간 모습", "example": "양팔저울 한쪽에 사과, 다른 쪽에 귤을 올렸더니 사과 쪽이 내려갔다면 사과가 더 무거워요.", "heading": "여러 가지 저울"}], "parent_tip": "부모님께: 아이들은 '크면 무겁다'고 생각하기 쉽습니다. 크기는 크지만 가벼운 스펀지와 작지만 무거운 쇠붙이를 들어 보게 하고, '시소에서 엄마랑 균형을 맞추려면 누가 어디에 앉아야 할까?'를 물어보면 수평 잡기 원리를 쉽게 떠올립니다.", "expressions": []}$j$::jsonb where slug='s3-04';
update public.lessons set content=$j${"quiz": [{"q": "다음 중 혼합물이 __아닌__ 것은?", "answer": 3, "choices": ["팥빙수", "잡곡", "바닷물", "순수한 물"], "explain": "순수한 물은 한 가지 물질이에요. 나머지는 여러 물질이 섞인 혼합물이에요."}, {"q": "콩과 좁쌀이 섞여 있을 때 가장 쉽게 나누는 방법은?", "answer": 0, "choices": ["체로 거른다", "물에 녹인다", "불로 태운다", "자석을 댄다"], "explain": "콩과 좁쌀은 알갱이 크기가 달라서 체로 나눌 수 있어요."}, {"q": "모래와 철 가루를 나누는 데 알맞은 도구는?", "answer": 2, "choices": ["거름종이", "체", "자석", "돋보기"], "explain": "철 가루는 자석에 붙고 모래는 붙지 않아요."}, {"q": "소금과 모래 혼합물을 물에 녹여 거르면 거름종이 위에 남는 것은?", "answer": 1, "choices": ["소금", "모래", "소금물", "아무것도 안 남는다"], "explain": "모래는 물에 녹지 않아 거름종이 위에 남고, 소금은 물에 녹아 빠져나가요."}, {"q": "소금물에서 소금을 얻으려면 어떻게 해야 할까요?", "answer": 3, "choices": ["체로 거른다", "자석을 댄다", "얼린다", "물을 증발시킨다"], "explain": "물이 증발해 날아가면 소금만 남아요."}], "intro": "콩, 팥, 좁쌀이 한 그릇에 뒤섞였어요. 하나하나 손으로 골라내려면 너무 오래 걸리겠죠? 더 쉬운 방법이 있을까요?", "summary": ["혼합물은 여러 물질이 섞인 것이고, 섞여도 각 물질의 성질은 그대로예요.", "크기는 체, 철은 자석, 녹는 성질은 거름으로 나눠요.", "소금물의 물을 증발시키면 소금을 얻을 수 있어요."], "keywords": [{"word": "혼합물", "meaning": "두 가지 이상의 물질이 섞여 있는 것"}, {"word": "분리", "meaning": "섞여 있는 물질을 나누는 것"}, {"word": "체", "meaning": "알갱이 크기 차이로 물질을 나누는 도구"}, {"word": "거름", "meaning": "거름종이로 녹지 않은 물질을 걸러 내는 방법"}, {"word": "증발", "meaning": "물이 표면에서 수증기가 되어 날아가는 것"}], "sections": [{"paras": ["두 가지 이상의 물질이 섞여 있는 것을 '혼합물'이라고 해요. 섞여 있어도 각 물질의 성질은 그대로 남아 있어요.", "김밥, 팥빙수, 잡곡, 바닷물(물+소금)도 모두 혼합물이에요. 그래서 각 물질의 성질 차이를 이용하면 다시 나눌(분리할) 수 있어요."], "figure": "콩, 팥, 좁쌀이 섞인 그릇 그림", "example": "콩·팥·좁쌀을 섞어도 콩은 콩대로, 팥은 팥대로 크기와 색이 그대로예요.", "heading": "혼합물이란?"}, {"paras": ["알갱이의 크기가 다른 혼합물은 '체'로 나눌 수 있어요. 체의 눈보다 작은 알갱이는 빠져나가고 큰 알갱이는 체에 남아요.", "눈의 크기가 다른 체를 차례로 쓰면 콩, 팥, 좁쌀을 모두 나눌 수 있어요."], "figure": "눈 크기가 다른 체 두 개로 콩, 팥, 좁쌀을 차례로 분리하는 과정 그림", "example": "모래사장에서 체로 모래를 거르면 조개껍데기처럼 큰 알갱이가 체에 남아요.", "heading": "알갱이 크기로 나누기 – 체"}, {"paras": ["철로 된 물체가 섞여 있으면 자석으로 쉽게 골라낼 수 있어요. 자석에 붙는 성질을 이용한 것이지요.", "재활용 공장에서는 큰 자석으로 철 캔과 알루미늄 캔을 나눠요."], "figure": "모래와 철 가루 혼합물에 자석을 대어 철 가루만 끌려 나오는 모습", "example": "모래 속에 섞인 철 가루는 자석을 대면 자석에 달라붙어 나와요.", "heading": "자석으로 나누기"}, {"paras": ["소금과 모래가 섞여 있으면 먼저 물을 부어 저어요. 소금은 물에 녹고 모래는 녹지 않아요.", "이것을 거름종이를 올린 깔때기에 부으면 모래는 거름종이 위에 남고 소금물만 아래로 빠져요. 이렇게 거름종이로 거르는 것을 '거름'이라고 해요."], "figure": "깔때기에 거름종이를 끼우고 소금물과 모래를 부어 거르는 실험 장치 그림", "example": "커피를 내릴 때 커피 가루는 필터에 남고 커피 물만 내려오는 것도 거름이에요.", "heading": "물에 녹는 성질로 나누기 – 거름"}, {"paras": ["거름으로 얻은 소금물을 가열하거나 햇볕에 오래 두면 물이 증발해 날아가고 하얀 소금만 남아요. 가열할 때는 소금물이 튈 수 있으니 꼭 어른과 함께하고, 햇볕에 며칠 두는 방법이 더 안전해요.", "바닷가 염전에서는 바닷물을 햇볕과 바람에 증발시켜 소금을 얻어요."], "figure": "넓은 염전에 바닷물을 가두고 하얀 소금을 긁어모으는 모습", "example": "", "heading": "물을 날려 보내 나누기 – 증발"}], "parent_tip": "부모님께: 아이들은 소금이 물에 녹으면 '없어졌다'고 생각하곤 합니다. 소금물을 조금 맛보게 하거나 접시에 담아 며칠 두어 소금이 다시 나타나는 것을 보여 주세요. '주방에서 혼합물을 나누는 도구는 뭐가 있을까?'(체, 커피 필터, 국자 등)를 함께 찾아보는 것도 좋습니다.", "expressions": []}$j$::jsonb where slug='s3-05';
update public.lessons set content=$j${"quiz": [{"q": "배추흰나비의 한살이 순서로 옳은 것은?", "answer": 1, "choices": ["알 → 번데기 → 애벌레 → 어른벌레", "알 → 애벌레 → 번데기 → 어른벌레", "애벌레 → 알 → 번데기 → 어른벌레", "알 → 어른벌레 → 애벌레 → 번데기"], "explain": "배추흰나비는 알, 애벌레, 번데기, 어른벌레 순서로 자라요."}, {"q": "번데기 단계가 없는 불완전 탈바꿈을 하는 곤충은?", "answer": 2, "choices": ["배추흰나비", "벌", "잠자리", "무당벌레"], "explain": "잠자리는 알-애벌레-어른벌레로 자라 번데기 단계가 없어요."}, {"q": "배추흰나비 애벌레가 자라면서 하는 일은?", "answer": 0, "choices": ["허물을 벗는다", "알을 낳는다", "날개로 난다", "꽃꿀을 빤다"], "explain": "애벌레는 잎을 먹고 여러 번 허물을 벗으며 커져요."}, {"q": "다음 중 새끼를 낳는 동물은?", "answer": 3, "choices": ["닭", "개구리", "거북", "고양이"], "explain": "고양이는 새끼를 낳고 젖을 먹여 길러요. 나머지는 알을 낳아요."}, {"q": "번데기 시기의 특징으로 옳은 것은?", "answer": 1, "choices": ["잎을 많이 먹는다", "거의 움직이지 않고 먹지 않는다", "알을 낳는다", "날아다닌다"], "explain": "번데기는 먹지 않고 움직이지 않지만 안에서 어른벌레로 변하고 있어요."}], "intro": "봄에 배추밭을 날던 흰나비는 어디에서 왔을까요? 처음부터 나비였을까요?", "summary": ["한살이는 동물이 태어나 자라서 자손을 남기는 과정이에요.", "배추흰나비는 알-애벌레-번데기-어른벌레로 자라요(완전 탈바꿈).", "잠자리처럼 번데기 없이 자라는 것은 불완전 탈바꿈이에요."], "keywords": [{"word": "한살이", "meaning": "동물이 태어나 자라서 자손을 남기는 과정"}, {"word": "애벌레", "meaning": "알에서 깨어난 어린 곤충"}, {"word": "번데기", "meaning": "애벌레가 어른벌레가 되기 전 움직이지 않는 단계"}, {"word": "완전 탈바꿈", "meaning": "알-애벌레-번데기-어른벌레로 자라는 것"}, {"word": "불완전 탈바꿈", "meaning": "번데기 단계 없이 알-애벌레-어른벌레로 자라는 것"}], "sections": [{"paras": ["동물이 알이나 새끼로 태어나서 자라 어른이 되고, 다시 알이나 새끼를 낳는 과정을 '한살이'라고 해요.", "동물마다 한살이 모습이 달라요. 어떤 동물은 자라면서 생김새가 크게 바뀌고, 어떤 동물은 모습이 거의 그대로예요."], "figure": "알에서 어른까지 둥글게 이어진 한살이 순환 화살표 그림", "example": "", "heading": "한살이란?"}, {"paras": ["배추흰나비는 '알 → 애벌레 → 번데기 → 어른벌레(나비)' 순서로 자라요. 알은 주로 배추나 케일 잎 뒷면에 낳아요.", "애벌레는 잎을 먹으며 허물을 벗고 자라요. 번데기 때는 아무것도 먹지 않고 움직이지 않지만, 그 안에서 어른벌레로 변하고 있어요."], "figure": "배추흰나비의 알, 애벌레, 번데기, 어른벌레를 순서대로 그린 그림", "example": "배추흰나비 애벌레는 배추 잎을 갉아 먹어 잎에 구멍을 내요.", "heading": "배추흰나비의 한살이"}, {"paras": ["배추흰나비 같은 나비, 벌, 파리, 무당벌레처럼 번데기 단계를 거치는 것을 '완전 탈바꿈'이라고 해요.", "잠자리, 매미, 메뚜기, 사마귀는 '알 → 애벌레 → 어른벌레'로 자라고 번데기 단계가 없어요. 이것을 '불완전 탈바꿈'이라고 해요."], "figure": "완전 탈바꿈(알-애벌레-번데기-어른)과 불완전 탈바꿈(알-애벌레-어른)을 위아래로 비교한 그림", "example": "잠자리 애벌레(학배기)는 물속에서 살다가 물 밖으로 나와 허물을 벗고 잠자리가 돼요.", "heading": "완전 탈바꿈과 불완전 탈바꿈"}, {"paras": ["닭, 개구리, 거북, 물고기처럼 알을 낳는 동물이 있어요. 닭의 알은 약 21일 동안 품으면 병아리가 깨어나요.", "개, 고양이, 소, 사람처럼 새끼를 낳는 동물은 어미 배 속에서 어느 정도 자란 뒤 태어나고, 어릴 때 어미젖을 먹고 자라요."], "figure": "알을 낳는 동물(닭, 개구리)과 새끼를 낳는 동물(개, 소)을 나눈 그림", "example": "개구리는 알 → 올챙이 → 개구리 순서로 자라면서 아가미 대신 폐로 숨 쉬게 돼요.", "heading": "알을 낳는 동물, 새끼를 낳는 동물"}], "parent_tip": "부모님께: 아이들은 애벌레와 나비를 서로 다른 동물로 생각하기 쉽습니다. 나비 사진과 애벌레 사진을 보여 주며 '이 둘이 같은 동물이래, 어떻게 바뀔까?'라고 물어보세요. 사람도 아기-어린이-어른으로 자라지만 탈바꿈은 하지 않는다는 점을 비교해 보면 좋습니다.", "expressions": []}$j$::jsonb where slug='s3-06';
update public.lessons set content=$j${"quiz": [{"q": "씨가 싹트는 데 꼭 필요한 조건 두 가지는?", "answer": 1, "choices": ["빛과 바람", "물과 알맞은 온도", "흙과 비료", "소리와 빛"], "explain": "씨는 알맞은 물과 온도가 있으면 싹이 터요. 씨 속 양분을 쓰기 때문에 빛은 꼭 필요하지 않아요."}, {"q": "강낭콩이 싹틀 때 가장 먼저 나오는 것은?", "answer": 2, "choices": ["꽃", "본잎", "뿌리", "열매"], "explain": "강낭콩은 뿌리가 먼저 나오고 그다음 떡잎이 올라와요."}, {"q": "다음 중 한해살이 식물은?", "answer": 3, "choices": ["사과나무", "감나무", "개나리", "벼"], "explain": "벼는 한 해 안에 한살이를 마치는 한해살이 식물이에요."}, {"q": "강낭콩 꼬투리 속 콩알은 무엇일까요?", "answer": 0, "choices": ["씨", "뿌리", "떡잎", "꽃잎"], "explain": "꼬투리는 열매이고 그 안의 콩알이 씨예요."}, {"q": "식물의 한살이 순서로 옳은 것은?", "answer": 2, "choices": ["꽃 → 씨 → 싹 → 열매", "싹 → 씨 → 열매 → 꽃", "씨 → 싹 → 꽃 → 열매", "열매 → 꽃 → 싹 → 씨"], "explain": "씨가 싹트고 자라 꽃이 피고, 열매를 맺어 다시 씨를 남겨요."}], "intro": "작은 강낭콩 한 알을 심으면 싹이 나고 꽃이 피고, 어느새 콩이 주렁주렁 열려요. 그 과정을 따라가 볼까요?", "summary": ["씨는 알맞은 물과 온도가 있으면 싹터요.", "식물은 싹 → 자람 → 꽃 → 열매(씨) 순서로 한살이를 해요.", "한해살이 식물은 한 해에, 여러해살이 식물은 여러 해 동안 살아요."], "keywords": [{"word": "한살이", "meaning": "씨가 싹터서 자라 꽃과 열매를 맺고 다시 씨를 남기는 과정"}, {"word": "떡잎", "meaning": "싹이 틀 때 처음 나오는, 양분을 담은 잎"}, {"word": "본잎", "meaning": "떡잎 다음에 나오는 잎"}, {"word": "한해살이 식물", "meaning": "한 해 안에 한살이를 마치고 죽는 식물"}, {"word": "여러해살이 식물", "meaning": "여러 해 동안 살면서 해마다 꽃과 열매를 맺는 식물"}], "sections": [{"paras": ["씨가 싹트려면 알맞은 양의 '물'과 알맞은 '온도'가 필요해요. 물을 주지 않거나 너무 추우면 싹이 트지 않아요.", "씨가 싹틀 때는 씨 속에 들어 있는 양분을 쓰기 때문에 빛이 없어도 싹이 틀 수 있어요. 하지만 싹이 튼 뒤 잘 자라려면 빛이 필요해요."], "figure": "젖은 솜과 마른 솜 위에 놓인 강낭콩을 비교한 그림", "example": "물에 적신 솜 위의 강낭콩은 싹이 트고, 마른 솜 위의 강낭콩은 그대로예요.", "heading": "씨가 싹트려면"}, {"paras": ["강낭콩은 싹이 틀 때 뿌리가 먼저 나오고, 이어서 떡잎 두 장이 땅 위로 올라와요. 떡잎은 씨 속 양분을 담고 있어서 시간이 지나면 쭈글쭈글해지고 떨어져요.", "그다음 본잎이 나고 줄기가 길어지며 잎의 수가 늘어나요. 식물이 잘 자라려면 물, 빛, 알맞은 온도와 공기가 필요해요."], "figure": "강낭콩 싹이 트는 과정: 뿌리 → 떡잎 → 본잎 순서 그림", "example": "콩나물은 빛 없이 길러서 잎이 노랗지만, 햇빛을 받으면 초록색으로 변해요.", "heading": "싹이 트고 자라요"}, {"paras": ["식물이 충분히 자라면 꽃이 피고, 꽃이 진 자리에 열매가 생겨요. 열매 속에는 다음 한살이를 시작할 씨가 들어 있어요.", "강낭콩은 꼬투리가 열매이고, 그 안의 콩알 하나하나가 씨예요."], "figure": "강낭콩 꽃, 꼬투리, 꼬투리 속 콩알을 순서대로 그린 그림", "example": "사과를 반으로 자르면 가운데에 작은 씨가 들어 있어요.", "heading": "꽃이 피고 열매를 맺어요"}, {"paras": ["강낭콩, 벼, 옥수수, 해바라기처럼 한 해 안에 한살이를 마치고 죽는 식물을 '한해살이 식물'이라고 해요.", "사과나무, 감나무, 개나리, 무궁화처럼 여러 해 동안 살면서 해마다 꽃과 열매를 맺는 식물을 '여러해살이 식물'이라고 해요."], "figure": "한해살이(벼, 강낭콩)와 여러해살이(사과나무, 개나리)를 나눈 그림", "example": "벼는 봄에 심어 가을에 거두고 나면 죽지만, 감나무는 해마다 감이 열려요.", "heading": "한해살이와 여러해살이"}], "parent_tip": "부모님께: 아이들은 '씨가 싹트려면 햇빛이 꼭 필요하다'고 자주 오해합니다. 강낭콩을 젖은 솜에 올려 하나는 밝은 곳, 하나는 어두운 상자 속에 두고 비교해 보세요. '마트에서 파는 콩나물은 왜 노랄까?'라고 물어보는 것도 좋은 대화거리입니다.", "expressions": []}$j$::jsonb where slug='s3-07';
update public.lessons set content=$j${"quiz": [{"q": "지구 표면에서 더 넓은 곳은?", "answer": 1, "choices": ["육지", "바다", "둘이 같다", "알 수 없다"], "explain": "지구 표면을 10칸으로 나누면 바다가 약 7칸, 육지가 약 3칸이라 바다가 더 넓어요."}, {"q": "달에 대한 설명으로 옳은 것은?", "answer": 2, "choices": ["공기가 많다", "바다에 물이 가득하다", "공기와 물이 없다", "생물이 많이 산다"], "explain": "달에는 공기와 물이 없어서 생물이 살 수 없어요."}, {"q": "달 표면에 있는 둥글게 움푹 파인 곳을 무엇이라고 할까요?", "answer": 0, "choices": ["충돌 구덩이", "화산", "강", "바다"], "explain": "운석이 부딪쳐 생긴 구덩이를 충돌 구덩이(크레이터)라고 해요."}, {"q": "지구에 생물이 살 수 있는 까닭으로 알맞지 __않은__ 것은?", "answer": 3, "choices": ["물이 있다", "공기가 있다", "알맞은 온도이다", "충돌 구덩이가 많다"], "explain": "지구에는 물, 공기, 알맞은 온도가 있어 생물이 살 수 있어요."}, {"q": "달에서 우주 비행사의 발자국이 오래 남는 까닭은?", "answer": 2, "choices": ["달이 차가워서", "달이 작아서", "바람이 불지 않아서", "달이 둥글어서"], "explain": "달에는 공기가 없어 바람이 불지 않아 발자국이 지워지지 않아요."}], "intro": "밤하늘의 둥근 달을 보면 토끼 모양 무늬가 보여요. 달은 어떤 곳일까요? 그리고 우리가 사는 지구는 어떤 모습일까요?", "summary": ["지구는 둥글고, 바다가 육지보다 넓어요.", "지구에는 공기와 물이 있어 생물이 살 수 있어요.", "달은 둥글고 지구보다 작으며, 공기와 물이 없고 충돌 구덩이가 많아요."], "keywords": [{"word": "육지", "meaning": "지구 표면에서 물로 덮이지 않은 땅"}, {"word": "바다", "meaning": "지구 표면에서 짠물로 덮인 넓은 곳"}, {"word": "공기", "meaning": "지구를 둘러싸고 있어 생물이 숨 쉴 수 있게 해 주는 기체"}, {"word": "달의 바다", "meaning": "달 표면에서 어둡게 보이는 넓고 평평한 곳(물은 없음)"}, {"word": "충돌 구덩이", "meaning": "운석이 부딪쳐 생긴 둥글게 움푹 파인 곳"}], "sections": [{"paras": ["우주에서 찍은 사진을 보면 지구는 공처럼 둥근 모양이에요. 지구가 너무 커서 땅 위에 서 있는 우리에게는 평평해 보일 뿐이에요.", "지구 표면에는 육지와 바다가 있는데, 바다가 육지보다 훨씬 넓어요. 지구 표면을 10칸으로 나누면 바다가 약 7칸, 육지가 약 3칸이에요."], "figure": "우주에서 본 파랗고 둥근 지구 사진", "example": "멀리서 다가오는 배는 꼭대기의 돛부터 보이기 시작하는데, 지구가 둥글기 때문이에요.", "heading": "지구는 둥글어요"}, {"paras": ["지구는 공기로 둘러싸여 있어요. 공기가 있어서 생물이 숨을 쉴 수 있고, 바람이 불고 구름이 생겨요.", "또 지구에는 물이 있어 생물이 살아갈 수 있어요. 알맞은 온도, 공기, 물이 있어서 지구에는 많은 생물이 살아요."], "figure": "공기층에 둘러싸인 지구와 바다, 숲, 동물을 함께 그린 그림", "example": "", "heading": "지구에는 공기와 물이 있어요"}, {"paras": ["달도 지구처럼 둥근 공 모양이에요. 크기는 지구보다 작아서 지름이 지구의 약 4분의 1이에요.", "달 표면의 어둡게 보이는 넓은 곳을 '달의 바다'라고 하는데, 실제로 물이 있는 것은 아니에요. 또 달 표면에는 운석이 부딪쳐 생긴 움푹 파인 구덩이인 '충돌 구덩이(크레이터)'가 많아요."], "figure": "달 표면의 어두운 '바다'와 둥근 충돌 구덩이를 표시한 사진", "example": "보름달의 어두운 무늬(달의 바다)를 보고 옛사람들은 방아 찧는 토끼를 떠올렸어요.", "heading": "달은 어떻게 생겼을까요?"}, {"paras": ["달에는 공기와 물이 없어요. 그래서 바람이 불지 않고, 생물이 살 수 없어요. 공기가 없어서 소리도 전해지지 않아요.", "또 낮에는 아주 뜨겁고 밤에는 아주 차가워요. 지구는 공기와 물이 있어 생물이 살기에 알맞은 환경이에요."], "figure": "지구와 달을 나란히 놓고 공기·물·생물 유무를 표로 비교한 그림", "example": "달에 간 우주 비행사의 발자국은 바람이 없어서 오랫동안 그대로 남아 있어요.", "heading": "지구와 달 비교하기"}], "parent_tip": "부모님께: '달의 바다'라는 이름 때문에 달에 물이 있다고 오해하는 아이가 많습니다. 보름달이 뜨는 날 함께 달을 보며 어두운 무늬를 찾아보고, '달에 가면 친구 목소리가 들릴까?'처럼 지구와 비교하는 질문을 해 보세요.", "expressions": []}$j$::jsonb where slug='s3-09';
update public.lessons set content=$j${"quiz": [{"q": "프리즘에 햇빛을 통과시키면 어떻게 될까요?", "answer": 1, "choices": ["빛이 사라진다", "여러 빛깔로 나뉜다", "검은색이 된다", "빛이 더 하얘진다"], "explain": "햇빛은 여러 빛깔의 빛으로 이루어져 있어 프리즘을 지나면 나뉘어 보여요."}, {"q": "물이 든 컵 속 젓가락이 꺾여 보이는 까닭은?", "answer": 0, "choices": ["빛의 굴절", "빛의 반사", "그림자", "소리의 반사"], "explain": "빛이 물과 공기의 경계에서 꺾이기 때문이에요."}, {"q": "볼록 렌즈의 모양으로 옳은 것은?", "answer": 2, "choices": ["가장자리가 가운데보다 두껍다", "모든 곳의 두께가 같다", "가운데가 가장자리보다 두껍다", "가운데에 구멍이 있다"], "explain": "볼록 렌즈는 가운데가 가장자리보다 두꺼워요."}, {"q": "볼록 렌즈를 이용한 도구가 __아닌__ 것은?", "answer": 3, "choices": ["돋보기", "현미경", "사진기", "평면 거울"], "explain": "평면 거울은 빛을 반사하는 도구이고 렌즈가 아니에요."}, {"q": "볼록 렌즈로 햇빛을 모은 곳의 특징은?", "answer": 1, "choices": ["더 어둡고 차갑다", "더 밝고 온도가 높다", "색이 검게 변한다", "아무 변화가 없다"], "explain": "빛이 한 곳에 모여서 그곳은 밝고 뜨거워져요."}], "intro": "돋보기로 개미를 보면 커다랗게 보이고, 햇빛을 한 점에 모으면 종이를 태울 수도 있어요. 렌즈는 어떻게 빛을 다룰까요?", "summary": ["햇빛은 여러 빛깔의 빛으로 이루어져 있어요.", "빛은 서로 다른 물질의 경계에서 꺾여요(굴절).", "볼록 렌즈는 빛을 모으고, 물체를 크게 또는 거꾸로 보이게 해요."], "keywords": [{"word": "프리즘", "meaning": "빛을 여러 빛깔로 나누는 투명한 삼각기둥 모양의 기구"}, {"word": "빛의 굴절", "meaning": "빛이 서로 다른 물질의 경계에서 꺾여 나아가는 것"}, {"word": "볼록 렌즈", "meaning": "가운데가 가장자리보다 두꺼운 렌즈"}, {"word": "돋보기", "meaning": "볼록 렌즈로 물체를 크게 보이게 하는 도구"}, {"word": "간이 사진기", "meaning": "볼록 렌즈와 스크린으로 만든 간단한 사진기"}], "sections": [{"paras": ["햇빛을 프리즘에 통과시키면 하얀 종이 위에 빨강, 주황, 노랑, 초록, 파랑, 남색, 보라처럼 여러 빛깔이 나타나요.", "이것으로 햇빛이 여러 가지 빛깔의 빛으로 이루어져 있다는 것을 알 수 있어요."], "figure": "프리즘을 통과한 햇빛이 무지갯빛으로 나뉘는 그림", "example": "비가 그친 뒤 하늘에 생기는 무지개는 공기 중 물방울이 프리즘처럼 햇빛을 여러 빛깔로 나눈 거예요.", "heading": "햇빛은 여러 빛깔로 되어 있어요"}, {"paras": ["빛이 공기 중에서 물이나 유리로 비스듬히 들어가면 두 물질의 경계에서 꺾여 나아가요. 이것을 '빛의 굴절'이라고 해요.", "빛이 경계에 수직으로(똑바로) 들어가면 꺾이지 않고 그대로 나아가요."], "figure": "물컵 속 젓가락이 수면에서 꺾여 보이는 모습과 빛이 꺾이는 경로 화살표", "example": "물이 든 컵에 젓가락을 넣으면 젓가락이 수면에서 꺾여 보여요.", "heading": "빛은 경계에서 꺾여요 – 굴절"}, {"paras": ["볼록 렌즈는 가운데가 가장자리보다 두꺼운 렌즈예요. 볼록 렌즈를 통과한 빛은 굴절하여 한 곳으로 모여요.", "햇빛을 볼록 렌즈로 모으면 빛이 모인 곳은 더 밝고 온도도 높아요. 그래서 검은 종이를 태울 수 있어요. 이 활동은 반드시 어른과 함께하고, 렌즈로 해를 직접 보면 절대 안 돼요!"], "figure": "볼록 렌즈를 통과한 평행한 햇빛이 한 점으로 모이는 그림", "example": "물이 담긴 둥근 어항이나 유리구슬도 볼록 렌즈처럼 빛을 모을 수 있어요.", "heading": "볼록 렌즈의 특징"}, {"paras": ["볼록 렌즈로 가까운 물체를 보면 실제보다 크게 보여요. 멀리 있는 물체를 보면 상하좌우가 바뀌어(거꾸로) 보이기도 해요.", "볼록 렌즈의 성질을 이용한 도구로는 돋보기, 현미경, 망원경, 사진기, 확대경 등이 있어요."], "figure": "돋보기로 가까운 글자는 크게, 먼 풍경은 거꾸로 보이는 두 장면 비교", "example": "간이 사진기를 만들면 볼록 렌즈 때문에 스크린에 바깥 풍경이 거꾸로 비쳐요.", "heading": "볼록 렌즈로 본 모습"}], "parent_tip": "부모님께: 아이들은 빛의 '반사'와 '굴절'을 헷갈려 합니다. 거울에 비친 모습은 반사, 물컵 속 빨대가 꺾여 보이는 것은 굴절이라고 짝지어 주세요. 돋보기로 햇빛을 모으는 활동은 반드시 보호자와 함께하고, 렌즈로 해를 직접 보지 않도록 알려 주세요.", "expressions": []}$j$::jsonb where slug='s5-03';
update public.lessons set content=$j${"quiz": [{"q": "태양계에서 가장 큰 행성은?", "answer": 2, "choices": ["지구", "토성", "목성", "해왕성"], "explain": "목성이 가장 크며 지름이 지구의 약 11배예요."}, {"q": "태양에서 가장 가까운 행성은?", "answer": 0, "choices": ["수성", "금성", "지구", "화성"], "explain": "태양에서 가까운 순서는 수성, 금성, 지구, 화성…이에요."}, {"q": "별과 행성의 차이로 옳은 것은?", "answer": 2, "choices": ["행성은 스스로 빛을 낸다", "별은 태양 둘레를 돈다", "별은 스스로 빛을 내고, 행성은 태양 빛을 반사한다", "별과 행성은 같은 것이다"], "explain": "별은 스스로 빛을 내지만 행성은 태양 빛을 반사해 밝게 보여요."}, {"q": "북두칠성으로 북극성을 찾을 때, 국자 끝 두 별 사이 거리의 몇 배만큼 가면 될까요?", "answer": 2, "choices": ["2배", "3배", "5배", "10배"], "explain": "국자 끝 두 별을 이은 거리의 약 5배 떨어진 곳에 북극성이 있어요."}, {"q": "태양이 우리 생활에 주는 영향이 __아닌__ 것은?", "answer": 3, "choices": ["식물이 양분을 만든다", "물이 증발해 비가 내린다", "알맞은 온도를 만든다", "밀물과 썰물을 주로 일으킨다"], "explain": "밀물과 썰물은 주로 달의 영향으로 생겨요. 나머지는 태양 덕분이에요."}], "intro": "밤하늘에는 반짝이는 별이 가득해요. 그런데 그중에는 별이 아닌 '행성'도 섞여 있다는 사실, 알고 있나요?", "summary": ["태양은 스스로 빛과 열을 내며 지구의 생물에게 꼭 필요해요.", "태양계 행성은 수성·금성·지구·화성·목성·토성·천왕성·해왕성 8개이고, 목성이 가장 커요.", "별은 스스로 빛을 내고, 북극성은 북두칠성이나 카시오페이아자리로 찾을 수 있어요."], "keywords": [{"word": "태양계", "meaning": "태양과 태양의 영향을 받는 천체들, 그리고 그 공간"}, {"word": "행성", "meaning": "태양 둘레를 도는, 스스로 빛을 내지 못하는 천체"}, {"word": "위성", "meaning": "행성 둘레를 도는 천체(예: 달)"}, {"word": "별", "meaning": "스스로 빛을 내는 천체"}, {"word": "별자리", "meaning": "밝은 별들을 이어 이름을 붙인 것"}, {"word": "북극성", "meaning": "항상 북쪽 하늘에 있어 방위를 알려 주는 별"}], "sections": [{"paras": ["태양은 스스로 빛과 열을 내는 별이에요. 태양 빛 덕분에 식물이 양분을 만들고, 동물은 그 식물을 먹고 살아요.", "태양은 물을 증발시켜 비와 눈이 내리게 하고, 우리가 생활하기에 알맞은 온도를 만들어 줘요. 태양이 없다면 지구의 생물은 살 수 없어요."], "figure": "태양 빛을 받아 자라는 식물, 태양 전지판, 염전 그림", "example": "햇빛으로 전기를 만드는 태양 전지판, 바닷물을 말려 소금을 얻는 염전도 태양 에너지를 이용해요.", "heading": "태양은 우리에게 꼭 필요해요"}, {"paras": ["태양과 태양의 영향을 받는 천체들, 그리고 그 공간을 '태양계'라고 해요. 태양계의 중심에는 태양이 있어요.", "태양 둘레를 도는 행성은 태양에서 가까운 순서대로 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성 8개예요. 달처럼 행성 둘레를 도는 천체는 '위성'이라고 해요."], "figure": "태양을 중심으로 8개 행성이 순서대로 늘어선 태양계 그림", "example": "외우기 팁: '수·금·지·화·목·토·천·해'!", "heading": "태양계의 구성원"}, {"paras": ["태양계 행성 중 가장 큰 것은 목성이고, 가장 작은 것은 수성이에요. 지구를 기준으로 보면 목성은 지름이 지구의 약 11배나 돼요.", "수성, 금성, 지구, 화성은 상대적으로 작고 표면이 암석으로 되어 있어요. 목성, 토성, 천왕성, 해왕성은 크고 주로 기체로 되어 있으며 고리가 있어요. 태양에서 멀수록 행성 사이의 거리도 대체로 멀어요."], "figure": "지구 크기를 1로 놓고 8개 행성의 크기를 비교한 막대 또는 원 그림", "example": "지구 지름을 1이라고 하면 목성은 약 11.2, 수성은 약 0.4예요.", "heading": "행성의 크기와 거리"}, {"paras": ["별은 태양처럼 스스로 빛을 내는 천체예요. 행성은 스스로 빛을 내지 못하고 태양 빛을 반사해서 밝게 보여요.", "별은 아주 멀리 있어서 여러 날 관측해도 위치가 거의 변하지 않지만, 행성은 태양 둘레를 돌기 때문에 여러 날 관측하면 별들 사이에서 위치가 조금씩 바뀌어요."], "figure": "며칠 동안 별자리 사이에서 위치가 바뀐 행성을 점선으로 표시한 그림", "example": "새벽 동쪽 하늘에 아주 밝게 보이는 '샛별'은 별이 아니라 행성인 금성이에요.", "heading": "별과 행성은 달라요"}, {"paras": ["옛날 사람들은 밝은 별들을 이어 동물이나 물건 모양을 떠올려 '별자리'라고 이름 붙였어요. 북쪽 하늘에는 큰곰자리(북두칠성이 있는 별자리), 카시오페이아자리, 작은곰자리가 있어요.", "북극성은 항상 북쪽 하늘에 있어서 방위를 찾는 데 도움이 돼요. 북두칠성 국자 끝의 두 별을 이은 거리의 약 5배만큼 떨어진 곳에 북극성이 있어요. 카시오페이아자리를 이용해서도 찾을 수 있어요."], "figure": "북두칠성 국자 끝 두 별에서 5배 거리에 북극성을 찾는 방법을 나타낸 별자리 그림", "example": "북극성을 바라보면 내가 바라보는 쪽이 북쪽, 등 뒤가 남쪽이에요.", "heading": "북쪽 하늘의 별자리와 북극성"}], "parent_tip": "부모님께: 아이들은 '밤하늘에서 반짝이는 것은 모두 별'이라고 생각하거나 달도 별이라고 말하곤 합니다. 맑은 밤에 함께 북쪽 하늘을 보며 북두칠성을 찾고 북극성까지 따라가 보세요. '샛별은 왜 별이 아닐까?'라는 질문도 좋은 대화 소재입니다.", "expressions": []}$j$::jsonb where slug='s5-04';
update public.lessons set content=$j${"quiz": [{"q": "연소의 조건이 __아닌__ 것은?", "answer": 3, "choices": ["탈 물질", "산소", "발화점 이상의 온도", "이산화 탄소"], "explain": "연소에는 탈 물질, 산소, 발화점 이상의 온도가 필요해요."}, {"q": "초가 탄 뒤 석회수가 뿌옇게 흐려졌다면 어떤 물질이 생긴 것일까요?", "answer": 2, "choices": ["물", "산소", "이산화 탄소", "질소"], "explain": "석회수는 이산화 탄소를 만나면 뿌옇게 흐려져요."}, {"q": "알코올램프 뚜껑을 덮어 불을 끄는 것은 어떤 조건을 없앤 것일까요?", "answer": 1, "choices": ["탈 물질", "산소", "발화점 이상의 온도", "빛"], "explain": "뚜껑을 덮으면 산소가 공급되지 않아 불이 꺼져요."}, {"q": "불이 났을 때 올바른 행동은?", "answer": 1, "choices": ["승강기를 타고 빨리 내려간다", "젖은 수건으로 코와 입을 막고 몸을 낮춰 대피한다", "기름에 붙은 불에 물을 붓는다", "숨어서 기다린다"], "explain": "연기를 마시지 않도록 코와 입을 막고 몸을 낮춰 계단으로 대피해요."}, {"q": "크기가 다른 통으로 같은 촛불을 덮었을 때 더 오래 타는 경우는?", "answer": 1, "choices": ["작은 통", "큰 통", "둘이 같다", "통을 덮으면 바로 꺼진다"], "explain": "큰 통 안에 산소가 더 많아서 촛불이 더 오래 타요."}], "intro": "캠핑장의 모닥불, 생일 케이크의 촛불! 물질이 탈 때는 무엇이 필요하고, 불을 끄려면 어떻게 해야 할까요?", "summary": ["연소는 물질이 산소와 빠르게 반응해 빛과 열을 내는 현상이에요.", "연소에는 탈 물질, 산소, 발화점 이상의 온도가 모두 필요하고, 타면 물과 이산화 탄소가 생겨요.", "세 조건 중 하나 이상을 없애면 불이 꺼지고(소화), 불이 나면 119 신고 후 몸을 낮춰 대피해요."], "keywords": [{"word": "연소", "meaning": "물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상"}, {"word": "발화점", "meaning": "물질이 불에 직접 닿지 않아도 스스로 타기 시작하는 온도"}, {"word": "소화", "meaning": "불을 끄는 것"}, {"word": "석회수", "meaning": "이산화 탄소를 만나면 뿌옇게 흐려지는 용액"}, {"word": "염화 코발트 종이", "meaning": "물에 닿으면 푸른색에서 붉은색으로 변하는 종이"}], "sections": [{"paras": ["물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상을 '연소'라고 해요.", "초나 알코올이 탈 때는 빛과 열이 나서 주변이 밝고 따뜻해지고, 시간이 지나면 탈 물질의 양이 줄어들어요."], "figure": "타고 있는 촛불과 알코올램프의 불꽃 모습", "example": "", "heading": "물질이 탈 때 나타나는 현상"}, {"paras": ["물질이 타려면 세 가지가 모두 있어야 해요. 바로 '탈 물질', '산소', 그리고 '발화점 이상의 온도'예요.", "발화점은 물질이 불에 직접 닿지 않아도 스스로 타기 시작하는 가장 낮은 온도예요. 물질마다 발화점이 달라서 같은 온도로 가열해도 먼저 불이 붙는 물질이 있어요."], "figure": "탈 물질, 산소, 발화점 이상의 온도를 세 꼭짓점으로 한 삼각형 그림", "example": "크기가 다른 아크릴 통으로 촛불을 덮으면 큰 통 안의 촛불이 더 오래 타요. 산소가 더 많기 때문이에요. (불을 쓰는 실험은 반드시 어른과 함께하고, 주변에 탈 물건을 치운 뒤 해요.)", "heading": "연소의 세 가지 조건"}, {"paras": ["초가 타면 물과 이산화 탄소가 생겨요. 푸른색 염화 코발트 종이가 붉게 변하면 물이 생긴 것이에요.", "초가 탄 뒤 집기병에 석회수를 넣고 흔들면 뿌옇게 흐려지는데, 이것으로 이산화 탄소가 생겼음을 알 수 있어요."], "figure": "촛불을 덮은 집기병 안쪽 벽의 푸른색 염화 코발트 종이가 붉게 변한 모습과 뿌옇게 흐려진 석회수", "example": "", "heading": "연소 후 생기는 물질"}, {"paras": ["불을 끄는 것을 '소화'라고 해요. 연소의 세 가지 조건 중 한 가지 이상을 없애면 불이 꺼져요.", "탈 물질을 없애고(촛불 심지 자르기, 가스 밸브 잠그기), 산소를 막고(모래나 담요 덮기, 소화기 사용), 온도를 발화점 아래로 낮추면(물 뿌리기) 불이 꺼져요."], "figure": "심지 자르기, 뚜껑 덮기, 물 뿌리기로 불을 끄는 세 가지 장면", "example": "알코올램프는 뚜껑을 덮어 산소를 막아서 불을 꺼요.", "heading": "불을 끄는 방법 – 소화"}, {"paras": ["기름이나 전기 때문에 난 불에 물을 뿌리면 불이 더 커지거나 감전될 수 있어서 소화기나 모래를 써야 해요.", "불이 나면 '불이야!' 하고 크게 외치고 119에 신고해요. 젖은 수건으로 코와 입을 막고 몸을 낮춰 계단으로 대피해요. 승강기(엘리베이터)는 타지 않아요."], "figure": "젖은 수건으로 입을 막고 몸을 낮춰 비상구로 대피하는 어린이 그림", "example": "", "heading": "화재 안전"}], "parent_tip": "부모님께: 아이들은 '불은 물로만 끈다'고 생각하기 쉽습니다. 식용유에 붙은 불에 물을 부으면 위험하다는 점을 꼭 알려 주세요. 집의 소화기 위치를 함께 확인하고, '우리 집에서 불이 나면 어디로 대피할까?'를 이야기하며 대피 경로를 정해 보시길 권합니다. 촛불·알코올램프·가열 실험은 반드시 보호자가 함께하며, 주변에 불에 타는 물건이 없는지 확인해 주세요.", "expressions": []}$j$::jsonb where slug='s5-08';
update public.activities set content=$j$[{"note": "살 것 없음 · 우유팩을 모아 두세요", "rows": [{"how": "깨끗이 씻어 말려요. 2개를 엇갈려 끼우면 정육면체 블록 1개가 돼요.", "kit": false, "name": "1L 우유팩 10개"}, {"how": "A~Z 26장 (A4 2장)", "kit": false, "name": "알파벳 카드 도안"}, {"how": "투명 테이프로 덮으면 오래 써요", "kit": false, "name": "풀, 가위, 테이프"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "우유팩 아랫부분을 높이 7cm 정도로 잘라 상자 2개를 만들고, 서로 입구를 맞대어 끼우면 정육면체 블록이 돼요.", "warn": "", "image": "assets/img/s_alphabet-blocks_1.jpg", "title": "블록 만들기"}, {"body": "알파벳 카드를 오려 블록 면에 하나씩 붙여요. 블록 5개면 26글자를 모두 붙일 수 있어요.", "warn": "", "image": "assets/img/s_alphabet-blocks_2.jpg", "title": "카드 붙이기"}, {"body": "블록을 굴려 위에 나온 글자를 읽고, 그 글자로 시작하는 낱말을 말해요. \"B! B is for ball!\"", "warn": "", "image": "assets/img/s_alphabet-blocks_3.jpg", "title": "굴려서 말하기"}, {"body": "블록을 돌려 가며 dog, cup, hat 같은 짧은 낱말을 만들어 쌓아요. 내 이름처럼 같은 블록에 있는 글자가 두 번 필요하면 카드를 한 벌 더 인쇄해 블록을 늘려요.", "warn": "", "image": "assets/img/s_alphabet-blocks_4.jpg", "title": "이름 쌓기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻과 쓰는 때"], "note": "", "rows": [["What letter is it?", "무슨 글자야? (블록을 굴린 뒤 물어요)"], ["It's B.", "B야."], ["B is for ball.", "B는 ball(공)의 B야. (글자와 낱말을 이어 말해요)"], ["Big B, little b.", "대문자 B, 소문자 b."]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/alphabet-cards.pdf", "desc": "대문자와 소문자, 그 글자로 시작하는 쉬운 낱말이 함께 있는 카드 26장. A4 2장.", "type": "template", "title": "알파벳 카드 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["3~4학년 영어는 알파벳을 보고 이름을 말하며, 대문자와 소문자를 짝짓는 데서 시작합니다. 글자 이름(비, 씨)과 낱말 속 소리(ㅂ, ㅋ)가 다르다는 것을 놀이 속에서 자연스럽게 느끼게 해 주세요. 발음이 걱정되면 사전 앱의 듣기 버튼을 아이와 함께 눌러 보세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Good job! · Great! · You did it!", "잘했어! · 멋져! · 해냈구나! 틀려도 \"Nice try!(좋은 시도야!)\"라고 말해 주세요."]}], "title": ""}, {"type": "more", "items": [{"body": "카드를 A부터 Z까지 줄 세우며 노래를 불러요.", "title": "알파벳 순서 기차"}, {"body": "B 카드를 들고 b로 시작하는 물건(book, bag)을 찾아요.", "title": "집 안 보물찾기"}, {"body": "대문자와 소문자를 따로 오려 뒤집어 놓고 짝을 찾아요.", "title": "짝 맞추기"}]}, {"type": "info", "items": [{"label": "도안", "value": "알파벳 카드 26장 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 알파벳 대소문자, 쉬운 낱말 읽기"}]}]$j$::jsonb, updated_at=now() where slug='alphabet-blocks';
update public.activities set content=$j$[{"note": "풍선 2개만 있으면 돼요", "rows": [{"how": "300~500mL 투명 생수병", "kit": false, "name": "작은 페트병 1개"}, {"how": "작은 것 1개, 보통 것 1개", "kit": true, "name": "풍선 2개"}, {"how": "굵은 빨대가 좋아요", "kit": false, "name": "빨대 1개"}, {"how": "병 입구 빈틈을 막는 용도", "kit": false, "name": "찰흙이나 클레이"}, {"how": "고정하고 자르기용", "kit": false, "name": "고무줄 2개, 테이프, 가위"}], "type": "materials", "image": "assets/img/e6_mat.jpg"}, {"type": "steps", "items": [{"body": "페트병 바닥에서 3cm 위를 잘라 내요. 잘린 면이 날카로우면 테이프를 한 바퀴 둘러요.", "warn": "자르기는 어른이 해요.", "image": "assets/img/s_bottle-lung_1.jpg", "title": "병 바닥 잘라 내기"}, {"body": "작은 풍선 입구에 빨대를 넣고 고무줄로 단단히 감아 공기가 새지 않게 해요. 이 풍선이 '폐(허파)'예요.", "warn": "", "image": "assets/img/e6_s1.jpg", "title": "빨대에 풍선 달기 (폐)"}, {"body": "풍선이 병 안쪽으로 들어가도록 빨대를 병 입구에 꽂고, 빈틈을 찰흙으로 꼼꼼히 막아요. 틈이 있으면 실험이 잘 안 돼요.", "warn": "", "image": "assets/img/s_bottle-lung_3.jpg", "title": "병 입구 막기"}, {"body": "보통 풍선의 입구를 묶고 둥근 아랫부분을 잘라 내요. 남은 부분을 병의 잘린 바닥에 팽팽하게 씌우고 고무줄로 고정해요. 이것이 '가로막'이에요.", "warn": "", "image": "assets/img/s_bottle-lung_4.jpg", "title": "가로막 만들기"}, {"body": "아래 풍선의 매듭을 잡고 살짝 당겨 보세요. 병 안의 풍선이 부풀어요. 손을 놓으면 다시 오그라들어요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_bottle-lung_5.jpg", "title": "숨쉬기"}], "notes": [], "title": "만드는 방법"}, {"type": "questions", "items": ["아래 막을 당길 때와 밀어 올릴 때 안쪽 풍선은 어떻게 되나요?", "입구의 찰흙에 틈을 내면 어떻게 될까요?", "내 배에 손을 얹고 크게 숨을 쉬어 보세요. 무엇이 움직이나요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["가슴 아래에는 '가로막'이라는 얇은 근육이 있어요. 가로막이 아래로 내려가면 가슴 속 공간이 넓어지고, 그 틈으로 바깥 공기가 폐 안으로 쑥 들어와요. 페트병의 아래 풍선이 가로막, 안쪽 풍선이 폐 역할을 해요."]}, {"label": "부모님께", "paras": ["숨을 들이쉴 때는 가로막이 내려가고 갈비뼈가 올라가 가슴 속 공간이 커집니다. 공간이 커지면 안쪽 압력이 낮아져 바깥 공기가 기관을 따라 폐로 들어옵니다. 이 모형은 가로막의 움직임만 보여 주므로, 실제로는 갈비뼈 사이 근육도 함께 움직인다는 점을 덧붙여 주세요.", "이렇게 물어보세요: \"빨대는 우리 몸의 어디에 해당할까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "빨대 두 개를 Y자로 이어 풍선 2개를 달아요.", "title": "폐 두 개 만들기"}, {"body": "1분 동안 숨을 몇 번 쉬는지 세고, 제자리 뛰기 후와 비교해요.", "title": "숨 세기"}, {"body": "안쪽 풍선이 크면 어떻게 달라질까요?", "title": "풍선 크기 바꾸기"}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "풍선 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 우리 몸의 구조와 기능 (호흡 기관)"}]}]$j$::jsonb, updated_at=now() where slug='bottle-lung';
update public.activities set content=$j$[{"note": "공원·화단에서 재료를 조금씩 모아요", "rows": [{"how": "가운데를 잘라 아래는 그릇, 위는 뚜껑으로 써요", "kit": false, "name": "2L 투명 페트병"}, {"how": "맨 아래 물 빠짐 층", "kit": false, "name": "작은 자갈"}, {"how": "화분 흙", "kit": false, "name": "흙"}, {"how": "화단·공원에서 조금만 (허락받은 곳에서)", "kit": false, "name": "이끼와 작은 풀"}, {"how": "처음 한 번만 물을 뿌려요", "kit": false, "name": "분무기"}, {"how": "위아래 병을 이어 붙여요", "kit": false, "name": "투명 테이프"}, {"how": "공벌레를 넣을 때 먹이로 낙엽도 함께 넣어요", "kit": false, "name": "(선택) 공벌레 1~2마리, 마른 낙엽"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 일지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "페트병 가운데를 잘라 위아래로 나눠요.", "warn": "자르기는 어른이 해요.", "image": "assets/img/s_bottle-terrarium_1.jpg", "title": "병 자르기"}, {"body": "아래 병에 자갈 2cm, 흙 5cm를 차례로 넣어요.", "warn": "", "image": "assets/img/s_bottle-terrarium_2.jpg", "title": "층 쌓기"}, {"body": "이끼를 깔고 작은 풀을 심어요. 공벌레 한두 마리를 넣고 싶다면 먹이가 되는 마른 낙엽 몇 장도 함께 넣어 주세요.", "warn": "", "image": "assets/img/s_bottle-terrarium_3.jpg", "title": "식물 심기"}, {"body": "분무기로 흙이 촉촉해질 만큼만 물을 뿌리고, 위쪽 병을 덮어 테이프로 붙여요. 뚜껑도 닫아요.", "warn": "", "image": "assets/img/s_bottle-terrarium_4.jpg", "title": "물 주고 닫기"}, {"body": "햇빛이 직접 들지 않는 밝은 창가에 두고 일주일에 두 번 관찰 일지를 써요. 병 안쪽 물방울과 식물 상태를 봐요.", "warn": "", "image": "assets/img/s_bottle-terrarium_5.jpg", "title": "관찰하기"}], "notes": ["4주 관찰이 끝나면 넣었던 공벌레는 데려온 곳에 놓아 주세요."], "title": "실험 방법"}, {"type": "questions", "items": ["물을 다시 주지 않았는데 병 안이 촉촉한 까닭은 무엇일까요?", "아침과 저녁에 병 안쪽 물방울 양이 다른가요?", "식물이 시들었다면 어떤 환경 요인이 맞지 않았을까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["생태계는 식물, 동물 같은 생물과 햇빛, 물, 흙, 공기 같은 환경이 서로 영향을 주고받는 곳이에요. 병 속에서 식물은 햇빛을 받아 양분을 만들고, 물은 증발했다가 병 벽에서 물방울이 되어 다시 흙으로 떨어지며 돌고 돌아요."]}, {"label": "부모님께", "paras": ["5~6학년 '생물과 환경'은 생태계 구성 요소, 먹이 관계, 비생물 요소(빛, 온도, 물)가 생물에 미치는 영향을 다룹니다. 닫힌 병 안에서 물이 순환하는 모습은 생태계를 눈으로 보는 좋은 예입니다.", "곰팡이가 피면 실패가 아니라 분해자가 등장한 것이라는 점도 함께 이야기해 주세요. 다만 심하면 뚜껑을 열어 환기합니다.", "이렇게 물어보세요: \"병 속 생태계에서 한 가지가 사라진다면 무엇이 가장 먼저 영향을 받을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/bottle-terrarium.pdf", "desc": "4주 관찰 칸(주 2회)과 생태계 구성 요소 정리표. A4 1장.", "type": "template", "title": "미니 생태계 관찰 일지"}, {"type": "more", "items": [{"body": "똑같이 만든 병 두 개를 밝은 곳과 어두운 곳에 두고 비교해요.", "title": "빛 비교"}, {"body": "우리 동네 공원의 생물로 먹이 그물을 그려요.", "title": "먹이 그물 그리기"}, {"body": "사과 조각을 지퍼백에 넣어 곰팡이가 생기는 과정을 봐요.", "title": "분해자 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 일지 (A4 1장)"}, {"label": "실험 키트", "value": "집과 공원 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 생물과 환경 (생태계)"}]}]$j$::jsonb, updated_at=now() where slug='bottle-terrarium';
update public.activities set content=$j$[{"note": "애벌레만 구하면 나머지는 집 재료", "rows": [{"how": "윗부분을 잘라 내 관찰통으로 써요", "kit": false, "name": "2L 투명 페트병"}, {"how": "입구를 덮어 공기는 통하고 애벌레는 못 나가게. 고무줄 1개로 묶고, 바닥에 깔 키친타월도 준비해요", "kit": false, "name": "양파망이나 거즈"}, {"how": "텃밭 배추·케일 잎 뒷면에서 찾거나 관찰 세트로 구해요", "kit": true, "name": "배추흰나비 애벌레"}, {"how": "애벌레 먹이. 농약이 묻지 않은 잎이어야 해요", "kit": false, "name": "싱싱한 배추·케일 잎"}, {"how": "번데기가 붙을 자리예요", "kit": false, "name": "나무젓가락 1개"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 일지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "페트병 윗부분을 잘라 내고, 바닥에 키친타월을 깔아요. 나무젓가락을 비스듬히 세워 넣어요.", "warn": "자르기는 어른이 해요.", "image": "assets/img/s_butterfly-life-cycle_1.jpg", "title": "관찰통 만들기"}, {"body": "애벌레가 붙은 잎째로 옮겨요. 손으로 직접 잡으면 애벌레가 다칠 수 있어요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_2.jpg", "title": "애벌레 옮기기"}, {"body": "양파망이나 거즈를 씌우고 고무줄로 묶어요. 햇빛이 바로 드는 곳은 피해요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_3.jpg", "title": "입구 덮기"}, {"body": "하루 한 번 시든 잎과 똥을 치우고 새 잎을 넣어요. 잎에 물방울이 많으면 닦아 줘요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_4.jpg", "title": "매일 먹이와 청소"}, {"body": "크기, 색, 움직임을 날짜별로 그리고 적어요. 번데기가 되면 건드리지 말고 기다려요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_5.jpg", "title": "관찰 일지 쓰기"}, {"body": "나비가 나와 날개가 마르면 밖에 나가 날려 보내 줘요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_6.jpg", "title": "나비 날려 보내기"}], "notes": ["애벌레를 구하기 어려우면 다른 곤충의 한살이 영상을 함께 보고, 관찰 일지는 그림 카드로 순서 맞히기를 해도 좋아요."], "title": "실험 방법"}, {"type": "questions", "items": ["애벌레는 허물을 몇 번 벗나요? 벗을 때마다 무엇이 달라지나요?", "번데기일 때는 먹지도 움직이지도 않는데, 안에서는 무슨 일이 생길까요?", "애벌레와 나비는 먹는 것이 어떻게 다를까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["배추흰나비는 알에서 깨어나 애벌레가 되고, 배추 잎을 먹으며 몇 번 허물을 벗고 자라요. 다 자라면 번데기가 되어 한동안 꼼짝하지 않다가, 어느 날 껍질을 뚫고 나비가 되어 나와요. 이렇게 알에서 어른이 되기까지의 과정을 한살이라고 해요."]}, {"label": "부모님께", "paras": ["배추흰나비처럼 알 → 애벌레 → 번데기 → 어른벌레를 거치는 것을 완전 탈바꿈이라고 하고, 번데기 단계가 없는 메뚜기·잠자리 같은 곤충은 불완전 탈바꿈을 합니다. 3학년 '동물의 한살이' 단원의 핵심 비교입니다.", "관찰이 끝나면 반드시 자연으로 돌려보내는 것까지가 활동이라는 점을 함께 이야기해 주세요.", "이렇게 물어보세요: \"사람의 한살이와 나비의 한살이는 무엇이 같고 무엇이 다를까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/butterfly-life-cycle.pdf", "desc": "날짜별 관찰 칸 8개와 한살이 순서 그림 카드. A4 1장.", "type": "template", "title": "한살이 관찰 일지"}, {"type": "more", "items": [{"body": "벗은 허물을 테이프로 일지에 붙여 크기를 비교해요.", "title": "허물 모으기"}, {"body": "개미, 매미, 잠자리의 한살이를 찾아 그림으로 그려요.", "title": "다른 곤충 비교"}, {"body": "관찰 일지 그림을 오려 순서 맞히기 놀이를 해요.", "title": "한살이 순서 카드"}]}, {"type": "info", "items": [{"label": "도안", "value": "한살이 관찰 일지 (A4 1장)"}, {"label": "실험 키트", "value": "배추흰나비 애벌레 관찰 세트 (준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 동물의 한살이 (완전 탈바꿈)"}]}]$j$::jsonb, updated_at=now() where slug='butterfly-life-cycle';
update public.activities set content=$j$[{"note": "살 것 없음 · 부엌에 있는 재료", "rows": [{"how": "잘게 찢어서 써요", "kit": false, "name": "적양배추 잎 2~3장"}, {"how": "전기포트 물 (어른이 부어요)", "kit": false, "name": "뜨거운 물"}, {"how": "양배추 물을 우리는 용도. 뜨거운 물에 견디는 그릇", "kit": false, "name": "내열 그릇 1개"}, {"how": "유리컵이나 투명 플라스틱 컵", "kit": false, "name": "투명 컵 6개"}, {"how": "주방용 체나 거름망", "kit": false, "name": "체"}, {"how": "식초, 레몬즙", "kit": false, "name": "산성 재료"}, {"how": "베이킹소다, 비눗물", "kit": false, "name": "염기성 재료"}, {"how": "아래에서 내려받아 인쇄해요", "kit": false, "name": "색 비교표 도안"}], "type": "materials", "image": "assets/img/e7_mat.jpg"}, {"type": "steps", "items": [{"body": "잘게 찢은 잎을 그릇에 담고 뜨거운 물을 부어 10분 기다려요. 진한 보라색 물이 나오면 체로 걸러요.", "warn": "뜨거운 물은 어른이 다뤄요.", "image": "assets/img/e7_s1.jpg", "title": "양배추 물 우리기"}, {"body": "식은 양배추 물을 투명 컵 여러 개에 3cm씩 나눠 담아요. 한 컵은 비교용으로 그대로 둬요.", "warn": "", "image": "assets/img/s_cabbage-indicator_2.jpg", "title": "컵에 나눠 담기"}, {"body": "식초와 레몬즙을 한 숟가락씩 서로 다른 컵에 넣어요. 색이 어떻게 변하나요?", "warn": "", "image": "assets/img/e7_s2.jpg", "title": "산성 재료 넣기"}, {"body": "베이킹소다를 물에 녹여 다른 컵에 넣고, 비눗물도 넣어 봐요.", "warn": "", "image": "assets/img/s_cabbage-indicator_4.jpg", "title": "염기성 재료 넣기"}, {"body": "색 비교표 옆에 컵을 줄 세우고, 산성인지 염기성인지 기록표에 적어요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_cabbage-indicator_5.jpg", "title": "색 비교표와 맞춰 보기"}], "notes": ["안전: 락스, 변기 세정제 같은 청소용 세제는 절대 섞지 마세요. 위험한 기체가 나올 수 있어요. 실험한 물은 마시지 말고 싱크대에 버려요."], "title": "만드는 방법"}, {"pdf": "assets/pdf/ph-color-chart.pdf", "desc": "색 안내표와 내 실험 기록표가 들어 있어요. A4 1장, 컬러로 인쇄하면 좋아요.", "type": "template", "title": "산·염기 색 비교표"}, {"type": "questions", "items": ["가장 진한 분홍색이 된 컵은 무엇을 넣은 컵인가요?", "식초 컵에 베이킹소다를 조금씩 넣으면 어떤 일이 생기나요?", "우유, 사이다, 치약 녹인 물은 어느 쪽일까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["적양배추 속에는 '색깔 탐정' 물질이 들어 있어요. 이 탐정은 신맛 나는 산성을 만나면 분홍색 옷으로, 미끈미끈한 염기성을 만나면 파란색이나 초록색 옷으로 갈아입어요. 그래서 색만 보고도 산성인지 염기성인지 알 수 있어요."]}, {"label": "부모님께", "paras": ["적양배추에는 안토시아닌이라는 색소가 있어, 용액의 산성과 염기성 정도(pH)에 따라 색이 달라집니다. 이렇게 색으로 산성과 염기성을 알려 주는 물질을 지시약이라고 합니다. 식초에 베이킹소다를 넣으면 거품이 나며 색이 보라색 쪽으로 돌아가는데, 산과 염기가 서로의 성질을 약하게 만드는 중화 반응입니다.", "이렇게 물어보세요: \"양배추 물로 리트머스 종이 같은 지시약 종이를 만들 수 있을까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "키친타월을 양배추 물에 적셔 말린 뒤 잘라서 써요.", "title": "양배추 종이 만들기"}, {"body": "분홍 컵에 베이킹소다 물을 한 방울씩 넣어 보라색으로 되돌려요.", "title": "색 되돌리기"}, {"body": "면봉에 베이킹소다 물을 묻혀 글씨를 쓰고 말린 뒤 양배추 물을 바르면 초록색 글씨가 나타나요.", "title": "비밀 편지"}]}, {"type": "info", "items": [{"label": "도면", "value": "산·염기 색 비교표 (A4 1장)"}, {"label": "실험 키트", "value": "부엌 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 산과 염기 (지시약, 중화)"}]}]$j$::jsonb, updated_at=now() where slug='cabbage-indicator';
update public.activities set content=$j$[{"note": "반드시 어른이 곁에서 함께해요", "rows": [{"how": "작고 낮은 초가 안전해요", "kit": false, "name": "티라이트 초 1개"}, {"how": "잼병, 음료병처럼 입구가 넓은 것", "kit": false, "name": "크기가 다른 유리병 3개"}, {"how": "초 아래 쟁반을 받치고, 만일을 위해 젖은 행주와 냄비 뚜껑을 곁에 둬요 (촛농 불에는 물을 붓지 않아요)", "kit": false, "name": "쟁반, 젖은 행주, 냄비 뚜껑"}, {"how": "불은 어른만 붙여요", "kit": false, "name": "라이터 (어른용)"}, {"how": "꺼질 때까지 시간을 재요", "kit": false, "name": "시계"}, {"how": "아래에서 내려받아요", "kit": false, "name": "기록표 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "탁자 위 물건을 치우고 쟁반에 초를 올려요. 머리카락은 묶고, 젖은 행주와 냄비 뚜껑을 곁에 둬요.", "warn": "불은 어른만 붙이고 다뤄요.", "image": "assets/img/s_candle-jar_1.jpg", "title": "안전 준비"}, {"body": "어른이 불을 붙이고 가장 작은 병을 덮으면, 아이는 꺼질 때까지 시간을 재요.", "warn": "", "image": "assets/img/s_candle-jar_2.jpg", "title": "작은 병부터"}, {"body": "병이 식은 뒤 어른이 초에 다시 불을 붙이고 중간 병, 큰 병으로 바꿔 같은 방법으로 시간을 재요. 병은 뜨거우니 바로 만지지 않아요.", "warn": "병이 뜨거워요. 식을 때까지 기다려요.", "image": "assets/img/s_candle-jar_3.jpg", "title": "큰 병으로 반복"}, {"body": "병 크기와 꺼진 시간을 기록표에 적고, 어떤 관계가 있는지 이야기해요.", "warn": "", "image": "assets/img/s_candle-jar_4.jpg", "title": "결과 정리"}, {"body": "촛불을 끄는 다른 방법(입김, 뚜껑 덮기, 심지 집기)을 떠올리고, 각각 무엇을 없앤 것인지 나눠 봐요.", "warn": "", "image": "assets/img/s_candle-jar_5.jpg", "title": "소화 방법 찾기"}], "notes": ["안전: 아이 혼자 불을 붙이거나 다루지 않게 해 주세요. 실험이 끝나면 어른이 초를 끄고, 촛농이 완전히 굳어 식을 때까지 만지지 않아요. 초 불이 번지면 물을 붓지 말고 어른이 젖은 행주나 냄비 뚜껑을 덮어 꺼요."], "title": "실험 방법"}, {"type": "questions", "items": ["큰 병을 덮었을 때 촛불이 더 오래 탄 까닭은 무엇일까요?", "병 안쪽 벽에 무엇이 생겼나요?", "소화기는 불을 끌 때 무엇을 없애는 걸까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["불이 타려면 탈 물질, 산소, 불이 붙을 만큼의 온도 세 가지가 모두 있어야 해요. 병을 덮으면 촛불이 병 속 산소를 쓰다가 산소가 모자라서 꺼져요. 큰 병에는 공기가 더 많아서 더 오래 타요."]}, {"label": "부모님께", "paras": ["6학년 '연소와 소화' 단원은 연소의 조건(탈 물질, 산소, 발화점 이상의 온도)과, 이 중 하나 이상을 없애는 소화의 원리를 다룹니다. 병 안쪽에 맺히는 뿌연 물방울은 초가 탈 때 생긴 물입니다.", "병을 물 위에 덮어 물이 올라오는 실험은 산소 소비만으로 설명하기 어려운 부분이 있어 이 활동에서는 다루지 않았습니다. 시간 비교에 집중해 주세요.", "이렇게 물어보세요: \"우리 집에서 불이 나면 어떻게 대피하고, 소화기는 어디에 있을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/candle-jar.pdf", "desc": "병 크기별 시간 기록표와 소화의 세 가지 방법 정리 칸. A4 1장.", "type": "template", "title": "촛불 실험 기록표"}, {"type": "more", "items": [{"body": "소화기 위치와 사용 순서(안전핀 뽑기 → 노즐 잡기 → 손잡이 누르기)를 확인해요.", "title": "우리 집 소화기 찾기"}, {"body": "우리 집 대피 경로를 그려 현관에 붙여요.", "title": "대피 지도"}, {"body": "병 대신 크기가 다른 두꺼운 유리컵을 써서도 시간을 비교해요. 종이컵이나 플라스틱 컵은 불이 붙거나 녹을 수 있으니 절대 쓰지 않아요.", "title": "유리컵으로 비교"}]}, {"type": "info", "items": [{"label": "도안", "value": "기록표 (A4 1장)"}, {"label": "실험 키트", "value": "티라이트 초 (생활용품점)"}, {"label": "교육과정 연결", "value": "5~6학년 연소와 소화"}]}]$j$::jsonb, updated_at=now() where slug='candle-jar';
update public.activities set content=$j$[{"note": "살 것 없음 · 빈 용기를 모아 두세요", "rows": [{"how": "겉에 들이가 적혀 있어 기준이 돼요", "kit": false, "name": "1L 우유팩, 200mL 우유팩"}, {"how": "라벨의 숫자를 확인해요", "kit": false, "name": "500mL 페트병, 2L 페트병"}, {"how": "작은 단위 그릇으로 써요", "kit": false, "name": "종이컵 여러 개"}, {"how": "무게 비교에 써요", "kit": false, "name": "주방 저울 (있으면)"}, {"how": "아래에서 내려받아요", "kit": false, "name": "들이 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "그릇들을 줄 세우고 어느 것에 물이 가장 많이 들어갈지 예상 순서를 기록지에 적어요.", "warn": "", "image": "assets/img/s_carton-capacity_1.jpg", "title": "들이 어림하기"}, {"body": "각 그릇에 물을 가득 채운 뒤 종이컵에 옮겨 부어 몇 컵이 나오는지 세요.", "warn": "", "image": "assets/img/s_carton-capacity_2.jpg", "title": "종이컵으로 세기"}, {"body": "200mL 우유팩으로 1L 우유팩을 채워 보세요. 5번이면 가득 차요. 그래서 1L = 1000mL예요.", "warn": "", "image": "assets/img/s_carton-capacity_3.jpg", "title": "기준 그릇으로 비교"}, {"body": "페트병 라벨의 mL 숫자를 보고, 우리가 센 컵 수와 맞는지 확인해요.", "warn": "", "image": "assets/img/s_carton-capacity_4.jpg", "title": "라벨과 맞춰 보기"}, {"body": "저울이 있으면 물을 채운 그릇의 무게를 재 봐요. 물 1L는 약 1kg이에요.", "warn": "저울이 없으면 두 손에 들고 어느 쪽이 무거운지 느껴 봐요.", "image": "assets/img/s_carton-capacity_5.jpg", "title": "무게도 비교하기"}], "notes": ["종이컵은 가득 채우면 약 180~190mL쯤 돼요. 컵마다 조금씩 달라서 '정확한 단위'가 왜 필요한지 이야기 나누기 좋아요."], "title": "하는 방법"}, {"type": "questions", "items": ["모양이 다른데 들이가 같은 그릇이 있었나요?", "키가 큰 그릇이 항상 더 많이 담길까요?", "종이컵으로 재면 왜 정확하지 않을까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["그릇에 담을 수 있는 양을 '들이'라고 해요. 들이는 L(리터)와 mL(밀리리터)로 나타내고, 1L는 1000mL예요. 1L 우유팩에는 200mL 우유팩 5개만큼 들어가요. 키가 크다고 많이 들어가는 건 아니에요. 그릇의 바닥 넓이(굵기)와 높이를 모두 봐야 해요."]}, {"label": "부모님께", "paras": ["3학년 '들이와 무게'는 임의 단위(컵)로 비교하다가 표준 단위(L, mL, kg, g)가 왜 필요한지 깨닫는 흐름입니다. 생활 속 용기 라벨을 함께 읽으면 단위 감각이 빠르게 생깁니다.", "무게 부분은 '고무줄 저울' 활동(물체의 무게)과 함께 하면 더 좋습니다.", "이렇게 물어보세요: \"1L 3병과 500mL 2병을 합치면 몇 L 몇 mL일까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/carton-capacity.pdf", "desc": "예상 순서, 컵 수 기록, 단위 바꾸기 연습 칸. A4 1장.", "type": "template", "title": "들이 비교 기록지"}, {"type": "more", "items": [{"body": "냉장고 속 음료, 우유, 간장병의 들이를 모두 찾아 표로 만들어요.", "title": "라벨 찾기 탐험"}, {"body": "책, 과일 등을 들어 보고 1kg쯤 되는 물건을 찾아 저울로 확인해요.", "title": "1kg 맞히기"}, {"body": "물체의 무게 단원의 고무줄 저울로 물 100mL, 200mL를 달아 봐요.", "title": "고무줄 저울과 함께"}]}, {"type": "info", "items": [{"label": "도안", "value": "들이 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 들이와 무게 (L, mL, kg, g)"}]}]$j$::jsonb, updated_at=now() where slug='carton-capacity';
update public.activities set content=$j$[{"note": "살 것 없음 · 종이컵과 신문지면 끝", "rows": [{"how": "다 쓴 종이컵이나 요구르트병", "kit": false, "name": "종이컵 10개"}, {"how": "신문지나 이면지를 뭉쳐 테이프로 감아요", "kit": false, "name": "신문지 공"}, {"how": "색깔 10장과 점수판 (A4 1장)", "kit": false, "name": "색깔 카드 도안"}, {"how": "카드를 컵에 붙여요", "kit": false, "name": "테이프, 가위"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "색깔 카드를 오려 종이컵에 하나씩 붙이고, 컵을 엎어서 볼링 핀처럼 바닥에 앞에서부터 1개, 2개, 3개, 4개 줄로 세워요.", "warn": "", "image": "assets/img/s_color-bowling_1.jpg", "title": "핀 만들기"}, {"body": "2~3m 떨어진 곳에서 신문지 공을 굴려요.", "warn": "", "image": "assets/img/s_color-bowling_2.jpg", "title": "공 굴리기"}, {"body": "쓰러진 컵을 하나씩 들며 색깔을 외쳐요. \"Red! Blue! Green!\"", "warn": "", "image": "assets/img/s_color-bowling_3.jpg", "title": "색깔 외치기"}, {"body": "\"How many cups?\" 하고 물으면 영어로 세어 대답해요. 점수판에 색깔과 개수를 적고, 여섯 판을 모아 이긴 사람을 정해요.", "warn": "", "image": "assets/img/s_color-bowling_4.jpg", "title": "개수 세고 기록하기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "수 낱말: one, two, three, four, five, six, seven, eight, nine, ten. 컵이 2개 이상이면 cups처럼 끝에 s를 붙여요.", "rows": [["What color is it?", "무슨 색이야?"], ["It's red.", "빨간색이야."], ["How many cups?", "컵이 몇 개야?"], ["Five cups! / Strike!", "다섯 개! / 스트라이크(모두 쓰러뜨림)!"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/color-bowling.pdf", "desc": "red부터 brown까지 색깔 카드 10장, 6판까지 기록하는 점수판, 외치는 문장. A4 1장.", "type": "template", "title": "색깔 카드와 점수판"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["몸을 움직이며 말하면 낱말이 훨씬 오래 기억에 남아요. 볼링처럼 신나는 놀이에서는 아이가 영어를 '공부'가 아니라 '게임 규칙'으로 받아들여 부담 없이 말하게 됩니다. 점수를 매길 때 영어 숫자를 꼭 함께 말해 주세요."]}, {"label": "이렇게 응원해 주세요", "paras": ["Go! Go! · Almost! · Awesome!", "힘내! · 아깝다! · 최고야!"]}], "title": ""}, {"type": "more", "items": [{"body": "\"Find something yellow!\" 하면 집 안에서 노란 물건을 찾아와요.", "title": "색깔 찾기 술래"}, {"body": "\"Red and yellow make orange!\" 물감으로 확인해요.", "title": "색 섞기 실험"}, {"body": "색마다 점수를 다르게 정해 합계를 영어로 말해요.", "title": "점수 덧셈"}]}, {"type": "info", "items": [{"label": "도안", "value": "색깔 카드 10장과 점수판 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 색깔 낱말, 1~10 수 세기"}]}]$j$::jsonb, updated_at=now() where slug='color-bowling';
update public.activities set title=$j$색깔 물 배추 줄기 관찰$j$, updated_at=now() where slug='colored-celery';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "없으면 상자 판을 동그랗게 오려요", "kit": false, "name": "종이접시 1개"}, {"how": "시계판, 바늘 2개, 일과 카드 8장 (A4 1장)", "kit": false, "name": "시계 도안"}, {"how": "바늘이 돌아가게 고정해요", "kit": false, "name": "할핀 1개"}, {"how": "바늘은 상자 판에 붙여 오리면 튼튼해요", "kit": false, "name": "풀, 가위"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "시계판을 오려 종이접시에 붙이고, 긴바늘과 짧은바늘을 가운데에 할핀으로 고정해요.", "warn": "", "image": "assets/img/s_daily-clock_1.jpg", "title": "시계 만들기"}, {"body": "카드 8장의 빈칸에 실제 내 시각을 적어요. 예: I get up at seven.", "warn": "", "image": "assets/img/s_daily-clock_2.jpg", "title": "일과 카드 채우기"}, {"body": "부모님이 카드 한 장을 뽑아 \"What time do you get up?\" 하고 물으면, 아이가 바늘을 돌려 시각을 맞추고 대답해요.", "warn": "", "image": "assets/img/s_daily-clock_3.jpg", "title": "묻고 바늘 돌리기"}, {"body": "카드 8장을 시간 순서로 늘어놓고, 아침부터 밤까지 내 하루를 영어로 이어서 말해요.", "warn": "", "image": "assets/img/s_daily-clock_4.jpg", "title": "순서대로 하루 말하기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "시각 읽기: 7:00 seven (o'clock), 7:30 seven thirty, 7:15 seven fifteen. 시와 분을 숫자 그대로 이어 읽어요. 단, 7:05처럼 분이 한 자리이면 seven oh five라고 읽어요.", "rows": [["What time do you get up?", "몇 시에 일어나니?"], ["I get up at seven.", "7시에 일어나요."], ["I go to school at eight thirty.", "8시 30분에 학교에 가요."], ["What time is it? / It's nine o'clock.", "몇 시야? / 9시 정각이야."]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/daily-clock.pdf", "desc": "1~12 숫자와 분 눈금이 있는 시계판, 긴바늘·짧은바늘, 빈칸 일과 카드 8장. A4 1장.", "type": "template", "title": "하루 시계 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["5~6학년 영어는 자신의 생활을 문장으로 말하고 쓰는 단계로 넘어갑니다. 실제 아이의 하루로 문장을 만들면 외운 문장이 아니라 '내 이야기'가 되어 훨씬 잘 기억해요. 아날로그 시계 읽기 복습도 함께 됩니다."]}, {"label": "가족 버전", "paras": ["아이가 부모님께 물어보게 해 보세요. \"What time do you go to work?\" 주어가 바뀌는 연습이 돼요."]}], "title": ""}, {"type": "more", "items": [{"body": "\"On Saturday, I get up at nine.\" 평일과 비교해요.", "title": "주말 일과"}, {"body": "한 사람이 바늘을 돌리면 다른 사람이 영어로 시각을 말해요.", "title": "시각 맞히기 게임"}, {"body": "카드를 벽에 붙여 방학 생활 계획표로 써요.", "title": "일과표 꾸미기"}]}, {"type": "info", "items": [{"label": "도안", "value": "시계판, 바늘, 일과 카드 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 하루 일과, 시각 묻고 답하기"}]}]$j$::jsonb, updated_at=now() where slug='daily-clock';
update public.activities set content=$j$[{"note": "살 것 없음 · 과자 상자 판지가 있으면 튼튼해요", "rows": [{"how": "앞뒤 인사 카드 4장 (A4 1장)", "kit": false, "name": "문고리 카드 도안"}, {"how": "카드를 붙여 두껍게 만들어요", "kit": false, "name": "과자 상자 판지"}, {"how": "", "kit": false, "name": "풀, 가위, 색연필"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안의 카드 4장(Good morning / Good night / Hello / See you)에 색칠해요.", "warn": "", "image": "assets/img/s_door-hanger-greetings_1.jpg", "title": "카드 꾸미기"}, {"body": "카드를 상자 판지에 붙이고 바깥선과 문고리 구멍을 오려요.", "warn": "구멍은 어른이 가위 끝으로 뚫어 주세요.", "image": "assets/img/s_door-hanger-greetings_2.jpg", "title": "판지에 붙여 자르기"}, {"body": "아침에는 Good morning 면, 밤에는 Good night 면이 보이도록 방문 손잡이에 걸어요.", "warn": "", "image": "assets/img/s_door-hanger-greetings_3.jpg", "title": "문에 걸기"}, {"body": "아침에 방에서 나오면 카드를 Good morning 면으로 뒤집고 가족에게 \"Good morning!\" 하고 인사해요. 듣는 사람도 똑같이 답해요.", "warn": "", "image": "assets/img/s_door-hanger-greetings_4.jpg", "title": "카드 보고 인사하기"}, {"body": "익숙해지면 How are you? I'm fine, thank you. 를 이어서 말해요.", "warn": "", "image": "assets/img/s_door-hanger-greetings_5.jpg", "title": "안부 묻기 더하기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻과 쓰는 때"], "note": "", "rows": [["Hello. / Hi.", "안녕. (언제든 쓰는 인사)"], ["Good morning.", "좋은 아침이야. (아침 인사)"], ["Good night.", "잘 자. (자기 전 인사)"], ["How are you?", "어떻게 지내? 잘 지내?"], ["I'm fine, thank you. And you?", "잘 지내, 고마워. 너는?"], ["Goodbye. / See you later.", "잘 가. / 나중에 봐."]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/door-hanger-greetings.pdf", "desc": "Good morning / Good night / Hello / See you 카드 4장 (문고리 2개의 앞뒷면). A4 1장.", "type": "template", "title": "문고리 인사 카드"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["3학년 영어는 인사 표현으로 시작합니다. 영어 인사는 시간대(Good morning, Good afternoon, Good evening)와 헤어질 때(Goodbye, See you)를 구분합니다. 카드에 없는 afternoon, evening 인사는 '시간대 맞히기' 놀이로 함께 익혀 주세요.", "How are you? 에 꼭 I'm fine만 하지 않아도 됩니다. I'm good. / I'm great! / Not bad. 도 함께 써 보세요.", "부모님이 먼저 카드를 뒤집으며 인사하면 아이가 훨씬 빨리 따라 합니다."]}], "title": ""}, {"type": "more", "items": [{"body": "가족이 원을 그리고 앉아 옆 사람에게 차례로 다른 인사를 건네요.", "title": "인사 릴레이"}, {"body": "시계 그림을 보여 주면 Good morning / Good afternoon / Good evening 중 맞는 인사를 말해요.", "title": "시간대 맞히기"}, {"body": "가족 인형 만들기 활동의 인형으로 인사 대화 연극을 해요.", "title": "인형과 인사하기"}]}, {"type": "info", "items": [{"label": "도안", "value": "문고리 카드 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 인사하기, 안부 묻고 답하기"}]}]$j$::jsonb, updated_at=now() where slug='door-hanger-greetings';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "포스터 틀과 단어 상자 (A4 2장)", "kit": false, "name": "포스터 도안"}, {"how": "그림과 글씨를 꾸며요", "kit": false, "name": "색연필, 사인펜"}, {"how": "병뚜껑, 과자 봉지 조각, 잡지 사진을 오려 붙여요", "kit": false, "name": "재활용 꾸미기 재료"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "우리 집에서 지구를 위해 하는 일, 하면 안 되는 일을 한국어로 먼저 이야기해요. 수학 '재활용품 막대그래프' 결과를 함께 보면 좋아요.", "warn": "", "image": "assets/img/s_earth-poster_1.jpg", "title": "이야기 나누기"}, {"body": "도안 2쪽 단어 상자에서 해야 할 일 3개, 하면 안 되는 일 2개를 골라요.", "warn": "", "image": "assets/img/s_earth-poster_2.jpg", "title": "단어 고르기"}, {"body": "포스터의 We should, We shouldn't 뒤에 고른 표현을 옮겨 써요. 소리 내어 읽으며 써요.", "warn": "", "image": "assets/img/s_earth-poster_3.jpg", "title": "문장 완성하기"}, {"body": "빈칸에 지구 그림을 그리고, 재활용 재료를 붙여 꾸며요.", "warn": "", "image": "assets/img/s_earth-poster_4.jpg", "title": "그리고 꾸미기"}, {"body": "현관에 붙이고 가족 앞에서 영어로 읽어요. 일주일 동안 포스터대로 실천했는지 확인해요.", "warn": "", "image": "assets/img/s_earth-poster_5.jpg", "title": "가족 앞에서 발표"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "shouldn't는 should not을 줄인 말이에요.", "rows": [["We should save water.", "우리는 물을 아껴야 해요."], ["We should recycle paper.", "우리는 종이를 재활용해야 해요."], ["We shouldn't waste food.", "우리는 음식을 낭비하면(남기면) 안 돼요."], ["Let's save the Earth together!", "함께 지구를 지켜요!"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/earth-poster.pdf", "desc": "SAVE THE EARTH! 포스터 틀과, 뜻이 함께 적힌 표현 10개가 들어 있는 단어 상자. A4 2장.", "type": "template", "title": "포스터 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["5~6학년에서는 의무나 충고를 나타내는 should를 배웁니다. DNA 키즈랩의 재활용 활동과 이어지는 주제라, 아이가 직접 겪은 일을 영어로 표현하게 돼요. 포스터처럼 '누군가에게 보여 줄 결과물'이 있으면 쓰기 동기가 크게 올라갑니다."]}, {"label": "자랑하기", "paras": ["완성한 포스터 사진을 찍어 두세요. 나중에 '우리 집 실험 자랑' 게시판에 올릴 수 있어요."]}], "title": ""}, {"type": "more", "items": [{"body": "\"We should be quiet in the library.\" 같은 규칙을 만들어요.", "title": "교실 규칙 포스터"}, {"body": "포스터 문장 옆에 일주일 동안 지킨 날을 표시해요.", "title": "실천 체크표"}, {"body": "\"I'm tired.\" \"You should go to bed early.\"", "title": "충고 놀이"}]}, {"type": "info", "items": [{"label": "도안", "value": "포스터 틀과 단어 상자 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 해야 할 일 말하고 쓰기 (should)"}]}]$j$::jsonb, updated_at=now() where slug='earth-poster';
update public.activities set content=$j$[{"note": "살 것 없음 · 병뚜껑을 모아 두세요", "rows": [{"how": "30구 달걀판 2개를 나란히 붙이면 6×6까지 놓을 수 있어요", "kit": false, "name": "종이 달걀판 2개"}, {"how": "페트병 뚜껑. 단추나 콩으로 바꿔도 돼요.", "kit": false, "name": "병뚜껑 36개"}, {"how": "보드게임 주사위. 없으면 1~6 숫자 카드를 만들어요.", "kit": false, "name": "주사위 2개"}, {"how": "아래에서 내려받아 인쇄해요", "kit": false, "name": "곱셈 기록판 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "주사위 두 개를 굴려 나온 수를 기록판에 적어요. 예를 들어 3과 4가 나왔어요.", "warn": "", "image": "assets/img/s_egg-tray-arrays_1.jpg", "title": "주사위 굴리기"}, {"body": "첫째 수만큼 줄을 만들고, 한 줄에 둘째 수만큼 병뚜껑을 놓아요. 4개씩 3줄을 놓으면 돼요.", "warn": "", "image": "assets/img/s_egg-tray-arrays_2.jpg", "title": "배열 만들기"}, {"body": "하나씩 세지 말고 한 줄씩 \"4, 8, 12\" 하고 뛰어 세요. 4씩 3줄이니까 곱셈식으로 4 × 3 = 12예요.", "warn": "", "image": "assets/img/s_egg-tray-arrays_3.jpg", "title": "뛰어 세기"}, {"body": "달걀판을 옆으로 돌리면 3개씩 4줄이 돼요. 3 × 4도 12인지 세어 봐요.", "warn": "", "image": "assets/img/s_egg-tray-arrays_4.jpg", "title": "달걀판 돌려 보기"}, {"body": "기록판 칸에 배열만큼 색칠하고, 곱셈식(4 × 3 = 12)과 덧셈식(4 + 4 + 4 = 12)을 함께 써요. 여섯 번 반복해요.", "warn": "", "image": "assets/img/s_egg-tray-arrays_5.jpg", "title": "기록판에 색칠하기"}], "notes": [], "title": "하는 방법"}, {"pdf": "assets/pdf/array-record.pdf", "desc": "주사위 수, 6×6 색칠 칸, 곱셈식과 덧셈식을 적는 칸이 여섯 번 들어 있어요. A4 1장.", "type": "template", "title": "곱셈 배열 기록판"}, {"type": "questions", "items": ["4 × 3과 3 × 4는 왜 답이 같을까요?", "병뚜껑 12개로 만들 수 있는 직사각형 배열은 몇 가지일까요?", "병뚜껑 7개로는 직사각형을 몇 가지 만들 수 있나요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["곱셈은 같은 수를 여러 번 더하는 것을 빠르게 하는 방법이에요. 3줄에 4개씩이면 4씩 3묶음, 곧 4 + 4 + 4이고, 줄여서 4 × 3이라고 써요. 달걀판을 돌려도 병뚜껑 수는 그대로라서 3 × 4도 12예요."]}, {"label": "부모님께", "paras": ["가로세로로 줄 맞춘 배열은 곱셈을 '같은 묶음의 반복'으로 이해하게 하는 좋은 모델이며, 이후 두 자리 수 곱셈과 5학년 넓이 개념으로 이어집니다. 달걀판을 돌려 보는 활동은 곱하는 순서를 바꿔도 결과가 같다는 성질을 눈으로 보여 줍니다. 구구단을 외우기 전에 '왜 그런지'를 손으로 경험하게 하는 것이 목표입니다.", "이렇게 물어보세요: \"하나씩 세는 것보다 빨리 세는 방법이 있을까?\""]}], "title": "개념 정리"}, {"type": "more", "items": [{"body": "병뚜껑 24개로 만들 수 있는 배열을 모두 찾아요.", "title": "24 만들기"}, {"body": "주사위 곱을 빙고판에서 지워 가며 한 줄을 먼저 완성해요.", "title": "곱셈 빙고"}, {"body": "초콜릿, 아파트 창문, 달력에서 곱셈 배열을 찾아요.", "title": "생활 속 배열 찾기"}]}, {"type": "info", "items": [{"label": "도안", "value": "곱셈 배열 기록판 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "2학년 곱셈 (곱셈의 뜻, 곱셈구구, 곱하는 순서) · 3학년 곱셈 복습"}]}]$j$::jsonb, updated_at=now() where slug='egg-tray-arrays';
update public.activities set content=$j$[{"note": "씨앗만 있으면 돼요", "rows": [{"how": "칸마다 흙을 담아 작은 화분으로 써요", "kit": false, "name": "종이 달걀판"}, {"how": "마트에서 파는 마른 강낭콩도 싹이 터요", "kit": true, "name": "강낭콩 6~8알"}, {"how": "화분 흙이나 마당 흙", "kit": false, "name": "흙"}, {"how": "물 주기용", "kit": false, "name": "분무기나 컵"}, {"how": "자란 키를 재요", "kit": false, "name": "자"}, {"how": "달걀판을 칸째로 잘라 옮겨 심어요", "kit": false, "name": "가위"}, {"how": "달걀판 아래에 받쳐 물이 새지 않게 해요", "kit": false, "name": "쟁반"}, {"how": "본잎이 나오면 옮겨 심어요", "kit": false, "name": "큰 화분 (또는 페트병 화분)"}, {"how": "아래에서 내려받아요", "kit": false, "name": "키 기록표 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "강낭콩을 하룻밤 물에 담가 불려요. 몇 알은 그대로 두고 비교해도 좋아요.", "warn": "", "image": "assets/img/s_egg-tray-beans_1.jpg", "title": "콩 불리기"}, {"body": "달걀판 칸에 흙을 채우고 콩을 손가락 한 마디 깊이로 심어요. 칸마다 번호를 적어요.", "warn": "", "image": "assets/img/s_egg-tray-beans_2.jpg", "title": "심기"}, {"body": "흙이 마르지 않게 하루 한 번 물을 줘요. 달걀판 아래에 쟁반을 받쳐요.", "warn": "", "image": "assets/img/s_egg-tray-beans_3.jpg", "title": "물 주기"}, {"body": "뿌리, 떡잎, 본잎이 나오는 순서를 관찰하고 날짜를 적어요.", "warn": "", "image": "assets/img/s_egg-tray-beans_4.jpg", "title": "싹 관찰하기"}, {"body": "본잎이 나오면 달걀판 칸째로 잘라 큰 화분이나 페트병 화분에 옮겨 심어요. 종이가 흙 속에서 썩어 없어져요.", "warn": "", "image": "assets/img/s_egg-tray-beans_5.jpg", "title": "화분으로 옮기기"}], "notes": [], "title": "실험 방법"}, {"type": "questions", "items": ["뿌리와 줄기 중 무엇이 먼저 나오나요?", "떡잎은 자라면서 어떻게 변하나요?", "햇빛이 드는 칸과 그늘진 칸의 강낭콩은 어떻게 다르게 자라나요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["씨앗 속에는 아기 식물과 처음 먹을 양분이 들어 있어요. 물을 먹으면 씨앗이 부풀고 뿌리가 먼저 나와요. 떡잎은 씨앗 속 양분 주머니라서, 본잎이 자라면 점점 쪼그라들어요."]}, {"label": "부모님께", "paras": ["3~4학년 '식물의 한살이'는 씨앗이 싹 트고 자라 꽃이 피고 열매를 맺어 다시 씨앗이 되는 과정을 다룹니다. 강낭콩은 싹이 빨리 트고 떡잎이 커서 관찰하기 좋아 교과서에서도 많이 쓰입니다.", "키를 매일 재서 기록표에 점으로 찍으면 꺾은선그래프의 기초 연습도 됩니다.", "이렇게 물어보세요: \"씨앗 속에는 무엇이 들어 있기에 흙 속에서 혼자 싹을 틔울까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/egg-tray-beans.pdf", "desc": "4주 동안 키를 점으로 찍는 그래프와 관찰 칸. A4 1장.", "type": "template", "title": "강낭콩 키 기록표"}, {"type": "more", "items": [{"body": "젖은 키친타월과 콩을 투명 컵 벽에 붙여 뿌리를 옆에서 봐요.", "title": "투명 컵 뿌리 관찰"}, {"body": "콩을 뒤집어 심어도 뿌리가 아래로 자랄까요?", "title": "거꾸로 심기"}, {"body": "큰 화분에 옮겨 꽃과 꼬투리가 생길 때까지 길러요.", "title": "열매까지"}]}, {"type": "info", "items": [{"label": "도안", "value": "강낭콩 키 기록표 (A4 1장)"}, {"label": "실험 키트", "value": "강낭콩 씨앗 (마트·문구점)"}, {"label": "교육과정 연결", "value": "3~4학년 식물의 한살이"}]}]$j$::jsonb, updated_at=now() where slug='egg-tray-beans';
update public.activities set content=$j$[{"note": "살 것 없음 · 휴지심을 모아 두세요", "rows": [{"how": "다 쓴 두루마리 휴지 심", "kit": false, "name": "휴지심 (가족 수만큼)"}, {"how": "얼굴 동그라미, 가족 낱말 카드, 소개 문장 (A4 1장)", "kit": false, "name": "가족 인형 도안"}, {"how": "머리카락과 옷을 꾸며요", "kit": false, "name": "색연필, 털실, 자투리 천"}, {"how": "얼굴과 이름표를 붙여요", "kit": false, "name": "풀, 가위"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안의 동그라미에 가족 얼굴을 그리고 오려요. 아빠의 안경, 동생의 머리핀처럼 특징을 살려요.", "warn": "", "image": "assets/img/s_family-puppets_1.jpg", "title": "얼굴 그리기"}, {"body": "얼굴을 휴지심 위쪽에 붙이고, 휴지심 몸통에 천이나 색종이로 옷을 입혀요.", "warn": "", "image": "assets/img/s_family-puppets_2.jpg", "title": "휴지심에 붙이기"}, {"body": "가족 낱말 카드를 오려 인형 앞에 붙여요. father, mother처럼 영어 낱말을 소리 내어 읽으며 붙여요.", "warn": "", "image": "assets/img/s_family-puppets_3.jpg", "title": "이름표 달기"}, {"body": "인형을 하나씩 들어 보이며 \"This is my father.\" 하고 소개해요. 가족이 실제로 앞에 있으면 더 신나요.", "warn": "", "image": "assets/img/s_family-puppets_4.jpg", "title": "가족 인형극"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "남자 가족은 he, 여자 가족은 she로 바꿔 말해요. 꾸미는 말: funny(재미있는), smart(똑똑한), strong(힘센), pretty(예쁜)", "rows": [["Who is he? / Who is she?", "이 사람은 누구야? (남자 / 여자)"], ["This is my mother.", "우리 엄마예요."], ["She is kind. / He is tall.", "엄마는 친절해요. / 아빠는 키가 커요."], ["I love my family!", "나는 우리 가족을 사랑해요!"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/family-puppets.pdf", "desc": "얼굴 그리는 동그라미 8개, 가족 낱말 카드 8장(grandfather부터 me까지), 소개 문장. A4 1장.", "type": "template", "title": "가족 인형 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["사람을 소개하는 표현은 3~4학년 영어의 기본 표현입니다. 인형을 쓰면 아이가 직접 말하는 부담이 줄어들어, 수줍음 많은 아이도 쉽게 따라 해요. 영어에는 형, 오빠, 남동생이 모두 brother 한 낱말이라는 것도 재미있게 알려 주세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Wonderful! · I like your puppet!", "멋지다! · 네 인형 마음에 들어!"]}], "title": ""}, {"type": "more", "items": [{"body": "이름표를 가리고 \"Who is she?\" 하고 맞혀요.", "title": "누구일까요 퀴즈"}, {"body": "\"This is my dog. His name is Choco.\"", "title": "반려동물 인형"}, {"body": "인형극을 휴대폰으로 찍어 할머니께 보내요.", "title": "영상 편지"}]}, {"type": "info", "items": [{"label": "도안", "value": "얼굴, 가족 카드, 소개 문장 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 사람 소개하기, 가족 낱말"}]}]$j$::jsonb, updated_at=now() where slug='family-puppets';
update public.activities set content=$j$[{"note": "자석 1개만 있으면 돼요", "rows": [{"how": "바느질 바늘. 클립을 곧게 펴서 3cm로 쓰면 더 안전해요.", "kit": false, "name": "바늘 1개"}, {"how": "막대자석이나 말굽자석. 냉장고 고무 자석은 힘이 약해서 잘 안 될 수 있어요.", "kit": true, "name": "자석 1개"}, {"how": "페트병 플라스틱 뚜껑", "kit": false, "name": "병뚜껑 1개"}, {"how": "국그릇이나 넓은 접시", "kit": false, "name": "넓은 그릇과 물"}, {"how": "바늘 고정용", "kit": false, "name": "셀로판테이프"}, {"how": "스마트폰 나침반 앱, 자석이 됐는지 확인할 클립 1개, 방향 표시용 작은 스티커", "kit": false, "name": "확인용"}], "type": "materials", "image": "assets/img/e2_mat.jpg"}, {"type": "steps", "items": [{"body": "자석의 한쪽 끝으로 바늘을 바늘귀에서 바늘 끝 방향으로 30번 문질러요. 꼭 한 방향으로만 문지르고, 한 번 문지른 뒤에는 자석을 들어 올려 처음 자리로 돌아가요.", "warn": "", "image": "assets/img/e2_s1.jpg", "title": "바늘을 자석으로 만들기"}, {"body": "바늘을 클립에 가까이 대 보세요. 클립이 살짝 끌려오면 성공이에요.", "warn": "", "image": "assets/img/s_floating-compass_2.jpg", "title": "자석이 됐는지 확인하기"}, {"body": "병뚜껑 안쪽에 바늘을 눕혀 셀로판테이프로 붙여요. 바늘이 뚜껑 한가운데를 지나가게 붙여야 균형이 잘 맞아요.", "warn": "", "image": "assets/img/e2_s2.jpg", "title": "병뚜껑에 붙이기"}, {"body": "그릇에 물을 담고 병뚜껑을 가운데에 살며시 띄워요. 뚜껑이 천천히 돌다가 한 방향에서 멈춰요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_floating-compass_4.jpg", "title": "물에 띄우기"}, {"body": "스마트폰 나침반 앱으로 북쪽을 확인해요. 바늘의 어느 끝이 북쪽을 가리키는지 작은 스티커로 표시하면 나만의 나침반 완성! 휴대폰은 그릇에서 30cm 이상 떨어진 곳에서 방향만 확인해요.", "warn": "", "image": "assets/img/s_floating-compass_5.jpg", "title": "방향 확인하고 표시하기"}], "notes": ["잘 안 될 때: 실험하는 동안 휴대폰, 스피커, 쇠숟가락은 그릇에서 멀리 두세요. 근처에 쇠붙이나 자석이 있으면 바늘이 그쪽으로 끌려가요."], "title": "만드는 방법"}, {"type": "questions", "items": ["뚜껑을 손가락으로 살짝 돌려 놓으면 어떻게 되나요?", "자석을 그릇 옆으로 천천히 가져가면 바늘이 어떻게 움직이나요?", "10번만 문지른 바늘과 30번 문지른 바늘은 무엇이 다른가요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["바늘을 자석으로 문지르면 바늘도 작은 자석이 돼요. 그런데 우리가 사는 지구도 아주아주 큰 자석이에요. 그래서 자석이 된 바늘은 언제나 북쪽과 남쪽을 가리켜요. 물 위에 띄우면 뚜껑이 마음대로 돌 수 있어서 바늘이 스스로 방향을 찾아가요."]}, {"label": "부모님께", "paras": ["쇠로 된 바늘을 자석으로 한 방향으로 문지르면 바늘이 자화되어 약한 자석이 됩니다. 지구는 거대한 자석이므로, 자유롭게 회전하는 자침은 지구 자기장을 따라 남북 방향으로 놓입니다. 물에 띄우면 마찰이 줄어 바늘이 쉽게 돌아갑니다. 어느 끝이 북쪽을 향할지는 문지른 자석의 극에 따라 달라지니 앱으로 확인해 표시하세요. 떨어뜨리거나 시간이 지나 자성이 약해지면 다시 문지르면 됩니다.", "이렇게 물어보세요: \"진짜 나침반 바늘은 왜 한쪽만 빨간색일까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "이면지에 동서남북을 그려 그릇 아래에 깔아요.", "title": "동서남북 판 만들기"}, {"body": "냉장고 옆에서는 바늘이 어떻게 될까요?", "title": "집 안 탐험"}, {"body": "베란다 창문이 어느 방향을 보는지 찾아봐요.", "title": "우리 집은 어느 쪽?"}]}, {"text": "안전: 작은 자석, 특히 동그란 강력 자석은 어린 동생이 삼키지 않도록 꼭 높은 곳에 보관해 주세요. 바늘은 실험 후 바늘꽂이에 바로 정리해요.", "type": "note"}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "막대자석 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 자석의 성질 (나침반 만들기)"}]}]$j$::jsonb, updated_at=now() where slug='floating-compass';
update public.activities set content=$j$[{"note": "살 것 없음 · 마트 전단지나 영수증", "rows": [{"how": "무게(kg, g)가 적힌 상품이 있으면 좋아요", "kit": false, "name": "마트 전단지 또는 영수증"}, {"how": "예시 상품과 계산 칸 (A4 1장)", "kit": false, "name": "장보기 계산지 도안"}, {"how": "먼저 손으로 풀고 확인할 때만 써요", "kit": false, "name": "계산기 (확인용)"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "계산지의 예시 상품(사과 1kg 4,000원, 돼지고기 100g 2,500원 등)이나 전단지에서 무게 단위 상품을 골라요.", "warn": "", "image": "assets/img/s_flyer-decimal-shopping_1.jpg", "title": "상품 고르기"}, {"body": "사과 1.5kg이면 1kg보다 많고 2kg보다 적으니 4,000원과 8,000원 사이겠죠? 먼저 어림값을 적어요.", "warn": "", "image": "assets/img/s_flyer-decimal-shopping_2.jpg", "title": "어림하기"}, {"body": "4,000 × 1.5 = 6,000원. 자연수처럼 곱한 뒤 소수점 아래 자릿수만큼 소수점을 옮겨요.", "warn": "", "image": "assets/img/s_flyer-decimal-shopping_3.jpg", "title": "소수 곱셈하기"}, {"body": "사과 0.8kg은 4,000 × 0.8 = 3,200원. 1보다 작은 수를 곱하니 4,000원보다 작아졌어요.", "warn": "", "image": "assets/img/s_flyer-decimal-shopping_4.jpg", "title": "1보다 작은 수 곱하기"}, {"body": "고른 상품을 모두 더하고 20,000원을 냈을 때 거스름돈을 계산해요.", "warn": "", "image": "assets/img/s_flyer-decimal-shopping_5.jpg", "title": "총액과 거스름돈"}, {"body": "다음 장보기 때 영수증의 무게와 가격을 보고 계산이 맞는지 확인해요.", "warn": "", "image": "assets/img/s_flyer-decimal-shopping_6.jpg", "title": "실제 영수증과 비교"}], "notes": ["돼지고기처럼 100g당 가격이면 600g은 2,500 × 6 = 15,000원이에요. 1kg당 25,000원으로 바꿔 25,000 × 0.6으로 계산해도 같은 값이 나와요."], "title": "하는 방법"}, {"type": "questions", "items": ["어떤 수에 0.5를 곱하는 것은 어떤 계산과 같을까요?", "곱했는데 처음 수보다 작아지는 경우는 언제일까요?", "1.2 × 1.5에서 소수점은 어디에 찍어야 할까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["소수를 곱할 때는 먼저 소수점이 없다고 생각하고 자연수처럼 곱해요. 그다음 두 수의 소수점 아래 자릿수를 더한 만큼 오른쪽에서부터 세어 소수점을 찍어요. 그리고 1보다 작은 수를 곱하면 결과가 원래 수보다 작아진다는 것도 기억해요."]}, {"label": "부모님께", "paras": ["5학년 '소수의 곱셈'은 '곱하면 커진다'는 자연수의 직관이 깨지는 단원입니다. 0.8kg이 1kg보다 싸다는 생활 감각과 연결하면 아이들이 쉽게 받아들입니다.", "계산 전에 어림을 꼭 하게 하세요. 소수점 위치 실수를 스스로 잡아내는 가장 좋은 습관입니다.", "이렇게 물어보세요: \"4,000 × 0.8이 4,000보다 큰지 작은지 계산 전에 말해 볼래?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/flyer-decimal-shopping.pdf", "desc": "예시 상품 6개 가격표, 어림·계산·거스름돈 칸. A4 1장.", "type": "template", "title": "장보기 계산지"}, {"type": "more", "items": [{"body": "같은 상품의 대용량과 소용량 중 100g당 어느 쪽이 싼지 비교해요.", "title": "단위 가격 비교"}, {"body": "1L당 가격과 주유량(예: 35.5L)으로 주유비를 계산해요.", "title": "기름값 계산"}, {"body": "2인분 요리법을 1.5배로 늘려 재료 양을 계산해요.", "title": "레시피 늘리기"}]}, {"type": "info", "items": [{"label": "도안", "value": "장보기 계산지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 소수의 곱셈"}]}]$j$::jsonb, updated_at=now() where slug='flyer-decimal-shopping';
update public.activities set content=$j$[{"note": "살 것 없음 · 도안과 색연필", "rows": [{"how": "1, 1/2, 1/3, 1/4, 1/6, 1/8, 1/12 막대 (A4 1장)", "kit": false, "name": "분수 막대 도안"}, {"how": "막대마다 다른 색으로 칠해요", "kit": false, "name": "가위, 색연필"}, {"how": "조각을 보관해요", "kit": false, "name": "봉투나 지퍼백"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "막대마다 한 가지 색으로 칠한 뒤, 맨 위 '1' 막대만 그대로 두고 나머지는 칸마다 잘라 조각으로 만들어요.", "warn": "", "image": "assets/img/s_fraction-strips_1.jpg", "title": "색칠하고 자르기"}, {"body": "1/2 조각 1개와 길이가 같은 조각 묶음을 찾아요. 2/4, 3/6, 4/8, 6/12. 크기가 같은 분수예요.", "warn": "", "image": "assets/img/s_fraction-strips_2.jpg", "title": "같은 크기 찾기"}, {"body": "1 막대 아래에 1/2 조각과 1/3 조각을 이어 놓아요. 이 길이를 한 종류의 조각으로만 덮을 수 있을까요?", "warn": "", "image": "assets/img/s_fraction-strips_3.jpg", "title": "1/2 + 1/3 놓아 보기"}, {"body": "1/6 조각으로 덮으면 딱 5개가 맞아요. 1/2 = 3/6, 1/3 = 2/6이니까 1/2 + 1/3 = 5/6.", "warn": "", "image": "assets/img/s_fraction-strips_4.jpg", "title": "통분 찾기"}, {"body": "3/4 위에 1/3을 겹쳐 놓고 남은 길이를 1/12 조각으로 재요. 3/4 − 1/3 = 9/12 − 4/12 = 5/12.", "warn": "", "image": "assets/img/s_fraction-strips_5.jpg", "title": "뺄셈도 해 보기"}, {"body": "조각으로 찾은 답을 기록지에 식으로 써요. 공통분모가 두 분모의 공배수라는 것을 확인해요.", "warn": "", "image": "assets/img/s_fraction-strips_6.jpg", "title": "식으로 정리하기"}], "notes": ["1을 넘는 덧셈(예: 3/4 + 2/3)은 1 막대를 넘쳐서 대분수 1 5/12가 돼요."], "title": "하는 방법"}, {"type": "questions", "items": ["1/3과 1/4을 같은 조각으로 나타내려면 어떤 조각이 필요할까요?", "공통분모로 왜 두 분모의 공배수를 쓸까요?", "1/2 + 1/3이 2/5가 아닌 이유를 막대로 설명할 수 있나요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["분모가 다른 분수는 조각의 크기가 달라서 바로 더할 수 없어요. 그래서 두 분수를 같은 크기의 조각으로 바꿔 줘요. 이걸 통분이라고 해요. 1/2과 1/3은 둘 다 1/6 조각으로 바꿀 수 있어서 3/6 + 2/6 = 5/6이 돼요."]}, {"label": "부모님께", "paras": ["5학년 '분수의 덧셈과 뺄셈'에서 가장 흔한 오류가 '분자는 분자끼리, 분모는 분모끼리' 더하는 것입니다(1/2 + 1/3 = 2/5). 두 분수를 더하면 1/2보다 커야 하는데, 2/5는 1/2(=2.5/5)보다 작으니 답이 될 수 없다는 점을 1/2 막대와 견주어 짚어 주면 이 실수가 확 줄어듭니다.", "통분은 '약수와 배수'에서 배운 공배수와 바로 연결됩니다. 1~100 수표 활동을 먼저 하면 더 좋습니다.", "이렇게 물어보세요: \"1/2 + 1/3이 2/5라면 1/2보다 클까, 작을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/fraction-strips.pdf", "desc": "1, 1/2, 1/3, 1/4, 1/6, 1/8, 1/12 막대(길이 18cm)와 계산 기록 칸. A4 1장.", "type": "template", "title": "분수 막대"}, {"type": "more", "items": [{"body": "1/2, 2/3, 3/4, 5/6을 막대로 비교해 작은 순서로 놓아요.", "title": "분수 크기 줄 세우기"}, {"body": "요리법의 1/2컵, 1/3컵을 합치면 얼마인지 막대로 계산해요.", "title": "분수 레시피"}, {"body": "3~4학년 피자 분수 원판으로 같은 덧셈을 해 보고 막대와 비교해요.", "title": "분수 원판과 비교"}]}, {"type": "info", "items": [{"label": "도안", "value": "분수 막대 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 분수의 덧셈과 뺄셈 (통분)"}]}]$j$::jsonb, updated_at=now() where slug='fraction-strips';
update public.activities set title=$j$얼음 녹이기 경주와 병 물방울$j$, summary=$j$얼음을 가장 빨리 녹이는 방법을 겨루고, 차가운 병 겉에 맺히는 물방울의 정체를 찾아요.$j$, caution=array[$j$얼음을 오래 쥐지 않기$j$,$j$소금 만진 손으로 눈 비비지 않기$j$]::text[], content=$j$[{"note": "살 것 없음 · 부엌 재료", "rows": [{"how": "같은 얼음 틀에서 꺼내요", "kit": false, "name": "같은 크기 얼음 5개"}, {"how": "얼음을 하나씩 담아요", "kit": false, "name": "지퍼백 5개"}, {"how": "녹이는 방법마다 써요", "kit": false, "name": "소금, 수건, 그릇"}, {"how": "주스·보리차처럼 색이 있는 음료를 담아요. 하나는 냉장고에서 차갑게, 하나는 실온", "kit": false, "name": "색깔 음료를 담은 페트병 2개"}, {"how": "녹는 시간을 재요", "kit": false, "name": "시계"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "가족마다 얼음 녹이는 방법을 하나씩 골라요. 손으로 쥐기, 소금 뿌리기, 수건으로 싸기, 햇볕에 두기, 그대로 두기. 손으로 쥐는 사람은 손이 너무 차가우면 잠깐씩 내려놓아요.", "warn": "", "image": "assets/img/s_ice-and-dew_1.jpg", "title": "방법 정하기"}, {"body": "지퍼백에 얼음을 넣고 같은 시각에 시작해요. 다 녹은 시각을 기록지에 적어요.", "warn": "", "image": "assets/img/s_ice-and-dew_2.jpg", "title": "동시에 시작"}, {"body": "가장 빨리 녹은 방법과 가장 늦게 녹은 방법을 찾아요. 수건으로 싼 얼음은 왜 늦게 녹았을까요?", "warn": "", "image": "assets/img/s_ice-and-dew_3.jpg", "title": "결과 비교"}, {"body": "냉장고에서 꺼낸 페트병과 실온 페트병을 나란히 두고 5분 기다려요. 어느 쪽 겉에 물방울이 맺히나요?", "warn": "", "image": "assets/img/s_ice-and-dew_4.jpg", "title": "병 물방울 관찰"}, {"body": "맺힌 물방울을 흰 휴지로 닦아 음료 색이 묻어나는지 봐요. 병 안의 음료가 새어 나온 걸까요?", "warn": "", "image": "assets/img/s_ice-and-dew_5.jpg", "title": "물방울 닦아 보기"}], "notes": [], "title": "실험 방법"}, {"type": "questions", "items": ["얼음이 녹으면 무게는 어떻게 될까요? 부피는 어떻게 될까요?", "차가운 병 겉의 물방울은 어디에서 왔을까요?", "겨울 아침 유리창이 뿌옇게 되는 것도 같은 까닭일까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["물은 얼음(고체), 물(액체), 수증기(기체)로 모습을 바꿔요. 따뜻한 열을 받으면 얼음이 녹아 물이 되고, 물이 증발하면 눈에 보이지 않는 수증기가 돼요. 공기 속 수증기가 차가운 병에 닿으면 다시 물방울로 변해서 병 겉에 맺혀요."]}, {"label": "부모님께", "paras": ["얼음이 녹는 것은 융해, 물이 수증기가 되는 것은 증발, 수증기가 차가운 표면에서 물방울이 되는 것은 응결입니다. 병 겉 물방울이 '병에서 샌 물'이 아니라 공기 중 수증기라는 것을 아이 스스로 추론하게 하는 것이 이 활동의 핵심입니다.", "수건으로 싼 얼음이 늦게 녹는 것은 수건이 바깥 열이 들어오는 것을 막기 때문입니다. 아이스박스와 같은 원리예요.", "이렇게 물어보세요: \"아이스크림을 오래 안 녹게 가져가려면 무엇으로 싸면 좋을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/ice-and-dew.pdf", "desc": "얼음 녹이기 경주 기록표와 물방울 관찰 칸. A4 1장.", "type": "template", "title": "물의 상태 변화 기록지"}, {"type": "more", "items": [{"body": "녹기 전 얼음과 녹은 물의 무게를 저울로 비교해요.", "title": "얼음 무게 재기"}, {"body": "식용색소 얼음이 녹으며 물에 퍼지는 모습을 관찰해요.", "title": "색깔 얼음"}, {"body": "접시에 물을 담아 두고 하루마다 양을 표시해요.", "title": "물 증발 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 기록지 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 물의 상태 변화 (얼음이 녹음, 증발, 응결)"}]}]$j$::jsonb, updated_at=now() where slug='ice-and-dew';
update public.activities set summary=$j$원액과 물을 1:3, 1:4, 1:5로 섞어 맛을 비교하며 비, 비율, 백분율을 맛으로 알아봐요.$j$, updated_at=now() where slug='juice-ratio';
update public.activities set content=$j$[{"note": "살 것 없음 · 자석이나 테이프", "rows": [{"how": "음식 그림 낱말 8개와 가족 기록 칸 (A4 1장)", "kit": false, "name": "좋아요 설문판 도안"}, {"how": "", "kit": false, "name": "색연필, 연필"}, {"how": "설문판을 붙여요", "kit": false, "name": "냉장고 자석 또는 테이프"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "음식 낱말(pizza, carrot, milk, chicken, kimchi, ice cream, fish, banana) 옆 그림에 색칠해요.", "warn": "", "image": "assets/img/s_like-survey_1.jpg", "title": "설문판 꾸미기"}, {"body": "맨 위 칸에 Mom, Dad, 형제 이름, 그리고 Me를 써요.", "warn": "", "image": "assets/img/s_like-survey_2.jpg", "title": "가족 이름 쓰기"}, {"body": "아이가 가족에게 Do you like pizza? 하고 물어요. Yes, I do.면 O, No, I don't.면 X를 써요.", "warn": "", "image": "assets/img/s_like-survey_3.jpg", "title": "묻고 답하기"}, {"body": "다 모으면 Dad likes chicken. Mom doesn't like fish. 처럼 결과를 말해요. 어려우면 Dad, chicken, yes! 도 괜찮아요.", "warn": "", "image": "assets/img/s_like-survey_4.jpg", "title": "결과 말하기"}, {"body": "완성한 설문판을 냉장고에 붙이고, 저녁 메뉴 정할 때 참고해요.", "warn": "", "image": "assets/img/s_like-survey_5.jpg", "title": "냉장고에 붙이기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻과 쓰는 때"], "note": "", "rows": [["Do you like pizza?", "피자 좋아해?"], ["Yes, I do.", "응, 좋아해."], ["No, I don't.", "아니, 안 좋아해."], ["I like chicken.", "나는 치킨을 좋아해."], ["I don't like carrots.", "나는 당근을 안 좋아해."], ["What food do you like?", "무슨 음식 좋아해?"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/like-survey.pdf", "desc": "음식 8가지와 가족 5명 O·X 칸, 대화 표현 띠. A4 1장.", "type": "template", "title": "좋아요 설문판"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["3~4학년 '좋아하는 것 말하기'는 Do you like ~? / Yes, I do. / No, I don't. 대화가 핵심입니다. 영어에서 좋아하는 것을 일반적으로 말할 때는 carrots, bananas처럼 복수형을 쓰지만(pizza, milk처럼 셀 수 없는 것은 그대로), 초등 단계에서는 문장 구조에 먼저 집중하고 복수형은 들려주기만 해도 충분합니다.", "가족 결과를 말하는 3인칭(Dad likes)은 고학년 내용이니, 아이가 시도하면 칭찬만 해 주세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Good question! · Nice! · Thank you for asking.", "좋은 질문이야! · 좋아! · 물어봐 줘서 고마워."]}], "title": ""}, {"type": "more", "items": [{"body": "음식 대신 동물, 운동, 색깔로 새 설문판을 만들어요.", "title": "좋아하는 것 넓히기"}, {"body": "결과를 '재활용 막대그래프' 활동처럼 막대그래프로 그려요.", "title": "그래프로 그리기"}, {"body": "휴대폰으로 서로 인터뷰하는 짧은 영상을 찍어요.", "title": "인터뷰 영상"}]}, {"type": "info", "items": [{"label": "도안", "value": "설문판 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 좋아하는 것 묻고 답하기"}]}]$j$::jsonb, updated_at=now() where slug='like-survey';
update public.activities set content=$j$[{"note": "전기 부품 4가지가 필요해요", "rows": [{"how": "3V용, 지름 5mm 흰색 LED", "kit": true, "name": "LED 1개"}, {"how": "AA 2개용, 빨간 선·검은 선 달린 것", "kit": true, "name": "건전지 끼우개"}, {"how": "스위치용. 클립은 집에 있는 것", "kit": true, "name": "할핀 2개, 클립 1개"}, {"how": "리모컨용 건전지", "kit": false, "name": "AA 건전지 2개"}, {"how": "손전등 몸통", "kit": false, "name": "우유팩 1개"}, {"how": "반사판에 붙여 빛을 모아요", "kit": false, "name": "알루미늄 호일"}, {"how": "송곳은 어른이 사용해요", "kit": false, "name": "테이프, 가위, 송곳"}], "type": "materials", "image": "assets/img/t_torch.jpg"}, {"type": "steps", "items": [{"body": "우유팩 윗부분을 잘라 내고, 건전지 끼우개가 안에 쏙 들어가는지 확인해요.", "warn": "", "image": "assets/img/s_milk-carton-torch_1.jpg", "title": "몸통 만들기"}, {"body": "우유팩 옆면에 3cm 간격으로 할핀 두 개를 꽂고, 한쪽 할핀에 클립을 걸어요. 클립을 돌려 다른 할핀에 닿게 하면 불이 켜지는 스위치가 돼요.", "warn": "할핀 구멍은 어른이 송곳으로 뚫어요.", "image": "assets/img/e10_s2.jpg", "title": "클립 스위치 만들기"}, {"body": "도안의 반사판을 오려 안쪽에 호일을 붙이고 원뿔 모양으로 말아요. 가운데 작은 구멍에 LED를 끼워요.", "warn": "", "image": "assets/img/s_milk-carton-torch_3.jpg", "title": "반사판 만들기"}, {"body": "회로 연결도를 보며 연결해요. LED의 긴 다리(+)는 빨간 선에, 짧은 다리(−)는 할핀 하나에, 다른 할핀은 검은 선에 감아 테이프로 고정해요.", "warn": "", "image": "assets/img/s_milk-carton-torch_4.jpg", "title": "회로 연결하기"}, {"body": "건전지를 넣고 반사판을 우유팩 입구에 테이프로 붙여요. 클립 스위치를 닫으면 불이 켜져요. 맨 위 사진처럼요! 안 켜지면 LED 다리 방향을 바꿔 다시 연결해 보세요.", "warn": "", "image": "assets/img/s_milk-carton-torch_5.jpg", "title": "불 켜기"}], "notes": ["안전: LED는 3V용을 쓰고, 건전지는 2개까지만 연결해요. 더 많이 연결하면 LED가 타 버려요. 빨간 선과 검은 선이 직접 닿으면(합선) 건전지가 뜨거워져요. 다 쓰면 건전지를 빼 두세요. 동전 모양 리튬 건전지는 아이가 삼키면 매우 위험해요. 이 실험에는 쓰지 말고 손 닿지 않는 곳에 보관해요."], "title": "만드는 방법"}, {"pdf": "assets/pdf/torch-circuit.pdf", "desc": "회로를 어떻게 이어야 하는지 그림으로 보여 주고, 반사판을 오려 만들 수 있는 전개도가 들어 있어요. A4 1장 (위 준비물 옆 미리보기).", "type": "template", "title": "회로 연결도와 반사판 전개도"}, {"type": "questions", "items": ["클립 스위치를 열면 불이 어떻게 되나요? 왜 그럴까요?", "LED 다리를 거꾸로 연결하면 어떻게 되나요?", "반사판이 있을 때와 없을 때 벽에 비친 빛은 어떻게 다른가요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["전기는 건전지에서 나와 전선을 따라 한 바퀴 빙 돌아 다시 건전지로 돌아가야만 흘러요. 이 길이 이어지면 LED에 불이 켜지고, 클립 스위치를 열어 길을 끊으면 불이 꺼져요. LED는 한쪽 방향으로만 전기를 통과시켜서 다리 방향이 중요해요."]}, {"label": "부모님께", "paras": ["전지, 전선, 스위치, 전구(LED)가 끊김 없이 이어진 닫힌 회로에서만 전류가 흐릅니다. 스위치는 회로를 열고 닫는 장치입니다. LED는 전류가 한 방향으로만 흐르는 소자라 +와 − 방향이 맞아야 켜지는데, 교과서의 꼬마전구와 다른 점이니 비교해 이야기해 주세요. 호일 반사판은 옆으로 퍼지는 빛을 앞으로 모아 줍니다.", "이렇게 물어보세요: \"우리 집 전등 스위치는 회로의 어디를 끊고 이을까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "클립 대신 지우개, 동전, 나무젓가락을 대 보며 불이 켜지는지 확인해요.", "title": "전기가 통하는 물건 찾기"}, {"body": "반사판 입구에 색 셀로판을 씌워 봐요.", "title": "색깔 손전등"}, {"body": "스위치를 짧게, 길게 눌러 가족에게 신호를 보내요.", "title": "모스 부호 놀이"}]}, {"type": "info", "items": [{"label": "도면", "value": "회로 연결도와 반사판 전개도 (A4 1장)"}, {"label": "실험 키트", "value": "LED·건전지 끼우개·할핀 세트 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 전기의 이용 (전기 회로, 스위치)"}]}]$j$::jsonb, updated_at=now() where slug='milk-carton-torch';
update public.activities set content=$j$[{"note": "살 것 없음", "rows": [{"how": "달력판으로 써요 (없으면 상자 판을 동그랗게)", "kit": false, "name": "종이접시 1개"}, {"how": "30칸 달력과 달 모양 5단계 카드", "kit": false, "name": "달 관찰 달력 도안"}, {"how": "본 모양 그대로 칠해요", "kit": false, "name": "연필, 색연필"}, {"how": "달 모양이 바뀌는 까닭을 실험해요", "kit": false, "name": "손전등, 공 (선택)"}, {"how": "달력을 오려 종이접시에 붙여요", "kit": false, "name": "가위, 풀"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안의 30칸 달력을 오려 종이접시에 붙여요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_1.jpg", "title": "달력 붙이기"}, {"body": "저녁 같은 시각에 같은 곳에서 달을 찾아요. 보이는 모양을 칸에 그대로 칠해요. 구름 낀 날은 '구름'이라고 적어요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_2.jpg", "title": "매일 같은 시각에 보기"}, {"body": "모양 카드를 보고 초승달, 상현달, 보름달, 하현달, 그믐달 중 무엇인지 적어요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_3.jpg", "title": "이름 붙이기"}, {"body": "한 달이 지나면 달력을 보며 달 모양이 어떤 차례로 바뀌었는지 이어 말해요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_4.jpg", "title": "차례 찾기"}, {"body": "어두운 방 한쪽에 손전등을 켜서 고정해 두고(태양), 공(달)을 팔을 뻗어 얼굴 앞에 든 채 제자리에서 천천히 한 바퀴 돌아요. 공의 밝은 부분이 어떻게 보이나요?", "warn": "", "image": "assets/img/s_moon-phase-calendar_5.jpg", "title": "손전등 실험"}], "notes": ["초승달·상현달은 해 진 뒤 저녁 하늘에서 보이고, 보름달은 해 질 무렵 동쪽에서 떠요. 보름 뒤로는 달이 날마다 늦게 떠서 하현달은 새벽~아침 남쪽 하늘, 그믐달은 해 뜨기 전 동쪽 하늘에서만 보여요. 저녁에 안 보이는 날은 다음 날 아침 일찍 찾아보거나 '안 보임'이라고 기록해 두면 됩니다."], "title": "실험 방법"}, {"type": "questions", "items": ["보름달 다음에는 달이 어느 쪽부터 줄어드나요?", "같은 모양의 달이 다시 보이기까지 며칠쯤 걸리나요?", "달은 왜 날마다 모양이 바뀌어 보일까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["달은 스스로 빛을 내지 않고 햇빛을 받아 반사해요. 달이 지구 둘레를 돌면서 우리에게 햇빛 받은 부분이 보이는 만큼만 밝게 보이기 때문에, 날마다 모양이 달라 보여요. 달 모양은 약 한 달마다 다시 처음으로 돌아와요."]}, {"label": "부모님께", "paras": ["달의 위상은 초승달 → 상현달 → 보름달 → 하현달 → 그믐달 순으로 약 29.5일 주기로 바뀝니다. 음력 날짜와 거의 맞아서 음력 15일 무렵이 보름달입니다.", "손전등과 공 실험은 초등 수준에서 '보이는 부분이 달라진다'는 생각을 몸으로 이해하게 하는 데 목적이 있습니다. 정확한 궤도 설명보다 관찰한 차례를 말할 수 있으면 충분합니다.", "이렇게 물어보세요: \"추석이나 정월 대보름에는 왜 보름달을 볼 수 있을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/moon-phase-calendar.pdf", "desc": "30칸 관찰 달력과 달 모양 5단계 카드. A4 1장.", "type": "template", "title": "달 관찰 달력"}, {"type": "more", "items": [{"body": "오레오 쿠키 크림을 긁어 달 모양 5단계를 만들어요.", "title": "달 쿠키"}, {"body": "휴대폰 달력에서 음력 날짜와 관찰한 달 모양을 맞춰 봐요.", "title": "음력 달력 찾기"}, {"body": "보름달을 쌍안경으로 보고 어두운 무늬를 그려요.", "title": "달 표면 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "달 관찰 달력 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 지구와 달의 운동 (여러 날 동안 달의 모양 변화)"}]}]$j$::jsonb, updated_at=now() where slug='moon-phase-calendar';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "피자 상자나 택배 상자를 펼쳐서", "kit": false, "name": "두꺼운 종이 상자"}, {"how": "아래에서 내려받아 컬러로 인쇄해요", "kit": false, "name": "분수 원판 도안"}, {"how": "상자 자르기는 어른이 해요", "kit": false, "name": "풀, 가위, 커터칼"}, {"how": "조각 뒷면에 분수를 적어요", "kit": false, "name": "네임펜"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안을 인쇄해 원 6개를 오리고, 펼친 상자 판에 풀로 붙여요.", "warn": "", "image": "assets/img/s_pizza-fractions_1.jpg", "title": "도안 붙이기"}, {"body": "원 테두리와 안쪽 선을 따라 조각을 잘라요. 조각 뒷면에 1/2, 1/3처럼 분수를 적어 둬요.", "warn": "두꺼운 상자는 어른이 커터칼로 잘라 주세요.", "image": "assets/img/s_pizza-fractions_2.jpg", "title": "조각 자르기"}, {"body": "노란 '1' 원 위에 1/2 조각 두 개를 올려 보세요. 딱 맞게 덮이나요? 1/4 조각 몇 개로 덮을 수 있는지도 세어 봐요.", "warn": "", "image": "assets/img/s_pizza-fractions_3.jpg", "title": "전체 위에 덮어 보기"}, {"body": "조각 두 개를 골라 겹쳐 보고 더 큰 쪽을 맞혀요. \"1/3 피자와 1/4 피자 중 어느 쪽을 먹을래?\"", "warn": "", "image": "assets/img/s_pizza-fractions_4.jpg", "title": "크기 비교 게임"}, {"body": "1/2 조각 하나를 다른 조각들로 똑같이 덮어 보세요. 1/4로는 몇 개, 1/8로는 몇 개가 필요한가요?", "warn": "", "image": "assets/img/s_pizza-fractions_5.jpg", "title": "같은 크기 찾기"}], "notes": [], "title": "하는 방법"}, {"pdf": "assets/pdf/fraction-circles.pdf", "desc": "전체, 1/2, 1/3, 1/4, 1/6, 1/8 원판 6장. 분모마다 색이 달라 아이가 쉽게 구분해요. A4 1장.", "type": "template", "title": "분수 원판 도안"}, {"type": "questions", "items": ["아래 숫자가 커질수록 한 조각의 크기는 어떻게 되나요?", "1/4 조각 3개를 모으면 원의 얼마만큼이 될까요?", "크기가 다르게 자른 조각도 1/4이라고 부를 수 있을까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["피자를 더 많은 조각으로 똑같이 나눌수록 한 조각은 작아져요. 2명이 나누면 1/2, 4명이 나누면 1/4이에요. 아래 숫자(분모)는 몇 조각으로 똑같이 나눴는지, 위 숫자(분자)는 그중 몇 조각인지를 알려 줘요."]}, {"label": "부모님께", "paras": ["분수는 '전체를 똑같이 나눈 것 가운데 몇'입니다. 3~4학년에서는 분수의 뜻과 단위분수(분자가 1인 분수)의 크기 비교를 다루고, 크기가 같은 분수는 5학년 '약분과 통분'에서 본격적으로 배웁니다. 조각을 직접 겹쳐 보면 '숫자가 크면 더 크다'는 흔한 착각, 즉 1/4이 1/2보다 크다는 생각을 자연스럽게 바로잡을 수 있습니다. '똑같이' 나누는 것이 핵심이라는 점도 꼭 짚어 주세요.", "이렇게 물어보세요: \"피자를 친구 몇 명이랑 나눠 먹으면 더 큰 조각을 먹을 수 있을까?\""]}], "title": "개념 정리"}, {"type": "more", "items": [{"body": "케이크나 사과를 나눌 때 \"이건 몇 분의 몇?\" 하고 물어요.", "title": "식탁에서 분수 말하기"}, {"body": "1/2 = 2/4 = 4/8을 조각으로 줄 세워요.", "title": "같은 크기 사슬"}, {"body": "\"3/8 피자 주세요\" 주문을 받아 조각을 골라 줘요.", "title": "분수 피자 가게"}]}, {"type": "info", "items": [{"label": "도안", "value": "분수 원판 6장 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 분수 (단위분수, 크기 비교)"}]}]$j$::jsonb, updated_at=now() where slug='pizza-fractions';
update public.activities set content=$j$[{"note": "살 것 없음 · 집에 있는 재료", "rows": [{"how": "백·십·일의 자리 컵이 돼요", "kit": false, "name": "종이컵 3개"}, {"how": "일의 자리 낱개로 써요", "kit": false, "name": "마른 콩이나 병뚜껑 30개"}, {"how": "콩 10개 = 십 묶음 1개라는 것을 먼저 보여 줄 때 고무줄로 묶어 써요. 계산판에서는 콩만 써요", "kit": false, "name": "(선택) 빨대 또는 이쑤시개 10개"}, {"how": "아래에서 내려받아요", "kit": false, "name": "자릿값 계산판 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안을 인쇄해 책상에 놓고, 백·십·일 칸 위에 종이컵을 하나씩 올려요. 컵에 '백', '십', '일'이라고 적어요.", "warn": "", "image": "assets/img/s_place-value-cups_1.jpg", "title": "계산판 펼치기"}, {"body": "예를 들어 247이면 백 컵에 2개, 십 컵에 4개, 일 컵에 7개를 넣어요. 같은 콩이라도 어느 컵에 있느냐에 따라 값이 달라져요.", "warn": "", "image": "assets/img/s_place-value-cups_2.jpg", "title": "수를 컵에 담기"}, {"body": "247 + 185라면 185만큼 콩을 더 넣어요. 백 컵에 1개, 십 컵에 8개, 일 컵에 5개.", "warn": "", "image": "assets/img/s_place-value-cups_3.jpg", "title": "더하는 수 담기"}, {"body": "일 컵의 콩을 세어요. 7+5=12개! 10개를 빼서 십 컵에 콩 1개로 바꿔 넣어요. 이게 받아올림이에요. 일 컵에는 2개가 남아요.", "warn": "", "image": "assets/img/s_place-value-cups_4.jpg", "title": "일의 자리부터 정리"}, {"body": "십 컵이 4+8+1=13개가 되면 또 10개를 백 컵 1개로 바꿔요. 최종 답은 4, 3, 2. 즉 432예요.", "warn": "", "image": "assets/img/s_place-value-cups_5.jpg", "title": "십, 백의 자리도 정리"}, {"body": "예를 들어 432 − 185라면, 일 컵의 콩 2개에서 5개를 뺄 수 없으니 십 컵에서 1개를 꺼내 일 컵 콩 10개로 바꿔요(12 − 5 = 7). 이게 받아내림이에요. 십, 백의 자리도 같은 방법으로 빼요.", "warn": "", "image": "assets/img/s_place-value-cups_6.jpg", "title": "뺄셈은 거꾸로"}], "notes": ["처음에는 두 자리 수로 시작하고, 익숙해지면 세 자리 수로 늘려요. 문제 카드는 도안 아래쪽에 있어요."], "title": "하는 방법"}, {"type": "questions", "items": ["일 컵에 콩이 10개 넘게 있으면 왜 안 될까요?", "십 컵의 콩 1개는 일 컵의 콩 몇 개와 같을까요?", "받아올림이 두 번 생기는 덧셈 문제를 직접 만들어 볼 수 있나요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["우리가 쓰는 수는 한 칸에 0부터 9까지만 들어갈 수 있어요. 10이 되면 한 칸 왼쪽으로 이사를 가요. 일의 자리 10개가 십의 자리 1개, 십의 자리 10개가 백의 자리 1개가 되는 거예요. 그래서 덧셈할 때 10이 넘으면 윗자리에 1을 올려 주는 거랍니다."]}, {"label": "부모님께", "paras": ["3학년 '덧셈과 뺄셈'은 세 자리 수의 받아올림·받아내림이 핵심입니다. 아이가 세로셈에서 작은 '1'을 왜 쓰는지 모르고 외우기만 하면 실수가 잦아집니다. 콩 10개를 1개로 바꾸는 손동작을 세로셈의 작은 1과 연결해 주세요.", "정리가 끝나면 계산판 옆에 세로셈을 같이 써서 비교해 보세요.", "이렇게 물어보세요: \"일 컵에서 십 컵으로 콩을 옮길 때, 세로셈에서는 어디에 무엇을 쓰면 될까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/place-value-cups.pdf", "desc": "백·십·일 자리 판과 덧셈·뺄셈 문제 카드 12장. A4 1장.", "type": "template", "title": "자릿값 계산판"}, {"type": "more", "items": [{"body": "계산 전에 '대략 400쯤?' 하고 어림한 뒤 결과와 비교해요.", "title": "어림하고 계산하기"}, {"body": "100원·10원·1원 동전을 컵 대신 써서 거스름돈 계산을 해요.", "title": "가게 놀이"}, {"body": "아이가 문제를 내고 부모님이 풀어요. 일부러 틀려서 아이가 찾아내게 해 보세요.", "title": "문제 내기"}]}, {"type": "info", "items": [{"label": "도안", "value": "자릿값 계산판 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 덧셈과 뺄셈 (세 자리 수, 받아올림·받아내림)"}]}]$j$::jsonb, updated_at=now() where slug='place-value-cups';
update public.activities set content=$j$[{"note": "살 것 없음 · 종이접시나 도안", "rows": [{"how": "반지름 6cm 원과 붙이기 칸 (A4 2장)", "kit": false, "name": "원 16등분 도안"}, {"how": "도안 대신 접어서 써도 돼요", "kit": false, "name": "종이접시 1장 (선택)"}, {"how": "원의 둘레(원주)를 재요", "kit": false, "name": "실 1m와 자"}, {"how": "조각을 잘라 붙여요", "kit": false, "name": "가위, 풀, 색연필"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "종이접시나 동그란 컵 둘레에 실을 감아 길이를 재고, 지름으로 나눠요. 3.1~3.2쯤이 나오나요? 이 값이 원주율(약 3.14)이에요.", "warn": "", "image": "assets/img/s_plate-circle-area_1.jpg", "title": "원주율 재기"}, {"body": "도안의 원에서 위쪽 반원과 아래쪽 반원을 서로 다른 색으로 칠해요.", "warn": "", "image": "assets/img/s_plate-circle-area_2.jpg", "title": "반쪽씩 색칠하기"}, {"body": "중심에서 나가는 선을 따라 16조각으로 잘라요. 피자 조각 같은 모양이 나와요.", "warn": "", "image": "assets/img/s_plate-circle-area_3.jpg", "title": "16조각 자르기"}, {"body": "도안 2쪽의 붙이기 칸에 한 조각은 뾰족한 쪽이 위, 다음 조각은 아래로 엇갈려 일렬로 붙여요. 직사각형에 가까운 모양이 돼요.", "warn": "", "image": "assets/img/s_plate-circle-area_4.jpg", "title": "엇갈려 붙이기"}, {"body": "세로는 반지름(6cm), 가로는 원주의 반(6 × 2 × 3.14 ÷ 2 = 18.84cm)이에요. 둘을 곱하면 원의 넓이예요.", "warn": "", "image": "assets/img/s_plate-circle-area_5.jpg", "title": "가로와 세로 찾기"}, {"body": "반지름 × 반지름 × 3.14 = 6 × 6 × 3.14 = 113.04cm². 모눈 칸 세기와도 비교해요.", "warn": "", "image": "assets/img/s_plate-circle-area_6.jpg", "title": "공식으로 확인하기"}], "notes": ["조각을 더 잘게(32조각) 나눌수록 더 반듯한 직사각형이 돼요. 아이와 '조각이 무한히 많으면?'을 이야기해 보세요."], "title": "하는 방법"}, {"type": "questions", "items": ["실로 잰 원주율이 정확히 3.14가 나오지 않는 이유는 무엇일까요?", "조각을 더 많이 자르면 모양이 어떻게 달라질까요?", "반지름이 2배가 되면 넓이는 몇 배가 될까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["원을 아주 잘게 잘라 엇갈려 붙이면 직사각형에 점점 가까워져요. 이 직사각형의 세로는 원의 반지름, 가로는 원 둘레의 절반이에요. 그래서 원의 넓이는 반지름 × 반지름 × 3.14로 구할 수 있어요. 어떤 원이든 둘레를 지름으로 나누면 약 3.14가 나오는데, 이 값을 원주율이라고 해요."]}, {"label": "부모님께", "paras": ["6학년 '원의 넓이'는 원주율(지름에 대한 원주의 비율)과 원의 넓이 공식을 다룹니다. 공식을 외우기 전에 '왜 반지름을 두 번 곱하지?'를 이 활동으로 이해하면 응용 문제에서 덜 흔들립니다.", "원주율을 실로 잴 때 오차가 생기는 것이 자연스럽다는 것도 함께 이야기해 주세요. 측정과 계산의 차이를 배우는 좋은 기회입니다.", "이렇게 물어보세요: \"반지름이 4cm인 원과 8cm인 원의 넓이는 몇 배 차이일까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/plate-circle-area.pdf", "desc": "반지름 6cm 원 16등분, 직사각형 붙이기 칸, 원주율 기록표. A4 2장.", "type": "template", "title": "원 16등분 도안"}, {"type": "more", "items": [{"body": "냄비 뚜껑, 컵, 시계의 원주와 지름을 재서 비율을 표로 정리해요.", "title": "집 안 원주율 찾기"}, {"body": "지름 30cm 피자와 지름 20cm 피자 2판 중 어느 쪽이 더 많은지 넓이로 비교해요.", "title": "피자 가격 비교"}, {"body": "모눈종이(1cm 칸)에 반지름 6cm 원을 그려 칸을 세어 어림 넓이를 구해요.", "title": "모눈 세기"}]}, {"type": "info", "items": [{"label": "도안", "value": "원 넓이 도안 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 원의 넓이 (원주율, 원의 넓이)"}]}]$j$::jsonb, updated_at=now() where slug='plate-circle-area';
update public.activities set content=$j$[{"note": "살 것 없음 · 간식만 있으면 돼요", "rows": [{"how": "간식을 담는 접시로 써요", "kit": false, "name": "종이컵 4~6개"}, {"how": "젤리, 시리얼, 콩과자 등 셀 수 있는 것", "kit": false, "name": "작은 간식 24개"}, {"how": "아래에서 내려받아요", "kit": false, "name": "나눗셈 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "간식 12개를 종이컵 3개에 하나씩 차례로 넣어요. 한 컵에 몇 개씩 들어갔나요? 12 ÷ 3 = 4.", "warn": "", "image": "assets/img/s_snack-division_1.jpg", "title": "똑같이 나누기"}, {"body": "이번에는 간식 12개를 4개씩 컵에 담아요. 컵이 몇 개 필요한가요? 12 ÷ 4 = 3.", "warn": "", "image": "assets/img/s_snack-division_2.jpg", "title": "묶어서 덜어 내기"}, {"body": "같은 12개인데 '몇 명에게 나누나'를 물으면 한 사람 몫이, '몇 개씩 담나'를 물으면 묶음 수가 답이 돼요. 기록지 두 칸에 그림으로 그려요.", "warn": "", "image": "assets/img/s_snack-division_3.jpg", "title": "두 방법 비교하기"}, {"body": "4 × 3 = 12, 3 × 4 = 12. 나눗셈 답이 맞는지 곱셈으로 거꾸로 확인해요.", "warn": "", "image": "assets/img/s_snack-division_4.jpg", "title": "곱셈으로 확인하기"}, {"body": "간식 14개를 컵 3개에 나누면 2개가 남아요. 남는 수(나머지)는 나누는 수보다 항상 작아요.", "warn": "나머지는 3학년 2학기에 배우는 내용이에요. 어려워하면 넘어가도 돼요.", "image": "assets/img/s_snack-division_5.jpg", "title": "남는 것 알아보기"}], "notes": ["다 하고 나면 나눈 간식은 맛있게 먹어요. 가족 수대로 나누면 더 재미있어요."], "title": "하는 방법"}, {"type": "questions", "items": ["24개를 똑같이 나눌 수 있는 컵의 수를 모두 찾아볼까요?", "나눗셈 답을 곱셈으로 확인하는 방법을 말해 볼까요?", "20개를 6명에게 나누면 어떻게 될까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["나눗셈은 똑같이 나누는 계산이에요. '12개를 3명에게 똑같이 나누면 한 명이 몇 개?'처럼 나눌 수도 있고(12 ÷ 3 = 4), '12개를 4개씩 담으면 몇 봉지?'처럼 묶을 수도 있어요(12 ÷ 4 = 3). 어느 쪽이든 나눗셈식으로 써요."]}, {"label": "부모님께", "paras": ["3학년 나눗셈은 '똑같이 나누기(등분제)'와 '몇 번 덜어 내기(포함제)' 두 가지 뜻으로 소개됩니다. 아이가 문장제에서 헷갈려 하면 실물로 두 방법을 직접 해 보는 것이 가장 빠릅니다.", "곱셈구구를 거꾸로 쓰는 것이 나눗셈이라는 연결도 꼭 짚어 주세요.", "이렇게 물어보세요: \"12 ÷ 3 = 4를 보고 곱셈식을 두 개 만들어 볼까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/snack-division.pdf", "desc": "나누기·묶기 그림 칸과 곱셈 확인 칸. A4 1장.", "type": "template", "title": "나눗셈 기록지"}, {"type": "more", "items": [{"body": "15 ÷ 5를 보고 간식, 연필, 스티커로 이야기 문제를 지어요.", "title": "나눗셈 이야기 만들기"}, {"body": "분수 활동의 피자 판으로 8조각을 2명, 4명에게 나눠요.", "title": "피자 나누기"}, {"body": "주사위 두 개로 수를 만들고 3으로 나눴을 때 나머지를 맞혀요.", "title": "나머지 찾기 놀이"}]}, {"type": "info", "items": [{"label": "도안", "value": "나눗셈 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 나눗셈 (등분제와 포함제, 곱셈과의 관계)"}]}]$j$::jsonb, updated_at=now() where slug='snack-division';
update public.activities set content=$j$[{"note": "살 것 없음 · 휴대폰 손전등도 OK", "rows": [{"how": "다 쓴 두루마리 휴지 심", "kit": false, "name": "휴지심 3개"}, {"how": "검은 도화지. 없으면 이면지를 매직으로 검게 칠해요.", "kit": false, "name": "검은 종이"}, {"how": "종이를 고정하는 용도", "kit": false, "name": "고무줄 3개"}, {"how": "굵은 바늘도 돼요. 아래에 접은 수건을 깔아요.", "kit": false, "name": "압정 1개"}, {"how": "휴대폰 손전등도 돼요", "kit": false, "name": "손전등"}, {"how": "아래에서 내려받아 인쇄해요", "kit": false, "name": "별자리 도안"}], "type": "materials", "image": "assets/img/e9_mat.jpg"}, {"type": "steps", "items": [{"body": "도안을 인쇄해 별자리 동그라미를 바깥 점선을 따라 오려요.", "warn": "", "image": "assets/img/s_star-projector_1.jpg", "title": "도안 오리기"}, {"body": "검은 종이 위에 도안을 겹쳐 대고, 접은 수건 위에서 흰 점마다 압정으로 구멍을 뚫어요. 밝은 별은 압정을 살짝 돌려 조금 더 크게 뚫어요.", "warn": "압정 끝에 찔리지 않게 조심하고, 다 쓰면 바로 상자에 넣어요.", "image": "assets/img/e9_s1.jpg", "title": "별 구멍 뚫기"}, {"body": "구멍 뚫린 검은 종이를 휴지심 한쪽 끝에 씌우고 고무줄로 팽팽하게 고정해요. 도안을 대고 뚫었던 면이 바깥(천장 쪽)을 보도록 씌워야 별자리가 바른 모양으로 비쳐요. 휴지심 옆면에 별자리 이름을 적어 둬요.", "warn": "", "image": "assets/img/s_star-projector_3.jpg", "title": "휴지심에 씌우기"}, {"body": "방을 어둡게 하고, 휴지심 반대쪽 끝에 손전등을 대고 천장을 비춰요. 휴지심을 천장에 가까이, 멀리 해 보며 별이 또렷해지는 거리를 찾아요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_star-projector_4.jpg", "title": "천장에 띄우기"}], "notes": [], "title": "만드는 방법"}, {"pdf": "assets/pdf/star-templates.pdf", "desc": "북두칠성, 카시오페이아, 오리온. 천장에 비쳤을 때 바른 모양이 되도록 도안은 좌우를 뒤집어 그렸어요. A4 1장.", "type": "template", "title": "별자리 도안 3종"}, {"type": "questions", "items": ["휴지심을 천장에서 멀리 하면 별자리 크기는 어떻게 되나요?", "북두칠성 국자 끝의 두 별을 이은 길이를 다섯 배 늘리면 어디에 닿을까요?", "카시오페이아와 북두칠성은 어느 별을 사이에 두고 마주 보고 있을까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["손전등 빛은 검은 종이에 막히고, 작은 구멍으로만 빠져나가요. 빛은 똑바로 나아가니까 구멍 모양 그대로 천장에 점이 찍혀요. 진짜 별들도 아주아주 멀리 있어서 밤하늘에 작은 점처럼 보여요."]}, {"label": "부모님께", "paras": ["빛이 곧게 나아가는 성질 때문에 구멍 배열이 그대로 확대되어 천장에 비칩니다. 별자리는 지구에서 볼 때 비슷한 방향에 보이는 별들을 이어 이름 붙인 것으로, 실제로는 별마다 지구와의 거리가 크게 다릅니다. 북두칠성은 큰곰자리의 꼬리와 엉덩이 부분에 있는 일곱 별입니다. 북두칠성 국자 끝 두 별 사이 거리를 약 다섯 배 늘이면 북극성을 찾을 수 있으니, 맑은 날 북쪽 하늘에서 함께 찾아보세요.", "이렇게 물어보세요: \"별자리는 계절마다 왜 다르게 보일까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "가족 이름의 첫 글자나 반려동물 모양으로 나만의 별자리를 만들어요.", "title": "우리 가족 별자리"}, {"body": "맑은 밤 북쪽 하늘에서 북두칠성과 북극성을 찾아봐요.", "title": "진짜 하늘 찾기"}, {"body": "별자리에 얽힌 옛이야기를 찾아 천장 극장으로 들려줘요.", "title": "별자리 이야기"}]}, {"type": "info", "items": [{"label": "도면", "value": "별자리 도안 3종 (A4 1장)"}, {"label": "실험 키트", "value": "집 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 태양계와 별 (별자리, 북극성 찾기)"}]}]$j$::jsonb, updated_at=now() where slug='star-projector';
update public.activities set content=$j$[{"note": "각설탕 한 봉지면 충분해요", "rows": [{"how": "치약 상자, 과자 상자, 약 상자처럼 뚜껑이 열리는 것", "kit": false, "name": "작은 상자 2~3개"}, {"how": "마트 커피 코너. 실험 후 다시 봉지에 담아 써요.", "kit": false, "name": "각설탕 1봉지"}, {"how": "30cm 자", "kit": false, "name": "자"}, {"how": "아래에서 내려받아 인쇄해요", "kit": false, "name": "부피 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "각설탕의 가로, 세로, 높이를 자로 재서 기록지에 적어요. 회사마다 크기가 조금씩 달라서 꼭 직접 재야 해요.", "warn": "", "image": "assets/img/s_sugar-cube-volume_1.jpg", "title": "각설탕 한 개 재기"}, {"body": "상자들을 눈으로만 보고 어느 상자가 가장 큰지, 각설탕이 몇 개 들어갈지 예상해서 적어요.", "warn": "", "image": "assets/img/s_sugar-cube-volume_2.jpg", "title": "예상하기"}, {"body": "상자 바닥에 각설탕을 빈틈없이 한 층 깔고 개수를 세요. 그다음 몇 층까지 쌓이는지 확인해 '한 층 개수 × 층 수'로 계산해요.", "warn": "", "image": "assets/img/s_sugar-cube-volume_3.jpg", "title": "한 층 깔고 쌓기"}, {"body": "상자 안쪽의 가로, 세로, 높이를 cm로 재고 곱해서 부피(cm³)를 구해요.", "warn": "", "image": "assets/img/s_sugar-cube-volume_4.jpg", "title": "자로 재서 계산하기"}, {"body": "각설탕 개수와 계산한 cm³가 왜 다른지 이야기해요. 기록지의 질문에 답을 적어요.", "warn": "", "image": "assets/img/s_sugar-cube-volume_5.jpg", "title": "두 결과 비교하기"}], "notes": [], "title": "하는 방법"}, {"pdf": "assets/pdf/volume-record.pdf", "desc": "상자별 측정표, 두 방법을 비교하는 질문, 1cm 모눈이 한 장에 들어 있어요. A4 1장.", "type": "template", "title": "부피 기록지"}, {"type": "questions", "items": ["각설탕을 하나하나 다 세지 않고 빨리 세는 방법은 무엇인가요?", "모양은 다른데 부피는 같은 상자가 있을까요?", "각설탕 한 개는 몇 cm³쯤 될까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["부피는 물건이 차지하는 공간의 크기예요. 각설탕으로 재면 각설탕 크기에 따라 개수가 달라져서 사람마다 답이 달라요. 그래서 모두가 똑같이 쓰려고 '한 변이 1cm인 정육면체'를 약속 단위로 정했어요. 이것이 1cm³(1세제곱센티미터)예요."]}, {"label": "부모님께", "paras": ["6학년 '직육면체의 부피와 겉넓이' 단원은 임의 단위로 부피를 비교한 뒤 표준 단위 1cm³의 필요성을 배우고, (가로)×(세로)×(높이) 공식을 '한 층의 개수 × 층 수'로 이해하는 흐름입니다. 각설탕은 한 변이 1cm보다 커서 개수와 계산값이 달라지는데, 이 차이가 표준 단위가 왜 필요한지 이야기할 좋은 기회입니다. 상자 두께 때문에 안쪽이 바깥보다 조금 작다는 점도 함께 짚어 주세요.", "이렇게 물어보세요: \"택배 회사는 상자 크기를 어떻게 정할까?\""]}], "title": "개념 정리"}, {"type": "more", "items": [{"body": "1L 우유팩의 가로, 세로, 높이를 재서 계산하면 1000cm³와 얼마나 가까울까요?", "title": "1L 우유팩 재기"}, {"body": "각설탕 12개로 모양이 다른 직육면체를 여러 개 쌓아 봐요.", "title": "같은 부피 다른 모양"}, {"body": "상자를 펼쳐 여섯 면의 넓이를 모두 더해 봐요.", "title": "겉넓이 구하기"}]}, {"type": "info", "items": [{"label": "도안", "value": "부피 기록지 (A4 1장)"}, {"label": "키트", "value": "1cm 정육면체 블록 세트 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 직육면체의 부피 (1cm³, 부피 구하는 방법)"}]}]$j$::jsonb, updated_at=now() where slug='sugar-cube-volume';
update public.activities set content=$j$[{"note": "살 것 없음 · 이면지 한 장이면 책 한 권", "rows": [{"how": "8쪽 틀과 접는 법·과거형 단어 (A4 2장). 1쪽만 인쇄해 접어요.", "kit": false, "name": "미니북 도안"}, {"how": "가운데 빨간 선 하나만 잘라요", "kit": false, "name": "가위"}, {"how": "그림을 그리거나 작게 인쇄한 사진을 붙여요", "kit": false, "name": "색연필, 방학 사진"}, {"how": "사진을 붙여요", "kit": false, "name": "풀"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안 1쪽을 인쇄해 2쪽의 접는 법대로 8칸 자국을 내고, 가운데 빨간 선만 잘라 책 모양으로 접어요. 윗줄이 거꾸로 인쇄된 것은 접으면 바르게 보이게 하려는 거예요.", "warn": "", "image": "assets/img/s_summer-minibook_1.jpg", "title": "미니북 접기"}, {"body": "방학 사진을 함께 보며 어디에 갔는지, 누구와 갔는지, 무엇을 보고 먹었는지 한국어로 이야기해요.", "warn": "", "image": "assets/img/s_summer-minibook_2.jpg", "title": "방학 떠올리기"}, {"body": "쪽마다 이미 적힌 문장의 빈칸을 채워요. 예: I went to the beach. 모르는 낱말은 사전 앱으로 함께 찾아요.", "warn": "", "image": "assets/img/s_summer-minibook_3.jpg", "title": "빈칸 채우기"}, {"body": "네모 칸에 그림을 그리거나 사진을 붙이고, 표지에 이름을 써요.", "warn": "", "image": "assets/img/s_summer-minibook_4.jpg", "title": "그림 넣기"}, {"body": "완성한 책을 가족 앞에서 읽어 주어요. 영상으로 찍어 두면 방학 기념이 돼요.", "warn": "", "image": "assets/img/s_summer-minibook_5.jpg", "title": "작가 낭독회"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "지난 일은 동사 모양이 바뀌어요. play → played처럼 ed를 붙이는 말도 있고, go → went, see → saw처럼 모양이 완전히 바뀌는 말도 있어요. 도안 2쪽에 정리되어 있어요.", "rows": [["What did you do this summer?", "이번 여름에 뭐 했어?"], ["I went to Jeju Island.", "제주도에 갔어요."], ["I saw dolphins. / I ate fish.", "돌고래를 봤어요. / 생선을 먹었어요."], ["It was great!", "정말 멋졌어요!"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/summer-minibook.pdf", "desc": "빈칸 문장이 들어간 8쪽 미니북 틀, 접는 방법 다섯 단계, 과거형 단어 8쌍과 느낌 낱말. A4 2장.", "type": "template", "title": "여름방학 미니북 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["5~6학년 영어에서는 지난 일을 묻고 답하며, 간단한 글로 쓰는 활동을 합니다. 빈칸이 있는 문장 틀을 주면 아이가 '쓸 거리'에만 집중할 수 있어 영어 쓰기 부담이 크게 줄어요. 철자가 조금 틀려도 끝까지 완성한 것을 먼저 칭찬해 주세요."]}, {"label": "계절마다 한 권", "paras": ["겨울방학, 생일, 가족 여행마다 한 권씩 만들면 아이만의 영어 그림책 시리즈가 생겨요."]}], "title": ""}, {"type": "more", "items": [{"body": "\"What did you do yesterday?\" 가족끼리 서로 물어봐요.", "title": "인터뷰 놀이"}, {"body": "자기 전에 오늘 한 일을 영어 한 문장으로 써요.", "title": "한 줄 영어 일기"}, {"body": "\"I will ~\"로 다음 방학 계획책도 만들어요.", "title": "미래 미니북"}]}, {"type": "info", "items": [{"label": "도안", "value": "8쪽 미니북 틀과 과거형 단어 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 지난 일 묻고 답하기, 짧은 글 쓰기"}]}]$j$::jsonb, updated_at=now() where slug='summer-minibook';
update public.activities set content=$j$[{"note": "살 것 없음 · 택배 상자에 붙이면 튼튼해요", "rows": [{"how": "조각 선과 모양 카드 (A4 1장)", "kit": false, "name": "칠교 도안"}, {"how": "도안을 붙여 두꺼운 조각을 만들어요", "kit": false, "name": "얇은 택배 상자 판지"}, {"how": "조각마다 색을 칠하면 구분하기 쉬워요", "kit": false, "name": "풀, 가위, 색연필"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안의 큰 정사각형을 상자 판지에 풀로 붙여요.", "warn": "", "image": "assets/img/s_tangram_1.jpg", "title": "도안 붙이기"}, {"body": "선을 따라 큰 삼각형 2개, 중간 삼각형 1개, 작은 삼각형 2개, 정사각형 1개, 평행사변형 1개로 잘라요.", "warn": "두꺼운 판지는 어른이 칼로 잘라 주세요.", "image": "assets/img/s_tangram_2.jpg", "title": "일곱 조각 자르기"}, {"body": "삼각자나 책 모서리를 대 보며 직각이 있는 조각을 찾아 표시해요.", "warn": "", "image": "assets/img/s_tangram_3.jpg", "title": "직각 찾기"}, {"body": "도안 아래 도전 카드 3장(정사각형, 삼각형, 직사각형)을 보고 카드에 적힌 조각만 써서 같은 모양을 만들어요.", "warn": "", "image": "assets/img/s_tangram_4.jpg", "title": "도전 카드 풀기"}, {"body": "작은 삼각형 2개로 정사각형, 중간 삼각형, 평행사변형을 각각 만들 수 있는지 해 봐요.", "warn": "", "image": "assets/img/s_tangram_5.jpg", "title": "조각 합치기"}, {"body": "새로운 모양을 만들고 테두리를 따라 그려 가족에게 문제로 내요.", "warn": "", "image": "assets/img/s_tangram_6.jpg", "title": "나만의 모양"}], "notes": ["일곱 조각을 다시 정사각형으로 맞추는 것이 생각보다 어려워요. 막히면 큰 삼각형 2개부터 놓아 보세요."], "title": "하는 방법"}, {"type": "questions", "items": ["일곱 조각 중 직각이 있는 조각은 몇 개인가요?", "작은 삼각형 2개로 만들 수 있는 모양은 무엇무엇일까요?", "정사각형도 직사각형이라고 할 수 있을까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["종이를 반듯하게 두 번 접었을 때 생기는 각을 직각이라고 해요. 직각이 있는 삼각형은 직각삼각형, 네 각이 모두 직각인 사각형은 직사각형이에요. 그중 네 변의 길이까지 모두 같으면 정사각형이에요. 그래서 정사각형은 직사각형의 한 종류랍니다."]}, {"label": "부모님께", "paras": ["3학년 '평면도형'은 선분·반직선·직선, 각과 직각, 직각삼각형·직사각형·정사각형을 다룹니다. 아이들이 '정사각형은 직사각형인가?'를 가장 헷갈려 하니, 칠교 조각을 직접 대 보며 조건을 하나씩 확인하게 해 주세요.", "4학년 다각형·사각형 분류(평행사변형, 사다리꼴)로 이어질 때 이 조각들을 다시 쓰면 좋습니다.", "이렇게 물어보세요: \"이 조각은 왜 직사각형이 아니라고 생각해?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/tangram.pdf", "desc": "칠교 정사각형(15cm)과 모양 만들기 도전 카드 3장. A4 1장.", "type": "template", "title": "칠교 도안"}, {"type": "more", "items": [{"body": "같은 모양 카드를 누가 더 빨리 만드는지 겨뤄요.", "title": "시간 재기 대결"}, {"body": "아무 모양 종이를 두 번 접어 직각 자를 만들고 집 안 직각을 찾아요.", "title": "종이 접어 직각 만들기"}, {"body": "모양 테두리만 그려 주고 조각 배치를 맞히게 해요.", "title": "그림자 맞히기"}]}, {"type": "info", "items": [{"label": "도안", "value": "칠교 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 평면도형 (직각, 직각삼각형, 직사각형, 정사각형)"}]}]$j$::jsonb, updated_at=now() where slug='tangram';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "지도판으로 써요", "kit": false, "name": "택배 상자 뚜껑"}, {"how": "지도와 표현 카드 6장 (A4 1장)", "kit": false, "name": "동네 지도 도안"}, {"how": "지도 위를 걸어 다닐 말이에요", "kit": false, "name": "작은 인형이나 지우개"}, {"how": "약 상자로 건물을 세우면 입체 지도가 돼요", "kit": false, "name": "작은 상자들 (선택)"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "지도를 상자 뚜껑에 붙여요. 작은 상자로 건물을 세우면 더 실감 나요.", "warn": "", "image": "assets/img/s_town-map_1.jpg", "title": "지도 붙이기"}, {"body": "인형을 START에 세우고, 한 사람이 \"Where is the library?\" 하고 물어요.", "warn": "", "image": "assets/img/s_town-map_2.jpg", "title": "출발점에 서기"}, {"body": "다른 사람은 표현 카드를 보며 \"Go straight. Turn left.\" 하고 말로만 안내해요. 묻는 사람은 들은 대로만 인형을 움직여요.", "warn": "", "image": "assets/img/s_town-map_3.jpg", "title": "말로만 안내하기"}, {"body": "\"It's next to the bank.\"처럼 위치를 설명하고, 맞게 도착했는지 확인한 뒤 역할을 바꿔요.", "warn": "", "image": "assets/img/s_town-map_4.jpg", "title": "도착 확인하기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "left와 right는 인형이 바라보는 방향을 기준으로 해요. 아이와 인형의 방향이 다를 때 헷갈리니, 처음에는 인형 뒤에서 같은 방향을 보며 연습해요.", "rows": [["Where is the library?", "도서관이 어디예요?"], ["Go straight.", "쭉 가세요."], ["Turn left. / Turn right.", "왼쪽으로 / 오른쪽으로 도세요."], ["It's next to the bank.", "은행 옆에 있어요."], ["It's across from the park.", "공원 맞은편에 있어요."]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/town-map.pdf", "desc": "school, hospital, library 등 건물 12개가 있는 지도와 길 안내 표현 카드 6장. A4 1장.", "type": "template", "title": "동네 지도 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["5~6학년 영어에서는 위치를 묻고 길을 안내하는 표현을 배웁니다. 말로만 안내하는 규칙이 핵심이에요. 손가락으로 가리키지 않고 영어로만 설명해야 하니, 자연스럽게 문장을 끝까지 말하게 됩니다."]}, {"label": "우리 동네 버전", "paras": ["도안 지도가 익숙해지면, 이면지에 진짜 우리 동네 지도를 그려 학교 가는 길을 영어로 설명해 보세요."]}], "title": ""}, {"type": "more", "items": [{"body": "한 건물 아래 보물 쪽지를 숨기고 영어로만 안내해 찾게 해요.", "title": "보물찾기"}, {"body": "\"Go straight two blocks.\"처럼 거리를 넣어 말해요.", "title": "몇 블록?"}, {"body": "바닥의 물건을 치우고, 눈을 가린 가족을 영어로 냉장고까지 안내해요. 부딪히지 않게 옆에서 함께 걸어 주세요.", "title": "집 안 길 찾기"}]}, {"type": "info", "items": [{"label": "도안", "value": "동네 지도와 표현 카드 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 위치 묻고 길 안내하기"}]}]$j$::jsonb, updated_at=now() where slug='town-map';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "무늬 없이 매끈한 둥근 병. 라벨은 떼요.", "kit": false, "name": "투명 페트병 1개"}, {"how": "수돗물", "kit": false, "name": "물"}, {"how": "주방용 랩", "kit": false, "name": "비닐 랩"}, {"how": "물방울을 떨어뜨리는 용도 (스포이트도 OK)", "kit": false, "name": "숟가락"}, {"how": "글씨가 작은 것", "kit": false, "name": "신문이나 책"}], "type": "materials", "image": "assets/img/e8_mat.jpg"}, {"type": "steps", "items": [{"body": "페트병에 물을 가득 채우고 뚜껑을 꼭 닫아요. 공기 방울이 적을수록 또렷하게 보여요.", "warn": "", "image": "assets/img/s_water-lens_1.jpg", "title": "물병 돋보기 만들기"}, {"body": "병을 눕혀 신문 위에 올리고 글씨를 봐요. 병을 조금씩 들어 올리며 글씨가 어떻게 바뀌는지 살펴봐요. 위아래로는 그대로인데 옆으로만 넓어지는 것도 찾아봐요.", "warn": "", "image": "assets/img/s_water-lens_2.jpg", "title": "글씨 위에서 보기"}, {"body": "신문 위에 랩을 펴고, 숟가락으로 물을 한 방울 떨어뜨려요. 물방울 아래 글씨를 들여다봐요.", "warn": "", "image": "assets/img/e8_s2.jpg", "title": "물방울 돋보기 만들기"}, {"body": "작은 물방울과 큰 물방울 중 어느 쪽이 글씨를 더 크게 보여 주는지 비교해요.", "warn": "", "image": "assets/img/s_water-lens_4.jpg", "title": "물방울 크기 바꾸기"}, {"body": "물병 돋보기로 나뭇잎 잎맥, 손가락 지문, 그림책을 살펴봐요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_water-lens_5.jpg", "title": "주변 관찰하기"}], "notes": ["안전: 둥근 물병은 햇빛을 한 점으로 모아 불이 날 수 있어요. 물이 든 페트병을 햇빛 드는 창가나 자동차 안에 두지 마세요."], "title": "만드는 방법"}, {"type": "questions", "items": ["물병 돋보기는 왜 옆으로만 커 보일까요?", "물방울 돋보기는 왜 모든 방향으로 커 보일까요?", "물을 비운 빈 병으로 보면 어떻게 될까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["물이 둥글게 볼록한 모양이 되면 빛이 그 안을 지나면서 살짝 꺾여요. 꺾인 빛이 우리 눈에 들어오면 물건이 실제보다 크게 보여요. 진짜 돋보기도 가운데가 볼록한 유리로 만들어요."]}, {"label": "부모님께", "paras": ["가운데가 두껍고 가장자리가 얇은 볼록렌즈는 빛을 굴절시켜 가까운 물체를 크게 보이게 합니다. 물방울은 사방으로 둥근 볼록렌즈라 모든 방향으로 커 보이고, 눕힌 원통형 물병은 한 방향으로만 휘어 있어 그 방향으로만 늘어나 보입니다. 작고 동그랗게 볼록한 물방울일수록 빛이 더 많이 꺾여 글씨가 더 크게 보이고, 큰 물방울은 납작해져서 덜 커 보입니다. 볼록렌즈가 햇빛을 모으는 성질 때문에 생기는 화재 위험도 함께 이야기해 주세요.", "이렇게 물어보세요: \"할머니 돋보기 안경은 어떤 모양의 렌즈일까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "물 대신 식용유 방울로 보면 더 크게 보일까요?", "title": "식용유 돋보기"}, {"body": "물을 채운 둥근 컵과 네모난 통으로 보면 무엇이 다를까요?", "title": "유리컵 비교"}, {"body": "돋보기로 본 것을 크게 그려서 기록해요.", "title": "관찰 일기"}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "집 재료로 충분해요 (볼록렌즈 세트 준비 중)"}, {"label": "교육과정 연결", "value": "5~6학년 빛과 렌즈 (볼록렌즈)"}]}]$j$::jsonb, updated_at=now() where slug='water-lens';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "이면지에 인쇄해도 돼요 (A4 1장)", "kit": false, "name": "날씨 돌림판 도안"}, {"how": "과자 상자나 택배 상자를 펼쳐서", "kit": false, "name": "두꺼운 종이"}, {"how": "화살표를 돌릴 수 있게 고정해요 (없으면 압정과 지우개를 쓰되, 압정은 보호자가 꽂아 주세요)", "kit": false, "name": "할핀 1개"}, {"how": "벽이나 현관문에 걸 때 써요", "kit": false, "name": "풀, 가위, 끈"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안을 두꺼운 종이에 붙이고 큰 원과 화살표를 오려요.", "warn": "", "image": "assets/img/s_weather-wheel_1.jpg", "title": "판 만들기"}, {"body": "원 가운데 점과 화살표 아래쪽 점을 맞추고 할핀으로 꽂아요. 화살표가 빙글빙글 도는지 확인해요.", "warn": "", "image": "assets/img/s_weather-wheel_2.jpg", "title": "화살표 달기"}, {"body": "아이 눈높이에 맞춰 현관문이나 창문 옆에 걸어요.", "warn": "", "image": "assets/img/s_weather-wheel_3.jpg", "title": "현관에 걸기"}, {"body": "학교 가기 전에 부모님이 \"How's the weather today?\" 하고 물으면, 아이가 창밖을 보고 화살표를 돌리며 대답해요.", "warn": "", "image": "assets/img/s_weather-wheel_4.jpg", "title": "매일 아침 1분"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "돌림판 낱말: sunny(맑은), cloudy(흐린), rainy(비 오는), snowy(눈 오는), windy(바람 부는), hot(더운)", "rows": [["How's the weather today?", "오늘 날씨 어때?"], ["It's sunny. / It's rainy.", "맑아. / 비가 와."], ["Take your umbrella!", "우산 챙겨! (rainy일 때)"], ["Let's go outside!", "밖에 나가자! (sunny일 때)"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/weather-wheel.pdf", "desc": "날씨 그림 6칸 원판, 화살표, 아침 대화 문장. A4 1장.", "type": "template", "title": "날씨 돌림판 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["외국어는 짧게라도 매일 쓰는 것이 가장 효과적입니다. 하루 1분 날씨 대화를 아침 습관으로 만들어 보세요. 한 달이면 날씨 낱말 6개와 질문·대답 표현이 자연스럽게 입에 붙어요."]}, {"label": "수학도 함께", "paras": ["한 달 동안 날씨를 달력에 기록하면, 수학 '재활용품 막대그래프'처럼 날씨 그래프도 그릴 수 있어요."]}], "title": ""}, {"type": "more", "items": [{"body": "\"It's cold. Wear your coat!\" 날씨에 맞는 옷을 말해요.", "title": "옷 입히기 놀이"}, {"body": "TV 기상캐스터처럼 내일 날씨를 영어로 발표해요.", "title": "일기 예보관"}, {"body": "지금 다른 나라 날씨를 찾아보고 비교해요.", "title": "세계 날씨"}]}, {"type": "info", "items": [{"label": "도안", "value": "날씨 돌림판과 화살표 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 날씨 묻고 답하기"}]}]$j$::jsonb, updated_at=now() where slug='weather-wheel';
update public.lessons set title='시곗바늘이 알려 주는 시각은?' where slug='m1-07';
